window.__SUM[2]={"LR002064":{"pair":"ADA -> DPP4","headline":"ADA binds DPP4 directly, shown by a 3.0 angstrom crystal structure; DPP4 acts as ADA receptor in T-cell co-stimulation.","interaction_type":"direct binding","direction_and_effect":"DPPIV acts as a receptor for ADA, mediating co-stimulatory signals in T-lymphocytes [PMID:15213224]. ADA binding could regulate adhesion by abolishing DPPIV tetramerization [PMID:15213224]. UniProt: positive regulator of T-cell coactivation by binding DPP4 [DB:UniProt].","molecular_requirements":"Each beta-propeller domain of the DPPIV dimer binds one ADA; two hydrophobic loops of DPPIV contact charged alpha-helices of ADA, and four N-glycans at Asn229 of DPPIV also contact ADA [PMID:15213224]. UniProt lists the DPP4 extracellular domain as the interaction region [DB:UniProt].","affinity_potency":[],"species_and_systems":"Crystal of human DPPIV with bovine ADA [PMID:15213224]; the human and mouse pairs are ortholog-inferred.","localisation_and_range":"ADA is flagged not secreted and DPP4 transmembrane [flag]; DPPIV is a type II membrane glycoprotein [PMID:15213224].","caveats":"Structure used bovine ADA; the paper is abstract only. Also BioGRID affinity capture-western [DB:BioGRID]. UniProt says its interaction with DPP4 regulates lymphocyte-epithelial adhesion [DB:UniProt].","key_references":[{"PMID":"15213224","why":"Co-crystal structure of human DPPIV with bovine ADA"}],"covers":["LR002064","LR005390"]},"LR005016":{"pair":"ADAM23 -> ITGA4","headline":"Human ADAM23 supports integrin alpha4-dependent cell adhesion; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Human ADAM11, ADAM23 and ADAM29 selectively support integrin alpha4-dependent cell adhesion; the disintegrin-like domains of these catalytically inactive ADAMs are ligands [PMID:28913673].","molecular_requirements":"Dependent on alpha4; partner beta chain not stated in our abstract [PMID:28913673].","affinity_potency":[],"species_and_systems":"Human proteins; integrin binding assays with cell adhesion [PMID:28913673]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM23 is flagged secreted and receptor [flag].","caveats":"Abstract read only (evidence sentence is truncated). The paper states ADAMs 'selectively support' adhesion, not affinity.","key_references":[{"PMID":"28913673","why":"Non-catalytic ADAMs incl. ADAM23 are integrin alpha4 ligands"}],"covers":["LR001628","LR005016"]},"LR002073":{"pair":"ADAM28 -> ITGB1","headline":"ADAM28 disintegrin domain adhesion to Jurkat cells is blocked by anti-beta1 antibody; functional, human, abstract only.","interaction_type":"functional only","direction_and_effect":"Adhesion of Jurkat cells to the MDC-L (ADAM 28) disintegrin domain was inhibited by anti-alpha4 and anti-beta1 function-blocking mAbs; alpha4beta1-transfected K562 cells adhered [PMID:11724793].","molecular_requirements":"Beta1 acts as the partner of alpha4 (alpha4beta1) [PMID:11724793]; beta1 alone is not tested.","affinity_potency":[],"species_and_systems":"Human; Jurkat cells and K562 transfectants with recombinant Fc fusion [PMID:11724793]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM28 is flagged secreted [flag], but the paper says MDC-L is expressed on the surface of human lymphocytes [PMID:11724793].","caveats":"Abstract read only; adhesion assays.","key_references":[{"PMID":"11724793","why":"ADAM28 disintegrin recognised by alpha4beta1"}],"covers":["LR002073","LR005399"]},"LR008202":{"pair":"ADAM9 -> ITGA3:ITGB1","headline":"Alpha3beta1 is captured by the ADAM9 disintegrin domain from renal lysate; abstract only, human.","interaction_type":"direct binding","direction_and_effect":"GST-disintegrin affinity capture from renal cortical lysates recovered alpha3 and beta1 chains by Western analysis [PMID:15361064].","molecular_requirements":"Both alpha3 and beta1 were recovered; the disintegrin domain is the binding region [PMID:15361064].","affinity_potency":[],"species_and_systems":"HEK-293 cells and renal cortical lysate; human [PMID:15361064].","localisation_and_range":"ADAM9 flagged secreted [flag]; basolateral on renal tubular cells per the paper [PMID:15361064].","caveats":"Abstract read only; lysate capture is not proof of direct contact.","key_references":[{"PMID":"15361064","why":"Renal integrins captured by ADAM9 disintegrin"}],"covers":["LR008202"]},"LR005403":{"pair":"ADAMTS13 -> CD36","headline":"Recombinant human ADAMTS13 binds CD36 dose-dependently in an immunoassay; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"rHuCD36 bound rHuADAMTS13 in a dose-dependent fashion; ADAMTS13 also preferentially bound platelet membrane fragments expressing CD36 over those expressing GPIb/IX. Binding did not inhibit ADAMTS13 VWF-cleaving activity, so CD36 may localise active enzyme rather than inhibit it [PMID:19389207].","molecular_requirements":"Thrombospondin-2 competed but even high concentrations failed to fully block binding, suggesting partly overlapping sites [PMID:19389207].","affinity_potency":[],"species_and_systems":"Recombinant human proteins in enzyme-linked immunoassay; platelet membrane fragments [PMID:19389207].","localisation_and_range":"Ligand flagged secreted [flag]; CD36 is described as a transmembrane protein on endothelial cells and platelets [PMID:19389207].","caveats":"Abstract-only read; no affinity value in our evidence; no cell-signalling readout. No database support.","key_references":[{"PMID":"19389207","why":"dose-dependent ADAMTS13 binding to CD36, thrombospondin-2 competition"}],"covers":["LR002077","LR005403"]},"LR001632":{"pair":"ADGRB1 -> RTN4R","headline":"ADGRB1 ectodomain binds RTN4R directly in a CRISPRa and AVEXIS study; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probe stained cells overexpressing RTN4R, RTN4RL1 and RTN4RL2 and ectodomains interacted directly in AVEXIS in both bait-prey orientations [PMID:30477585]. Notably, RTN4R was not enriched in the CRISPRa screen (a false negative is acknowledged for one family member) and was confirmed by individual transfection and AVEXIS [PMID:30477585].","molecular_requirements":"The N-terminal thrombospondin type 1 repeats 1-3 of ADGRB1 were sufficient for binding; ADGRB1 but not ADGRB2 interacted [PMID:30477585].","affinity_potency":[],"species_and_systems":"Human cDNAs in HEK293 cells and recombinant ectodomains; four independent experiments for the staining result [PMID:30477585]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor side is a GPI-linked membrane protein per the paper [PMID:30477585]; ADGRB1 is flagged secreted [flag] but the assay used its ectodomain, and its native range is not reported in our evidence.","caveats":"Single paper; binding only, no signalling or functional effect shown. No affinity value. No database support.","key_references":[{"PMID":"30477585","why":"CRISPRa screen and AVEXIS showing ADGRB1-RTN4R family binding"}],"covers":["LR001632","LR005020"]},"LR002082":{"pair":"ADGRL1 -> NRXN3","headline":"Latrophilin-1 ectodomain binds neurexins with nanomolar affinity; evidence is one abstract-only paper that covers neurexins as a group.","interaction_type":"direct binding","direction_and_effect":"Direct binding between the extracellular domains of latrophilin-1 (CL1) and neurexins; CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing both formed stable adhesion, so trans-cellular [PMID:22262843].","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1; those with an SS4 insert do not. The olfactomedin-like domain of CL1 mediates binding [PMID:22262843].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"saturation binding","system":"purified ectodomains","cite":"PMID:22262843"}],"species_and_systems":"Purified ectodomains and cell adhesion assays; species not stated beyond curator label human [PMID:22262843]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both partners are membrane proteins [flag]; interaction is trans-cellular, suggesting juxtacrine signalling [PMID:22262843].","caveats":"Abstract only, and the abstract speaks of neurexins generally, so isoform specificity for NRXN3 is not shown in our evidence. Only the SS4-minus form binds [PMID:22262843]. Ligand-receptor direction is not defined, as both are membrane proteins.","key_references":[{"PMID":"22262843","why":"identifies latrophilin-1/neurexin binding"}],"covers":["LR002082","LR005408"]},"LR005412":{"pair":"ADIPOQ -> LAIR1","headline":"The globular adiponectin domain interacts with inhibitory receptor LAIR-1 (one 2021 abstract).","interaction_type":"functional only","direction_and_effect":"Globular adiponectin (gAdp) interacted with LAIR-1 and inhibited T cell activation via LAIR-1, involving downstream SHP-2 [PMID:34403808]. Inhibitory effect.","molecular_requirements":"The globular domain was the form studied; other forms not reported in our evidence [PMID:34403808].","affinity_potency":[],"species_and_systems":"In vitro T cell experiments; species not specified in our evidence [PMID:34403808].","localisation_and_range":"Adiponectin flagged secreted [flag]; LAIR1 flagged transmembrane [flag].","caveats":"Abstract only; binding method and affinity not reported, so classed as direct_binding by curators on limited detail. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"34403808","why":"reports gAdp-LAIR-1 interaction"}],"covers":["LR002086","LR005412"]},"LR008022":{"pair":"ADM -> CALCR:RAMP2","headline":"No paper evidence for this specific CALCR:RAMP2 complex; only GtoPdb, PDB, Reactome and UniProt records for related ADM receptors.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists ADM as full agonist at ADM-CALCR (pEC50 6.5 to 8.4) and ADM-RAMP2 (pKi 8.3 to 9.2) [DB:GtoPdb]. Structures include CLR:RAMP2 ECD with adrenomedullin [DB:PDB 4RWF] and an active AM1 receptor G protein complex [DB:PDB 6UUN].","molecular_requirements":"UniProt says RAMP2 with CALCRL forms an ADM receptor complex [DB:UniProt]; the dossier complex pairs RAMP2 with CALCR, not CALCRL.","affinity_potency":[{"value":"pKi 8.3-9.2","assay":"GtoPdb ADM-RAMP2 record","system":"not specified","cite":"PMID:11693189"}],"species_and_systems":"Species not stated in our evidence.","localisation_and_range":"ADM flagged secreted [flag].","caveats":"Both judged rows were different_entity, meaning the papers concerned other entities. Records support CALCRL:RAMP2, not CALCR:RAMP2.","key_references":[],"covers":["LR008022"]},"LR005025":{"pair":"ADM2 -> RAMP2","headline":"ADM2 binds RAMP-CLR extracellular complexes including the RAMP2 one; RAMP2 acts with CLR, evidence is one abstract plus database records.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound all three purified RAMP-CLR ECD complexes with a selectivity profile distinct from CGRP and AM [PMID:30139742]. GtoPdb lists a full agonist [DB:GtoPdb]. Reactome records the adrenomedullin receptor binding adrenomedullin and intermedin [DB:Reactome R-HSA-420214].","molecular_requirements":"RAMP2 with CLR; the RAMP1 and RAMP3 complexes were preferred over RAMP2 [PMID:30139742].","affinity_potency":[{"value":"pEC50 7.5-8.3","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Purified recombinant ECD complexes; curators annotate human ligand and receptor. Mouse pair projected from human.","localisation_and_range":"RAMP2 is flagged receptor [flag]; ADM2 flagged secreted [flag].","caveats":"Abstract-only. The crystal structure was with RAMP1, not RAMP2. Three review_only, one abstract_insufficient and one different_entity paper are not shown.","key_references":[{"PMID":"30139742","why":"AM2/IMD binding across RAMP-CLR ECD complexes"}],"covers":["LR001637","LR005025"]},"LR002091":{"pair":"AGRN -> ITGAV","headline":"One 1997 abstract-only paper implicates alpha-v integrin in agrin signalling and adhesion; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Agrin-induced acetylcholine receptor aggregation on cultured myotubes was partially blocked by antibodies to the alpha(v) subunit, and inhibited by alpha(v) antisense oligonucleotides and an alpha(v) binding-site-blocking peptide [PMID:9367446]. Alpha(v)-negative cells did not adhere to agrin but became adherent when alpha(v) was introduced [PMID:9367446]. The curator labels the effect as agonist.","molecular_requirements":"The cells expressing alpha(v) and beta1 adhered to agrin; the authors implicate alpha(v)beta1 as a component or modulator of agrin signalling [PMID:9367446]. Beta1 antibodies blocked completely, alpha(v) only partially [PMID:9367446].","affinity_potency":[],"species_and_systems":"Species not specified in the abstract (curation tags human/human, but the experiments use cultured myotubes and non-muscle cells) [PMID:9367446].","localisation_and_range":"Agrin is described as a basal lamina-associated proteoglycan [PMID:9367446].","caveats":"Abstract read only. The paper says integrins are 'components or modulators' of the pathway, so it is not clear that agrin is a direct ligand of alpha-v. The pair is given as alpha-v alone while the evidence points to alpha-v with beta1. No affinity reported.","key_references":[{"PMID":"9367446","why":"Antibody, antisense and gain-of-function evidence for alpha-v in agrin adhesion and signalling"}],"covers":["LR002091","LR005417"]},"LR000039":{"pair":"AGRN -> LRP4","headline":"LRP4 is identified as a receptor for agrin that activates MuSK; well supported by a landmark paper and structure/pathway records.","interaction_type":"direct binding","direction_and_effect":"Lrp4 is reported to be a receptor for Agrin, to form a complex with MuSK and to mediate MuSK activation by Agrin [PMID:18848351]. Effect is agonist/stimulatory. Reactome lists an AGRN:LRP4:MUSK complex [DB:Reactome].","molecular_requirements":"Lrp4 forms a complex with MuSK, and MuSK activation by agrin runs through Lrp4 [PMID:18848351]. A PDB structure contains chains of agrin and LRP4 [DB:PDB 8S9P].","affinity_potency":[],"species_and_systems":"The paper's excerpts describe BaF3 cells expressing Lrp4 binding to substrate-attached Agrin [PMID:18848351]; the curator tags both species as human, which the excerpt does not confirm. Mouse entry is not ortholog-inferred; human is.","localisation_and_range":"Agrin is an extracellular matrix protein presented to muscle cells [PMID:18848351].","caveats":"Paper read as abstract plus excerpts; the binding assay is cell adhesion to agrin, with no affinity reported in our evidence.","key_references":[{"PMID":"18848351","why":"Identifies Lrp4 as an agrin receptor that complexes with MuSK"}],"covers":["LR000039","LR003589"]},"LR005421":{"pair":"AGRP -> MC1R","headline":"AGRP competes with alpha-MSH for the binding site at MC1R in one 1998 abstract-only study; the receptor binding is shown for agouti protein, not AGRP itself.","interaction_type":"conflicting","direction_and_effect":"In 293T cells, Mc1r conferred a specific, high-affinity binding site for HA-Agouti, and this binding was inhibited by alpha-MSH or by Agrp, indicating mutually exclusive binding [PMID:9450927]. The abstract describes Agouti and Agrp as antagonists of melanocortins [PMID:9450927].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"293T cells and Xenopus melanophores, with mouse in vivo mutant studies; curation tags human/human [PMID:9450927].","localisation_and_range":"Agouti protein and Agrp are described as paracrine-signalling molecules [PMID:9450927].","caveats":"Abstract-only. The direct binding measured is of agouti protein, with AGRP acting only as a competitor, so AGRP binding to MC1R is inferred. The curator effect label is 'agonist', whereas AGRP is described as an antagonist at melanocortin receptors.","key_references":[{"PMID":"9450927","why":"Agouti binds Mc1r and is competed by AGRP"}],"covers":["LR002095","LR005421"]},"LR000048":{"pair":"AGT -> MAS1","headline":"Mas is a functional receptor for angiotensin-(1-7) in mouse knockout and transfected-cell data; the ligand is a processed AGT peptide.","interaction_type":"direct binding","direction_and_effect":"Ang-(1-7) acts as an agonist at Mas: Mas deletion abolished Ang-(1-7) binding to mouse kidney, the antidiuretic action and aortic relaxation; Ang-(1-7) bound Mas-transfected cells and elicited arachidonic acid release [PMID:12829792]. Reactome lists an AGT(25-31):MAS1 complex [DB:Reactome R-HSA-9944535].","molecular_requirements":"Not reported in our evidence beyond Mas itself.","affinity_potency":[],"species_and_systems":"Mouse knockout tissues and Mas-transfected cells; curator records human ligand, mouse receptor. Human and mouse pairs are both ortholog-inferred [PMID:12829792].","localisation_and_range":"Ligand flagged secreted, so likely endocrine or paracrine [flag].","caveats":"Single paper, abstract only. The ligand is Ang-(1-7), not full-length AGT or Ang II. Pair rests on one paper plus one Reactome record. No affinity reported.","key_references":[{"PMID":"12829792","why":"Mas knockout abolishes Ang-(1-7) binding and responses"}],"covers":["LR000048","LR003598"]},"LR001641":{"pair":"ALCAM -> CHL1","headline":"Antibody blocking suggests Chl1 is needed for ALCAM-promoted axon growth of mouse midbrain dopamine neurons; no direct binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM promoted axon growth of mouse midbrain dopamine neurons, and neutralizing antibodies for Chl1 abolished the effect; the authors propose a trans-heterophilic interaction [PMID:31300520]. ALCAM also abolished Sema3A's growth effect and induced branching with Sema3C [PMID:31300520].","molecular_requirements":"Chl1 is described as one of three components of a Semaphorin receptor complex (Nrp1, Chl1, L1cam) [PMID:31300520]; which is needed alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine primary midbrain cultures [PMID:31300520]; curator records human for both partners.","localisation_and_range":"ALCAM acts as an extracellular substrate presented to cell-bound partners (juxtacrine/matrix-like) [PMID:31300520]. ","caveats":"Single paper, abstract only; inhibition by antibodies is indirect and shows no binding. No affinity.","key_references":[{"PMID":"31300520","why":"Antibody blocking of Nrp1/Chl1/L1cam abolishes ALCAM growth effect"}],"covers":["LR001641","LR005029"]},"LR005034":{"pair":"ALKAL2 -> ALK","headline":"ALKAL2 is a high-affinity agonist ligand of ALK, supported by binding, activation and structural papers in human systems.","interaction_type":"direct binding","direction_and_effect":"ALKAL2 (FAM150B) binds ALK with high affinity and activates it in cells with subnanomolar potency [PMID:26630010]. ALKAL1 and ALKAL2 both activate ALK-dependent proliferation, but only ALKAL2 potently activates ALK [PMID:34646012]. FAM150A/B bind the ALK extracellular domain and also 'superactivate' neuroblastoma-derived activated ALK mutants [PMID:26418745].","molecular_requirements":"ALK ectodomain TNF-like plus glycine-rich (TG) region contacts ALKAL2; ALKAL2 uses an amphipathic patch on the ALK TNF-like subdomain (Ser758, Thr967, Leu970, Val972) [PMID:34646012]. ALK-ALKAL1/2 complexes were 1:1, not the canonical 2:2 [PMID:34646012]. ALKAL2 charge-reversal site 1 mutants markedly reduced affinity [PMID:34646012]. Glycosaminoglycan binding to its HBD is described as an additional regulation, as background [PMID:34646012].","affinity_potency":[],"species_and_systems":"Human proteins. Purified human ALK fragments for crystals; PC12 cell neurite outgrowth and ALK phosphorylation with FAM150A/B [PMID:26418745]; NIH/3T3 and Ba/F3 cell assays [PMID:26630010]. Mouse pair inferred by orthology.","localisation_and_range":"ALKAL2 is flagged secreted and ALK transmembrane [flag]; Reactome shows the ALK dimer:ALKAL2 complex at the plasma membrane [DB:Reactome].","caveats":"[PMID:26630010] was read as abstract only; the 'subnanomolar' potency has no numeric value in our evidence. Several PDB structures and IntAct co-IP are recorded [DB:PDB 7LS0] [DB:IntAct].","key_references":[{"PMID":"26630010","why":"First identification of ALKAL2 as high-affinity ALK ligand"},{"PMID":"26418745","why":"FAM150A/B bind and activate ALK, including mutants"},{"PMID":"34646012","why":"Crystal structure of ALK-ALKAL2 and stoichiometry"}],"covers":["LR001646","LR005034"]},"LR001650":{"pair":"ANG -> PLXNB2","headline":"ANG binds PLXNB2 with nM Kd by SPR and PLXNB2 mediates ANG function; well supported by one major paper.","interaction_type":"direct binding","direction_and_effect":"PLXNB2 is the functional receptor for ANG: knockdown abolished ANG cell-surface binding, nuclear translocation, proliferation and AKT/ERK phosphorylation; ectopic human PLXNB2 in COS-7 cells enabled ANG responses. Antibodies to the ANG-binding site on PLXNB2 restricted ANG activity [PMID:29100074]. Agonist direction.","molecular_requirements":"The Sema domain of PLXNB2 is needed; the putative ANG binding site lies between residues 334 and 449. ANG did not bind the Sema domain of PLXNB1 or PLXNB3, and RNASE4 did not bind PLXNB2 [PMID:29100074].","affinity_potency":[{"value":"apparent Kd 0.74 nM","assay":"surface plasmon resonance","system":"ANG with purified PLXNB2 Sema domain","cite":"PMID:29100074"},{"value":"steady-state Kd 2.87 nM","assay":"surface plasmon resonance","system":"ANG with purified PLXNB2 Sema domain","cite":"PMID:29100074"}],"species_and_systems":"Human ANG and PLXNB2 in recombinant protein, cancer cell lines and COS-7 transfectants; mouse in vivo xenograft work is described in the abstract [PMID:29100074].","localisation_and_range":"ANG is flagged as secreted and PLXNB2 as transmembrane [flag]; ANG is endocytosed and translocates to the nucleus [DB:UniProt].","caveats":"One paper only. The UniProt note about endocytosis via PLXNB2 cites the same paper plus PMID:32510170 [DB:UniProt]. Mouse pair listed as not ortholog-inferred, but the mouse experiments are not detailed in our excerpts.","key_references":[{"PMID":"29100074","why":"PLXNB2 identified as ANG receptor; SPR Kd, specificity vs PLXNB1/B3"}],"covers":["LR001650","LR005038"]},"LR003603":{"pair":"ANGPT1 -> ITGA5","headline":"A truncated monomeric ANGPT1 fragment binds integrin alpha5beta1 in one abstract-only paper; native full-length ANGPT1 binding is not shown.","interaction_type":"direct binding","direction_and_effect":"Monomeric DeltaAng1 (isolated fibrinogen-like receptor-binding domain) bound alpha(5)beta(1) integrin with similar affinity compared with Tie2, and reproduced some full-length Ang1 effects in endothelial cells (reduced permeability, increased adhesion, MAPK activation); curator labels it agonist [PMID:15781448].","molecular_requirements":"The integrin tested is the alpha5beta1 heterodimer, so ITGA5 alone is not shown to be sufficient; ITGB1 is also required in the measured receptor [PMID:15781448]. The ligand was a truncated monomer, not the native oligomer.","affinity_potency":[],"species_and_systems":"Recombinant human DeltaAng1 made in insect cells; endothelial cells and chick chorioallantoic membrane; human ligand and receptor per curation [PMID:15781448]. The mouse pair is ortholog-inferred.","localisation_and_range":"ANGPT1 is flagged as secreted [flag]; ITGA5 is flagged as a receptor and not secreted [flag].","caveats":"Single paper, read as abstract only. A numerical affinity is not given in our evidence (only 'similar affinity compared with Tie2'). The fragment was monomeric and did not trigger Tie2 phosphorylation. No database support.","key_references":[{"PMID":"15781448","why":"Monomeric Ang1 fragment binds alpha5beta1 integrin"}],"covers":["LR000053","LR003603"]},"LR000057":{"pair":"ANGPT2 -> TEK","headline":"Ang2 binds Tie2 and acts as a context-dependent antagonist or weak agonist; strong database support, abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Ang2 was identified as a naturally occurring antagonist for Ang1 and Tie2 [PMID:9204896]. In hematopoietic cells Ang2 bound TEK with similar affinity to Ang1, induced a low level of TEK phosphorylation and weakened Ang1-induced phosphorylation [PMID:9723709]. The annotated modulatory effect is Stimulatory, which conflicts with the antagonist label from these papers.","molecular_requirements":"UniProt says Ang2 binds TEK/TIE2 competing for the same binding site as ANGPT1 [DB:UniProt]. Single receptor chain (TEK).","affinity_potency":[],"species_and_systems":"Human ligand and receptor in hematopoietic cells [PMID:9723709]; Ang2 overexpression in transgenic mice [PMID:9204896]. Database records include SPR and a PDB structure 2GY7 with both chains [DB:IntAct][DB:PDB 2GY7].","localisation_and_range":"ANGPT2 is flagged as secreted and TEK as transmembrane [flag].","caveats":"Both papers were abstract only, and no numeric affinity is given. The effect is context-dependent, so the Stimulatory flag may mislead. One row was different_entity, one review-only, one pending.","key_references":[{"PMID":"9204896","why":"Ang2 identified as antagonist of Ang1 and Tie2"},{"PMID":"9723709","why":"Ang2 binds TEK with affinity similar to Ang1 and gives weak phosphorylation"}],"covers":["LR000057","LR003607"]},"LR005430":{"pair":"ANGPTL1 -> LAIR1","headline":"ANGPTL1 binds LAIR1-expressing cells in one paper; weak binding, no purified-protein assay for LAIR1 shown.","interaction_type":"direct binding","direction_and_effect":"Angptl1 bound LAIR1-overexpressing 293T cells [PMID:22660330]. Effect on LAIR1 signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor expressed in 293T cells and primary human cord blood cells; the pair's mouse version is projected from human [PMID:22660330].","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"Angptl1 binding to LAIR1+ human cord blood cells was described as relatively weak [PMID:22660330]. The paper's co-IP and surface plasmon resonance confirmations and its focus were on LILRB2, not LAIR1, so direct binding to LAIR1 rests on cell-binding assays. No affinity reported.","key_references":[{"PMID":"22660330","why":"Angptl1 binds LAIR1-overexpressing cells, weakly on cord blood cells"}],"covers":["LR002104","LR005430"]},"LR002109":{"pair":"ANGPTL2 -> MCAM","headline":"CD146 (MCAM) is a direct ANGPTL2 binding partner on adipocytes, shown by pull-down with purified proteins and co-IP in mouse fat.","interaction_type":"direct binding","direction_and_effect":"ANGPTL2 interacted with CD146 in white adipose tissue and the interaction was stronger in obese than lean mice. Pull-down with purified proteins showed direct interaction. ANGPTL2 binding activated CREB, which upregulated CD146 [PMID:33747748]. Anti-CD146 antibodies disrupted the interaction and inhibited obesity [PMID:33747748].","molecular_requirements":"The fourth domain of CD146 was required for the interaction in 293 cells [PMID:33747748].","affinity_potency":[],"species_and_systems":"CD146 was found as an ANGPTL2 interactor on a human proteome microarray; co-IP in mouse white adipose tissue and 293 cells [PMID:33747748]. CD146 also detected in human adipose tissue [PMID:33747748].","localisation_and_range":"The paper calls CD146 a membrane receptor on preadipocytes and mature adipocytes [PMID:33747748]; the entity flag for MCAM says not transmembrane [flag].","caveats":"One paper. CD146 did not co-IP with ANGPTL3 or ANGPTL4 [PMID:33747748]. No affinity reported.","key_references":[{"PMID":"33747748","why":"Direct ANGPTL2-CD146 binding and role in adipocytes"}],"covers":["LR002109","LR005431"]},"LR003612":{"pair":"ANGPTL3 -> ITGB3","headline":"ANGPTL3 binds integrin alphaVbeta3, of which ITGB3 is the beta chain; evidence is for the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Recombinant ANGPTL3 bound alpha(v)beta(3) and drove alpha(v)beta(3)-dependent endothelial adhesion and migration with Akt, MAPK and FAK signalling [PMID:11877390]. UniProt agrees [DB:UniProt].","molecular_requirements":"Evidence is for the alphaVbeta3 heterodimer; ITGB3 alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells and rat corneal assay; recombinant protein species not reported in our evidence [PMID:11877390]. The mouse pair is projected from human.","localisation_and_range":"ANGPTL3 is described as liver-specific and secreted [PMID:11877390].","caveats":"Abstract-only; no affinity. Chain-only attribution: a CCC tool scoring ITGB3 alone assumes the other chain is present.","key_references":[{"PMID":"11877390","why":"ANGPTL3 binds alphaVbeta3 integrin"}],"covers":["LR000062","LR003612"]},"LR002118":{"pair":"ANGPTL4 -> SDC1","headline":"ANGPTL4 is reported as a syndecan binder in one full-text paper; SDC1-specific data are thin in our excerpts.","interaction_type":"direct binding","direction_and_effect":"The paper identifies ANGPTL4 as a Wnt signalling antagonist that binds syndecans and promotes LRP6 turnover; curator labels it antagonist [PMID:29017031]. The evidence sentence is the title, and SDC1-specific data are not shown in our excerpts.","molecular_requirements":"N-terminal ANGPTL4 (nANGPTL4) increased LRP6-SDC4 clustering while cANGPTL4 had no effect, so the N-terminal fragment seems relevant, unlike the C-terminal fragment elsewhere [PMID:29017031].","affinity_potency":[],"species_and_systems":"Xenopus embryos and HEK293T cells; human ANGPTL4 and human receptor constructs in the SDC4 data (a sister pair) [PMID:29017031].","localisation_and_range":"SDC1 is flagged both secreted and transmembrane, so shed and membrane forms are possible [flag]; ANGPTL4 is flagged secreted.","caveats":"Binding to SDC1 itself is only supported by the title and by a general statement that syndecans bind ANGPTL4; strongest evidence is for SDC4.","key_references":[{"PMID":"29017031","why":"ANGPTL4 is a Wnt antagonist that binds syndecans and promotes LRP6 turnover"}],"covers":["LR002118","LR005440"]},"LR005043":{"pair":"ANXA2 -> TLR2","headline":"Monomeric ANXA2 binds and activates TLR2 in co-immunoprecipitation and reporter assays; single paper, human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"Monomeric ANXA2 (ANXA2m) was identified as a TLR2-binding protein by mass spectrometry, and ANXA2 and TLR2 coimmunoprecipitated in GL261 lysates [PMID:26885373]. It acts as an agonist: it activated TLR2-expressing reporter cells and immature dendritic cells, upregulated CD80 and CD86, and induced IL-12p70, TNF-alpha and IFN-gamma; the adjuvant effect was TLR2-dependent in TLR2+/+ versus TLR2-/- mice [PMID:26885373]. BioGRID records the interaction from the same paper [DB:BioGRID].","molecular_requirements":"The monomeric form is the TLR2 ligand; the heterotetramer is described as signalling via TLR4 (background statement). The amino-terminal 15 amino acids of ANXA2m are necessary and sufficient for TLR2 binding and DC activation [PMID:26885373]. Whether other TLR2 partners are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine GL261 glioma lysates, human TLR2-expressing HEK-Blue reporter cells, murine and human DCs, and mice [PMID:26885373]. The human pair in this dossier is ortholog-inferred; the mouse pair is not.","localisation_and_range":"ANXA2 is flagged as secreted [flag]; the paper notes it can be intracellular, membrane-bound or secreted [PMID:26885373].","caveats":"Single paper, abstract plus excerpts; no affinity measured. Active form is oxygen-regulated (enriched at 5 % O2) and monomeric, which matters when scoring expression.","key_references":[{"PMID":"26885373","why":"Identifies monomeric ANXA2 as TLR2 ligand and maps the 15-aa N-terminal binding region."}],"covers":["LR001656","LR005043"]},"LR012144":{"pair":"APCDD1 -> FZD4:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD4 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD4 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD4 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD4. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012144"]},"LR000066":{"pair":"APLN -> APLNR","headline":"Apelin is the classical endogenous agonist of the apelin receptor (APJ), with direct binding and functional evidence from several species.","interaction_type":"direct binding","direction_and_effect":"Apelin is an agonist of APJ. It was isolated from bovine stomach extract by its ability to raise acidification rate in APJ-expressing cells [PMID:9792798]. Radiolabelled apelin analogues bound APJ with high affinity [PMID:10777510][PMID:11336787]. Apelin acts through Gi: acidification was blocked by a Gi inhibitor [PMID:10777510], and it inhibits cAMP production and induces receptor internalisation [PMID:15341513]. GtoPdb lists full agonist action [DB:GtoPdb].","molecular_requirements":"Single-chain GPCR, no co-receptor reported. Apelin-36 and pyroglutamylated apelin-13 differ in dissociation kinetics and signalling duration [PMID:10777510][PMID:11336787]. Leu5 and Arg2/Arg4 of apelin-13 are needed for potency and affinity [PMID:12603839]. For K17F, the first five N-terminal and last two C-terminal residues are dispensable for binding and cAMP inhibition, but full length is needed for maximal internalisation [PMID:15341513].","affinity_potency":[{"value":"pIC50 8.8 to 9.5","assay":"GtoPdb affinity range for the record citing this paper","system":"database record","cite":"PMID:10777510"},{"value":"10(-7) to 10(-10) M","assay":"acidification-rate response to synthetic apelin peptides","system":"cells expressing APJ","cite":"PMID:9792798"}],"species_and_systems":"Human APJ with human apelin [PMID:10777510][PMID:12603839]; rat receptor in CHO cells [PMID:15341513][PMID:11336787]; bovine-derived peptide on human APJ [PMID:9792798]. The mouse pair is a separate, non-inferred interaction record in our database.","localisation_and_range":"Apelin is flagged secreted, non-transmembrane; APLNR is transmembrane [flag]. Apelin forms differ among tissues in rat [PMID:11336787].","caveats":"All papers shown were read as abstracts only. Affinities come mostly from analogue ligands (radioiodinated analogues) rather than native peptide [PMID:10777510][PMID:11336787]. Two further papers were judged abstract_insufficient and one is pending.","key_references":[{"PMID":"9792798","why":"Isolation of apelin as the APJ ligand."},{"PMID":"10777510","why":"Radioligand binding and function of apelin-36 vs apelin-13."},{"PMID":"12603839","why":"Structure-activity of apelin analogues at human APJ."}],"covers":["LR000066","LR003615"]},"LR002145":{"pair":"APOE -> ABCA1","headline":"Two abstract-level reports of APOE complexing with ABCA1 (human fibroblasts, rat astrocytes); mechanism is lipidation rather than classical signalling.","interaction_type":"direct binding","direction_and_effect":"Purified human plasma apoE3 formed a complex with ABCA1 in normal fibroblasts and competitively inhibited 125I-apoA-I binding to ABCA1 [PMID:14754908]. Endogenous astrocytic apoE co-immunoprecipitated with ABCA1, not in ABCA1-knockout astrocytes, and is involved in generating HDL-like particles [PMID:24814386]. The Tangier mutation C1477R abolished apoE3 binding and efflux [PMID:14754908].","molecular_requirements":"ApoE isoforms bound ABCA1 similarly; lipid association reduced binding [PMID:14754908]. Other subunits not reported in our evidence.","affinity_potency":[{"value":"IC50 2.5 +/- 0.4 microg/ml","assay":"lipid-free apoE3 inhibition of 125I-apoA-I binding to ABCA1","system":"human fibroblasts, stimulated","cite":"PMID:14754908"},{"value":"IC50 12.3 +/- 1.3 microg/ml","assay":"reconstituted HDL inhibition of 125I-apoA-I binding to ABCA1 (comparator)","system":"human fibroblasts, stimulated","cite":"PMID:14754908"}],"species_and_systems":"Human fibroblasts with human apoE3 [PMID:14754908]; rat astrocytes [PMID:24814386]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted, ABCA1 flagged transmembrane receptor [flag].","caveats":"Both papers read as abstracts only. The IC50 values are competition against apoA-I, not a Kd.","key_references":[{"PMID":"14754908","why":"apoE3-ABCA1 complex, competition and Tangier mutant"},{"PMID":"24814386","why":"endogenous apoE co-IP with ABCA1 in rat astrocytes"}],"covers":["LR002145","LR005462"]},"LR003621":{"pair":"APOE -> LDLR","headline":"Structural NMR/SPR work shows ApoE peptides bind LDLR repeat LR5; also database-supported; abstract read only.","interaction_type":"direct binding","direction_and_effect":"NMR and SPR showed a peptide encompassing the putative ApoE binding region binds the hydrophilic convex face of LDLR repeat LR5; complexes weakened at low Ca2+ and low pH, favouring endosomal dissociation [PMID:24447298]. Reactome and IntAct (NMR, pull down) records also list the pair [DB:Reactome] [DB:IntAct].","molecular_requirements":"Binding used the LR5 repeat alone with ApoE peptides, not intact receptor with lipoprotein; the authors suggest LDLR may use more than one repeat to bind multivalent ApoE particles [PMID:24447298].","affinity_potency":[],"species_and_systems":"In vitro with peptides and a receptor fragment; species not stated in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted [flag]; lipoprotein-associated ApoE is taken up by the receptor in the Reactome records [DB:Reactome].","caveats":"Six other papers were abstract-insufficient and one unresolvable. Evidence is peptide-level only.","key_references":[{"PMID":"24447298","why":"NMR/SPR of ApoE peptide with LDLR LR5"}],"covers":["LR000072","LR003621"]},"LR000075":{"pair":"APOE -> LRP5","headline":"Single 1998 abstract: LRP5-transduced cells bound more apoE-enriched beta-VLDL; no purified-protein binding.","interaction_type":"direct binding","direction_and_effect":"LDLR-deficient cells transduced with human LRP5 showed increased binding of apoE-enriched beta-VLDL [PMID:9832610]. LRP5 is called an apoE-recognising receptor.","molecular_requirements":"Binding was to apoE-enriched lipoprotein particles, not free apoE; LRP5 has three ligand-binding repeats [PMID:9832610].","affinity_potency":[],"species_and_systems":"Human LRP5 expressed in cells; rabbit tissue also studied [PMID:9832610]. Mouse pair is ortholog-inferred.","localisation_and_range":"LRP5 is a type I membrane protein [PMID:9832610]; ApoE flagged secreted [flag].","caveats":"Abstract only; lipoprotein-level evidence, apoE-specific contribution not isolated.","key_references":[{"PMID":"9832610","why":"LRP5 cloning and beta-VLDL binding"}],"covers":["LR000075","LR003624"]},"LR007104":{"pair":"APOE -> TREM2:TYROBP","headline":"No paper evidence for the complex; database records concern TREM2 alone.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the complex. Database records list APOE binding TREM2 alone [DB:BioGRID] [DB:IntAct] [DB:UniProt].","molecular_requirements":"TYROBP (DAP12) contribution not reported in our evidence; records name only TREM2 (Q9NZC2).","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane [flag].","caveats":"The only judged paper was classed different_entity. Support is inherited from TREM2-only records, so subunit TYROBP is unsupported here.","key_references":[],"covers":["LR007104"]},"LR002154":{"pair":"APP -> APLP1","headline":"APP-APLP1 association shown by FRET and co-IP in cis on the same membrane; a family interaction, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"APP and APLP1 formed heterotypic cis interactions (same membrane) detected by FRET and co-immunoprecipitation; coexpression with APP diminished Abeta42 generation [PMID:19126676]. Only APLP1, not APP or APLP2, also forms trans (cell-cell) interactions [PMID:19126676].","molecular_requirements":"The N-terminal half of the ectodomain is crucial for the interaction [PMID:19126676].","affinity_potency":[],"species_and_systems":"Human proteins in cell imaging [PMID:19126676]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners flagged secreted and receptor; the evidence is cis, same-membrane [flag] [PMID:19126676].","caveats":"Abstract only. Cis association is not a classical secreted ligand to receptor signalling event; direction not applicable.","key_references":[{"PMID":"19126676","why":"APP family cis interactions by FRET and co-IP"}],"covers":["LR002154","LR005469"]},"LR003630":{"pair":"APP -> FPR2","headline":"Amyloid-beta (derived from APP) activates FPR2 in chemotaxis and calcium assays; functional agonist evidence from two papers and GtoPdb.","interaction_type":"functional only","direction_and_effect":"Abeta(42) is a chemotactic agonist at FPRL1 (FPR2) [PMID:11160457]. FPR2 transfection reconstituted amyloid-beta-dependent chemotaxis and calcium flux in HEK 293 cells, while related receptors including FPR did not [PMID:11316806]. Activity was desensitised by a specific FPR2 agonist and by pertussis toxin, indicating Gi coupling [PMID:11316806]. GtoPdb lists full agonist action [DB:GtoPdb].","molecular_requirements":"Single seven-transmembrane GPCR; no co-receptor reported in our evidence. The active ligand is the Abeta peptide, not full-length APP [PMID:11160457].","affinity_potency":[],"species_and_systems":"Human mononuclear phagocytes and FPRL1-expressing cells [PMID:11160457]; HEK 293 cells and mouse neutrophils and N9 microglia, with FPR2 mRNA detected in mouse brain [PMID:11316806].","localisation_and_range":"Abeta is a secreted peptide acting on a cell-surface receptor; APP is flagged secreted, FPR2 transmembrane [flag]. Range inferred from flags only.","caveats":"Both papers read from abstracts. GtoPdb records pEC50 as the affinity unit, but no values are in our dossier [DB:GtoPdb]. One further paper was judged abstract-insufficient. For single-cell use, note the ligand activity belongs to cleaved Abeta, not APP expression itself.","key_references":[{"PMID":"11160457","why":"Abeta(42) chemotaxis through FPRL1"},{"PMID":"11316806","why":"FPR2 reconstitutes Abeta chemotaxis and calcium flux"}],"covers":["LR000081","LR003630"]},"LR002163":{"pair":"APP -> LRP6","headline":"One paper reports APP physically binding LRP6 and co-activating canonical Wnt signalling; full text read.","interaction_type":"direct binding","direction_and_effect":"APP binds LRP6 and enhances Wnt3a-driven canonical (TCF/LEF) signalling; LRP6 overexpression enhanced APP's effect on that pathway, labelled agonist/co-activator [PMID:30232325].","molecular_requirements":"LRP6 extracellular domain bound four sites in the APP extracellular domain (two in E1, two in E2) by peptide array [PMID:30232325]. A second co-receptor, Vangl2, binds APP separately [PMID:30232325].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation from primary rat cortical neurons, peptide array with recombinant human LRP6 ECD, and reporter assays in HEK293A cells [PMID:30232325]. Human and mouse pairs are both listed; the dossier's experiments are human/rat.","localisation_and_range":"APP is flagged secreted, receptor and transmembrane [flag]; the binding is described through the extracellular domains, and the paper's role for APP is as a Wnt co-receptor partner, not a classical secreted ligand [PMID:30232325].","caveats":"Single paper. The ligand/receptor direction is a database convention, since APP is itself described as interacting with a Wnt co-receptor.","key_references":[{"PMID":"30232325","why":"Co-IP, peptide-array mapping and reporter assays for APP-LRP6"}],"covers":["LR002163","LR005478"]},"LR000084":{"pair":"AREG -> EGFR","headline":"AREG binds EGFR, though more weakly than EGF; supported by two papers and several databases.","interaction_type":"direct binding","direction_and_effect":"Amphiregulin binds the EGF receptor but not as well as EGF does [PMID:2466334]. In EGFR-devoid NR6 fibroblasts, C-terminal truncation of EGFR did not affect AR binding but impaired AR mitogenic signalling [PMID:10085134]. Annotated stimulatory.","molecular_requirements":"EGFR C-terminal autophosphorylation region is needed for full AR signalling, not for binding [PMID:10085134].","affinity_potency":[],"species_and_systems":"Human amphiregulin and receptor in cell systems; NR6 fibroblasts expressing human EGFR [PMID:10085134]. Mouse pair is ortholog-inferred.","localisation_and_range":"AREG is flagged secreted and non-transmembrane [flag].","caveats":"Both papers abstract only. Binding strength is described qualitatively; no affinity reported. GtoPdb lists binding with no affinity [DB:GtoPdb].","key_references":[{"PMID":"2466334","why":"Amphiregulin binds EGF receptor, weaker than EGF"},{"PMID":"10085134","why":"AR binding unaffected by EGFR truncation"}],"covers":["LR000084","LR003633"]},"LR000093":{"pair":"ASIP -> MC5R","headline":"ASIP inhibits agonist-stimulated cAMP at human MC5R in one 1997 paper (abstract only); a relatively weak antagonist here, no affinity number in our evidence.","interaction_type":"functional only","direction_and_effect":"ASIP is an antagonist: purified recombinant ASIP inhibited agonist-stimulated cAMP generation (alpha-MSH, or ACTH for hMC2R) and also inhibited radiolabeled-melanocortin binding to hMCR1-5. At MC5R it is a relatively weak inhibitor (surmountable antagonism) [PMID:9058374].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence. Degree and mechanism of inhibition vary significantly among the five melanocortin receptor subtypes [PMID:9058374].","affinity_potency":[],"species_and_systems":"Human ASIP and human MC5R stably expressed in L cells [PMID:9058374]. Recombinant cell assays, not in vivo.","localisation_and_range":"ASIP is flagged secreted and the receptor as a transmembrane receptor [flag]; the paper calls agouti protein a paracrine signalling molecule (stated for mouse agouti) [PMID:9058374]. ","caveats":"Single paper, read as abstract only. No Kd, Ki or IC50 in our evidence, so potency is qualitative. Schild-analysis details are not available beyond the abstract-level curator note. The same paper covers all five melanocortin receptors, so this is one study counted in five pairs.","key_references":[{"PMID":"9058374","why":"Pharmacology of human ASIP at hMC1R-hMC5R: cAMP and binding inhibition"}],"covers":["LR000093"]},"LR012063":{"pair":"BAMBI -> BMPR1B:BMPR2","headline":"BAMBI to BMPR1B:BMPR2 has no verified paper; support is one BioGRID reconstituted-complex record for BMPR1B only.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are BMPR1B and BMPR2; the BioGRID record concerns BMPR1B only, one member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012063"]},"LR002172":{"pair":"BGLAP -> GPR158","headline":"Mouse genetics and a pull-down support GPR158 as a hippocampal osteocalcin receptor; human pair is ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"Osteocalcin acts on Gpr158 in CA3 hippocampal neurons; Gpr158 is identified as transducing osteocalcin's regulation of hippocampal-dependent memory in part through inositol 1,4,5-trisphosphate and brain-derived neurotrophic factor [PMID:28851741]. Biotin-labeled osteocalcin pulled down a complex with Gpr158 and Galpha-q, greatly reduced in Gpr158-/- membranes [PMID:28851741]. Osteocalcin did not increase cAMP [PMID:28851741]. Effect is agonist-like.","molecular_requirements":"Galpha-q is in the complex and IP3 production is greater in WT than Gpr158-/- neurons [PMID:28851741]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (knockout mice, hippocampal neurons and membranes); the human pair is ortholog-inferred [PMID:28851741].","localisation_and_range":"Osteocalcin has a secreted flag [flag]; acts from circulation on neurons, with local delivery into the hippocampus also tested [PMID:28851741].","caveats":"Abstract plus full-text excerpts of one paper. The pull-down is on solubilised membranes, not purified protein, so direct binding is not shown. No affinity reported.","key_references":[{"PMID":"28851741","why":"Gpr158 mediates osteocalcin's regulation of cognition in mice"}],"covers":["LR002172","LR005486"]},"LR007113":{"pair":"BMP2 -> ACVR2B:BMPR1B","headline":"Database-listed only; the one paper judged found neither BMPR1B nor ACVR2B significant for BMP signalling in primary human MSCs.","interaction_type":"conflicting","direction_and_effect":"BMPR1B and ACVR2B were expressed at low levels and not found to play a significant role in signalling by BMP-2, -4, -6 or -7 in hMSC [PMID:18436533]. GtoPdb lists BMP2 as agonist at ACVR2B and at BMPR1B separately [DB:GtoPdb].","molecular_requirements":"Not reported for this heteromer. BioGRID has BMP2-BMPR1B and ACVR2B-BMP2 reconstituted-complex records [DB:BioGRID]; PDB 2H62 is a ternary ligand-receptor complex of BMP-2 [DB:PDB 2H62].","affinity_potency":[],"species_and_systems":"Negative from human primary mesenchymal stem cells [PMID:18436533]. Other records: species not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"Negative may reflect low receptor expression rather than inability to bind [PMID:18436533]. Abstract-only read. Both chains are negative in that screen. No positive paper; support rests on databases [DB:BioGRID][DB:GtoPdb].","key_references":[{"PMID":"18436533","why":"explicit negative for BMPR1B and ACVR2B in hMSC"}],"covers":["LR007113"]},"LR000129":{"pair":"BMP4 -> BMPR1B","headline":"BMP4 binds BMPR1B (ALK-6) in cloned-receptor binding assays; three abstract-only papers, no affinity.","interaction_type":"direct binding","direction_and_effect":"A cloned receptor, CFK-43a (ALK6), specifically binds BMP-2 and BMP-4 [PMID:7811286]. BMP-4 bound ALK-3 and ALK-6 efficiently in transfected COS cells [PMID:8006002]. BMP-4 induced osteoblast differentiation through Smad1/5/8, and type I receptors acted synergistically on alkaline phosphatase induction [PMID:11282024]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Binding was enhanced by a type II co-receptor (C. elegans DAF-4) in COS cells [PMID:8006002]. BMP-4 did not bind ALK-2 (ACVR1) per the curator note [PMID:8006002].","affinity_potency":[],"species_and_systems":"Transfected COS cells [PMID:8006002]; osteoprogenitor cells [PMID:11282024]; species unspecified in the cloning paper [PMID:7811286].","localisation_and_range":"BMP4 flagged secreted [flag]; BMPR1B transmembrane status not stated.","caveats":"All three papers are abstract only; the Smad paper does not name BMPR1B in the evidence shown [PMID:11282024]. The human pair record is ortholog-inferred per the dossier. A DB BioGRID record is a reconstituted BMP4-BMPR1B complex [DB:BioGRID 282659].","key_references":[{"PMID":"7811286","why":"Cloned ALK6 receptor specifically binds BMP-4"},{"PMID":"8006002","why":"BMP-4 binds ALK-6 efficiently in COS cells"}],"covers":["LR000129","LR003678"]},"LR002181":{"pair":"BMP4 -> RGMA","headline":"BMP4 binds RGMA in SPR with Kd 14 nM, the weakest of the three RGMs for BMP4; one paper, human/human labels.","interaction_type":"direct binding","direction_and_effect":"RGMA is described as a BMP co-receptor family member and curators label the effect agonist [PMID:23029472]. In this paper, soluble RGMA.Fc inhibited BMP4 activity in a hepcidin-promoter assay (most robustly for BMP4 and BMP2), consistent with a binding and sequestering action by the fusion protein [PMID:23029472].","molecular_requirements":"Not reported in our evidence: which type I or type II receptors are needed with RGMA.","affinity_potency":[{"value":"Kd 14 nM","assay":"SPR","system":"RGMA vs BMP4, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label ligand and receptor as human; assay was SPR on recombinant proteins, with the functional assay in Hep3B hepatoma cells [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"RGMA is flagged secreted in our entity annotation [flag]; the paper does not say whether the membrane form is needed in the excerpts.","caveats":"Only the abstract was read by the curators (excerpts come from full text). RGMA had the lowest affinity among RGMs for most BMPs tested [PMID:23029472]. Effect direction 'agonist' comes from curation; the tested fusion protein inhibited BMP activity.","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP2/4/5/6/7"}],"covers":["LR002181","LR005495"]},"LR007122":{"pair":"BMP5 -> ACVR1:ACVR2A","headline":"BMP5 to ACVR1:ACVR2A rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Chains in the complex: ACVR1 and ACVR2A; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 3 review_only, 4 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007122"]},"LR007131":{"pair":"BMP6 -> ACVR1:ACVR2A","headline":"BMP6 to ACVR1:ACVR2A is supported only by database records (BioGRID, GtoPdb, UniProt), with no verified paper row.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP6 as agonist (Stimulatory) at each chain [DB:GtoPdb]. UniProt says BMP6 associates with type I receptor ACVR1 and type II receptor ACVR2B [DB:UniProt][PMID:18070108]. BioGRID has an affinity-capture-Western record of ACVR2A-BMP6 from the 1999 paper [DB:BioGRID][PMID:10504300] and a reconstituted-complex record BMP6-ACVR2A [DB:BioGRID][PMID:18070108].","molecular_requirements":"Complex of ACVR1 and ACVR2A; whether both chains are needed is not reported in our evidence. The database rows are per chain, not for this assembled complex.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence beyond the database annotations; the pair is annotated human.","localisation_and_range":"BMP6 is flagged secreted and the complex flagged transmembrane [flag].","caveats":"Three screened papers were review_only; none is a verified primary result for this complex. UniProt names ACVR2B, not ACVR2A, as the type II partner.","key_references":[],"covers":["LR007131"]},"LR000138":{"pair":"BMP6 -> BMPR2","headline":"BMP-6 binds BMPR-II less efficiently than ActR-II/IIB in one full-text paper (data not shown).","interaction_type":"direct binding","direction_and_effect":"BMP-6 bound BMPR-II, less efficiently than ActR-II and ActR-IIB; curated effect is agonist [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR2 [DB:GtoPdb].","molecular_requirements":"Type II receptors alone bound BMP-6; with type I receptors co-transfected, BMP-6 bound various type I receptors with affinities that varied by combination [PMID:10504300].","affinity_potency":[],"species_and_systems":"125I-BMP-6 (recombinant human) cross-linking in transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 lines [PMID:10504300]. Human pair not ortholog-inferred; mouse pair is.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"The BMPR-II binding result is stated as data not shown in the paper, so it is weakly documented. One more paper is pending and unused. No affinity value.","key_references":[{"PMID":"10504300","why":"BMP-6 binds BMPR-II less efficiently, data not shown"}],"covers":["LR000138","LR003687"]},"LR007140":{"pair":"BMP7 -> ACVR1:ACVR2A","headline":"Complex pair supported by database records only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP7 as agonist at ACVR1 and ACVR2A [DB:GtoPdb]. UniProt says BMP7 initiates canonical BMP signalling by associating with type I receptor ACVR1 and type II receptor ACVR2A [DB:UniProt].","molecular_requirements":"Type I ACVR1 plus type II ACVR2A are named by UniProt [DB:UniProt]. BioGRID records BMP7-ACVR2A affinity capture-western and a co-crystal structure [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"BMP7 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"No paper was judged (three review-only). The BioGRID BMP7-BMPR1B reconstituted-complex records concern a different chain.","key_references":[],"covers":["LR007140"]},"LR005502":{"pair":"BMP7 -> RGMB","headline":"BMP7 binds RGMB directly by SPR (Kd 166 nM); single abstract-level paper with full-text support, human proteins.","interaction_type":"direct binding","direction_and_effect":"Curators record the effect as agonist; the paper's abstract describes RGM proteins as co-receptors that enhance cellular responses to BMP ligands, but this paper measured binding only [PMID:23029472].","molecular_requirements":"Binding was measured for the RGM protein alone; type I/II BMP receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 166 nM","assay":"surface plasmon resonance","system":"recombinant human proteins (curator-annotated species)","cite":"PMID:23029472"}],"species_and_systems":"SPR with recombinant proteins; curators annotate both partners as human, mouse pair is ortholog-inferred [PMID:23029472].","localisation_and_range":"BMP7 is flagged secreted; RGMB is flagged not secreted [flag], and its membrane or soluble form is not stated in our evidence.","caveats":"RGMB bound BMP7 with the lowest affinity among the three RGMs [PMID:23029472]. BMP7 had the lowest relative affinity of the BMPs tested for the RGMs, and BMP7-RGM data needed CM4 sensor chips because fitting on CM5 chips was poor [PMID:23029472]. Curator read depth is abstract-only. Only one paper.","key_references":[{"PMID":"23029472","why":"SPR kinetics of all RGM-BMP pairs including BMP7"}],"covers":["LR002188","LR005502"]},"LR002190":{"pair":"BSG -> CAV1","headline":"BSG (CD147) associates with CAV1 in human cells, but the described link is intracellular glycoform regulation, not classic ligand-receptor signalling.","interaction_type":"direct binding","direction_and_effect":"Caveolin-1 associates with low-glycoform CD147 and restricts its biosynthetic conversion to the high-glycoform that self-aggregates and induces MMP production; effect on BSG is inhibitory [PMID:15201341]. Reactome lists caveolin-1 binding basigin in the Golgi membrane [DB:Reactome].","molecular_requirements":"Only the low-glycoform BSG (LG-CD147) is reported to associate; high-glycoform is the self-aggregating, MMP-inducing form [PMID:15201341].","affinity_potency":[],"species_and_systems":"Human cells; abstract-level reading [PMID:15201341]. Ortholog-inferred mouse version.","localisation_and_range":"BSG flagged transmembrane and not secreted [flag]; the interaction concerns biosynthetic trafficking, not an extracellular range.","caveats":"Association is stated as previously shown plus a new result; abstract only; no binding assay detail or affinity [PMID:15201341]. CAV1 is an intracellular scaffold, so the pair does not fit an extracellular ligand-receptor model.","key_references":[{"PMID":"15201341","why":"Caveolin-1 associates with low-glycoform CD147 and restricts glycoform conversion."}],"covers":["LR002190","LR005504"]},"LR000147":{"pair":"BTC -> ERBB2","headline":"BTC -> ERBB2 is supported only by heterodimer activation and phosphorylation papers, not by binding to ERBB2 alone.","interaction_type":"functional only","direction_and_effect":"BTC and AREG show similar affinity for EGFR/ErbB2 heterodimers and EGFR homodimers (balanced agonists), in luciferase-fragment-complementation and radioligand-binding assays [PMID:25086039]. In MIN-6 beta cells BTC induced phosphorylation of ErbB-1 and ErbB-2 [PMID:21897861].","molecular_requirements":"ErbB2 acts as a heterodimer partner of EGFR in the first paper, so activation is via the EGFR/ErbB2 heterodimer rather than ErbB2 alone [PMID:25086039]. PDB 8U4K has BTC and ERBB2 chains [DB:PDB 8U4K].","affinity_potency":[],"species_and_systems":"Human cell systems [PMID:25086039]; MIN-6 mouse beta cell line and mice [PMID:21897861].","localisation_and_range":"BTC is flagged secreted and transmembrane; ERBB2 flagged transmembrane [flag].","caveats":"Evidence is for heterodimer activity, not binding to ERBB2 alone; two further papers are pending and not shown. Abstract-level reading.","key_references":[{"PMID":"25086039","why":"BTC affinity for EGFR/ErbB2 heterodimers versus EGFR homodimers."},{"PMID":"21897861","why":"BTC induces ErbB-1 and ErbB-2 phosphorylation in beta cells."}],"covers":["LR000147","LR003696"]},"LR005511":{"pair":"C1qa -> Gpr62","headline":"Candidate C1q receptor from an unbiased pull-down screen in human neural stem cells; mouse pair is projected from human evidence.","interaction_type":"functional only","direction_and_effect":"C1q was cross-linked to membrane proteins and GPR62 was among five transmembrane candidates identified by pull-down and mass spectrometry; the proximity-ligation assay was reported to validate the C1q-GPR62 interaction and the curator labels it agonist [PMID:32894219].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were in human neural stem cells (hNSC); the mouse pair is ortholog-inferred, not tested in mouse [PMID:32894219].","localisation_and_range":"C1q is annotated secreted [flag]. Cell-surface receptor role is a candidate assignment.","caveats":"Candidate-level evidence; functional validation in the paper was for CD44 only, not for GPR62. Paper read as abstract and excerpts. ","key_references":[{"PMID":"32894219","why":"screen identifying five candidate C1q receptors in hNSC"}],"covers":["LR005511"]},"LR002217":{"pair":"C1QL3 -> ADGRB3","headline":"C1QL3 binds ADGRB3 with high affinity and forms a proposed trans-synaptic complex with NPTX1/NPTXR; two abstract-level papers, one with excerpts.","interaction_type":"direct binding","direction_and_effect":"C1ql proteins decrease synapse density in cultured neurons, blocked by the BAI3 thrombospondin-repeat fragment [PMID:21262840]. A second paper reports that C1QL3 mediates a cell-cell adhesion complex involving ADGRB3 and neuronal pentraxins NPTX1 and NPTXR [PMID:33337553].","molecular_requirements":"Binding is via the globular C1q domain to the BAI3 thrombospondin-repeat domain [PMID:21262840]. C1QL3 co-precipitated NPTX1 and NPTXR, and gC1QL3 alone bound NPTX1, so C1QL3 may be part of a larger complex [PMID:33337553].","affinity_potency":[],"species_and_systems":"Species not stated in the 2011 abstract. The 2020 study used an in vivo interactome (mass spectrometry) and cortical single-cell RNA-Seq; the species is not stated in our excerpts. BioGRID lists Affinity Capture-MS and Reconstituted Complex [DB:BioGRID]; UniProt also [DB:UniProt].","localisation_and_range":"Presynaptically secreted C1QL3, NPTX1 and NPTXR are proposed to bind postsynaptic ADGRB3 across the synapse [PMID:33337553]; flags: ligand secreted, receptor transmembrane [flag].","caveats":"The trans-synaptic complex is a suggestion ('suggest the possibility'), not demonstrated. First paper covers all four C1ql proteins together; no affinity number.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"},{"PMID":"33337553","why":"C1QL3 with NPTX1/NPTXR and ADGRB3 in a proposed trans-synaptic complex"}],"covers":["LR002217","LR005530"]},"LR000156":{"pair":"C3 -> C5AR2","headline":"C3a binds C5L2 (C5AR2) at moderate affinity in one abstract-only paper; signalling role unclear.","interaction_type":"direct binding","direction_and_effect":"C5L2 has moderate affinity for C3a, and cross-competition suggests C3a binds a site distinct from C5a [PMID:11773063]. C4a displaced C3a. Unlike CD88 and C3aR, C5L2 did not support degranulation or calcium increase, though ligation potentiated IgE-receptor degranulation [PMID:11773063].","molecular_requirements":"Single receptor chain; no co-receptor reported. Binding site distinct from C5a's [PMID:11773063].","affinity_potency":[],"species_and_systems":"Human C5L2 transfected into RBL-2H3 cells [PMID:11773063]; mouse pair is ortholog-inferred.","localisation_and_range":"C3a flagged secreted and C5AR2 transmembrane [flag].","caveats":"One paper, abstract only; no numeric affinity in our evidence. UniProt text describes C5AR2 as receptor for dearginated C3a [DB:UniProt]. C3a is a cleavage fragment of C3.","key_references":[{"PMID":"11773063","why":"C5L2 binds C3a at moderate affinity"}],"covers":["LR000156","LR003705"]},"LR005052":{"pair":"C3 -> CR2","headline":"C3d fragment binds CR2 SCR1-2; strong structural, binding and database support.","interaction_type":"direct binding","direction_and_effect":"CR2 (CD21) SCR1-2 mediate C3d binding [PMID:19164292]. CR2 isolated from B cells adhered to C3d-coated particles [PMID:6230668]. Reactome records CR2 binding C3d, C3dg, iC3b [DB:Reactome].","molecular_requirements":"SCR1 and SCR2 and the linker form the C3d surface, with distinct binding modes [PMID:19164292]. UniProt: via N-terminal Sushi 1 and 2 [DB:UniProt]. Structures exist [DB:PDB 1GHQ].","affinity_potency":[],"species_and_systems":"Human proteins: NMR with SCR1-2 [PMID:19164292], B lymphocytes and Raji cells [PMID:6230668], molecular dynamics at pH 7.4, 6.0 and 5.0 [PMID:30566277]. Mouse pair is ortholog-inferred.","localisation_and_range":"CR2 is flagged transmembrane [flag]: contact-dependent on B cells.","caveats":"All papers abstract only. Ligand is the C3d fragment, not intact C3. The NMR surface disagrees with a prior crystal structure [PMID:19164292]. Binding is pH dependent in simulation [PMID:30566277].","key_references":[{"PMID":"19164292","why":"NMR mapping of C3d site on CR2"},{"PMID":"6230668","why":"Identification of CR2 as C3d receptor on B cells"},{"PMID":"30566277","why":"pH effects on C3d-CR2, simulation"}],"covers":["LR001675","LR005052"]},"LR003711":{"pair":"C4bp -> Cd40","headline":"Mouse pair inferred from human data: human C4BP alpha chain binds CD40 and activates B cells.","interaction_type":"direct binding","direction_and_effect":"The alpha chain of human C4BP binds directly to CD40 on human B cells at a site different from CD40 ligand and acts as an agonist, inducing proliferation, CD54/CD86 upregulation and IL-4-dependent IgE switching [PMID:12818164].","molecular_requirements":"Alpha chain of C4BP; response was lost in B cells from CD40 or IKKgamma/NEMO deficient patients [PMID:12818164].","affinity_potency":[],"species_and_systems":"All experiments used human proteins and human B cells; the mouse pair is ortholog-inferred and no mouse experiments are reported in our evidence [PMID:12818164].","localisation_and_range":"C4bp is flagged secreted; Cd40 flagged receptor [flag]. C4BP colocalised with B cells in human tonsil germinal centres [PMID:12818164].","caveats":"Abstract only. Mouse relevance rests on orthology. No affinity reported.","key_references":[{"PMID":"12818164","why":"Direct C4BP alpha-chain binding to CD40 and B-cell activation"}],"covers":["LR003711"]},"LR000165":{"pair":"C4BPA -> LRP1","headline":"C4BP alpha chains bind LRP1 by SPR; LRP1 acts as a clearance receptor.","interaction_type":"direct binding","direction_and_effect":"Plasma C4BP and recombinant alpha-chain C4BP bound immobilized LRP; binding was inhibited by RAP, heparin and antibody RU-3B9 against the heparin-binding region [PMID:11705989]. LRP1 mediates catabolism, not signalling [PMID:11705989].","molecular_requirements":"Alpha chains alone suffice; LRP clusters II and IV both bind [PMID:11705989].","affinity_potency":[],"species_and_systems":"Human proteins and human-derived cells in SPR/degradation; mouse clearance was delayed with RAP co-injection [PMID:11705989].","localisation_and_range":"Not reported beyond flags: C4BPA secreted [flag].","caveats":"Abstract only; no affinity values in our evidence. LRP-deficient fibroblasts degraded 4-fold less 125I-rC4BPalpha [PMID:11705989].","key_references":[{"PMID":"11705989","why":"SPR, degradation and clearance assays"}],"covers":["LR000165"]},"LR002226":{"pair":"CADM1 -> CADM2","headline":"CADM1 interacts with CADM2 by SPR imaging in one full-text paper; no other direct evidence.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc injected on a chip with immobilized IgSF-Fc proteins showed interaction with CADM2 [PMID:30131958]. Effect direction is not reported in our evidence.","molecular_requirements":"CADM1 and CADM2 extracellular Fc fusion proteins [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human recombinant extracellular proteins in a cell-free SPRi platform [PMID:30131958]. The mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged non-secreted; CADM1 transmembrane [flag]; suggests contact-dependent adhesion.","caveats":"Single paper; the specific kinetics for CADM2 are not reported in our excerpts. Reactome records cover Necl transhomodimerization, not this heterophilic pair [DB:Reactome].","key_references":[{"PMID":"30131958","why":"SPRi shows CADM1-CADM2 interaction"}],"covers":["LR002226","LR005536"]},"LR005061":{"pair":"CADM3 -> NECTIN3","headline":"Heterophilic CADM3-nectin-3 adhesion shown in cell-aggregation assay; one abstract-level paper plus Reactome.","interaction_type":"functional only","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with nectin-3, but not nectin-2 or Necl-5 [PMID:15741237]. Reactome lists a Necl-1:Nectin-3 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell-aggregation assays; abstract only, human-labelled [PMID:15741237]. Human pair is ortholog-inferred; mouse is not.","localisation_and_range":"Membrane-bound [flag]; Necl-1 is neural-specific at axon-glia contact sites [PMID:15741237]. Contact-dependent.","caveats":"Abstract only; one review-only row not shown. No affinity reported.","key_references":[{"PMID":"15741237","why":"Necl-1 heterophilic adhesion with nectin-3"}],"covers":["LR001685","LR005061"]},"LR002235":{"pair":"CADM4 -> CADM2","headline":"CADM4 and CADM2 interact by SPRi (family-wide screen); direct binding, one paper, no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi of CADM2-Fc, CADM3-Fc and CADM4-Fc detected homophilic and heterophilic interactions with all CADM family proteins [PMID:30131958]. No functional effect or direction is reported for this pair.","molecular_requirements":"SPRi only detects direct interactions between two molecules; no accessory protein needed in this assay [PMID:30131958].","affinity_potency":[],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"CADM2 transmembrane status is not flagged; CADM4 is flagged transmembrane [flag]. The paper describes CADM family adhesion between cells [PMID:30131958].","caveats":"Support is a family-level statement from one paper; the tabulated Kd values are for CADM1 and are not for this pair [PMID:30131958]. Affinity for CADM4-CADM2 not reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002235","LR005545"]},"LR000174":{"pair":"CALCB -> CALCR","headline":"beta-CGRP to calcitonin receptor rests only on GtoPdb agonist records; no paper in our evidence supports it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists beta-CGRP as agonist of CALCR, with one record giving full agonist and pEC50 without a value [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence. The receptor entity is annotated as AMY1 receptor [flag], suggesting a RAMP1-containing complex, but no paper here tests this.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"No curator-confirmed papers: all judged rows were different_entity, abstract_insufficient or review_only. Treat as database-only.","key_references":[],"covers":["LR000174","LR003719"]},"LR003720":{"pair":"CALCB -> CALCRL","headline":"beta-CGRP acts through CALCRL in complex with RAMP1; support is functional and from GtoPdb, with CALCRL alone not sufficient.","interaction_type":"functional only","direction_and_effect":"CALCRL associated predominantly with RAMP1 to form a CALCB receptor in rat uterine artery smooth muscle cells, and only minimally with RAMP2 or RAMP3; CALCB increased ERK1/2 phosphorylation and reversed TNF-alpha-induced loss of CALCRL/RAMP1 association [PMID:27784654]. CRLR acts as a CGRP receptor when paired with RAMP1 [PMID:9620797]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"CALCRL needs a RAMP; RAMP1 gives the CGRP receptor, RAMP2 an adrenomedullin receptor [PMID:9620797][PMID:27784654]. CALCRL alone is not a CGRP receptor in this evidence.","affinity_potency":[{"value":"pKi 7.3 to 7.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"},{"value":"pIC50 7.0 to 7.5","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat uterine artery smooth muscle cells with proximity ligation assay [PMID:27784654]; [PMID:9620797] used transfected mammalian cells, species unspecified. Mouse and human pairs are projected from other evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Both papers read as abstracts (the first with full-text excerpts). Experimental species is rat, not human, although the curator table says human [PMID:27784654]. [PMID:9620797] does not name CALCB specifically, only CGRP.","key_references":[{"PMID":"27784654","why":"CALCB with CALCRL/RAMP1 in rat uterine artery cells"},{"PMID":"9620797","why":"RAMP1 makes CRLR a CGRP receptor"}],"covers":["LR000175","LR003720"]},"LR002244":{"pair":"CBLN1 -> NRXN2","headline":"One paper identifies NRXN2 as the receptor mediating CBLN1 axon growth and guidance in embryos.","interaction_type":"functional only","direction_and_effect":"Cbln1 functions as a growth and guidance cue; these functions are mediated by neurexin-2, described as the Cbln1 receptor for axon growth and guidance [PMID:36395107]. Cbln1 acts in an autocrine manner and as an attractive cue.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse and chick embryos, including commissural neurons [PMID:36395107]. The pair is ortholog-inferred in both human and mouse.","localisation_and_range":"CBLN1 is flagged secreted and NRXN2 transmembrane [flag]; the paper says Cbln1 is expressed on axons and growth cones and in intermediate targets [PMID:36395107].","caveats":"Functional only; no binding measurement is reported in our evidence. The curator's full-text read gave only discussion text. A second confirmed paper was not shown.","key_references":[{"PMID":"36395107","why":"Cbln1 axon growth and guidance mediated by Nrxn2"}],"covers":["LR002244","LR005554"]},"LR002253":{"pair":"CCL11 -> ACKR1","headline":"Direct strong binding of CCL11 to human Duffy antigen (ACKR1) on erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CCL11 binds Duffy on red blood cells; effect on signalling or scavenging is not reported in our evidence [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 67.3 nM","assay":"radioligand displacement","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes [PMID:15358176]. Mouse pair is projected from human evidence.","localisation_and_range":"CCL11 flagged secreted, ACKR1 transmembrane [flag].","caveats":"Ki < 100 nM is the paper's strong-binding class [PMID:15358176]. Single paper.","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of the Duffy antigen"}],"covers":["LR002253","LR005562"]},"LR000183":{"pair":"CCL11 -> ACKR4","headline":"CCL11 (eotaxin) competes for binding to ACKR4 (reported as CCR11) at low-nM IC50; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Eotaxin bound the receptor with greater affinity than MCP-1 but acted as an agonist in chemotaxis assays only at 100-fold higher concentrations [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 = 6.7 nM","assay":"competition binding against radiolabeled MCP-4","system":"receptor transfected into murine L1.2 cells","cite":"PMID:10734104"}],"species_and_systems":"Human receptor expressed in mouse L1.2 cells [PMID:10734104]. Mouse pair is projected.","localisation_and_range":"CCL11 flagged secreted, ACKR4 transmembrane [flag].","caveats":"Abstract only. The paper named the receptor CCR11 and framed it as a functional chemotactic receptor [PMID:10734104].","key_references":[{"PMID":"10734104","why":"Competition binding and chemotaxis for the MCP-family receptor"}],"covers":["LR000183","LR003728"]},"LR000192":{"pair":"CCL13 -> CCR5","headline":"MCP-4 (CCL13) binds CCR5 with high affinity but is a weak functional agonist; two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"MCP-4 bound CCR5 with high affinity and was displaced by other CCR5 ligands, but only partially displaced MIP-1alpha and induced chemotaxis only at high concentrations [PMID:9790730]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 9.1","assay":"binding","system":"CCR5, human","cite":"PMID:9790730"},{"value":"IC50 5.89 nmol/L","assay":"[125I]-MIP-1beta competition binding","system":"CCR5-expressing stable cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor [PMID:9790730][PMID:10477718].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Functional agonism is weak/partial per the first paper, conflicting with GtoPdb's full-agonist label. Abstract-only; the IC50 list sentence does not name the ligand.","key_references":[{"PMID":"9790730","why":"MCP-4 binds CCR5 with high affinity, weak chemotaxis"},{"PMID":"10477718","why":"CCR5 competition binding panel"}],"covers":["LR000192"]},"LR000237":{"pair":"CCL2 -> CCR3","headline":"Direct but lower-affinity binding and agonism of CCL2 at CCR3, from two papers.","interaction_type":"conflicting","direction_and_effect":"Cells expressing CCR3 were activated by MCP-1, which the paper calls an agonist of CCR3 [PMID:15207250]. In the earlier paper CC CKR3 bound MCP-1 with lower affinity than eotaxin, MCP-3 and RANTES, but MCP-1 and other chemokines did not activate the Ca2+ flux, in contrast with eotaxin, RANTES and MCP-3 [PMID:8642344].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 7.2-7.8","assay":"GtoPdb record","system":"not specified","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor; high-expression CHO-CCR3 cells [PMID:15207250] and AML14.3D10 cells [PMID:8642344]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"The two papers conflict on activation: one reports agonism, the other no Ca2+ flux from MCP-1. Paper 15207250 abstract only; 8642344 full text. BioGRID and GtoPdb records cite the earlier paper [DB:BioGRID][DB:GtoPdb].","key_references":[{"PMID":"8642344","why":"CC CKR3 binds MCP-1 with lower affinity"},{"PMID":"15207250","why":"CHO-CCR3 line; MCP-1 agonist of CCR3"}],"covers":["LR000237","LR003758"]},"LR000219":{"pair":"CCL23 -> CCR1","headline":"CCL23 binds and activates CCR1; several binding and calcium/GTPgammaS studies in human cells agree, though CCR1 is promiscuous.","interaction_type":"direct binding","direction_and_effect":"Agonist: CCL23 (MPIF-1) induced calcium flux in CCR1-transfected HEK-293 cells, monocytes and dendritic cells, but not in CCR5-, CCR8- or CX3CR1-transfected cells [PMID:9886417]. Both CKbeta8 forms were potent CCR1 agonists [PMID:9558365]. A panel including MPIF-1 showed full agonism in [35S]-GTPgammaS exchange except MCP-2 [PMID:12381680].","molecular_requirements":"CCR1 alone in transfected cells was sufficient [PMID:10660125][PMID:9886417]. Truncated forms differ: CKbeta8 (25-99) is more potent than the longer variants [PMID:10660125].","affinity_potency":[{"value":"IC50 0.22 nM","assay":"displacement of 125I-CKbeta8 (25-99) by CKbeta8 (25-99)","system":"CHO cells expressing human CCR1","cite":"PMID:10660125"},{"value":"IC50 6.5 nM and 16 nM","assay":"displacement by CKbeta8 (24-99) and (1-99)","system":"CHO cells expressing human CCR1","cite":"PMID:10660125"},{"value":"pKi 8.9","assay":"125I-MIP-1alpha displacement, curated affinity for this pair","system":"Ba/F3-hCCR1 membranes","cite":"PMID:12381680"}],"species_and_systems":"Human ligand and receptor throughout: CHO, HEK-293 and Ba/F3 transfectants plus human monocytes and dendritic cells [PMID:10660125][PMID:9886417][PMID:12381680].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; paracrine.","caveats":"CCR1 is described as promiscuous, so binding is not specific to CCL23 [PMID:12381680]. All papers read as abstracts only. Which panel member the pKi belongs to is taken from the curated row, not the abstract text.","key_references":[{"PMID":"10660125","why":"Binding displacement shows CCR1 is the CKbeta8 receptor"},{"PMID":"9886417","why":"MPIF-1 calcium agonist on CCR1 but not CCR5/CCR8/CX3CR1"},{"PMID":"12381680","why":"Binding and GTPgammaS panel on CCR1"}],"covers":["LR000219"]},"LR002262":{"pair":"CCL26 -> CX3CR1","headline":"CCL26 is a weak, species-selective agonist of human CX3CR1, with binding competition and functional data.","interaction_type":"direct binding","direction_and_effect":"Agonist: at relatively high concentrations CCL26 induced calcium flux and chemotaxis in L1.2 cells expressing human CX3CR1 and competed with CX3CL1 for binding [PMID:20974991]. CCL26 attracted human NK cells and monocytes and recruited human NK cells in mice [PMID:20974991]. A 2023 study reports CX3CR1+ macrophages activated by epithelial CCL26 via receptor-ligand interaction [PMID:36790376].","molecular_requirements":"CX3CR1 alone was sufficient in transfectants [PMID:20974991].","affinity_potency":[],"species_and_systems":"Mouse L1.2 cells expressing human CX3CR1 responded, but not those with mouse CX3CR1 [PMID:20974991]. The 2023 study used human and mouse allergic lung models; species of the interaction assay is not specified [PMID:36790376].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"Activity needs relatively high concentrations and is species-selective [PMID:20974991]. Abstracts only; PMID 36790376 curator sentence is an abstract-level statement.","key_references":[{"PMID":"20974991","why":"Calcium, chemotaxis and competition on CX3CR1"},{"PMID":"36790376","why":"Macrophage activation by CCL26 in allergic lung models"}],"covers":["LR002262"]},"LR000228":{"pair":"CCL27 -> CCR10","headline":"CCL27 is a CCR10 agonist, supported by transfectant assays and in vivo skin neutralisation.","interaction_type":"functional only","direction_and_effect":"Agonist: CCL27 induced migration and calcium flux in GPR2/CCR10 transfectants [PMID:10725696][PMID:10725697]. In vivo, intracutaneous CCL27 attracted lymphocytes and neutralising CCL27-CCR10 interactions impaired lymphocyte recruitment and suppressed allergen-induced skin inflammation [PMID:11821900].","molecular_requirements":"CCR10 alone in L1.2 transfectants was sufficient [PMID:10725696].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in transfected cells and human skin samples [PMID:10725697][PMID:11821900]; in vivo neutralisation setting species not stated in our evidence.","localisation_and_range":"Secreted ligand flag [flag]; CCL27 is produced by keratinocytes, bound extracellular matrix and was displayed on dermal endothelial cells [PMID:10725697][PMID:11821900].","caveats":"No affinity values in our evidence. Abstracts only. Reactome and GtoPdb agree [DB:Reactome][DB:GtoPdb].","key_references":[{"PMID":"10725697","why":"CCL27 binds GPR-2, renamed CCR10"},{"PMID":"10725696","why":"GPR2 as receptor for ESkine"},{"PMID":"11821900","why":"In vivo skin T cell recruitment via CCL27-CCR10"}],"covers":["LR000228"]},"LR000246":{"pair":"CCL3 -> CCR1","headline":"CCL3 (MIP-1alpha) is a well-supported full agonist of CCR1 with binding, photo-crosslinking and functional data in human systems.","interaction_type":"direct binding","direction_and_effect":"CCL3 acts as a full agonist at human CCR1, stimulating [35S]-GTPgammaS exchange in a CCR1-transfected cell line [PMID:12381680]; GtoPdb also lists full agonist [DB:GtoPdb]. A modified MIP-1alpha analogue was covalently cross-linked to CCR1 in CHO cells [PMID:11170631]. In human neutrophils CCR1 mediates responses to MIP-1 alpha, with a negligible calcium flux and chemotaxis response [PMID:10202040].","molecular_requirements":"CCR1 alone in transfected cells is sufficient for binding and signalling [PMID:12381680][PMID:11170631]. Other subunits: not reported in our evidence.","affinity_potency":[{"value":"Kd 3.2 nM","assay":"Scatchard analysis, hMIP-1 alpha on neutrophils","system":"human neutrophils","cite":"PMID:10202040"},{"value":"pKi 7.8 to 10.2","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human proteins in CHO, Ba/F3 and HEK293 transfectants and human neutrophils [PMID:12381680][PMID:11170631][PMID:10202040].","localisation_and_range":"CCL3 is flagged as secreted and CCR1 as transmembrane [flag].","caveats":"Most papers were read as abstracts only. Several are about other ligands that include MIP-1alpha only as comparator or radioligand [PMID:10660125][PMID:7545673][PMID:8530354][PMID:9624164]. In neutrophils MIP-1 alpha induced only negligible calcium flux and chemotaxis [PMID:10202040]. No mouse data in our evidence.","key_references":[{"PMID":"12381680","why":"Binding and full agonism of MIP-1alpha at hCCR1"},{"PMID":"11170631","why":"Photoaffinity cross-linking of MIP-1alpha analogue to CCR1"},{"PMID":"10202040","why":"Kd of MIP-1 alpha on human neutrophils via CCR1"}],"covers":["LR000246"]},"LR000255":{"pair":"CCL5 -> ACKR2","headline":"CCL5 binds human D6/ACKR2 in competition binding; ACKR2 is a non-signalling scavenger receptor.","interaction_type":"direct binding","direction_and_effect":"Human D6 (ACKR2) bound RANTES in ligand displacement on CHO cells [PMID:9405404]. D6 is promiscuous for beta-chemokines and, per the abstract, does not appear to flux calcium on ligand binding [PMID:9405404]. Unlabeled CCL5 reduced CCL2 uptake in HEK-ACKR2 cells and trophoblasts, consistent with scavenging [PMID:25297873].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 in stably transfected CHO cells with 125I-labeled murine MIP-1a tracer [PMID:9405404]; HEK-ACKR2 cells and primary trophoblasts [PMID:25297873]. The mouse pair is inferred from human evidence.","localisation_and_range":"ACKR2 is transmembrane [flag]; chemokine is taken up and not signalled through (curator notes) [PMID:25297873].","caveats":"BioGRID and UniProt also list CCL5 [DB:BioGRID, DB:UniProt]. PMID:25297873 was read via browser; the quote is unverified. PMID:9405404 lacks a CCL5 affinity value in our evidence.","key_references":[{"PMID":"9405404","why":"Human D6 binds RANTES; displacement assay"},{"PMID":"25297873","why":"CCL5 competes for ACKR2-mediated CCL2 uptake"}],"covers":["LR000255","LR003765"]},"LR000264":{"pair":"CCL7 -> ACKR2","headline":"Human ACKR2 (D6) binds MCP-3 (CCL7) in competition binding on CHO cells; no affinity value and no calcium signalling in our evidence.","interaction_type":"direct binding","direction_and_effect":"Human D6 binds many CC chemokines; the full text states binding is seen with RANTES, MCP3, MCP4 and HCC1 [PMID:9405404]. D6 did not flux calcium after ligand binding, so signalling is unclear [PMID:9405404]. BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt lists CCL7 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 stably expressed in CHO cells, 125I-MIP-1a tracer [PMID:9405404].","localisation_and_range":"CCL7 flagged secreted; ACKR2 flagged transmembrane receptor [flag].","caveats":"No affinity reported for MCP-3 specifically. Promiscuous binder, so specificity for CCL7 is low. A second confirmed row cites PMID:9364936, which is about CCR10, not ACKR2.","key_references":[{"PMID":"9405404","why":"D6/ACKR2 promiscuous CC chemokine binding including MCP3"}],"covers":["LR000264","LR003774"]},"LR000273":{"pair":"CCL8 -> ACKR4","headline":"One paper reports MCP-2 (curator-mapped to CCL8) binding the receptor called CCR11 (ACKR4) with IC50 0.45 nM; interpretation is contested.","interaction_type":"direct binding","direction_and_effect":"MCP-2 was the second most potent competitor of radiolabelled MCP-4 binding (IC50 0.45 nM) and MCP-2 induced chemotaxis of L1.2 cells expressing the receptor [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 0.45 nM","assay":"competition vs radiolabelled MCP-4","system":"receptor-transfected murine L1.2 cells (human receptor)","cite":"PMID:10734104"}],"species_and_systems":"Human ligand and receptor expressed in murine L1.2 cells [PMID:10734104]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL8 flagged secreted; ACKR4 flagged transmembrane receptor [flag].","caveats":"Abstract only. Curator notes say the accepted ACKR4 ligands differ, so MCP-family claims were not upheld. Equating MCP-2 with CCL8 is the curators' mapping, not stated in the dossier. No database records.","key_references":[{"PMID":"10734104","why":"MCP-2 binds CCR11/ACKR4, IC50 0.45 nM"}],"covers":["LR000273","LR003783"]},"LR002271":{"pair":"CCN2 -> EGFR","headline":"CCN2 binds the EGFR extracellular domain by SPR and activates EGFR signalling; evidence is abstract-level from one paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports CCN2 as a novel EGFR ligand with agonist effect: its C-terminal module (CCN2-IV) increased renal EGFR phosphorylation in mice, and EGFR kinase inhibition reduced CCN2-IV-induced ERK activation and inflammation [PMID:23929714].","molecular_requirements":"The EGFR-binding site was localised to the C-terminal module (CCN2-IV) [PMID:23929714]. EGFR/TrkA crosstalk occurred after CCN2-IV stimulation, and CCN2 blockade inhibited TGF-beta-induced EGFR activation [PMID:23929714].","affinity_potency":[],"species_and_systems":"SPR with soluble EGFR extracellular domain; in vivo injection in mice; cultured tubular epithelial cells (species not specified in the abstract) [PMID:23929714]. BioGRID also lists affinity-capture Western records [DB:BioGRID].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Binding was shown for the C-terminal module; full-length affinity is not reported in our evidence. BioGRID support is Affinity Capture-Western from PMID 23175185 [DB:BioGRID].","key_references":[{"PMID":"23929714","why":"SPR binding of CCN2 to EGFR plus in vivo and cell signalling"}],"covers":["LR002271","LR005572"]},"LR002280":{"pair":"CCN3 -> ITGB3","headline":"CCN3 binds integrin alphavbeta3 directly (half-maximal binding 10 nM); beta3 evidence via the alphavbeta3 heterodimer.","interaction_type":"direct binding","direction_and_effect":"CCN3 is an agonist, supporting HUVEC adhesion and migration through alphavbeta3 [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522].","molecular_requirements":"The receptor is the alphavbeta3 heterodimer (UniProt: ITGAV:ITGB3 interacts with CCN3) [DB:UniProt][PMID:12695522]. Whether the beta3 chain alone suffices is not reported in our evidence.","affinity_potency":[{"value":"10 nM","assay":"half-maximal binding (EC50) to alphavbeta3, solid-phase ELISA","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"The 10 nM value is for the alphavbeta3 heterodimer, not ITGB3 alone. Single primary paper; UniProt and GtoPdb cite it [DB:UniProt][DB:GtoPdb].","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002280","LR005581"]},"LR005070":{"pair":"CCN4 -> ITGB1","headline":"Functional evidence only: CCN4-driven fibroblast migration depends on alpha5beta1 integrin; direct ITGB1 binding not shown.","interaction_type":"functional only","direction_and_effect":"CCN4-induced migration of dermal fibroblasts appears to work via alpha5beta1 integrin receptors, further stimulating ERK/JNK signalling; the dossier labels CCN4 an agonist [PMID:29330021].","molecular_requirements":"The paper implicates the alpha5beta1 integrin heterodimer; whether one chain alone suffices is not reported in our evidence. Both ITGA5 and ITGB1 pairs rest on the same single paper [PMID:29330021].","affinity_potency":[],"species_and_systems":"Human adult dermal fibroblasts (siRNA knockdown or adenoviral CCN4) and Ccn4-knockout mouse dermal fibroblasts and wounds [PMID:29330021].","localisation_and_range":"CCN4 is flagged secreted and the integrin as a receptor [flag]; matrix-associated paracrine action is plausible but not stated in our evidence.","caveats":"No binding assay is reported; the link to the integrin is inferred from migration experiments, and the paper was read mainly as abstract plus excerpts. No database record supports this pair. The integrin subunit is a chain of a heterodimer.","key_references":[{"PMID":"29330021","why":"CCN4 wound healing via alpha5beta1 in dermal fibroblasts"}],"covers":["LR001701","LR005070"]},"LR001704":{"pair":"CD1D -> LILRB2","headline":"One abstract-read paper shows ILT4 (LILRB2) as an inhibitory CD1d receptor in human monocytes; thin evidence.","interaction_type":"direct binding","direction_and_effect":"ILT4 (LILRB2) binds CD1d and inhibits CD1d-mediated immune responses by blocking lipid antigen loading, reducing NKT recognition (labelled antagonist) [PMID:19124746].","molecular_requirements":"Interaction mapped to the two N-terminal domains of ILT4 and the CD1d alpha1/alpha2 antigen-binding groove; CD1d tetramers recognised ILT4- but not ILT2-transfected HEK293T cells [PMID:19124746].","affinity_potency":[],"species_and_systems":"Human monocytes and HEK293T transfectants [PMID:19124746].","localisation_and_range":"Interaction occurs at the cell surface and in endosomal/lysosomal compartments, so it is cell-contact or intracellular [PMID:19124746].","caveats":"Single paper, read as abstract only (with full text excerpts). IntAct holds one solid-phase record [DB:IntAct]. No affinity reported. Direction is CD1d acting on ILT4, and the effect is inhibitory.","key_references":[{"PMID":"19124746","why":"ILT4 identified as human CD1d receptor"}],"covers":["LR001704"]},"LR001713":{"pair":"CD274 -> CD80","headline":"PD-L1 binds CD80 (B7-1) with intermediate affinity, with multiple direct-binding papers and an in vivo mouse study of trans interactions.","interaction_type":"direct binding","direction_and_effect":"B7-1 and PD-L1 interacted and the interaction inhibited T cell activation and cytokine production, a bidirectional inhibitory interaction [PMID:17629517]. Human B7-1 interacts with human PD-L1 with affinity greater than B7-1:CD28 but less than B7-1:CTLA-4 or PD-L1:PD-1 [PMID:18585785]. In mice, blocking PD-L1/CD80 interactions augmented antitumour CD8 T cell immunity [PMID:37036990].","molecular_requirements":"The PD-L1:B7-1 interface overlaps with the B7-1:CTLA-4 and PD-L1:PD-1 interfaces [PMID:17629517]. Trans effects between tumour and T cells required tumour MHC-I and T cell CD28 [PMID:37036990]. UniProt notes the interaction blocks PD-L1/PD-1 binding [DB:UniProt]. PDB 7TPS has a structure [DB:PDB 7TPS].","affinity_potency":[],"species_and_systems":"Human recombinant and cell assays [PMID:17629517][PMID:18585785][PMID:20587542]; mouse tumour models (MC38, B16 in C57BL/6) [PMID:37036990].","localisation_and_range":"Both flagged membrane-bound and also secreted [flag]. Cis and trans configurations are discussed: earlier reports found only cis interactions, while this study reports that trans interactions between tumour and T cells exist [PMID:37036990].","caveats":"Three papers are abstract-only. No numeric affinity in our evidence. Cis and trans PD-L1/CD80 interactions may have opposite effects on antitumour immunity [PMID:37036990].","key_references":[{"PMID":"17629517","why":"First report of PD-L1:B7-1 binding and inhibitory function"},{"PMID":"18585785","why":"Human B7-1 and PD-L1 affinity ranking, blocking antibodies"},{"PMID":"37036990","why":"Trans PD-L1/CD80 in vivo; blockade augments antitumour immunity"}],"covers":["LR001713","LR005080"]},"LR000282":{"pair":"CD34 -> SELL","headline":"CD34 as an L-selectin ligand is supported by several abstract-only papers, but the strongest direct data are on a mouse lymph-node glycoform.","interaction_type":"direct binding","direction_and_effect":"Sgp90 from high endothelial venules has a protein core identical to CD34, and an HEV glycoform of CD34 can function as an L-selectin ligand [PMID:7692600]. Neutrophils tethered and rolled on CD34 at comparable site density to E- and P-selectin, rolling 7.5- to 10.5-fold faster on CD34 [PMID:8977216]. Interaction annotated stimulatory [flag].","molecular_requirements":"Sulfated carbohydrate structures (6-sulfo-sLex) on the mucin domain are described as the recognition determinant, but this is background in [PMID:12889478], not tested there.","affinity_potency":[],"species_and_systems":"Murine CD34 antiserum and lymph-node endothelium in [PMID:7692600]; human neutrophils/lymphocytes in flow assays [PMID:8977216]. Mouse interaction listed as not ortholog-inferred.","localisation_and_range":"CD34 flagged transmembrane, not secreted [flag]; mediates leukocyte-endothelium contact and rolling.","caveats":"All papers abstract only. [PMID:12889478] concerns endoglycan and cites CD34 only as background. [PMID:8977216] is a rolling-adhesion measurement, not a binding assay. No affinity reported.","key_references":[{"PMID":"7692600","why":"HEV glycoform of CD34 functions as L-selectin ligand"},{"PMID":"8977216","why":"Neutrophil rolling on CD34 versus E-/P-selectin"}],"covers":["LR000282","LR003792"]},"LR001722":{"pair":"CD48 -> CD2","headline":"Cell-surface adhesion pair supported by force measurements, a cell-binding assay and curated database records; binding is low-affinity.","interaction_type":"direct binding","direction_and_effect":"CD48 is a ligand of CD2 and the bond mediates adhesion; the CD48 interaction with the T11(1) region of CD2 was reported to be the same region that binds CD58, and CD48 binds CD2 with about 100-fold lower affinity than CD58 [PMID:7691954]. Direct force measurements describe a low-affinity bond that gives weak adhesion [PMID:12356317].","molecular_requirements":"Full-length extracellular domains adhere head-to-head; lateral receptor mobility is required for appreciable adhesion [PMID:12356317]. Extra evidence: an engineered CD2 showed about threefold higher CD48-binding affinity than wild type [PMID:18287277].","affinity_potency":[],"species_and_systems":"Force measurements used murine CD2 and CD48 [PMID:12356317]. Cell binding used human PBL and human CD48-transfected COS cells, with multimeric rCD2 binding CD48 transfectants [PMID:7691954]. The human pair is ortholog-inferred in the dossier; the mouse pair is listed directly.","localisation_and_range":"Both are cell-surface proteins; adhesion is between cells (contact-dependent) [PMID:12356317][PMID:7691954]. Annotation flags mark CD48 as both secreted and transmembrane, so the flag does not settle range [flag].","caveats":"All three confirming papers were read as abstracts only. No numeric affinity is given. The PMID 18287277 result is a protein-engineering paper that uses wild-type CD2-CD48 binding only as the baseline. A BioGRID record (reconstituted complex) and UniProt text also support the pair [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"7691954","why":"Human cell binding plus blocking mAbs; CD48 and CD58 compete for CD2"},{"PMID":"12356317","why":"Direct force measurement of murine CD2-CD48 adhesion"}],"covers":["LR001722","LR005089"]},"LR001731":{"pair":"CD84 -> CD84","headline":"CD84 binds itself (homophilic) according to a 2001 binding study and database records.","interaction_type":"direct binding","direction_and_effect":"CD84-Ig bound CD84-transfected cells and no other CD2-subfamily receptor, showing CD84 binds itself [PMID:11564780]. Concurrent ligation of CD84 with CD3 enhanced IFN-gamma secretion, a costimulatory effect [PMID:11564780].","molecular_requirements":"Only the first extracellular domain is involved, shown with human/mouse chimeras, and the interaction was independent of the cytoplasmic tail [PMID:11564780].","affinity_potency":[],"species_and_systems":"Human CD84-Ig and transfected cells and platelets [PMID:11564780]; mouse pair ortholog-inferred. Reactome lists CD84 homodimerisation [DB:Reactome] and BioGRID/IntAct list reconstituted-complex and cosedimentation records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Cell-surface homophilic contact between cells; flags show secreted and receptor annotations [flag].","caveats":"One paper read as abstract only; no affinity in our evidence. Since both partners are the same protein, direction is not meaningful.","key_references":[{"PMID":"11564780","why":"CD84-Ig binds CD84 transfectants; first domain mediates binding"}],"covers":["LR001731","LR005096"]},"LR005601":{"pair":"CDH1 -> ITGB1","headline":"E-cadherin binds integrin alpha2beta1 in vitro; one abstract-level paper, binding looks direct but is untested for beta1 alone.","interaction_type":"direct binding","direction_and_effect":"Pentameric E-cadherin specifically bound purified alpha2beta1 and the recombinant alpha2 A-domain in a divalent cation-dependent manner; HT1080 adhesion to E-cadherin was blocked by anti-alpha2 and anti-beta1 antibodies [PMID:12392763].","molecular_requirements":"The alpha2beta1 heterodimer is the binding unit: binding mapped to the alpha2 A-domain, and antibodies to other subunits did not block [PMID:12392763]. ITGB1 alone is not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Solid-phase binding with purified protein and cell adhesion assays; species not stated in our evidence for the experiments. The mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane proteins (E-cadherin flagged transmembrane), so contact-dependent [flag].","caveats":"Abstract-only read. The pentameric construct was designed to detect low-affinity interaction; monomeric E-cadherin did not bind, which the curator treats as an avidity control [PMID:12392763]. No affinity reported.","key_references":[{"PMID":"12392763","why":"Binding of E-cadherin to alpha2beta1 and alpha2 A-domain"}],"covers":["LR002303","LR005601"]},"LR000291":{"pair":"CDH1 -> ITGB7","headline":"E-cadherin is a direct ligand of integrin alphaEbeta7, supported by binding assays, mutagenesis and curated database records.","interaction_type":"direct binding","direction_and_effect":"Human E-cadherin-Fc bound directly to soluble recombinant alphaEbeta7 and to alphaEbeta7 from intraepithelial T lymphocytes, with adhesion blocked by antibodies to either partner [PMID:9425167]. Epithelial cell to intraepithelial T cell adhesion is mediated by this pair [PMID:7969453]. The interaction is annotated Stimulatory [flag].","molecular_requirements":"Requires the alphaE chain with beta7: mutating the MIDAS (D190A) or F298A in the alphaE A-domain abolished E-cadherin binding [PMID:10837471]. UniProt describes ITGAE/ITGB7 as a receptor for E-cadherin [DB:UniProt]. Beta7 alone is not shown to bind.","affinity_potency":[],"species_and_systems":"Recombinant human proteins and human intraepithelial T lymphocytes [PMID:9425167,PMID:10837471]; the 1994 adhesion study does not state species in our evidence [PMID:7969453]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound on both sides, so cell-cell contact signalling [flag]. Reactome lists the complex and a PDB structure (9P99) exists [DB:Reactome][DB:PDB 9P99].","caveats":"Two of the three papers were read as abstracts only. One further paper is still pending in our curation. No affinity reported.","key_references":[{"PMID":"9425167","why":"Direct binding of E-cadherin-Fc to recombinant alphaEbeta7"},{"PMID":"10837471","why":"alphaE A-domain mutations abolish E-cadherin binding"},{"PMID":"7969453","why":"Epithelial-T cell adhesion via E-cadherin and alphaEbeta7"}],"covers":["LR000291","LR003800"]},"LR003801":{"pair":"CDH1 -> KLRG1","headline":"E-cadherin is a structurally defined, very weak-affinity ligand for the inhibitory receptor KLRG1; well supported.","interaction_type":"direct binding","direction_and_effect":"KLRG1 inhibits NK cell cytotoxicity: binding by E-cadherin prevents NK lysis of E-cadherin-expressing targets [PMID:16461340]. The curators classify E-cadherin as an antagonist-direction ligand of this inhibitory receptor, i.e. it blocks cytotoxicity [PMID:19604491].","molecular_requirements":"Crystal structures of KLRG1 with the N-terminal Ig-like domain of E-cadherin (hEC1) exist for human and mouse KLRG1 [PMID:19604491][DB:PDB 3FF7]. The KLRG1 site overlaps the cadherin-cadherin adhesion interface but is distinct from the alphaEbeta7 site, so co-engagement is suggested [PMID:19604491]. KLRG1 also binds N- and R-cadherins [PMID:16461340].","affinity_potency":[{"value":"KD 100-200 \u00b5M","assay":"SPR, hEC1 or EC1-EC2, with or without Ca2+","system":"human and mouse KLRG1 with human E-cadherin EC1","cite":"PMID:19604491"}],"species_and_systems":"Expression cloning with mouse KLRG1 tetramer found human E-cadherin as a xenogeneic ligand and mouse E-cadherin as a syngeneic one [PMID:16461340]. Structures used human and mouse KLRG1 with human E-cadherin EC1 [PMID:19604491].","localisation_and_range":"Both are membrane proteins (flagged transmembrane) [flag]; avidity through multipoint attachment on target cells is proposed [PMID:19604491].","caveats":"Monomeric affinity is exceptionally weak, so function depends on avidity [PMID:19604491]. The cloning paper was read as abstract plus full text but the effect-direction label comes from curator notes. One further paper pending, one review-only.","key_references":[{"PMID":"19604491","why":"Crystal structure and SPR affinity of KLRG1-E-cadherin"},{"PMID":"16461340","why":"Identification of cadherins as KLRG1 ligands"}],"covers":["LR000292","LR003801"]},"LR002307":{"pair":"CDH11 -> CDH11","headline":"Cadherin-11 homophilic binding and adhesion in mouse proteins; the human pair is inferred.","interaction_type":"direct binding","direction_and_effect":"Cadherin-11 binds itself: homophilic binding followed heterophilic cadherin-8 binding in SPR, and in co-culture cadherin-11-dendra and cadherin-11-cherry localized equally to homotypic and heterotypic contacts, indicating uniform homophilic interaction [PMID:29742438].","molecular_requirements":"Cadherin-8 and cadherin-11 form a specificity group preferring each other over other cadherins [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Homophilic binding was weaker than the heterophilic cadherin-8 interaction on the cadherin-11 surface [PMID:29742438]. Human result is ortholog-projected. Reactome lists only catenin association [DB:Reactome]. No affinity reported.","key_references":[{"PMID":"29742438","why":"Homophilic cadherin-11 localization and SPR"}],"covers":["LR002307","LR005605"]},"LR005610":{"pair":"CDH2 -> KLRG1","headline":"KLRG1 binds N-cadherin per one expression-cloning paper read as abstract; support is brief.","interaction_type":"direct binding","direction_and_effect":"KLRG1 bound N- and R-cadherins in addition to E-cadherin; KLRG1 is an inhibitory NK receptor [PMID:16461340].","molecular_requirements":"Not reported in our evidence beyond ectodomain tetramer binding.","affinity_potency":[],"species_and_systems":"The screen used a mouse KLRG1 tetramer on mouse and human cell lines; the syngeneic result in mouse is for E-cadherin, and N-cadherin binding is not resolved to species in our evidence [PMID:16461340].","localisation_and_range":"Both are membrane proteins [flag], so contact-dependent.","caveats":"Evidence rests on one paper and its abstract sentence; excerpts shown concern E-cadherin cell-line binding, not N-cadherin. Two other papers were abstract-insufficient. No affinity reported.","key_references":[{"PMID":"16461340","why":"KLRG1 binds N-cadherin among three classical cadherins"}],"covers":["LR002312","LR005610"]},"LR002316":{"pair":"CDH4 -> KLRG1","headline":"KLRG1 binds R-cadherin in one cloning paper read as abstract; brief support.","interaction_type":"direct binding","direction_and_effect":"KLRG1 binds N- and R-cadherins, besides E-cadherin; E-cadherin binding prevented NK-cell lysis of target cells, and KLRG1 is inhibitory [PMID:16461340].","molecular_requirements":"Not reported in our evidence beyond ectodomain tetramer binding.","affinity_potency":[],"species_and_systems":"A mouse KLRG1 tetramer was used on mouse and human cell lines [PMID:16461340]. Mouse pair is the direct one; human pair is ortholog-inferred.","localisation_and_range":"Both membrane proteins [flag]; contact-dependent.","caveats":"The R-cadherin result is stated only in the abstract; excerpts concern cell-line ligand screening, not R-cadherin. The cell-killing result is documented for E-cadherin, not R-cadherin. No affinity reported.","key_references":[{"PMID":"16461340","why":"KLRG1 binds three classical cadherins incl. R-cadherin"}],"covers":["LR002316","LR005614"]},"LR002325":{"pair":"CEACAM1 -> CEACAM6","headline":"CEACAM6 immunosuppressive signalling via CEACAM1 on T cells, supported by one abstract paper with full-text ELISA evidence.","interaction_type":"functional only","direction_and_effect":"CEACAM6's immunosuppressive activity was mediated by binding to CEACAM1 on activated tumor-specific T cells; blocking CEACAM6 with antibody BAY 1834942 increased T-cell cytokine secretion and killing [PMID:35141051]. A figure legend describes dose-dependent binding of recombinant CEACAM6-Fc to recombinant human CEACAM1 by ELISA [PMID:35141051].","molecular_requirements":"Not reported in our evidence beyond the two partners.","affinity_potency":[],"species_and_systems":"Human proteins and cancer cell lines/T cells in vitro [PMID:35141051]. IntAct lists protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Cell-surface CEACAM6 on tumor cells acting on CEACAM1 on T cells (contact) [PMID:35141051].","caveats":"Curated assay class is functional_in_vitro. A second row was pending and one was abstract-insufficient. The antibody cell-line EC50 values (0.15 nM to 5 nM) describe antibody binding to CEACAM6, not ligand-receptor affinity.","key_references":[{"PMID":"35141051","why":"CEACAM6 acts through CEACAM1 on T cells; antibody blockade"}],"covers":["LR002325"]},"LR001740":{"pair":"CEACAM5 -> CD8A","headline":"CEACAM5 binds CD8 alpha and activates Lck, from one paper; binding assays are cell-absorption and glycosylation-dependent.","interaction_type":"direct binding","direction_and_effect":"CEACAM5 binds CD8alpha and activates CD8-associated Lck; CEACAM5-activated CD8+ T cells suppress CD4+ T-cell proliferation in vitro [PMID:24104458]. CD8alpha-expressing hybridoma cells, but not CD4, absorbed CEACAM5 from supernatants [PMID:24104458].","molecular_requirements":"The CEACAM5 N domain is required, and removing N-domain glycosylated residues reduces CD8alpha-binding affinity and Lck activation [PMID:24104458].","affinity_potency":[],"species_and_systems":"Human CEACAM5 and CD8alpha, using murine hybridoma T cells expressing human CD8alpha and human T84 cells [PMID:24104458]. IntAct lists a solid phase assay [DB:IntAct].","localisation_and_range":"GPI-anchored epithelial glycoprotein that can be cleaved and absorbed from supernatant [PMID:24104458].","caveats":"Single paper, abstract-level curation. No affinity values given.","key_references":[{"PMID":"24104458","why":"CEACAM5 binds CD8alpha, glycosylation-dependent Lck activation"}],"covers":["LR001740"]},"LR002334":{"pair":"CELSR2 -> CELSR2","headline":"Homophilic CELSR2 interaction implied by one neurite-growth paper; no direct binding assay in our evidence.","interaction_type":"functional only","direction_and_effect":"Celsr2 was activated by homophilic interaction and enhanced neurite growth in rat-neuron coculture and silencing assays [PMID:17618280]. Effect direction differs between the two paralogues [PMID:17618280].","molecular_requirements":"Opposite functions of Celsr2 and Celsr3 trace to a single amino acid difference in the transmembrane domain; signalling may involve second messengers [PMID:17618280].","affinity_potency":[],"species_and_systems":"Rat neuron coculture and gene silencing; the curator labels the experiment species as mouse, which conflicts with the rat neurons named in the assay text [PMID:17618280].","localisation_and_range":"Membrane-bound seven-pass cadherin, so homophilic contact (juxtacrine) [flag] [PMID:17618280].","caveats":"Abstract only; no binding measurement or database record. One additional review-only row not shown. Paralog issue: the same paper covers CELSR2 and CELSR3 with opposing effects.","key_references":[{"PMID":"17618280","why":"Celsr2 and Celsr3 homophilic activation with opposing neurite effects"}],"covers":["LR002334","LR005623"]},"LR002343":{"pair":"CGB8 -> LHCGR","headline":"hCG beta (CGB8) pair supported by hCG-level binding papers on the human LH receptor; not gene-specific.","interaction_type":"direct binding","direction_and_effect":"hCG and LH both act on LHR [PMID:12727981]; hCG displaces [125I]hCG binding [PMID:1922095].","molecular_requirements":"Deleting exon 10 does not affect hCG action but impairs LH action [PMID:12727981]. PDB complexes 7FIG, 7FIH, 7FII listed [DB:PDB 7FIG].","affinity_potency":[{"value":"ED50 4.3 ng/ml (hCG)","assay":"[125I]hCG displacement","system":"human LH receptor in 293 cells","cite":"PMID:1922095"}],"species_and_systems":"Human; COS-7 and 293 cells [PMID:12727981][PMID:1922095].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Both papers abstract only and concern hCG/LH generally, not CGB8 specifically.","key_references":[{"PMID":"1922095","why":"hCG and LH displace [125I]hCG on human LH receptor"},{"PMID":"12727981","why":"LH/hCG binding to LHR variants"}],"covers":["LR002343"]},"LR003810":{"pair":"CLCF1 -> LIFR","headline":"LIFR is engaged only as a signalling chain of the CNTFR complex; evidence is functional activation, not direct binding.","interaction_type":"functional only","direction_and_effect":"The CLF/CLC complex activated gp130, LIFR and STAT3 and supported motor neuron survival [PMID:10966616]. CLC-CNTFR acted on cells expressing the gp130-LIFR complex [PMID:11285233]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"LIFR acts downstream of CNTFR: curator notes describe gp130/LIFR as signalling chains, not independent CLC binding partners [PMID:11285233]. CNTFR binding induces gp130 heterodimerisation with LIFR [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; abstract-level evidence only [PMID:10966616][PMID:11285233].","localisation_and_range":"Not reported in our evidence beyond annotation flags.","caveats":"Both papers abstract only. Direct CLCF1-LIFR binding is not shown; CNTFR is required.","key_references":[{"PMID":"10966616","why":"gp130 and LIFR activation by CLF/CLC"},{"PMID":"11285233","why":"CLC-CNTFR activity on gp130-LIFR cells"}],"covers":["LR000304","LR003810"]},"LR008013":{"pair":"CLCF1:CRLF1 -> CNTFR:IL6ST","headline":"Complex-level pair with no curated paper evidence here; rests on database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist actions for CLCF1 and CRLF1 at CNTFR and IL6ST [DB:GtoPdb]. UniProt describes CRLF1-CLCF1 as a heterodimer engaging the CNTF receptor complex [DB:UniProt].","molecular_requirements":"Ligand: CLCF1 plus CRLF1 heterodimer; receptor: CNTFR plus IL6ST. Reactome records gp130:JAKs binding CNTFR [DB:Reactome]. Cryo-EM structure of the human CLCF1 signalling complex [DB:PDB 8D7R].","affinity_potency":[],"species_and_systems":"Human; structure is of the human complex [DB:PDB 8D7R].","localisation_and_range":"Both ligand subunits are flagged secreted [flag].","caveats":"No papers judged as confirmed (one review-only row); support is database records only. LIFR is not part of this complex entry.","key_references":[],"covers":["LR008013"]},"LR005106":{"pair":"CLEC11A -> ITGA11","headline":"Integrin alpha11 (as alpha11beta1) binds Osteolectin/CLEC11A with nanomolar affinity and is required for the osteogenic response, in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"alpha11beta1 binds Osteolectin and is required for its osteogenic response; Osteolectin acts as an agonist, promoting Wnt-pathway activation [PMID:30632962]. Itga11 deletion blocked the response in mouse MC3T3-E1 cells and in human bone marrow stromal cells [PMID:30632962].","molecular_requirements":"The receptor is the alpha11beta1 heterodimer; flag-tagged Osteolectin pulled down endogenous integrin alpha11 and beta1 [PMID:30632962].","affinity_potency":[{"value":"Kd 1.0 nM","assay":"binding of alpha11beta1 to Osteolectin (curated value; abstract says nanomolar)","system":"not specified in dossier","cite":"PMID:30632962"}],"species_and_systems":"Human Osteolectin overexpressed in mouse MC3T3-E1 cells for pulldown; recombinant mouse Osteolectin used for osteogenesis; Lepr-cre;Itga11fl/fl mice show reduced osteogenesis [PMID:30632962]. Mouse pair is ortholog-inferred.","localisation_and_range":"CLEC11A flagged secreted [flag]; the receptor is a membrane integrin.","caveats":"Single paper; the species of the affinity assay is not stated in our evidence. No database records.","key_references":[{"PMID":"30632962","why":"Identifies integrin alpha11beta1 as Osteolectin receptor"}],"covers":["LR001746","LR005106"]},"LR002352":{"pair":"CLEC4G -> TYROBP","headline":"LSECtin associates with DAP12 (TYROBP) as a signalling partner in human DCs; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"LSECtin associates with DAP12 and signals via Syk; anti-LSECtin mAb or Ebola GP induces TNF-\u03b1 and IL-6, abolished by LSECtin silencing [PMID:26943817]. TYROBP is the signalling adaptor, so this is a receptor-adaptor association rather than a classical ligand binding to a receptor.","molecular_requirements":"DAP12 is required: LSECtin failed to induce TNF-\u03b1 and IL-6 in DAP12-knockdown MDDCs; mutation of key tyrosines in the DAP12 ITAM abrogated signalling; the LSECtin transmembrane region (amino acids 32-43) was required for the association [PMID:26943817].","affinity_potency":[],"species_and_systems":"Human MDDCs, HEK293 co-IP, and Jurkat transfectants [PMID:26943817]. Mouse pair is ortholog-inferred.","localisation_and_range":"CLEC4G is not flagged secreted [flag]; membrane-bound receptor on myeloid cells.","caveats":"Co-immunoprecipitation shows association of LSECtin with DAP12; this is not a ligand-receptor binding by an extracellular ligand. The paper's ligand for LSECtin is Ebola GP, and one mutation pair (N256D, N274D) abolished GP1-Fc binding [PMID:26943817].","key_references":[{"PMID":"26943817","why":"LSECtin associates with DAP12 and signals through Syk"}],"covers":["LR002352","LR005633"]},"LR002361":{"pair":"CLU -> VLDLR","headline":"Clusterin binds VLDLR and triggers a Reelin-like signal; one abstract-only paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Clusterin binds ApoER2 (LRP8) and VLDLR and is internalized by cells expressing either; binding triggers a Reelin-like signal in Dab1-expressing cells, inducing Dab1 phosphorylation and activation of PI3K/Akt and n-cofilin [PMID:24381170]. Agonist-like.","molecular_requirements":"Dab1 is needed for the signal in the described cells; either receptor alone was sufficient for internalization [PMID:24381170].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier abstract; cell lines and subventricular zone explants [PMID:24381170]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Clusterin is flagged secreted [flag]; present in the subventricular zone where Reelin is absent [PMID:24381170], so paracrine.","caveats":"Abstract only; affinity not reported. UniProt records the interaction citing the same paper [DB:UniProt P10909]. Because both pairs rely on one paper, they are not independent.","key_references":[{"PMID":"24381170","why":"Clusterin binds ApoER2/VLDLR and activates the Reelin pathway"}],"covers":["LR002361","LR005641"]},"LR000309":{"pair":"CNTN2 -> CNTN1","headline":"Heterophilic TAG-1/F3 binding is conditional: absent between soluble proteins, seen only when TAG-1 is membrane-presented.","interaction_type":"direct binding","direction_and_effect":"Soluble F3 (CNTN1)-Fc did not bind soluble preclustered TAG-1-Fc, but bound TAG-1 when it was presented in membrane-associated form [PMID:12139915]. Effect direction recorded as agonist.","molecular_requirements":"Binding requires TAG-1 in membrane-associated form [PMID:12139915]. In bead assays TAG-1-Fc did not form mixed aggregates with F3-Fc beads [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human proteins, Fc-chimeric beads and transfected CHO cells [PMID:12139915]. Mouse pair is inferred.","localisation_and_range":"CNTN2 is flagged secreted and CNTN1 transmembrane [flag]; the paper's data indicate membrane-bound contact-dependent binding [PMID:12139915].","caveats":"A single paper; its own bead assay is negative for the soluble pair. The 'agonist' label has no functional readout in our evidence.","key_references":[{"PMID":"12139915","why":"Conditional TAG-1 binding to F3"}],"covers":["LR000309","LR003815"]},"LR002370":{"pair":"CNTN4 -> APP","headline":"CNTN4 and APP act in one genetic pathway in mouse retinal axon targeting, with co-immunoprecipitation from brain; direct binding not shown here.","interaction_type":"functional only","direction_and_effect":"Loss of CNTN4 or APP reduces targeting of direction-selective retinal ganglion cell axons to the nucleus of the optic tract; ectopic CNTN4 biases axons to the NOT and this requires APP [PMID:25959733]. Curator labels the effect agonist.","molecular_requirements":"APP was needed for CNTN4-induced targeting: only 3/21 CNTN4-electroporated RGCs arborized in the NOT of APP mutants [PMID:25959733]. Double mutants matched single mutants, consistent with one pathway [PMID:25959733].","affinity_potency":[],"species_and_systems":"Mice in vivo (knockouts, electroporation) and P8 whole-brain lysate; curator species labels say human, but the paper's work was in mice [PMID:25959733].","localisation_and_range":"CNTN4 is annotated secreted and APP secreted and transmembrane [flag]; both are expressed by NOT-projecting RGC axons [PMID:25959733].","caveats":"CNTN4 was pulled down with APP from wild-type but not CNTN4-mutant lysates; the authors state this does not rule out other partners [PMID:25959733]. Direct binding is not shown in this paper; earlier chick binding work is cited only as background.","key_references":[{"PMID":"25959733","why":"Genetic and co-IP evidence for CNTN4-APP in axon targeting"}],"covers":["LR002370","LR005650"]},"LR000318":{"pair":"COL18A1 -> GPC4","headline":"Endostatin (collagen XVIII fragment) binds glypicans as a low-affinity, heparan sulfate-dependent receptor in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Alkaline phosphatase-tagged endostatin bound glypican-1 and glypican-4 overexpressed in NIH 3T3 cells; glypicans were identified as lower-affinity endostatin receptors, with antisense data suggesting they mediate endostatin activity [PMID:11336704]. The authors propose glypican acts as a presenting co-receptor passing endostatin to a high-affinity receptor [PMID:11336704]. Curator records agonist.","molecular_requirements":"Heparan sulfate chains are critical for binding; heparinase or salt treatment reduced binding, and GPI-linkage matters (PI-PLC reduces binding) [PMID:11336704]. The ligand acting is endostatin, the collagen XVIII fragment, not intact COL18A1 [PMID:11336704].","affinity_potency":[{"value":"Kd 200 pM","assay":"Scatchard analysis of AP-endostatin binding (lower-affinity site)","system":"cow pulmonary arterial endothelial (CPAE) cells","cite":"PMID:11336704"}],"species_and_systems":"Human and mouse endostatin tested; curator records human ligand and human GPC4 sequence. Binding quantified in cow endothelial cells and NIH 3T3 overexpressing cells; human and mouse pair rows partly ortholog-projected [PMID:11336704].","localisation_and_range":"Receptor is a GPI-anchored cell-surface proteoglycan [PMID:11336704] (entity flag lists it as secreted [flag]). Ligand is a secreted fragment, so action is paracrine or autocrine.","caveats":"Low affinity and glycan-mediated, so other heparan sulfate proteoglycans may bind similarly. The paper contrasts earlier work showing heparinase-resistant binding in situ [PMID:11336704]. Only one paper.","key_references":[{"PMID":"11336704","why":"Glypicans identified as low-affinity endostatin receptors"}],"covers":["LR000318","LR003824"]},"LR005115":{"pair":"COL1A1 -> GP6","headline":"GPVI is a platelet collagen receptor; recombinant GPVI binds collagen, with PDB structures of the complex; evidence not chain-specific.","interaction_type":"direct binding","direction_and_effect":"Recombinant human and mouse GPVI bound collagen, and the soluble protein blocked collagen-induced platelet aggregation [PMID:10961879]. Curator records stimulatory.","molecular_requirements":"GPVI associates with the FcR-gamma chain [PMID:10961879]. Collagen was used generically, not resolved to COL1A1 versus COL1A2.","affinity_potency":[],"species_and_systems":"Recombinant human and mouse GPVI, platelets; abstract only [PMID:10961879]. PDB lists structures 5OU8 and 5OU9 with chains of P02452 and Q9HCN6 [DB:PDB 5OU8] [DB:PDB 5OU9].","localisation_and_range":"Receptor is restricted to megakaryocytes and platelets and is membrane-bound [PMID:10961879]; collagen is matrix.","caveats":"Paper read as abstract only; collagen type not stated; no affinity reported.","key_references":[{"PMID":"10961879","why":"Cloning of GPVI and binding to collagen"}],"covers":["LR001757","LR005115"]},"LR000327":{"pair":"COL1A1 -> ITGA2","headline":"Type I collagen binds integrin alpha2 (alpha2beta1) directly by SPR with sub-micromolar Kd; supported by functional papers, some abstract-only.","interaction_type":"direct binding","direction_and_effect":"Collagen engagement of alpha2beta1 supports platelet adhesion (both alpha1(I) and alpha2(I) chains) [PMID:2156854] and ITGA2-collagen interaction drives ovarian cancer peritoneal metastasis [PMID:33026975]. The stimulatory effect is the annotated modulatory effect.","molecular_requirements":"Recombinant alpha2 I-domain alone bound type I collagen in SPR [PMID:16043429]. The binding entity in functional papers is the alpha2beta1 heterodimer [PMID:2156854]; ITGA2 is stored here without ITGB1.","affinity_potency":[{"value":"Kd 0.3 uM (range 0.15-1.75 uM)","assay":"SPR (BIAcore), two affinity classes","system":"recombinant human alpha2 I-domain, purified fibrillar collagen I","cite":"PMID:16043429"}],"species_and_systems":"Human recombinant I-domain SPR [PMID:16043429]; human platelets [PMID:2156854]; bovine chondrocyte membranes on collagen-Sepharose [PMID:7688313]; human ovarian cancer cells and patient material [PMID:33026975]. Mouse pair is ortholog-inferred.","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Chain-level: whole-collagen assays do not separate COL1A1 from COL1A2. PMID:7688313, PMID:2156854 and PMID:33026975 were read as abstracts (33026975 also has full-text excerpts); the PMID:33026975 abstract refers to 'collagens' as a class. In PMID:7688313 alpha2 was not visualised in human fetal cartilage sections, so the authors question its need in intact cartilage. BioGRID lists co-purification from PMID:2156854 [DB:BioGRID].","key_references":[{"PMID":"16043429","why":"SPR binding of alpha2 I-domain to collagen I with Kd"},{"PMID":"2156854","why":"Platelet adhesion via alpha2beta1 to collagen I chains"},{"PMID":"33026975","why":"ITGA2-collagen interaction in ovarian cancer metastasis"}],"covers":["LR000327","LR003833"]},"LR000336":{"pair":"COL2A1 -> ITGA1","headline":"SPR shows recombinant alpha1 I domain binds collagen II with micromolar-to-submicromolar affinity; alpha1 chain only, no beta1 tested.","interaction_type":"direct binding","direction_and_effect":"Recombinant integrin alpha1 I domain bound fibrillar collagen types I-III, including type II, with similar affinities [PMID:16043429]. Direction: collagen to integrin; the dossier carries a 'Stimulatory' label [flag].","molecular_requirements":"Only the isolated alpha1 I domain was tested; beta1 co-expression or requirement is not reported in our evidence [PMID:16043429]. Collagen I was the assembled heterotrimer; II and III are homotrimers.","affinity_potency":[{"value":"KD1 0.15-0.32 uM; KD2 5.5-7.3 uM","assay":"SPR (BIAcore), alpha1 I domain over collagens I-III","system":"recombinant human proteins","cite":"PMID:16043429"}],"species_and_systems":"Recombinant human I domains and purified collagens [PMID:16043429]; the mouse pair is ortholog-inferred.","localisation_and_range":"Collagen is a secreted matrix protein [flag]; binding is to ECM (inferred).","caveats":"Full text read. The two KD values are two affinity classes reported across the three collagen types, not specific to collagen II. A second confirmed paper is counted but not shown; one abstract was insufficient.","key_references":[{"PMID":"16043429","why":"SPR of alpha1 I domain to collagens I-III with KDs"}],"covers":["LR000336","LR003842"]},"LR000345":{"pair":"COL4A1 -> ITGA2","headline":"Collagen-integrin alpha2 link supported by a functional ovarian cancer paper that does not separate collagen chains.","interaction_type":"functional only","direction_and_effect":"ITGA2 on ovarian cancer cells triggers adhesion to collagen, migration and peritoneal metastasis; ITGA2-collagen interaction drives this [PMID:33026975].","molecular_requirements":"The binding entity is the ITGA2:ITGB1 heterodimer per the curator note; ITGA2 is stored alone [PMID:33026975].","affinity_potency":[],"species_and_systems":"Human ovarian cancer cell lines (gene-edited) and patient samples, plus in vivo metastasis [PMID:33026975].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"The paper says 'collagens' as a class, so COL4A1 is not separated from COL1/COL3 chains; COL4A1 is only noted as expressed in cancer cells. Evidence is functional, not direct binding. Two other papers were abstract_insufficient.","key_references":[{"PMID":"33026975","why":"ITGA2-collagen adhesion drives ovarian cancer peritoneal metastasis"}],"covers":["LR000345","LR003851"]},"LR000363":{"pair":"COL8A1 -> ITGA2","headline":"Antibody-blocking evidence that alpha2 integrin contributes to smooth muscle cell attachment to type VIII collagen; functional only.","interaction_type":"functional only","direction_and_effect":"Antibodies against alpha1 or alpha2 integrins reduced attachment of SMCs to type VIII collagen by 29% and 77%, respectively; anti-beta1 antibodies prevented attachment and migration [PMID:10666376]. Type VIII collagen signaled through integrins to stimulate MMP production [PMID:10666376].","molecular_requirements":"Beta1 integrin is implicated by antibody blocking; alpha1 and alpha2 were tested together as a pair of antibodies, so the effect of this chain alone is not separable in the evidence [PMID:10666376].","affinity_potency":[{"value":"29% and 77%","assay":"reduction of SMC attachment to type VIII collagen by anti-alpha1 or anti-alpha2 integrin antibodies, respectively","system":"smooth muscle cells","cite":"PMID:10666376"}],"species_and_systems":"Experiments used smooth muscle cells, with neointimal SMCs grown from rat [PMID:10666376]; the human and mouse pairs are ortholog-inferred from this evidence.","localisation_and_range":"Ligand flagged secreted [flag]; the paper describes matrix-deposited type VIII collagen [PMID:10666376].","caveats":"Abstract only; antibody blocking is indirect and does not show direct binding. A second confirmed paper exists but is not shown; one review-only and one abstract-insufficient row.","key_references":[{"PMID":"10666376","why":"Antibody blocking implicates alpha1/alpha2/beta1 integrins in SMC attachment to type VIII collagen"}],"covers":["LR000363","LR003869"]},"LR002424":{"pair":"COL8A1 -> ITGB1","headline":"COL8A1 is reported to interact directly with ITGB1 on colorectal cancer cells, activating PI3K-AKT; abstract-level evidence plus computational support.","interaction_type":"direct binding","direction_and_effect":"COL8A1 secreted from THBS2+ CAFs is reported to directly interact with ITGB1 on resistant malignant cells, activating PI3K-AKT signaling and promoting EMT and oxaliplatin resistance; ITGB1 knockdown or an AKT inhibitor mitigated these effects [PMID:39732719].","molecular_requirements":"ITGB1 only; alpha partner not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human colorectal cancer; mouse pair is ortholog-inferred. Abstract plus full-text excerpts [PMID:39732719].","localisation_and_range":"Ligand flagged secreted [flag]; CAF-derived, acting on neighbouring tumor cells [PMID:39732719].","caveats":"Excerpts show CellChat inference, spatial colocalisation and molecular docking for COL8A1-ITGB1 [PMID:39732719]; direct biochemical binding data are not shown in the excerpts.","key_references":[{"PMID":"39732719","why":"COL8A1-ITGB1 interaction drives oxaliplatin resistance in CRC"}],"covers":["LR002424","LR005703"]},"LR010614":{"pair":"COL9A1 -> MAG","headline":"Old solid-phase study shows soluble MAG binds collagen type IX; COL9A1 chain-level specificity is not resolved.","interaction_type":"direct binding","direction_and_effect":"Soluble MAG binds several collagens including type IX, with a kd of 5.7 X 10(-8) M for collagen type IX [PMID:2446864]. Binding of labelled MAG to collagen G was inhibited by unlabeled MAG and collagen G but not heat-denatured collagen [PMID:2446864]. Direction is receptor-to-collagen binding; signaling effect is not reported.","molecular_requirements":"The paper tested collagen type IX as a whole; whether the COL9A1 chain, or the intact heterotrimer, is required is not reported in our evidence [PMID:2446864].","affinity_potency":[{"value":"kd of 5.7 X 10(-8) M","assay":"solid-phase binding of soluble MAG to purified collagen type IX","system":"MAG from adult mouse brain","cite":"PMID:2446864"}],"species_and_systems":"Soluble MAG from adult mouse brain with purified collagens; the pair is listed as human [PMID:2446864].","localisation_and_range":"MAG flagged secreted and receptor [flag]; soluble MAG binds heparin and collagens, consistent with matrix binding [PMID:2446864]. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Single 1987 abstract; binding to type IX, not specific chains. Heparin and sulfated polysaccharides blocked MAG-collagen binding [PMID:2446864].","key_references":[{"PMID":"2446864","why":"Solid-phase binding of soluble MAG to collagens incl. type IX, with kd"}],"covers":["LR010614"]},"LR002433":{"pair":"COMP -> ITGAV","headline":"COMP cell attachment is partly blocked by anti-alphaVbeta3 antibody; functional, with the integrin acting as the alphaVbeta3 heterodimer.","interaction_type":"functional only","direction_and_effect":"A function-blocking anti-alphaVbeta3 antibody reduced cell attachment to COMP by 35%, one of two independent attachment mechanisms alongside CD47, with COMP acting as agonist/adhesive ligand [PMID:20033473].","molecular_requirements":"The receptor is the alphaVbeta3 heterodimer (entity named integrin alphaVbeta3 [flag]); ITGAV alone is not shown to suffice [PMID:20033473].","affinity_potency":[],"species_and_systems":"Ligament cells and chondrocytes on recombinant COMP; ligament cell species not stated in the excerpts [PMID:20033473].","localisation_and_range":"Extracellular matrix ligand acting on a cell-surface receptor [PMID:20033473].","caveats":"Antibody blocking only, no binding measurement; the authors cite other work for COMP-alphaVbeta3 interaction and report an RGD-dependent route. Reactome lists the binding reaction [DB:Reactome R-HSA-2426259]. One paper, abstract-level curation.","key_references":[{"PMID":"20033473","why":"Anti-alphaVbeta3 antibody reduces cell attachment to COMP"}],"covers":["LR002433","LR005712"]},"LR009201":{"pair":"CPAMD8 -> SCTR","headline":"Only a BioGRID peptide record exists; four papers were judged about a different entity.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"BioGRID lists the pair as Protein-peptide in both directions via a single paper [DB:BioGRID 304972]. Four papers were judged different_entity, so none supports this pair.","key_references":[],"covers":["LR009201"]},"LR000372":{"pair":"CRH -> CRHR1","headline":"CRH binds and activates CRHR1 with high affinity; well supported by binding, functional, structural and database evidence.","interaction_type":"direct binding","direction_and_effect":"CRH acts as a full agonist at CRHR1 [DB:GtoPdb]. Expressed human receptor bound rat/human CRF and coupled to adenylate cyclase; antagonist alpha-helCRF-(9-41) inhibited CRF-stimulated cAMP [PMID:7692441]. Agonists and antagonists give different apparent affinities depending on the radioligand [PMID:11123370]. In HEK293 cells hCRF1 mobilised calcium and coupled to Gs, but no calcium response occurred in SK-N-MC cells [PMID:15450949].","molecular_requirements":"Receptor regions: the third extracellular domain/fifth transmembrane junction is most important for CRF binding and activation; second extracellular domain residues play secondary roles [PMID:9178757]. An alternatively spliced form with a 29-amino-acid insert in the first intracellular loop is described [PMID:7692441]. Co-receptors not reported in our evidence.","affinity_potency":[{"value":"Kd = 3.3 +/- 0.45 nM","assay":"binding of rat/human CRF to expressed human receptor","system":"COS cells","cite":"PMID:7692441"},{"value":"Kd = 1.09 nM","assay":"binding of human/rat CRF to tree shrew CRF-R1","system":"HEK293 cells","cite":"PMID:9851694"},{"value":"pKd 7.099999904632568 to 9.0","assay":"GtoPdb curated affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in COS and HEK293 cells [PMID:7692441, PMID:15450949]. Tree shrew and Xenopus receptors were also tested [PMID:9851694, PMID:9326293]. The mouse pair is inferred from human evidence. Structures exist [DB:PDB 3EHT].","localisation_and_range":"CRH is flagged secreted and CRHR1 is flagged a receptor [flag].","caveats":"Most papers read as abstracts only. Xenopus CRF-R1 was very selective for ligands, unlike human CRF-R1, so cross-species pharmacology differs [PMID:9326293]. Signalling output depends on cell background [PMID:15450949]. One of the cited affinity values is from a non-human receptor.","key_references":[{"PMID":"7692441","why":"Cloning, Kd 3.3 nM, cAMP coupling"},{"PMID":"11123370","why":"Competitive binding with agonist and antagonist radioligands"},{"PMID":"9178757","why":"Maps receptor regions for CRF binding"}],"covers":["LR000372","LR003878"]},"LR001425":{"pair":"CRIPTO -> ACVR1B","headline":"Cripto binds ALK4 (ACVR1B) directly and acts as a Nodal co-receptor; also blocks activin signalling.","interaction_type":"direct binding","direction_and_effect":"Cripto binds ALK4 and enables Nodal signalling through it [PMID:11485994, PMID:11909953]. The synthetic CFC domain binds ALK4, and the paper frames this as blocking the activin/ALK4 pathway [PMID:19035567]. Cripto is a co-factor rather than a conventional signalling ligand [PMID:11485994].","molecular_requirements":"ALK4 mediates Nodal signalling only in the presence of Cripto [PMID:11485994]. Smad-2 phosphorylation required both Nodal and ALK4, whereas MAPK/AKT activation did not [PMID:11909953]. The CFC domain alone binds ALK4 but not ActRIIB [PMID:19035567].","affinity_potency":[{"value":"K(D) in micro M range","assay":"SPR binding of synthetic CFC domain to ALK4","system":"synthetic human Cripto CFC domain","cite":"PMID:19035567"}],"species_and_systems":"Human CFC domain in vitro [PMID:19035567]; mouse and human mammary epithelial cells [PMID:11909953]; vertebrate development model [PMID:11485994]. Human and mouse pairs are listed.","localisation_and_range":"CRIPTO is flagged secreted [flag]; papers describe it as a GPI-anchored co-receptor/co-factor [PMID:11909953].","caveats":"All three papers read as abstracts only. BioGRID lists a reconstituted ACVR2A-TDGF1 complex only [DB:BioGRID]. Part of Cripto activity is ALK4-independent [PMID:11909953].","key_references":[{"PMID":"11909953","why":"Binding by phage display, FACS and co-IP"},{"PMID":"19035567","why":"CFC domain SPR/NMR with ALK4"},{"PMID":"11485994","why":"Cripto with ALK4/ALK7 in Nodal signalling"}],"covers":["LR001425","LR004820"]},"LR002442":{"pair":"CRP -> FCGR1A","headline":"CRP binds Fc\u03b3RIa directly with micromolar affinity, supported by live-cell imaging and SPR in human systems.","interaction_type":"direct binding","direction_and_effect":"Anti-Fc\u03b3RI antibody essentially abolished CRP binding on Mono Mac 6 cells, whereas anti-Fc\u03b3RII had no noticeable effect [PMID:18412163]. SPR showed CRP binding Fc\u03b3RIa [PMID:33790888]; Fc\u03b3RIa blocking abrogated CRP's enhancement of IgG-mediated neutrophil functions [PMID:33790888]. Curators label the effect agonist [PMID:18412163].","molecular_requirements":"Fc\u03b3RIa as a single binding chain; co-subunits not reported in our evidence.","affinity_potency":[{"value":"KD (6.6 +/- 1.5) microM","assay":"live-cell confocal imaging of fluorescent CRP","system":"human Mono Mac 6 cells","cite":"PMID:18412163"}],"species_and_systems":"Human cell line and recombinant human proteins; also human effector cells in functional assays [PMID:18412163, PMID:33790888].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Low affinity. The 2008 paper was read as abstract only. Fc\u03b3RI blocking effects were on a background where IgG also binds Fc\u03b3Rs [PMID:33790888].","key_references":[{"PMID":"18412163","why":"Fc\u03b3RI-specific CRP binding with KD"},{"PMID":"33790888","why":"SPR profiling and functional blocking"}],"covers":["LR002442"]},"LR000381":{"pair":"CTF1 -> LIFR","headline":"CTF1 signals through a gp130/LIFR receptor; LIFR evidence is blockade in canine cells and database records.","interaction_type":"functional only","direction_and_effect":"CT-1 stimulated fibroblast growth and blockade of LIF receptor inhibited it, so CT-1 is an agonist [PMID:11834704]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"The receptor is the gp130/LIFR heterodimer; single-chain rows inherit complex-level evidence [PMID:11834704]. Reactome lists the OSM, LIF, CTF1 receptor complex binding gp130 [DB:Reactome R-HSA-6783524].","affinity_potency":[],"species_and_systems":"Cultured adult canine cardiac fibroblasts; the human and mouse pairs are ortholog-inferred [PMID:11834704].","localisation_and_range":"CTF1 flagged secreted [flag]; paracrine cytokine action on cell-surface receptor.","caveats":"Receptor blockade only, no binding; abstract only; LIFR alone not shown sufficient.","key_references":[{"PMID":"11834704","why":"LIFR blockade abolishes CT-1 growth effect in canine cells"}],"covers":["LR000381","LR003887"]},"LR000390":{"pair":"CTHRC1 -> FZD6","headline":"CTHRC1 co-precipitates with Fzd6 in HEK293 cells and modulates Wnt/PCP signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cthrc1 co-precipitated with Fzd6 in HEK293 cells, indicating interaction with multiple Fzd proteins; no binding to Smo or to C-terminally truncated Cthrc1 [PMID:18606138]. In HEK293T cells Cthrc1 activated the PCP pathway but suppressed canonical Wnt signalling [PMID:18606138].","molecular_requirements":"Cthrc1 forms a Cthrc1-Wnt-Fzd/Ror2 complex and enhances Wnt-Fzd/Ror2 interaction; it also bound Wnt3a, Wnt5a and Wnt11 [PMID:18606138]. Cthrc1 did not coprecipitate with LRP6 [PMID:18606138].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293 cells; mouse knockout (Cthrc1 LacZ) and Vangl2 genetic interaction; curator labels list human species for the proteins, mouse pair ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted [flag]; the paper describes cell-surface-anchored Cthrc1 binding [PMID:18606138].","caveats":"Co-IP shows association, not affinity or direct binding to purified protein; overexpression in cells. Single paper; Fzd paralogs bind similarly, so specificity among Fzd3/5/6 is not shown.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Fzd proteins and Ror2 and stabilizes the Wnt-receptor complex"}],"covers":["LR000390","LR003896"]},"LR002451":{"pair":"CTLA4 -> CD80","headline":"CTLA4 binds CD80 with strong structural and biochemical database support; a paper shows soluble CD80 binding CTLA-4-Ig.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble s1CD80 binds recombinant CD152(CTLA-4)-Ig and CD28-Ig by direct binding and inhibits mixed lymphocyte reaction and T-cell proliferation, acting inhibitory [PMID:17953528]. UniProt describes CTLA4 as a decoy receptor with stronger affinity for CD80 and CD86 than CD28 [DB:UniProt].","molecular_requirements":"CD80 also binds CD28; s1CD80 lacks the transmembrane domain [PMID:17953528]. A co-crystal structure exists [DB:PDB 1I8L] and Reactome lists CTLA-4 binding B7-1/B7-2 [DB:Reactome R-HSA-388809].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and human T cells, serum from healthy individuals [PMID:17953528]; mouse pair ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted, receptor and transmembrane [flag]; soluble CD80 occurs in serum, 0-1 mg/l in 24% of individuals [PMID:17953528]; otherwise membrane-bound juxtacrine.","caveats":"The paper is read as abstract only and tests the soluble s1CD80 isoform rather than the membrane form; no affinity reported in our evidence. Binding is to CTLA-4-Ig. Interaction also in BioGRID, IntAct [DB:BioGRID, DB:IntAct].","key_references":[{"PMID":"17953528","why":"Soluble CD80 binds CTLA-4-Ig and CD28-Ig"}],"covers":["LR002451","LR005727"]},"LR005124":{"pair":"CXADR -> CXADR","headline":"Homophilic CXADR adhesion reported in one mouse cell-aggregation study; not a distinct ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"C6 cells transfected with mouse CAR aggregated homophilically, and this was inhibited by antibodies against the extracellular domain [PMID:10814828]. This indicates self-association driving adhesion, not a separate ligand and receptor.","molecular_requirements":"Not reported in our evidence beyond the extracellular domain being the antibody target [PMID:10814828].","affinity_potency":[],"species_and_systems":"Mouse protein (mCAR) expressed in transfected C6 cells, aggregation assay [PMID:10814828]. The human pair is ortholog-inferred. IntAct has one protein-array record for human P78310 with itself [DB:IntAct].","localisation_and_range":"Both partners carry secreted and receptor flags [flag]; the paper describes a membrane protein mediating cell-cell adhesion [PMID:10814828].","caveats":"No direct binding assay, no affinity. Human version is inferred from the mouse result plus a protein-array record only [DB:IntAct]. Only an abstract was read.","key_references":[{"PMID":"10814828","why":"Homophilic aggregation of mCAR-transfected cells"}],"covers":["LR001766","LR005124"]},"LR000408":{"pair":"CXCL1 -> ACKR1","headline":"CXCL1 binds ACKR1 (DARC) directly in human systems, as an atypical scavenger or transporter receptor without signalling output.","interaction_type":"direct binding","direction_and_effect":"DARC bound pro-inflammatory chemokines including CXCL1 but not lymphoid chemokines, and CCL2 bound to DARC failed to induce a significant response (abstract is cut off) [PMID:13679391]. Duffy antigen on endothelial cells facilitates movement of CXCL1 across a monolayer, and in transfected cells did not alter gene expression after GRO-alpha/CXCL1 stimulation [PMID:12734373]. The curators classed the effect as neutral/decoy-like [PMID:13679391].","molecular_requirements":"The amino-terminal E1 domain of DARC carries the promiscuous binding, shown with a DARCe1/IL-8RB chimera that bound IL-8 and MGSA with KD values almost identical to native receptors [PMID:7592830].","affinity_potency":[{"value":"Kd 5.6 nM","assay":"saturable 125I-GRO-alpha/CXCL1 binding","system":"Duffy-transfected human endothelial cells","cite":"PMID:12734373"}],"species_and_systems":"Human ligand and receptor in transfected cells and HEV tissue; BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"CXCL1 is a secreted chemokine (flag); ACKR1 is a transmembrane receptor on endothelium and RBCs [PMID:12734373].","caveats":"The 5.6 nM Kd comes from a browser-read Results sentence flagged by curators as unverifiable with spot-check pending; the paper itself was read as abstract only [PMID:12734373]. Not a signalling receptor, so CCC tools scoring activation may mislead. Outcome counts also include review-only, pending and different-entity rows not shown.","key_references":[{"PMID":"12734373","why":"Kd and transendothelial transport"},{"PMID":"13679391","why":"Selective binding of pro-inflammatory chemokines"},{"PMID":"7592830","why":"E1 domain determines promiscuous binding"}],"covers":["LR000408"]},"LR003900":{"pair":"CXCL10 -> SDC4","headline":"CXCL10 interacts directly with syndecan-4 through its heparin-binding domain, independent of CXCR3; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"A direct CXCL10-syndecan-4 interaction inhibited primary lung fibroblast migration; mutating the heparin-binding domain, not the CXCR3 domain, diminished this effect, and CXCL10 inhibited fibrosis in wild-type but not Sdc4-null mice [PMID:20484822].","molecular_requirements":"The heparin-binding domain of CXCL10 is required; CXCR3 binding is not [PMID:20484822].","affinity_potency":[],"species_and_systems":"Experiments in mouse (bleomycin model, Sdc4-null) and fibroblasts including from fibrosis patients [PMID:20484822]. Human pair is ortholog-inferred.","localisation_and_range":"CXCL10 is flagged secreted [flag]; syndecan-4 is a heparan sulfate proteoglycan [PMID:20484822].","caveats":"Abstract only. SDC4 is more a binding partner/co-receptor than a signalling receptor; no affinity reported.","key_references":[{"PMID":"20484822","why":"CXCL10 antifibrotic action via syndecan-4"}],"covers":["LR000394","LR003900"]},"LR002460":{"pair":"CXCL11 -> ACKR1","headline":"CXCL11 binds human ACKR1 (Duffy) on erythrocytes with strong affinity in one full-text study.","interaction_type":"direct binding","direction_and_effect":"CXCL11 displaced radiolabelled CXCL8 from Duffy antigen on human erythrocytes and fell in the strong-binding category [PMID:15358176]. Signalling effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 12.7 nM","assay":"125I-CXCL8 competition displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor, native erythrocytes [PMID:15358176].","localisation_and_range":"CXCL11 is flagged secreted and ACKR1 transmembrane [flag].","caveats":"Single paper; binding measured by displacement of CXCL8.","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of human Duffy antigen"}],"covers":["LR002460"]},"LR000417":{"pair":"CXCL6 -> CXCR2","headline":"Well supported: CXCL6 binds and activates CXCR2 with high potency in human transfectants and neutrophils; GtoPdb and structures.","interaction_type":"direct binding","direction_and_effect":"Agonist: GCP-2/CXCL6 induced calcium rise in CXCR2-transfected cells at minimal effective concentration 3 nM, and migration EC50 was 0.1 nM [PMID:9692902]; radiolabelled IL-8 was displaced by GCP-2. Neutrophil binding to CXCR-2 was high affinity [PMID:10593335]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement reported. PDB 8XWM and 8XXX contain a CXCL6 chain and a CXCR2 chain [DB:PDB 8XWM].","affinity_potency":[{"value":"3 nM","assay":"minimal effective concentration, calcium rise","system":"CXCR2-transfected cells","cite":"PMID:9692902"},{"value":"0.1 nM","assay":"half-maximal migration, ENA-78 and GCP-2 similar","system":"CXCR2-transfectants","cite":"PMID:9692902"}],"species_and_systems":"Human transfected cell lines and human neutrophils [PMID:9692902][PMID:10593335].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"Abstract-only reads. The curated 'pKd 7.0' is not in the abstract and is not reported.","key_references":[{"PMID":"9692902","why":"Potency at CXCR2"},{"PMID":"10593335","why":"CXCR-2 high-affinity binding in neutrophils"}],"covers":["LR000417"]},"LR000921":{"pair":"CXCL8 -> CXCR1","headline":"CXCL8 (IL-8) binds and activates CXCR1; well supported by binding assays in transfected cells plus structures and database records.","interaction_type":"direct binding","direction_and_effect":"CXCL8 is an agonist of CXCR1 (full agonist, stimulatory). IL-8 displaced [125I]-IL-8 from CXCR1 in CHO cells [PMID:10188995], and CXCR1-transfected Jurkat cells bound IL-8 and mediated chemotaxis [PMID:8137938]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR1 alone is sufficient in transfected cells; no co-receptor is reported in our evidence. In one study an anti-CXCR1 antibody blocked signalling without affecting binding, which the curator reads as separable binding and signalling steps [PMID:8940121].","affinity_potency":[{"value":"pKi 8.89","assay":"[125I]-IL-8 competition binding","system":"CHO cells expressing HA-tagged human CXCR1","cite":"PMID:10188995"},{"value":"Kd ~2 nM","assay":"IL-8 binding","system":"human IL-8R-A and IL-8R-B expressed in mammalian cells","cite":"PMID:1379593"},{"value":"Kd 1-4 nM","assay":"radioligand binding","system":"CXCR1-transfected Jurkat cells","cite":"PMID:8137938"}],"species_and_systems":"Human ligand and receptor in recombinant cells. A mouse CXCR1 also responded to human IL-8 in binding, GTPgammaS exchange and chemotaxis assays in transfected cells [PMID:17197447].","localisation_and_range":"CXCL8 is flagged secreted and CXCR1 transmembrane [flag]; this implies a soluble chemokine acting on cell-surface receptors.","caveats":"Most papers were read as abstracts only. One confirmed paper (PMID:15282370) mentions the pairing only as background to an allosteric inhibitor study. Structures exist (PDB 1ILP, 6XMN, 8IC0) [DB:PDB 1ILP].","key_references":[{"PMID":"10188995","why":"competition binding and signalling in CHO cells"},{"PMID":"1379593","why":"high-affinity IL-8 binding, Kd ~2 nM"},{"PMID":"8137938","why":"binding and chemotaxis in transfected Jurkat cells"}],"covers":["LR000921"]},"LR000426":{"pair":"DCN -> ERBB4","headline":"ErbB4 involvement in decorin signalling is inferred from phosphorylation patterns; no binding shown.","interaction_type":"functional only","direction_and_effect":"Decorin effects appear to involve ErbB4 activation, which would block ErbB2/ErbB3 heterodimer phosphorylation; ErbB2 down-regulation and growth suppression occurred in breast carcinoma cells [PMID:10942781].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human breast carcinoma cells, de novo and recombinant decorin [PMID:10942781].","localisation_and_range":"Decorin flagged secreted; ERBB4 transmembrane receptor [flag].","caveats":"Abstract hedges ('appear to involve'); no direct binding, no affinity, one paper, no database record. Support is weak.","key_references":[{"PMID":"10942781","why":"Inferred ErbB4 activation by decorin"}],"covers":["LR000426","LR003923"]},"LR010056":{"pair":"DDC:SLC6A3 -> DRD2","headline":"No verified paper supports this complex-ligand pair; only IntAct records with DRD2.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Ligand is a DDC:SLC6A3 complex; members carry no secretion annotations [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; IntAct lists competition binding and pull down [DB:IntAct P14416-Q01959].","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on two IntAct records alone; eight judged papers were different-entity or abstract-insufficient. DDC is an enzyme and SLC6A3 a transporter, so a protein-protein ligand-receptor reading is doubtful.","key_references":[],"covers":["LR010056"]},"LR000435":{"pair":"DHH -> BOC","headline":"Structural evidence (PDB 3N1G) that DHH binds BOC; positive modulator role, abstract-level.","interaction_type":"direct binding","direction_and_effect":"x-ray structures of Sonic, Indian and Desert Hh alone and in complex with the active domains of CDO and BOC show all mammalian Hh proteins bind CDO and BOC in the same manner [PMID:20519495]. Database records agree: PDB 3N1G (DhhN bound to BOCFn3) [DB:PDB 3N1G], IntAct x-ray crystallography [DB:IntAct], UniProt subunit annotation [DB:UniProt]. The abstract notes that CDO and BOC positively regulate Hh signalling, but this is background and not measured for DHH here [PMID:20519495].","molecular_requirements":"The N-terminal signalling domain of DHH (DhhN) binds the BOC fibronectin domain in the structure [DB:PDB 3N1G]. Whether Patched is also needed is not reported for this pair.","affinity_potency":[],"species_and_systems":"Mammalian proteins in a crystal; the species of the recombinant proteins is not stated in the abstract [PMID:20519495]. The mouse row is projected by orthology (ortholog_inferred) [flag].","localisation_and_range":"DHH is flagged both secreted and transmembrane [flag]; membrane tethering is therefore suggested only by an annotation flag, and contact-dependent versus diffusible action is not reported in our evidence.","caveats":"Abstract only. Affinity for DHH is not given in the abstract; micromolar affinities are cited for Ihog and for CDO with Sonic Hh as background [PMID:20519495]. Crystal binding does not show signalling effect for DHH.","key_references":[{"PMID":"20519495","why":"Crystal structures of Hh proteins with CDO and BOC"}],"covers":["LR000435","LR003927"]},"LR005133":{"pair":"DKK1 -> LRP4","headline":"Direct binding to LRP4 shown in vitro by coprecipitation; one paper, supporting a bone-context link.","interaction_type":"direct binding","direction_and_effect":"Lrp4 binds Dkk1 and sclerostin in vitro; the authors suggest Lrp4 could compete with Lrp5/6 or present the ligands to Lrp5/6 [PMID:19936252].","molecular_requirements":"Binding was shown with HEK293A cells overexpressing Lrp4 and AP-fusion ligands; R-spondin2 served as negative control [PMID:19936252]. Co-receptor needs are not reported.","affinity_potency":[],"species_and_systems":"HEK293A cells overexpressing Lrp4 and primary osteoblasts; Lrp4 deficient mutant mice analysed for bone phenotype [PMID:19936252]. Both pairs are ortholog-inferred.","localisation_and_range":"DKK1 is flagged secreted; LRP4 as a receptor [flag].","caveats":"One paper; no affinity value; whether Lrp4 acts as receptor, competitor or presenter is not resolved by the authors [PMID:19936252].","key_references":[{"PMID":"19936252","why":"Lrp4 binds Dkk1 and sclerostin in vitro"}],"covers":["LR001777","LR005133"]},"LR000444":{"pair":"DKK2 -> KREMEN2","headline":"Functional evidence that Kremen2 switches Dkk2 from LRP6 activator to Wnt inhibitor; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Dkk2 activates LRP6 signalling in transfected human 293 fibroblasts, but co-transfection of krm2 blocks this and enhances inhibition of Wnt/Frizzled signaling; Krm2 can switch Dkk2 from activator to inhibitor [PMID:12527209].","molecular_requirements":"Interaction with Krm2 is mediated by the second cysteine-rich domain of Dkks; the abstract notes Kremen1 and 2 bind Dkk1 and Dkk2 with high affinity (from earlier work) [PMID:12527209]. LRP6 is part of the readout.","affinity_potency":[],"species_and_systems":"Human 293 fibroblasts and Xenopus embryos (Dkk2 and Krm2 cooperate to anteriorize embryos) [PMID:12527209]; the human pair is ortholog-inferred.","localisation_and_range":"DKK2 flagged secreted; KREMEN2 flagged receptor [flag].","caveats":"Abstract only; binding affinity is not measured here. Second confirmed row is the same paper.","key_references":[{"PMID":"12527209","why":"Krm2 turns Dkk2 into a Wnt/LRP6 inhibitor"}],"covers":["LR000444","LR003936"]},"LR000453":{"pair":"DLL4 -> NOTCH3","headline":"Two abstract-only papers support DLL4 activating NOTCH3 in cells, one with proximity-ligation interaction data.","interaction_type":"functional only","direction_and_effect":"Endogenous Notch2/3-DLL4 interactions were detected by in situ proximity ligation in human bladder cancer cell lines, and recombinant DLL4 activated canonical Notch signalling [PMID:39951484]. Dll4 interaction was sufficient to maintain Notch3 activity in quiescent C2C12 reserve cells [PMID:29230914].","molecular_requirements":"Not reported in our evidence beyond Notch3 being the receptor tested; Reactome lists a DLL4:NOTCH3 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human bladder cancer cell lines [PMID:39951484]; mouse C2C12 myoblast reserve cells and primary satellite cells [PMID:29230914]. The dossier's species fields are blank for both.","localisation_and_range":"Both partners annotated transmembrane, DLL4 not secreted [flag]; Dll4 on nascent myotubes acting on adjacent stem cells fits contact signalling [PMID:29230914].","caveats":"Abstracts only. In the bladder paper Notch2 and Notch3 are not separated, and the proximity assay is not a purified-protein binding test. Six papers were abstract-insufficient.","key_references":[{"PMID":"39951484","why":"DLL4-Notch2/3 proximity ligation in bladder cancer cells"},{"PMID":"29230914","why":"Dll4 activates Notch3 in muscle stem cells"}],"covers":["LR000453","LR003945"]},"LR009021":{"pair":"DRD2 -> GNAI2","headline":"Database-asserted only: UniProt notes DRD2 interacts with G(i) proteins by similarity; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states DRD2 interacts with G(i) proteins, GNAI1, GNAI2 and GNAI3 (By similarity) [DB:UniProt]. Effect and direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt statement is by similarity.","localisation_and_range":"Not reported in our evidence; GNAI2 is a G-protein, not annotated as a secreted or surface ligand.","caveats":"No confirmed papers; one review-only paper. The only support is a by-similarity database annotation.","key_references":[],"covers":["LR009021"]},"LR005142":{"pair":"DSC1 -> DSG4","headline":"DSC1-DSG4 support is a family-wide SPR claim; DSG4 is not among the paper's named Dsg1/2/3 matrix.","interaction_type":"direct binding","direction_and_effect":"Passing a Dsg over a Dsc surface or the reverse gave binding responses indicative of strong heterophilic interaction [PMID:27298358].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), all pairwise human Dsg/Dsc combinations; range across pairs, not specific to this pair","system":"human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Human proteins; mouse record ortholog-inferred [PMID:27298358].","localisation_and_range":"Annotated transmembrane [flag]; adhesive binding [PMID:27298358].","caveats":"Browser-read full text, quote unverifiable, spot-check pending. The curator note describes the matrix as Dsg1/2/3 x Dsc1/2/3, so Dsg4 testing is not shown.","key_references":[{"PMID":"27298358","why":"SPR of Dsc/Dsg ectodomains"}],"covers":["LR001786","LR005142"]},"LR005151":{"pair":"Dsg1a -> Dsc3","headline":"Dsg1a -> Dsc3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: mouse (ortholog-projected). The mouse pair is projected from human evidence; no mouse experiment is in our evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR005151"]},"LR002505":{"pair":"DSG3 -> DSG3","headline":"Homophilic trans DSG3 self-binding shown by cross-linking in keratinocytes; abstract only.","interaction_type":"direct binding","direction_and_effect":"Cross-linking showed isoform-specific homophilic trans binding of Dsg3 in HaCaT keratinocytes; adducts were detergent-insoluble and probably within desmosomes by electron microscopy [PMID:21098030].","molecular_requirements":"Trp-2 and Ala-80 mutations abolished Dsc2 binding specifically (not tested on Dsg3) [PMID:21098030]. UniProt notes DSG3 forms a complex with PKP1 and YWHAG for YAP1 localisation, a cytoplasmic interaction not relevant to the ectodomain pair [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes; mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged as non-secreted receptors, so this is membrane-bound, contact-dependent (juxtacrine) adhesion [flag].","caveats":"Abstract only. The authors found no evidence for heterophilic or cis interaction, though neither was excluded [PMID:21098030]. A self-pair is one chain acting as both ligand and receptor; a single-subunit homodimer.","key_references":[{"PMID":"21098030","why":"Cross-linking evidence for homophilic trans DSG3 binding"}],"covers":["LR002505","LR005773"]},"LR000462":{"pair":"EDN2 -> EDNRA","headline":"ET-2 acts as a full agonist on ETA in vitro; functional evidence only, abstracts only.","interaction_type":"functional only","direction_and_effect":"ET-2 constricts human isolated blood vessels via ETA, full agonist, equipotent with ET-1 with an EC50 value of 5.7 nM [PMID:7647976]; chicken EDNRA in HEK293 cells was activated by EDN1 and EDN2 [PMID:31351053]; in rat ovary the contraction by EDN2 was mediated by EDNRA, not EDNRB [PMID:20450830]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"EC50 5.7 nM","assay":"vasoconstriction, ET-2 equipotent with ET-1","system":"human isolated blood vessels","cite":"PMID:7647976"}],"species_and_systems":"Human blood vessels [PMID:7647976], chicken receptor in HEK293 cells [PMID:31351053], rat ovary [PMID:20450830]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"ET-2 is annotated secreted and EDNRA transmembrane [flag].","caveats":"No direct binding paper is shown; all three papers were read as abstracts only. Selectivity for ETA over ETB is shown in rat ovary only [PMID:20450830]. The dossier also lists pIC50 8.2 as the affinity field for the first paper [PMID:7647976].","key_references":[{"PMID":"7647976","why":"human vessels, ET-2 full agonist via ETA"},{"PMID":"20450830","why":"rat ovary, EDN2 contraction via EDNRA"},{"PMID":"31351053","why":"chicken EDNRA activated by EDN1/EDN2"}],"covers":["LR000462","LR003953"]},"LR000471":{"pair":"EFNA1 -> EPHA5","headline":"Database-asserted only: UniProt lists EphA receptors including EPHA5 as EFNA1 binders; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt PMID:18794797]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag]; no paper text on localisation.","caveats":"No curated paper evidence; support is a single UniProt annotation.","key_references":[],"covers":["LR000471","LR003962"]},"LR000507":{"pair":"EFNA5 -> EPHB2","headline":"Well supported direct binding, including a crystal structure; a cross-class (A-ephrin to B-receptor) pair.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A5 binds EphB2 with high affinity; exposing EphB2 cells to it caused receptor clustering, autophosphorylation, downstream signalling, growth cone collapse and neurite retraction [PMID:15107857]. Annotated stimulatory.","molecular_requirements":"The complex is a heterodimer by X-ray crystallography, distinct from the tetrameric EphB2-ephrin-B2 structure [PMID:15107857].","affinity_potency":[],"species_and_systems":"Cell-based and structural work annotated human [PMID:15107857]; an ELISA with Fc fusion proteins also showed ephrin-A5 binding EphB2, with species unspecified [PMID:22568954]. Pair listed for human and mouse, both ortholog-inferred.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No numeric affinity in our evidence; the abstract only says 'high affinity'. The ELISA paper was read through a browser and its quote is marked unverified [PMID:22568954].","key_references":[{"PMID":"15107857","why":"Binding, signalling and heterodimer structure of ephrin-A5/EphB2"},{"PMID":"22568954","why":"ELISA confirms ephrin-A5 binding to EphB2"}],"covers":["LR000507","LR003998"]},"LR000516":{"pair":"EFNB2 -> EPHA4","headline":"Cross-class pair with ELISA binding, rat neurite-repulsion data and structures (PDB, IntAct).","interaction_type":"direct binding","direction_and_effect":"Ephrin-B2 Fc bound EphA4, which can bind both A and B class ephrins [PMID:22568954]. In rat spiral ganglion explants, anti-ephrin-B2 or anti-ephrin-B3 antibodies each reduced repulsion by an EphA4 stripe; used together neurites crossed with no repulsion [PMID:12761826]. Annotated stimulatory.","molecular_requirements":"Ephrin-B2 and ephrin-B3 are redundant ligands for EphA4 in that system [PMID:12761826].","affinity_potency":[],"species_and_systems":"ELISA with Fc proteins, species unspecified [PMID:22568954]; rat neonatal explants [PMID:12761826]. Pair listed for human (ortholog-inferred) and mouse. Structures: PDB 2WO2, 3GXU [DB:PDB 2WO2] [DB:PDB 3GXU].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No numeric affinity in our evidence (ELISA 'apparent KD' not given as a value). ELISA quote was browser-read and unverified. IntAct has NMR and X-ray records [DB:IntAct].","key_references":[{"PMID":"22568954","why":"ELISA: ephrin-B2 Fc binds EphA4"},{"PMID":"12761826","why":"Ephrin-B2/B3 mediate EphA4 repulsion in rat explants"}],"covers":["LR000516","LR004007"]},"LR000525":{"pair":"EFNB3 -> EPHA4","headline":"Established pair with genetic and functional evidence in rodents; structures and binding records in databases.","interaction_type":"direct binding","direction_and_effect":"Lateral thalamic explants (EphA4+) had axonal growth inhibited on ephrin-B3 membranes, medial ones did not [PMID:12383247]. Mice lacking EphA4 or ephrinB3 lose left-right limb alternation and show synchrony [PMID:12649481]. Annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat brain explants [PMID:12383247]; mouse knockouts [PMID:12649481]. Pair listed for human (ortholog-inferred) and mouse. PDB 4BKF; BioGRID and IntAct records [DB:PDB 4BKF] [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"The rat explant result is correlative; EphA4 was not blocked [PMID:12383247]. The knockout paper does not measure binding [PMID:12649481]. Abstract level.","key_references":[{"PMID":"12649481","why":"EphA4 and ephrinB3 knockouts lose limb alternation"},{"PMID":"12383247","why":"Ephrin-B3 inhibits EphA4+ thalamic axons"}],"covers":["LR000525","LR004016"]},"LR004017":{"pair":"EFNB3 -> EPHB1","headline":"EphB1 acts on ephrin-B3 reverse signalling in mouse neuron migration; ELISA shows weak binding.","interaction_type":"direct binding","direction_and_effect":"EphB1 prevents cortical interneurons entering the striatum via ephrin-B3 reverse signalling, and acts as a stop signal for striatal neurons [PMID:25100946]. Ephrin-B3 Fc binds most weakly of the ephrin-Bs to all EphB receptors [PMID:22568954].","molecular_requirements":"Opposite outcomes come from different Src/FAK phosphorylation: reduced pSrc/pFAK in striatal neurons, increased in interneurons [PMID:25100946].","affinity_potency":[],"species_and_systems":"Curator annotated human for the migration paper; striatal anlage context and ELISA with species unspecified [PMID:25100946] [PMID:22568954]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). Reverse (ephrin-side) signalling is reported.","caveats":"ELISA quote unverified. No numeric affinity. Four confirmed rows, two shown. Species annotation of the migration paper is uncertain; the excerpt describes an EphB1-Fc binding assay on neurons [PMID:25100946].","key_references":[{"PMID":"25100946","why":"EphB1-ephrin-B3 reverse signalling in neuron migration"},{"PMID":"22568954","why":"ELISA of ephrin-B Fc binding to EphB receptors"}],"covers":["LR000526","LR004017"]},"LR002523":{"pair":"EGF -> AXL","headline":"EGF activates AXL kinase in human cancer cells, but via EGFR-AXL hetero-interaction; direct EGF-AXL binding is not shown.","interaction_type":"functional only","direction_and_effect":"EGF stimulated activation of Axl kinase; the paper reports a hetero-interaction between the two RTKs [PMID:27775700]. Axl phosphorylation by EGF was blocked by the EGFR inhibitor gefitinib but not by the Axl inhibitor BGB324 [PMID:27775700].","molecular_requirements":"EGFR activity is required; only the fully glycosylated mature 140 kDa Axl responded to EGF, not the 120 kDa Gas6-activated form [PMID:27775700].","affinity_potency":[],"species_and_systems":"Human glioblastoma cells, also seen in breast and head and neck cancer lines (western blot, kinase assay, co-IP, BiFC); mouse entry is ortholog-inferred [PMID:27775700].","localisation_and_range":"EGF is secreted and AXL is a transmembrane receptor [flag]; range not otherwise reported in our evidence.","caveats":"Curators note this is likely transactivation through EGFR, not direct EGF-AXL binding. Only one paper, read as abstract plus excerpts.","key_references":[{"PMID":"27775700","why":"EGF activates Axl via EGFR-Axl hetero-interaction in GBM cells"}],"covers":["LR002523","LR005791"]},"LR004026":{"pair":"EPGN -> EGFR","headline":"Epigen binds EGFR and is a partial agonist of receptor dimerization; supported by a structural study and database records.","interaction_type":"direct binding","direction_and_effect":"EPGN stabilises a different dimeric EGFR extracellular conformation than EGF and induces less stable dimers, making it a partial agonist of EGFR dimerization; this gives more sustained EGFR signalling and differentiation-associated responses in breast cancer cells [PMID:28988771]. GtoPdb records the action as binding [DB:GtoPdb].","molecular_requirements":"Acts on the EGFR extracellular region as a dimer; co-receptors not reported in our evidence [PMID:28988771].","affinity_potency":[],"species_and_systems":"Human ligand and receptor are recorded [PMID:28988771]; crystallography plus cell work in breast cancer cells. The mouse pair is ortholog-inferred. PDB 5WB8 is a structure of the pair [DB:PDB 5WB8].","localisation_and_range":"EPGN is flagged secreted, non-transmembrane, and EGFR is a transmembrane receptor [flag].","caveats":"One verified paper (full text available but no affinity values extracted). One additional row was judged as a different entity. UniProt lists EPGN among known EGFR ligands [DB:UniProt].","key_references":[{"PMID":"28988771","why":"Crystal structures and kinetics of EPGN-induced EGFR dimers"}],"covers":["LR000535","LR004026"]},"LR002532":{"pair":"EPHA1 -> EFNA3","headline":"EPHA1-EFNA3 rests on a single UniProt statement of low-affinity binding; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that EPHA1 binds EFNA3 with low affinity, and that EFNA1 is its probable cognate ligand [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Flags: EPHA1 non-secreted transmembrane receptor; EFNA3 non-secreted transmembrane [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows, no verified primary paper. Low affinity only per UniProt; no values.","key_references":[],"covers":["LR002532","LR005800"]},"LR002550":{"pair":"EPHA4 -> EFNA1","headline":"EPHA4-EFNA1 is supported by SPR/ELISA and BioGRID records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"IntAct lists direct interaction by ELISA and surface plasmon resonance [DB:IntAct]; BioGRID lists affinity capture-Western [DB:BioGRID]. UniProt says EphA4 is highly promiscuous and, on activation by EFNA1, induces NGEF phosphorylation by CDK5 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; the mouse pair is non-inferred.","localisation_and_range":"EFNA1 is flagged secreted, EPHA4 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002550","LR005818"]},"LR001803":{"pair":"EPHA4 -> EFNB1","headline":"EPHA4-EFNB1 rests on one SPR record in IntAct; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists surface plasmon resonance between the two proteins [DB:IntAct]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Six judged rows were review-only or abstract-insufficient; a single database record, no affinity values in our dossier.","key_references":[],"covers":["LR001803","LR005159"]},"LR005160":{"pair":"EPO -> CRLF3","headline":"Functional only: the Epo splice variant EV-3, not Epo itself, protects human iPSC neurons via CRLF3 in knock-out experiments.","interaction_type":"functional only","direction_and_effect":"EV-3, a natural Epo splice variant, prevented rotenone-induced apoptosis in wild-type human iPSC-derived neurons, but this protection was absent in CRLF3 knock-out neurons, so CRLF3 mediates the effect (agonist action) [PMID:37168680].","molecular_requirements":"EpoR but not betacR was reported expressed in these neurons (data not shown) [PMID:37168680]. Whether other subunits are needed: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human iPSC-derived neurons with CRISPR CRLF3 knock-out lines, in vitro [PMID:37168680].","localisation_and_range":"Not reported in our evidence; no annotation flags are listed for this pair.","caveats":"No direct binding of EV-3 or Epo to CRLF3 is shown in the abstract or excerpts; the sentence on binding in insect neurons is background citing other work. The experiments used EV-3, not full-length Epo. Rotenone stress model only.","key_references":[{"PMID":"37168680","why":"CRLF3 knock-out iPSC neurons lose EV-3 neuroprotection."}],"covers":["LR001804","LR005160"]},"LR002604":{"pair":"ERVH48-1 -> SLC1A5","headline":"Suppressyn (ERVH48-1) binds ASCT2 (SLC1A5) and inhibits syncytin-1-mediated trophoblast fusion.","interaction_type":"direct binding","direction_and_effect":"Suppressyn binds the syncytin-1 receptor ASCT2 and inhibits syn1-, but not syn2-mediated trophoblast syncytialization [PMID:23492904]. Curators classed it as an antagonist [PMID:23492904]. Knock-down promotes cell fusion [PMID:23492904].","molecular_requirements":"Reciprocal immunoprecipitation co-precipitated suppressyn and ASCT2 in doubly transfected cells, indicating direct binding [PMID:23492904]. Cell-associated and secreted suppressyn both bind ASCT2 per curator detail [PMID:23492904].","affinity_potency":[],"species_and_systems":"Human proteins; trophoblast cell lines (BeWo, HTR8/SVneo) and transfected cells [PMID:23492904].","localisation_and_range":"ERVH48-1 flagged secreted, SLC1A5 flagged transmembrane [flag].","caveats":"Full text excerpts support binding, but this is one paper. No affinity reported. The effect is on cell fusion, not classical signalling.","key_references":[{"PMID":"23492904","why":"Suppressyn binds ASCT2 and inhibits syncytin-1-driven fusion"}],"covers":["LR002604"]},"LR000543":{"pair":"F13A1 -> ITGB1","headline":"Factor XIII supports cell adhesion via beta1 integrins alpha9beta1 and alpha4beta1; ITGB1 evidence is heterodimer-level.","interaction_type":"functional only","direction_and_effect":"SW480 cells expressing alpha9beta1 adhered to FXIII [PMID:10816592], and FXIII promoted adhesion through alpha9beta1 or alpha4beta1 in G-361 or MOLT-3 cells [PMID:10816592].","molecular_requirements":"ITGB1 acts as the shared beta chain; its sole contribution is not tested.","affinity_potency":[],"species_and_systems":"Human cells [PMID:10816592]; mouse pair ortholog-inferred [flag].","localisation_and_range":"FXIII flagged secreted; ITGB1 non-secreted [flag].","caveats":"Chain-only caveat: ITGB1 evidence is inherited from alpha-beta heterodimers; adhesion assays only.","key_references":[{"PMID":"10816592","why":"FXIII adhesion via beta1 integrins"}],"covers":["LR000543","LR004034"]},"LR004035":{"pair":"F2 -> F2R","headline":"Thrombin (F2) cleaves the PAR1 exodomain at Arg41-Ser42 and binds it in SPR; recombinant evidence plus structures.","interaction_type":"direct binding","direction_and_effect":"Thrombin cleaved recombinant PAR1E at the Arg41-Ser42 activation site at concentrations known to induce cellular activation [PMID:10978167]. SPR on immobilised PAR1E and PAR1E S42P determined thrombin affinities [PMID:10978167]. Annotated stimulatory [flag].","molecular_requirements":"Activation is by proteolytic cleavage of the exodomain [PMID:10978167]. PDB 1NRN etc. show thrombin with PAR1 chain [DB:PDB 1NRN].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant PAR1 exodomain expressed in E. coli, SPR in vitro, not live cells [PMID:10978167]. Mouse pair is ortholog-inferred [flag].","localisation_and_range":"F2 flagged secreted, not transmembrane; F2R transmembrane [flag].","caveats":"Abstract-only; affinity values are not shown in the abstract excerpt. Three rows were different_entity. Enzyme-substrate rather than a classical agonist-receptor binding.","key_references":[{"PMID":"10978167","why":"SPR and MALDI cleavage mapping of thrombin on PAR1 exodomain"}],"covers":["LR000544","LR004035"]},"LR000552":{"pair":"F8 -> LRP1","headline":"FVIII binds LRP (cluster II) with high affinity by SPR; a clearance receptor interaction.","interaction_type":"direct binding","direction_and_effect":"In SPR with LRP cluster II, FVIII light chain showed high-affinity binding while the FVa light chain did not [PMID:12522143]. Annotation lists the effect as stimulatory; curator notes describe LRP1 as an endocytic clearance receptor.","molecular_requirements":"The FVIII a3-A3-C1 fragment bound LRP; peptide and antibody-fragment competition implicated the A3 region Lys(1804)-Ala(1834), notably Glu(1811)-Lys(1818); an FVIII/FV chimera retained reduced binding [PMID:12522143]. Both FVIII chains contribute to high-affinity interaction; a C2-domain site has lower affinity [PMID:12522143].","affinity_potency":[],"species_and_systems":"Purified FVIII fragments and LRP cluster II, species not stated in the abstract [PMID:12522143]; BioGRID reconstituted complex [DB:BioGRID 282746].","localisation_and_range":"F8 is annotated secreted [flag].","caveats":"Abstract-only; no numeric affinity in our evidence, and only LRP cluster II was tested rather than full-length LRP1.","key_references":[{"PMID":"12522143","why":"SPR mapping of FVIII A3 region binding to LRP cluster II"}],"covers":["LR000552","LR004043"]},"LR004044":{"pair":"F9 -> LRP1","headline":"Activated factor IXa binds LRP in vitro; FIXa only, as a clearance receptor interaction.","interaction_type":"direct binding","direction_and_effect":"Purified soluble LRP and full-length LRP showed similar binding to factor IXa [PMID:12522212]. A recombinant LRP cluster IV fragment interfered with factor IXa amidolytic activity [PMID:12522212]. Annotation lists effect as stimulatory.","molecular_requirements":"Binding involves the factor IXa surface loop Phe(342)-Asn(346) near the active site; variants showed reduced sLRP binding, and Asn(346)Asp had slower association to sLRP [PMID:12522212]. Curator notes say only activated IXa, not the zymogen, is bound.","affinity_potency":[],"species_and_systems":"Purified proteins, solid-phase and SPR; species not stated in the abstract [PMID:12522212]; BioGRID record [DB:BioGRID 301580].","localisation_and_range":"F9 annotated secreted [flag].","caveats":"Abstract-only; no numeric affinity in our evidence. The zymogen factor IX is not shown to bind.","key_references":[{"PMID":"12522212","why":"Factor IXa binding to LRP and loop mapping"}],"covers":["LR000553","LR004044"]},"LR002613":{"pair":"FAT1 -> GPC3","headline":"FAT1 C-terminal EGF-like domains bind GPC3 in liver cancer cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"GPC3 binding was mapped to the last four EGF-like domains of FAT1 (residues 4013-4181) by ELISA and flow cytometry [PMID:33420124]. Endogenous FAT1 was pulled down from HepG2 lysate by a GPC3 antibody [PMID:33420124]. Effect direction not reported in our evidence.","molecular_requirements":"The RTP domain (residues 3662-3788) and Laminin G-2nd EGF-like region (residues 3829-4050) showed non-specific GPC3 binding [PMID:33420124].","affinity_potency":[],"species_and_systems":"Human proteins in HCC cells including HepG2; the mouse pair is ortholog-inferred. An IntAct co-IP record exists [DB:IntAct].","localisation_and_range":"Both are flagged not secreted; GPC3 is flagged receptor [flag]. FAT1 is described as a cell-surface transmembrane protein and GPC3 as a cell-surface proteoglycan [PMID:33420124], so any signaling would be contact-dependent.","caveats":"Single paper, read as abstract only (excerpts available). The ligand/receptor direction is an annotation; both are membrane proteins. No affinity reported.","key_references":[{"PMID":"33420124","why":"Identifies and maps the FAT1-GPC3 interaction."}],"covers":["LR002613","LR005880"]},"LR000561":{"pair":"FBN1 -> ITGB3","headline":"Fibrillin-1 supports adhesion through integrin alphaVbeta3 in human cell assays; curated databases agree, but no purified-protein binding data for this pair.","interaction_type":"functional only","direction_and_effect":"Fibrillin-1 acts as an adhesion ligand for alphaVbeta3: human fibroblast adhesion to fibrillin-1 fragments involved alpha v beta 3 (and mainly alpha 5 beta 1) [PMID:12807887], and A375-SM melanoma cells bound RGD-containing fibrillin-1 fragments mainly through alpha v beta 3 [PMID:12807887]. In HUVECs, fibrillin-1 fragment PF14 signalled via alphav beta3 and alpha5 beta1 integrins, raising calcium and enhancing proliferation and migration [PMID:20686071]. UniProt and Reactome describe ITGAV:ITGB3 as an RGD-dependent fibrillin-1 receptor [DB:UniProt] [DB:Reactome R-HSA-265416].","molecular_requirements":"The receptor is the alphaV/beta3 heterodimer (ITGAV:ITGB3), so both chains are needed [DB:Reactome R-HSA-265416]. The RGD-containing fibrillin-1 fragment PF14 was active, PF9 was not [PMID:20686071]. Adhesion was Arg-Gly-Asp and cation dependent [PMID:12807887].","affinity_potency":[],"species_and_systems":"Human cells (dermal fibroblasts, melanoma lines, HUVECs) with human fibrillin-1 fragments or microfibrils. The mouse pair is projected from human evidence only; no mouse experiments in our evidence.","localisation_and_range":"Fibrillin-1 is flagged secreted [flag]; it is described as a microfibril component, so signalling is likely local/contact with matrix (from paper text [PMID:12807887]).","caveats":"All three papers were read as abstracts only. Evidence is cell adhesion/signalling, with antibody or fragment dependence, not direct binding of purified FBN1 to ITGB3; no affinity for alphaVbeta3 reported. Fibrillin-1 binding to alpha5beta1 was stronger in fibroblasts [PMID:12807887].","key_references":[{"PMID":"12807887","why":"Fibroblast and melanoma adhesion to fibrillin-1 via alphaVbeta3 and alpha5beta1"},{"PMID":"20686071","why":"alphaVbeta3/alpha5beta1-mediated signalling by fibrillin-1 fragment in HUVECs"}],"covers":["LR000561","LR004052"]},"LR004053":{"pair":"FBN1 -> ITGB6","headline":"Fibrillin-1 binds integrin alphaVbeta6 directly (SPR, Kd about 0.45 uM); database records agree.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaVbeta6 is identified as a cellular receptor for human fibrillin-1 [PMID:17158881]; UniProt states ITGAV:ITGB6 mediates RGD-dependent cell adhesion to FBN1 [DB:UniProt] and Reactome lists fibrillin-1 binding integrins [DB:Reactome R-HSA-2328037]. Effect on signalling not reported in our evidence.","molecular_requirements":"Receptor is the alphaV:beta6 heterodimer [DB:UniProt]. The TB4 domain carries an RGD loop; module requirements for alphaVbeta6 differ from alphaVbeta3, and a linked N-terminal calcium-binding EGF-like domain can modulate alphaV integrin specificity [PMID:17158881].","affinity_potency":[{"value":"Kd approximately 0.45 uM","assay":"surface plasmon resonance","system":"recombinant human fibrillin-1 fragments with alphaVbeta6","cite":"PMID:17158881"}],"species_and_systems":"Human fibrillin-1 fragments and human integrin; mouse pair is ortholog-inferred, not tested.","localisation_and_range":"Fibrillin-1 is flagged secreted [flag]; matrix microfibril component per paper text [PMID:17158881].","caveats":"Single primary paper, read as abstract only. A further judged paper was review-only.","key_references":[{"PMID":"17158881","why":"SPR identification of alphaVbeta6 as fibrillin-1 receptor, Kd about 0.45 uM"}],"covers":["LR000562","LR004053"]},"LR002622":{"pair":"FCN2 -> TLR4","headline":"Ficolin-2 is reported to bind TLR4 on macrophages and DCs; abstract-level, single paper, binding assay not described.","interaction_type":"direct binding","direction_and_effect":"Ficolin-2 binds TLR4 on macrophages and DCs and promotes antigen presentation to CD8+ T cells; it activates macrophages and promotes M1 polarisation (agonist) [PMID:28844702].","molecular_requirements":"Not reported in our evidence (no co-receptor such as MD-2 is mentioned).","affinity_potency":[],"species_and_systems":"Curator fields say human, but the abstract also uses murine tumour models, ficolin-A (a mouse ficolin-2-like molecule) and knockout mice [PMID:28844702].","localisation_and_range":"FCN2 is flagged secreted [flag]; serum protein.","caveats":"Abstract only; the binding assay is not described, so direct binding rests on one sentence. Antitumour effect partly shown with mouse ficolin-A [PMID:28844702].","key_references":[{"PMID":"28844702","why":"ficolin-2 binds TLR4, antitumour immunity"}],"covers":["LR002622"]},"LR000570":{"pair":"FGA -> ITGB2","headline":"Fibrinogen engages beta2 integrins alphaM-beta2 and alphaX-beta2; adhesion evidence, two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"alphaEC supported adhesion of alphaMbeta2- and alphaXbeta2-expressing cells, inhibited by anti-beta2 antibody [PMID:11588042]; neutrophils adhered to fibrinogen via CD11c/CD18 [PMID:1671533].","molecular_requirements":"The beta2 chain is needed with an alpha chain (alphaM or alphaX); beta2 alone was not tested. The alpha I domain binds alphaEC [PMID:11588042].","affinity_potency":[],"species_and_systems":"Human cells (curator fields for PMID:11588042; species not recorded for PMID:1671533).","localisation_and_range":"FGA flagged secreted; ITGB2 not secreted [flag].","caveats":"Abstract only for both; cell adhesion rather than purified binding; chain-level attribution. One further paper abstract_insufficient.","key_references":[{"PMID":"11588042","why":"alphaEC binds alphaM/alphaX beta2 integrins"},{"PMID":"1671533","why":"CD11c/CD18 and Aalpha N-terminus"}],"covers":["LR000570"]},"LR007014":{"pair":"FGA:FGB:FGG -> ITGAM:ITGB2","headline":"Fibrinogen-dependent adhesion of activated eosinophils is mediated by alphaM-beta2; functional only, one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Airway eosinophils adhered to fibrinogen among other ligands, blocked by anti-alphaMbeta2; IL-5 reproduced this in blood eosinophils, which did not adhere (agonist-like adhesion) [PMID:16601240].","molecular_requirements":"Requires the activated alphaMbeta2 conformation (CBRM1/5-reactive) [PMID:16601240]; subunit requirements on fibrinogen not reported.","affinity_potency":[],"species_and_systems":"Eosinophils from airway after segmental antigen challenge; species not recorded in our evidence [PMID:16601240].","localisation_and_range":"Ligand complex flagged not secreted [flag].","caveats":"Abstract only; fibrinogen is one of several adhesive substrates; no purified binding or affinity.","key_references":[{"PMID":"16601240","why":"eosinophil adhesion via activated alphaMbeta2"}],"covers":["LR007014"]},"LR001812":{"pair":"FGB -> TLR4","headline":"Functional and database support for fibrinogen as an endogenous TLR4 ligand; no direct binding measurement in our evidence.","interaction_type":"functional only","direction_and_effect":"Fibrinogen exposure increased inflammatory cytokine production by monocytes from pre-eclamptic patients, not normotensive pregnant controls; the authors suggest a fibrinogen-TLR4 axis [PMID:24661950]. Reactome records that cleaved fibrinogen products bind TLR4:LY96 [DB:Reactome R-HSA-8870678].","molecular_requirements":"Reactome describes the receptor as the TLR4:LY96 complex and the ligand as cleaved fibrinogen products, so LY96 and the processed form may matter [DB:Reactome R-HSA-8870678].","affinity_potency":[],"species_and_systems":"Human monocytes from pre-eclamptic and normotensive pregnant patients [PMID:24661950]. Mouse record is ortholog-inferred.","localisation_and_range":"FGB is flagged secreted [flag]; plasma fibrinogen levels were higher in pre-eclamptic patients [PMID:24661950].","caveats":"Abstract only; the abstract does not show TLR4 dependence directly (no blocking result reported), and the effect was absent in normotensive monocytes [PMID:24661950]. A review-only paper was also judged. Fibrinogen here is the whole protein, not FGB specifically.","key_references":[{"PMID":"24661950","why":"Fibrinogen activates monocytes from pre-eclamptic patients, framed as TLR4 axis"}],"covers":["LR001812","LR005167"]},"LR004080":{"pair":"FGF1 -> FGFR3","headline":"Well-supported direct FGF1-FGFR3 binding, with crystal structure, binding and signalling data in human proteins.","interaction_type":"direct binding","direction_and_effect":"The crystal structure of three-Ig FGFR3c in complex with FGF1 is reported, with FGF1 described as binding promiscuously to each of the seven principal FGFRs [PMID:14732692]. FGF1 binds FGFR3c more strongly than FGF2 but gives lower activation-loop phosphorylation [PMID:21894939]. FGF1 is the agonist in these assays.","molecular_requirements":"The D1 domain and D1-D2 linker are dispensable for binding, and the three-Ig form shows lower affinity for FGF1 and heparin than the two-Ig form [PMID:14732692]. Ternary complexes with FGF1 and FGFR3c form with perlecan heparan sulfate [PMID:24509440].","affinity_potency":[],"species_and_systems":"Human FGF1 and FGFR3 in recombinant structure [PMID:14732692]; HEK 293T cells [PMID:21894939]; ternary-complex assay [PMID:24509440]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 secreted; FGFR3 transmembrane receptor [flag].","caveats":"Numerical affinities are not given in our evidence. Two of the papers were abstract level [PMID:14732692]. A BaF3 paper was browser-read with quote pending spot-check [PMID:16597617]. Two review-only papers were judged. Database: PDB [DB:PDB 1RY7], BioGRID, IntAct.","key_references":[{"PMID":"14732692","why":"Crystal structure of FGFR3c with FGF1"},{"PMID":"21894939","why":"FGF1 versus FGF2 binding and phosphorylation at FGFR3c"},{"PMID":"24509440","why":"Heparan-sulfate-dependent FGF1-FGFR3c ternary complexes"}],"covers":["LR000596","LR004080"]},"LR004062":{"pair":"FGF16 -> FGFR3","headline":"FGF16 shows activity toward FGFR3b-expressing cells and FGFRc isoforms in a BaF3 panel; functional evidence only.","interaction_type":"functional only","direction_and_effect":"These FGFs activated FGFRc isoforms and FGFR4 with high activity and, unlike other FGFs, consistently showed activity toward FGFR3b-expressing cells [PMID:16597617]. Agonist.","molecular_requirements":"Isoform matters: the paper notes activity on both c forms and FGFR3b [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF16 flagged secreted; FGFR3 a membrane receptor [flag].","caveats":"Single functional paper, read as full text in a browser (quote unverified); activity is mitogenesis in BaF3 cells, not binding. Two other judged rows were review-only.","key_references":[{"PMID":"16597617","why":"BaF3 panel including FGFR3b"}],"covers":["LR000578","LR004062"]},"LR004071":{"pair":"FGF18 -> FGFR4","headline":"FGF18 activates the two-Ig-domain FGFR4 in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 activated the two Ig-like domain forms of FGFR4 (4delta) [PMID:16597617]. Agonist.","molecular_requirements":"The active form is the two Ig-like domain FGFR4 variant [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF18 flagged secreted; FGFR4 flagged secreted and transmembrane [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified; one abstract-insufficient paper not shown [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFR4 delta"}],"covers":["LR000587","LR004071"]},"LR002631":{"pair":"FGF2 -> ITGB3","headline":"FGF2 binds integrin alphavbeta3 and its integrin-binding mutants antagonise FGF2 signalling; evidence concerns the heterodimer.","interaction_type":"direct binding","direction_and_effect":"WT FGF2 bound immobilised soluble \u03b1v\u03b23 on SPR, and integrin-binding-defective FGF2 mutants were inactive and suppressed WT FGF2 signalling in NIH3T3 cells and endothelial cells [PMID:28302677]. UniProt notes ITGAV:ITGB3 binds FGF2 and is essential for FGF2 signalling [DB:UniProt].","molecular_requirements":"Evidence is for \u03b1v\u03b23, so \u03b23 needs its \u03b1v partner; \u03b15\u03b21 binding was also suggested [PMID:28302677].","affinity_potency":[{"value":"Kd 7.75 \u00d7 10\u22128 M","assay":"SPR, WT FGF2 on immobilised soluble \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"}],"species_and_systems":"Human recombinant proteins; NIH3T3 (mouse) and HUVEC cell assays [PMID:28302677]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor non-secreted [flag].","caveats":"The curated evidence sentence is background from earlier work. Docking and interface mapping are predicted. Single paper.","key_references":[{"PMID":"28302677","why":"FGF2-\u03b1v\u03b23 SPR binding and antagonist mutants"}],"covers":["LR002631","LR005897"]},"LR000615":{"pair":"FGF2 -> SDC1","headline":"FGF2 binds syndecan-1 through its heparan sulfate chains in several assays; mostly proteoglycan-chain binding.","interaction_type":"direct binding","direction_and_effect":"bFGF bound only the HS chains of syndecan-1 and -4 ectodomains by BIAcore [PMID:15226297]. FGF2-GST affinity precipitation bound human SDC1 via heparitinase-cleavable HS [PMID:16982797]. Cotransfection of syndecans with FGFR1 raised specific 125I-bFGF binding two- to three-fold in K562 cells [PMID:8609172]. BioGRID lists co-purification and affinity-capture records [DB:BioGRID].","molecular_requirements":"Binding needs HS chains, not CS chains or core protein [PMID:15226297; PMID:16982797]. In K562 cells syndecan supports FGF2 binding to FGFR1 [PMID:8609172]. Lacritin and FGF2 appear to target different forms of SDC1 [PMID:16982797].","affinity_potency":[],"species_and_systems":"BIAcore on murine mammary epithelial syndecan ectodomains [PMID:15226297]; HEK293T cells expressing human SDC1 [PMID:16982797]; human K562 cells [PMID:8609172].","localisation_and_range":"SDC1 is flagged transmembrane and FGF2 secreted [flag], so FGF2 presented at the cell surface in cis or trans.","caveats":"Evidence is binding to HS chains, a feature shared with many proteoglycans, not a specific protein-protein interface. FGF2 was a positive control in one paper [PMID:16982797]. Two further papers were judged abstract_insufficient or review_only and are not shown.","key_references":[{"PMID":"15226297","why":"BIAcore: bFGF binds HS chains of syndecan-1"},{"PMID":"16982797","why":"FGF2-GST pull-down of SDC1, full text"},{"PMID":"8609172","why":"Syndecans increase FGF2 binding to FGFR1"}],"covers":["LR000615","LR004099"]},"LR000606":{"pair":"FGF23 -> FGFR4","headline":"FGF23 binds and activates FGFR4 in SPR/mitogenesis and BaF3 assays; stimulatory.","interaction_type":"direct binding","direction_and_effect":"FGF23 binds and activates FGFR4 and the c isoforms of FGFR1-3 [PMID:16081635, PMID:16597617]. Curated as agonist [PMID:16081635].","molecular_requirements":"Highly sulfated, longer GAGs, not standard heparan sulfate, promote activity; removal of cell surface GAGs abolishes it [PMID:16081635].","affinity_potency":[],"species_and_systems":"Human reagents per curators; opossum kidney cells for signaling [PMID:16081635]; BaF3 screen species unspecified [PMID:16597617].","localisation_and_range":"FGF23 secreted [flag]; paper describes circulation to kidney [PMID:16081635].","caveats":"Abstract-only reading; mouse pair is ortholog-inferred. PDB 7YSW lists FGF23 and FGFR4 chains [DB:PDB 7YSW].","key_references":[{"PMID":"16081635","why":"SPR and mitogenesis for FGF23"},{"PMID":"16597617","why":"BaF3 screen"}],"covers":["LR000606","LR004090"]},"LR001821":{"pair":"FGF3 -> FGFRL1","headline":"FGFRL1 binds FGF3 with high affinity but lacks a kinase domain; proposed decoy receptor.","interaction_type":"direct binding","direction_and_effect":"Soluble and membrane-bound FGFRL1 bind FGF3 among other FGFs with high affinity by dot blot, cell binding and SPR [PMID:19920134]. FGFRL1 is proposed as a decoy and antagonizes FGFR signaling in Xenopus embryos [PMID:19920134].","molecular_requirements":"No split tyrosine kinase domain; ectodomain shed from cells [PMID:19920134].","affinity_potency":[],"species_and_systems":"C2C12, HEK293 cells and Xenopus embryos; human per curators [PMID:19920134].","localisation_and_range":"Both shed and membrane-bound forms bind [PMID:19920134].","caveats":"Abstract-only reading; no FGF3-specific affinity number. Antagonism is shown for FGFR signaling generally. Mouse pair is projected.","key_references":[{"PMID":"19920134","why":"FGFRL1 binds FGF3 and acts as decoy"}],"covers":["LR001821","LR005176"]},"LR004107":{"pair":"FGF4 -> FGFR3","headline":"FGF4 activates FGFR3 IIIc, not IIIb, in a BaF3 screen; structural paper supports isoform specificity.","interaction_type":"functional only","direction_and_effect":"FGF4 binds and activates IIIc forms of FGFR1-3 [PMID:11486033]; FGFs 4, 5, 6 and 8 activate c receptor splice forms in BaF3 cells [PMID:8663044]. No numeric affinity.","molecular_requirements":"IIIc isoform required [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human FGF4 structure [PMID:11486033]; BaF3 species unspecified [PMID:8663044].","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only readings; gene-level row hides isoform specificity.","key_references":[{"PMID":"11486033","why":"FGF4 structure"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000623","LR004107"]},"LR000624":{"pair":"FGF4 -> FGFR4","headline":"Weakly supported and partly contradicted: papers say FGF4 shows little activity toward FGFR4.","interaction_type":"conflicting","direction_and_effect":"The pair is annotated stimulatory, but the FGF4 structure/mutagenesis paper states FGF4 shows little activity towards FGFR4 [PMID:11486033]. The BaF3 survey reports FGF4 activating c splice forms of receptors [PMID:8663044]; FGFR4 is not named in the evidence sentence.","molecular_requirements":"Specificity is described as arising from FGF/FGFR sequence differences and the IIIb/IIIc alternative exons; heparin binding sites were mapped on FGF4 [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the mutagenesis paper (abstract only) [PMID:11486033]; BaF3 assays with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGF4 is flagged secreted and non-transmembrane [flag]; FGFR4 is flagged as a transmembrane receptor [flag].","caveats":"No paper shows FGF4 binding or activating FGFR4; the main abstract says the opposite. Papers were read as abstracts (PMID:8663044 as a browser-read quote pending spot-check).","key_references":[{"PMID":"11486033","why":"States FGF4 has little activity towards FGFR4; maps receptor and heparin sites"},{"PMID":"8663044","why":"BaF3 survey, FGF4 activates c splice forms"}],"covers":["LR000624","LR004108"]},"LR004116":{"pair":"FGF6 -> FGFR3","headline":"Database-asserted only; no curated paper supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect is reported in our evidence; UniProt lists FGF6 among interactors of FGFR3 [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our evidence. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"No papers were shown (0 papers judged; abstract_insufficient and review_only rows only). The sole support is a UniProt subunit statement.","key_references":[],"covers":["LR000632","LR004116"]},"LR000633":{"pair":"FGF6 -> FGFR4","headline":"FGF6 binds FGFR4 in a ligand competition experiment, but weaker than aFGF and K-FGF; limited data.","interaction_type":"direct binding","direction_and_effect":"FGF-6 bound FGFR-4 in ligand competition experiments, and ligand binding to FGFR-4 induced receptor autophosphorylation [PMID:1385111]. The pair is annotated stimulatory.","molecular_requirements":"FGFR-4 is not alternatively spliced in the region that determines specificity in FGFR-1/2 [PMID:1385111]. Heparin requirement is not reported for FGF6 in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; abstract-only reading [PMID:1385111]; BaF3 survey with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGFR4 is flagged as a transmembrane receptor [flag]; localisation of FGF6 is not reported in our evidence.","caveats":"FGF-6 was not the highest-affinity ligand (aFGF, then K-FGF/hst-1, then bFGF are stronger) [PMID:1385111]. No affinity value is given for FGF6. The BaF3 sentence cited concerns c splice forms and does not name FGFR4 [PMID:8663044].","key_references":[{"PMID":"1385111","why":"FGF-6 binds FGFR-4 in competition experiments"},{"PMID":"8663044","why":"BaF3 survey (c forms; FGFR4 not named)"}],"covers":["LR000633","LR004117"]},"LR004125":{"pair":"FGF9 -> FGFR1","headline":"FGF9 activates FGFR1c in BaF3 assays; structure and database interaction records exist.","interaction_type":"functional only","direction_and_effect":"FGF9 subfamily members activated FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. FGFs 2 and 9 preferentially activate c splice forms [PMID:8663044].","molecular_requirements":"c splice form is the preferred responder [PMID:8663044]. PDB 5W59 has a chain of each partner [DB:PDB 5W59]; IntAct records surface plasmon resonance [DB:IntAct]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:16597617][PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Both papers use the same BaF3 readout with browser-read quotes pending spot-check; neither sentence names FGFR1 explicitly. No affinity in our evidence.","key_references":[{"PMID":"16597617","why":"FGF9 subfamily activates FGFRc isoforms"},{"PMID":"8663044","why":"FGF9 preferentially activates c forms"}],"covers":["LR000641","LR004125"]},"LR000642":{"pair":"FGF9 -> FGFR2","headline":"FGF9 efficiently activates FGFR2c, shown by direct binding and mitogenesis; broader BaF3 support.","interaction_type":"direct binding","direction_and_effect":"FGF-9 efficiently activates the c splice form of FGFR2 and FGFR3 [PMID:8576175]. FGF9 subfamily members activated FGFRc isoforms with high activity [PMID:16597617]. Agonist.","molecular_requirements":"c splice form of FGFR2 is the efficiently activated one [PMID:8576175]. BioGRID has a protein-peptide record [DB:BioGRID]; Reactome records concern FGFR2 mutant binding generally [DB:Reactome].","affinity_potency":[],"species_and_systems":"Murine FGF-9 expressed in mammalian cells and E. coli, tested by direct binding to soluble and cell-surface FGFR splice variants and mitogenesis (abstract only) [PMID:8576175]; BaF3 cells with unspecified species [PMID:16597617][PMID:8663044]. Both human and mouse pairs are non-inferred.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"No affinity value in our evidence. The cited 1996 paper used murine ligand; the curator's species label of human may not match. BaF3 quotes are browser-read and pending spot-check.","key_references":[{"PMID":"8576175","why":"Direct binding and mitogenesis; FGF-9 activates FGFR2c"},{"PMID":"16597617","why":"FGF9 subfamily activates FGFRc isoforms"}],"covers":["LR000642","LR004126"]},"LR002640":{"pair":"FGG -> ITGB3","headline":"Fibrinogen gamma chain binds alphaIIbbeta3 (beta3 chain) by structure and binding assays; alphaVbeta3 also reported.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the gammaC peptide bound to alphaIIbbeta3, with the MIDAS ion on beta3 binding the gammaC Asp [PMID:18710925]. RGD binding activates high-affinity fibrinogen binding [PMID:2018974]. Fibrinogen bound activated alphaIIbbeta3 on murine platelets [PMID:23551977]. Fibrinogen was recognised by alphaVbeta3 and alphaIIbbeta3 [PMID:15031111].","molecular_requirements":"Binding needs the alpha/beta heterodimer; beta3 alone is not tested by these papers as the full receptor. Chain-level separation of fibrinogen is not made in [PMID:2018974].","affinity_potency":[],"species_and_systems":"Human structures and platelets [PMID:18710925][PMID:2018974]; mouse platelets in vivo [PMID:23551977]; human fibrinogen on mouse trophoblasts [PMID:15031111].","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"Several papers abstract-only. PDB 2VDO-2VDR [DB:PDB 2VDO], IntAct ELISA and BioGRID records support binding [DB:IntAct][DB:BioGRID].","key_references":[{"PMID":"18710925","why":"Structure of alphaIIbbeta3 with fibrinogen gammaC peptide"},{"PMID":"23551977","why":"Fibrinogen-bound alphaIIbbeta3 on mouse platelets in vivo"},{"PMID":"2018974","why":"RGD activation of fibrinogen binding"}],"covers":["LR002640","LR005906"]},"LR007203":{"pair":"FLRT1:TENM2 -> ADGRL1","headline":"Complex-as-ligand pair supported only by database records; no curated paper has judged it.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper. UniProt says ADGRL1 is a receptor for TENM2 mediating heterophilic synaptic cell-cell contact [DB:UniProt, PMID:35907405], and that TENM2 acts as a ligand of ADGRL1 and ADGRL3 on adjacent cells [DB:UniProt, PMID:21724987]. IntAct lists an anti-tag coimmunoprecipitation association [DB:IntAct EBI-54534689, PMID:33961781].","molecular_requirements":"The ligand is a FLRT1:TENM2 complex; the records do not show that both subunits are needed together, nor which subunit contacts ADGRL1 (not reported in our evidence).","affinity_potency":[],"species_and_systems":"Species of the experiments is not reported in our evidence; the pair is listed as human.","localisation_and_range":"Complex flagged membrane-bound, not secreted [flag]; UniProt describes ligand and receptor on adjacent cells, i.e. contact-dependent [DB:UniProt, PMID:21724987].","caveats":"Rests on database records alone. The records concern TENM2-ADGRL1 and do not show FLRT1 and TENM2 acting as one joint ligand; the IntAct record's partners are not detailed in our evidence.","key_references":[],"covers":["LR007203"]},"LR004143":{"pair":"FN1 -> ITGA4","headline":"Fibronectin is reported as a ligand of the alpha4 integrin via CS-1, but both papers study alpha4beta1 and are abstract-level.","interaction_type":"functional only","direction_and_effect":"The fibronectin CS-1 peptide costimulated T-cell proliferation exclusively through alpha4beta1 and not alpha4beta7 [PMID:9842903]. CS-1 and Hep II fibronectin ligands triggered different intracellular events and migration in B lymphoid cells [PMID:9117345]. Agonist/adhesion.","molecular_requirements":"Both papers refer to the alpha4beta1 dimer, so alpha4 alone is not tested. Alpha4beta7 did not mediate costimulation by CS-1 [PMID:9842903].","affinity_potency":[],"species_and_systems":"T cells and B lymphoid cells in vitro; species not stated in our evidence; mouse pair is orthology-inferred.","localisation_and_range":"FN1 flagged secreted; matrix-to-cell contact is inferred from flags [flag].","caveats":"No direct binding assay is in the shown evidence; IntAct has one FACS record [DB:IntAct]. 2 more papers were abstract-insufficient.","key_references":[{"PMID":"9842903","why":"CS-1 costimulates T cells through alpha4beta1"},{"PMID":"9117345","why":"alpha4beta1 binding to CS-1/Hep II induces migration and signalling"}],"covers":["LR000659","LR004143"]},"LR000660":{"pair":"FN1 -> ITGA5","headline":"Fibronectin binds integrin alpha5beta1; supported by epitope mapping and a mouse in vivo study, plus curated databases.","interaction_type":"direct binding","direction_and_effect":"FN1 acts as an agonist ligand of alpha5beta1; muscle-secreted FN1 drives hepatic autophagy through alpha5beta1 and IKKalpha/beta-JNK1-BECN1 signalling [PMID:36812915]. Annotated stimulatory [flag].","molecular_requirements":"High-affinity binding to the fibronectin central cell-binding domain needs both the RGD site and the adjacent synergy site; the synergy site is recognised mainly by the alpha5 N-terminal repeats and RGD binding mainly by beta1 [PMID:9211865]. The receptor is the alpha5beta1 heterodimer, so ITGB1 is needed alongside ITGA5. Reactome lists an alpha5beta1:FN1 dimer complex [DB:Reactome]; UniProt says ITGA5:ITGB1 is a receptor for FN1 with R-G-D-dependent adhesion [DB:UniProt].","affinity_potency":[],"species_and_systems":"Binding mapping with human proteins/antibodies [PMID:9211865]; hESC integrin screen [PMID:23154389]; mouse exercise model [PMID:36812915]. The mouse pair is ortholog-inferred, not separately tested.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that. Muscle-secreted circulating FN1 acts on liver, i.e. endocrine-type signalling [PMID:36812915].","caveats":"All three papers were read as abstracts (two with partial full-text excerpts). PMID:23154389 only names FN-binding ITGA5 and shows integrin expression changes, so it is weak. Structures with a P02751 and a P05556 chain exist [DB:PDB 7NWL].","key_references":[{"PMID":"9211865","why":"Maps the RGD and synergy sites to beta1 and alpha5"},{"PMID":"36812915","why":"In vivo functional role of FN1-alpha5beta1 in liver autophagy"}],"covers":["LR000660","LR004144"]},"LR004152":{"pair":"FN1 -> ITGB8","headline":"Beta8-containing integrins mediate chick neuron interaction with fibronectin; functional evidence only, in chick.","interaction_type":"functional only","direction_and_effect":"An anti-beta8 antibody inhibited sensory neurite outgrowth on fibronectin-coated substrata; antibodies to beta1 and beta8 were completely effective only in combination on the C-terminal 40-kDa fibronectin fragment [PMID:7542940].","molecular_requirements":"Beta8 acts with one or more unidentified alpha subunits; beta1 also contributes [PMID:7542940].","affinity_potency":[],"species_and_systems":"Chick embryonic sensory neurons; human and mouse pairs are inferred by homology [PMID:7542940].","localisation_and_range":"Fibronectin flagged secreted [flag]; matrix substrate, inferred from the assay.","caveats":"Antibody blocking, no direct binding, no affinity. Abstract only. The paper is per beta8 subunit; the binding entity is an alpha/beta heterodimer.","key_references":[{"PMID":"7542940","why":"First ligands for beta8 integrins incl. fibronectin"}],"covers":["LR000668","LR004152"]},"LR004161":{"pair":"GAL -> GALR2","headline":"Galanin binds and activates GALR2 with sub-nanomolar to nanomolar affinity in human receptor assays; well supported.","interaction_type":"direct binding","direction_and_effect":"Galanin is a full agonist: human GALR2 signals mainly via phosphatidylinositol hydrolysis and calcium mobilisation [PMID:9880084], and GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. hGALR2 tolerates N-terminal extension and C-terminal deletion of galanin [PMID:9880084]. Amino-terminal galanin fragments displace binding; carboxy-terminal fragments do not [PMID:9685625].","affinity_potency":[{"value":"Ki 0.86 +/- 0.12 nM","assay":"125I-galanin competition binding","system":"human GalR2","cite":"PMID:9480833"},{"value":"K(D) = 0.3 nM","assay":"125I-galanin radioligand binding","system":"recombinant human GALR2","cite":"PMID:9832121"},{"value":"<10 nM","assay":"binding affinity","system":"CHO cells overexpressing hGalR2","cite":"PMID:11600206"}],"species_and_systems":"Experiments used human GALR2 in HEK-293 and CHO cells, plus a cloned mouse GalR2 shown to be functional [PMID:9832122]. The mouse pair is projected from human evidence.","localisation_and_range":"GAL is flagged as secreted and GALR2 as a transmembrane receptor [flag].","caveats":"All papers were read as abstracts only. [PMID:24517231] is mainly about spexin activating GALR2/3.","key_references":[{"PMID":"9480833","why":"Cloning of human GALR2 with Ki 0.86 nM galanin binding"},{"PMID":"9832121","why":"Kd 0.3 nM binding and PLC/calcium coupling of human GALR2"},{"PMID":"9880084","why":"Functional signalling of human GALR2 via phosphoinositide hydrolysis"}],"covers":["LR000677","LR004161"]},"LR007212":{"pair":"GAL -> GALR2:GPR151","headline":"Galanin is shown to act at GALR2 with beta-arrestin2 bias; GPR151's role is not shown.","interaction_type":"functional only","direction_and_effect":"GAL favours beta-arrestin2 recruitment at GALR2, unlike spexin which is G-protein-biased at the same receptor, shown with Galr2 and Galr3 knockout mice [PMID:42635078]. GtoPdb lists galanin as a full agonist at GALR2 [DB:GtoPdb].","molecular_requirements":"GPR151 is not individually tested; a GALR2:GPR151 complex requirement is not reported in our evidence [PMID:42635078].","affinity_potency":[],"species_and_systems":"Colitis study with knockout mice and intestinal epithelial-specific Gnaq/Arrb2 knockouts; the dossier lists human as experiment species, and the paper was read as an abstract only [PMID:42635078].","localisation_and_range":"GAL is flagged as secreted; the receptor entry is flagged as a transmembrane receptor [flag].","caveats":"Abstract-only evidence concerns GALR2 alone, not the GALR2:GPR151 complex. One further paper was judged review-only.","key_references":[{"PMID":"42635078","why":"Biased GALR2 signalling by GAL (beta-arrestin2) versus spexin"}],"covers":["LR007212"]},"LR012450":{"pair":"GAS1 -> PTCH2:SMO","headline":"GAS1 is described as a Hedgehog co-receptor for PTCH2 by UniProt only; no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes GAS1 as a coreceptor that binds ShhN and transfers it to its patched receptor (PTCH1 or PTCH2), followed by activation [DB:UniProt].","molecular_requirements":"GAS1 acts as co-receptor for ShhN handoff [DB:UniProt]. Whether SMO is bound directly is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No judged paper; two papers are pending. Experimental species are not reported in our evidence.","localisation_and_range":"GAS1 is flagged as non-secreted and as a receptor [flag].","caveats":"Database-only support; GAS1 is a co-receptor, so this may not be direct ligand-receptor binding.","key_references":[],"covers":["LR012450"]},"LR007221":{"pair":"GDF1 -> ACVR1B:ACVR2B","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at the ACVR1B and ACVR2B subunits (listed separately) [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. Three papers were review-only and three abstract-insufficient. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR007221"]},"LR004170":{"pair":"GDF10 -> ACVR1B","headline":"Functional evidence only: GDF10 (BMP-3b) activity needs ALK-4 with ActRIIA in mouse C2C12 cells; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"BMP-3b (GDF10) stimulated activin/TGF-beta-responsive promoters and directly activated Smad2/3 phosphorylation and PAI-1 expression, while failing to activate Smad1/5/8; it also suppressed BMP-2-induced osteoblast markers [PMID:22155034]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"Receptor-construct inhibition indicated activity was facilitated by the combination of ALK-4 and ActRIIA, not ALK-2/-3/-6 [PMID:22155034]; ALK-4 alone is not shown sufficient.","affinity_potency":[],"species_and_systems":"Mouse myoblastic C2C12 cells in the abstract [PMID:22155034]; the human and mouse pairs are both ortholog-inferred.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"Evidence is a single paper read as an abstract only (the abstract is cut off); no binding assay or affinity. The curator-assigned effect 'antagonist' reflects antagonism of BMP-2 signalling, whereas the paper reports GDF10 activating Smad2/3.","key_references":[{"PMID":"22155034","why":"BMP-3b signalling via ALK-4/ActRIIA and Smad2/3 in C2C12 cells"}],"covers":["LR000686","LR004170"]},"LR001830":{"pair":"GDF15 -> GFRAL","headline":"Well supported: GDF15 binds GFRAL with high affinity and acts through it to reduce food intake, shown in four papers and structures.","interaction_type":"direct binding","direction_and_effect":"GDF15 binds GFRAL; Gfral deletion abrogates GDF15 effects on food intake and body weight in mice [PMID:28846097][PMID:28846098][PMID:28846099]. Gfral-knockout mice are hyperphagic under stress and resistant to chemotherapy-induced anorexia [PMID:28953886]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"GFRAL requires the coreceptor RET for intracellular signalling [PMID:28846099]; UniProt describes a 2:2:2 GDF15-GFRAL-RET complex [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mice and nonhuman primates; Gfral expressed in area postrema and nucleus of the solitary tract in mice and humans [PMID:28846097]. PDB 5VZ4 and 6Q2J, IntAct entries [DB:PDB 5VZ4][DB:IntAct].","localisation_and_range":"GDF15 is a secreted 25-kDa dimer [PMID:28846097]; GFRAL is brainstem-restricted [PMID:28953886], so endocrine signalling to hindbrain neurons.","caveats":"All four papers read as abstracts. 'High affinity' is stated without a number in our evidence; GtoPdb gives pKd units but no value.","key_references":[{"PMID":"28846097","why":"GDF15 binds GFRAL; weight loss in mice and primates"},{"PMID":"28846098","why":"GFRAL required for GDF15 metabolic effects"},{"PMID":"28846099","why":"GFRAL needs RET to signal"}],"covers":["LR001830","LR005185"]},"LR011208":{"pair":"GDF2 -> BMPR1A","headline":"One abstract-level functional report for ALK3 (BMPR1A) plus a GtoPdb agonist record; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"GDF2 robustly activated SMAD1/5 signalling by increasing complex formation between ALK3 and ALK6 and the type-II receptor BMPRII in ovarian and breast epithelial cells [PMID:26678910]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Requires the type-II receptor BMPRII in the reported complex [PMID:26678910].","affinity_potency":[],"species_and_systems":"Ovarian and breast epithelial cells; species not stated in our evidence [PMID:26678910].","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"Single paper, abstract only [PMID:26678910]. It reports increased receptor complex formation, not direct ligand binding. ALK3 and ALK6 are described together, so it is not specific to BMPR1A.","key_references":[{"PMID":"26678910","why":"GDF2 increases ALK3/ALK6-BMPRII complex formation, SMAD1/5 activation"}],"covers":["LR011208"]},"LR011217":{"pair":"GDF3 -> BMPR1B","headline":"Asserted only by a GtoPdb agonist record; no papers in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF3 as an agonist of BMPR1B [DB:GtoPdb].","molecular_requirements":"not reported in our evidence","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF3 is flagged secreted [flag].","caveats":"No papers or other database records; no experimental evidence in our evidence.","key_references":[],"covers":["LR011217"]},"LR007230":{"pair":"GDF5 -> ACVR2A:BMPR1A","headline":"Complex pair with no curator-verified paper; rests on BioGRID, IntAct and UniProt records for single subunits.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says GDF5 binds BMPR1B with high affinity and BMPR1A with less affinity [DB:UniProt]. BioGRID has ACVR2A - GDF5 affinity capture-western [PMID:8702914][DB:BioGRID].","molecular_requirements":"The complex is assembled from separate subunit records and not shown as a unit in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"The receptor complex is flagged transmembrane [flag].","caveats":"Only review-level sources were judged. The BioGRID records shown name BMPR1B and the type II subunit, not BMPR1A; IntAct entries are SPR records [DB:IntAct].","key_references":[],"covers":["LR007230"]},"LR000705":{"pair":"GDF7 -> ACVR2A","headline":"GDF7 binds ACVR2A directly (KD 17.1 nM for rhBMP12) with functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ACVR2A with similar affinity to rhBMP13 (GDF6) [PMID:21702718]. ActRIIA shRNA suppressed GDF7-induced Smad1/5/8 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type II receptors act with a type I partner: ALK3 or ALK6 overexpression conferred GDF7 signalling [PMID:16049014].","affinity_potency":[{"value":"KD 17.1 nM","assay":"surface plasmon resonance, KD (kin), rhBMP12 (GDF7) vs ACVR2A ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. ACVR2A binding was more than 10-fold weaker than type I binding. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR000705","LR004189"]},"LR000714":{"pair":"GH1 -> PRLR","headline":"Direct binding shown by a human GH-PRLR extracellular domain crystal structure.","interaction_type":"direct binding","direction_and_effect":"hGH binds the hPRLR; the 1:1 crystal structure of hGH with the hPRLR extracellular domain was presented [PMID:7984244]. PDB 1BP3 and Reactome agree [DB:PDB 1BP3][DB:Reactome].","molecular_requirements":"hGH can bind hGHR and hPRLR through two distinctly different receptor-binding surfaces, with overlapping binding sites on hGH [PMID:7984244]. hPRL does not bind hGHR.","affinity_potency":[],"species_and_systems":"Human GH with human PRLR extracellular domain (structural) [PMID:7984244].","localisation_and_range":"GH1 is flagged secreted [flag].","caveats":"Abstract only; no affinity value in the dossier; three other rows still pending.","key_references":[{"PMID":"7984244","why":"Crystal structure of hGH bound to hPRLR"}],"covers":["LR000714"]},"LR010470":{"pair":"GLS:SLC1A1 -> GRIN1:GRIN2D","headline":"Protein-association records only; no paper confirms GLS:SLC1A1 -> GRIN1:GRIN2D as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010470"]},"LR009300":{"pair":"GNAI2 -> MTNR1B","headline":"Database-asserted only: IntAct tandem-affinity-purification records for GNAI2 and MTNR1B; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records come from tandem affinity purification [PMID:26514267][PMID:17215244]; cell system and species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Co-purification does not show direct binding or direction. One curated judgement: 'different_entity'.","key_references":[],"covers":["LR009300"]},"LR009012":{"pair":"GNAI2 -> UNC5B","headline":"Database-asserted only: UniProt states that UNC5B interacts with GNAI2 via its cytoplasmic part.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:UniProt].","molecular_requirements":"UniProt says UNC5B interacts with GNAI2 via its cytoplasmic part [DB:UniProt][PMID:12359238].","affinity_potency":[],"species_and_systems":"Species and assay not reported in our evidence; the pair is annotated human.","localisation_and_range":"UNC5B is annotated as a transmembrane receptor, not secreted [flag]. GNAI2 binds its cytoplasmic part, so this is an intracellular interaction, not an extracellular ligand-receptor one [DB:UniProt].","caveats":"No paper in our evidence supports this pair; it rests on database records alone. The only curated judgement was 'review_only'.","key_references":[],"covers":["LR009012"]},"LR000723":{"pair":"GPC3 -> IGF1R","headline":"GPC3 binds IGF-1R through its N-terminal proline-rich region and enhances IGF-II-triggered IGF-1R phosphorylation, in cell lines; one paper.","interaction_type":"direct binding","direction_and_effect":"GPC3 bound specifically through its N-terminal proline-rich region to both IGF-II and IGF-1R, and stimulated IGF-1R and ERK phosphorylation in an IGF-II-dependent way [PMID:18413366]. GPC3 knockdown in HCC cells reduced IGF-1R and ERK phosphorylation [PMID:18413366].","molecular_requirements":"N-terminal proline-rich region of GPC3 (P25-29A mutant weakened responses); IGF-II is required for the activation, and convertase digestion is needed for GPC3 to interact with IGF-II [PMID:18413366]. The authors suggest GPC3 joins a ligand-receptor multiprotein complex, possibly via heparan sulfate [PMID:18413366].","affinity_potency":[],"species_and_systems":"Human HCC cell lines (HuH-7), NIH3T3 and HEK293/HEK293T cells, by co-IP and pull-down [PMID:18413366]; mouse pair is ortholog-inferred.","localisation_and_range":"GPC3 is annotated non-secreted [flag] (cell-surface); IGF1R is a transmembrane receptor [flag].","caveats":"Abstract plus excerpts from one paper. Binding was shown by co-IP in cells, so it may be bridged by IGF-II or heparan sulfate; no affinity reported in our evidence.","key_references":[{"PMID":"18413366","why":"GPC3 binds IGF-1R and enhances IGF-II signalling"}],"covers":["LR000723","LR004205"]},"LR004206":{"pair":"GPHA2 -> TSHR","headline":"Thyrostimulin (GPHA2/GPHB5 heterodimer) binds with high affinity and activates the TSH receptor; one recombinant-protein paper plus database support.","interaction_type":"direct binding","direction_and_effect":"Agonist, stimulatory [flag]. Recombinant A2/B5 heterodimer activated human TSH receptors, but not LH and FSH receptors, and showed high affinity in a radioligand receptor assay; it stimulated cAMP and thymidine incorporation in cultured thyroid cells and raised serum thyroxine in TSH-suppressed rats [PMID:12045258]. UniProt and Reactome agree [DB:UniProt][DB:Reactome].","molecular_requirements":"The GPHA2/GPHB5 heterodimer (alpha2/beta5) is the ligand; the heterodimerisation was shown by yeast two-hybrid and immunology [PMID:12045258]. The GPHA2 chain alone is not shown to act. Our evidence inherits the heterodimer's activity for GPHA2.","affinity_potency":[],"species_and_systems":"Human TSH receptors with recombinant human proteins, cultured thyroid cells, rats in vivo [PMID:12045258]. Mouse pair is ortholog-inferred.","localisation_and_range":"GPHA2 is annotated secreted [flag]; the authors infer a paracrine mechanism from pituitary co-expression [PMID:12045258].","caveats":"Abstract only; no numeric affinity in our evidence. The GPHB5 partner is needed for the ligand, so expression of both chains matters in CCC scoring. Reactome pools TSH and thyrostimulin in one reaction.","key_references":[{"PMID":"12045258","why":"Thyrostimulin activates TSH receptor; radioligand binding"}],"covers":["LR000724","LR004206"]},"LR002703":{"pair":"GPNMB -> CD44","headline":"GPNMB signals through CD44 to damp astrocyte inflammation; functional knockout evidence, not binding data.","interaction_type":"functional only","direction_and_effect":"Recombinant GPNMB attenuated cytokine-induced inflammatory mediators in astrocyte cultures, and this was lost in CD44 knockout primary mouse astrocytes, so the anti-inflammatory effect is CD44-dependent [PMID:29519253]. Curators label it antagonist, meaning it dampens inflammation.","molecular_requirements":"CD44 is required for the effect [PMID:29519253]. Which GPNMB form acts: the paper describes a soluble peptide released by ADAM10 or other protease cleavage, but this is background [PMID:29519253].","affinity_potency":[],"species_and_systems":"Mouse astrocytes (IMA2.1 line and primary cells, including CD44 knockout) treated with recombinant GPNMB; expression data also from human Parkinson's disease substantia nigra and MPTP mice [PMID:29519253]. Human pair listed as ortholog-inferred.","localisation_and_range":"GPNMB is flagged as secreted [flag]; the paper states it is a transmembrane protein that is cleaved to release a soluble peptide [PMID:29519253]. CD44 is flagged as both secreted and transmembrane [flag].","caveats":"Direct GPNMB-CD44 binding is stated only as background in the abstract ('can bind'), not shown in this paper. Full text available, but only one paper is listed.","key_references":[{"PMID":"29519253","why":"CD44 knockout astrocytes lose the GPNMB anti-inflammatory effect"}],"covers":["LR002703","LR005968"]},"LR010740":{"pair":"GREM2 -> BMP4","headline":"Only a UniProt subunit statement supports this pair; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt for BMP4 states it interacts with GREM2 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; human pair.","localisation_and_range":"BMP4 is flagged as secreted and non-transmembrane [flag].","caveats":"No verified papers: the one judged row was a different entity. Rests on a single database record.","key_references":[],"covers":["LR010740"]},"LR004215":{"pair":"GZMB -> IGF2R","headline":"Granzyme B uptake via CI-MPR/IGF2R is reported in one 2000 paper; the model is contested.","interaction_type":"functional only","direction_and_effect":"Inhibiting the granzyme B-CI-MPR interaction prevented granzyme B cell-surface binding, uptake and apoptosis; CI-MPR was essential for cytotoxic T cell-mediated apoptosis in vitro and allogeneic rejection in vivo [PMID:11081635].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (ligand and receptor) in vitro and in vivo [PMID:11081635]. Human pair is ortholog-inferred in the mouse direction.","localisation_and_range":"GZMB is flagged secreted; IGF2R as a transmembrane receptor [flag].","caveats":"Curator notes that the uptake-receptor model was substantially challenged by later work (not in this dossier). Abstract-only reading; a pending row exists.","key_references":[{"PMID":"11081635","why":"CI-MPR as granzyme B receptor"}],"covers":["LR000733","LR004215"]},"LR000741":{"pair":"HCRT -> NPFFR2","headline":"Single binding paper suggests orexin interacts with NPGPR, a receptor variant related to NPFFR2; weak, with gene-identity uncertainty.","interaction_type":"direct binding","direction_and_effect":"Direction and effect not reported in our evidence. A radioligand displacement assay showed [125I]orexin B displaced by orexin B with an IC50 of 415 +/- 195 nM, and the authors conclude that orexins interact with NPGPR [PMID:12609745].","molecular_requirements":"Not reported in our evidence. The receptor studied is NPGPR, described as a splice variant of the NPFF receptor family, distinct from the shorter variant lacking exon 1 that was named NPFF2 [PMID:12609745].","affinity_potency":[{"value":"IC50 415 nM","assay":"[125I]orexin B displacement by orexin B","system":"NPGPR (species not stated in the dossier)","cite":"PMID:12609745"}],"species_and_systems":"Experimental species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"One paper, abstract only. The displacement used orexin B, not orexin-A, and the curators note uncertain identity of NPGPR versus NPFFR2 [PMID:12609745]. The abstract also states NPFF binds NPGPR about 100-fold weaker than the NPFF2 receptor. No database record supports the pair.","key_references":[{"PMID":"12609745","why":"Only study; radioligand displacement of orexin B at NPGPR"}],"covers":["LR000741","LR004223"]},"LR004224":{"pair":"HGF -> CD44","headline":"HGF binds CD44 variants directly (CD44v6 in the micromolar range; CD44v3 via heparan sulfate), but CD44 acts as a co-receptor for MET rather than a stand-alone receptor.","interaction_type":"direct binding","direction_and_effect":"CD44v3 binds HGF/SF through its heparan sulfate chains and enhances HGF-induced c-Met phosphorylation and ERK1/2 activation, acting as a co-receptor [PMID:10037743]. CD44v6 ectodomain, but not CD44s, reduced HGF-induced Met and Erk activation in a dose-dependent way [PMID:26181364].","molecular_requirements":"Isoform-specific: CD44v3 (heparan sulfate-modified; binding abolished by heparitinase) [PMID:10037743] and CD44v6 (binding heparan sulfate-independent) [PMID:26181364]. CD44s did not promote Met activation [PMID:10037743][PMID:26181364]. MET is also needed for signalling.","affinity_potency":[{"value":"micromolar range (no number given in the dossier)","assay":"MicroScale Thermophoresis, fluorescence correlation spectroscopy, fluorescence anisotropy","system":"CD44v6 with HGF","cite":"PMID:26181364"}],"species_and_systems":"Cell models: Namalwa lymphoma cells co-transfected with c-Met [PMID:10037743]; BSp73ASs6 cells and purified CD44v6 ectodomain [PMID:26181364]. Species of the proteins is not stated beyond the dossier labels; the mouse pair is ortholog-inferred.","localisation_and_range":"HGF flagged secreted; CD44 flagged transmembrane and also secreted [flag]; HGF acts on cell-surface CD44 as a presenting co-receptor.","caveats":"CD44 is a co-receptor presenting HGF to MET, not a classical signalling receptor, so scoring HGF-CD44 as an independent pair may overstate it. Both papers were abstract-level for the first and full-text for the second; one IntAct cross-linking record also exists [DB:IntAct].","key_references":[{"PMID":"10037743","why":"CD44v3 binds HGF/SF via heparan sulfate and enhances c-Met signalling"},{"PMID":"26181364","why":"Direct binding of CD44v6 to HGF with micromolar affinity"}],"covers":["LR000743","LR004224"]},"LR002712":{"pair":"HGF -> NRP2","headline":"HGF binds NRP2 according to one abstract-level paper; NRP2 appears to act as a co-receptor with c-Met.","interaction_type":"direct binding","direction_and_effect":"NRP2 binds HGF; knockdown of NRP1 or NRP2 in HUVECs decreased HGF-induced c-Met phosphorylation and signalling [PMID:18065694]. NRP2 acts as a co-receptor potentiating c-Met signalling [PMID:18065694].","molecular_requirements":"The N-terminal domain of HGF is involved in the binding [PMID:18065694]. Blocking antibodies had an enhanced effect when binding to both neuropilins was disrupted [PMID:18065694].","affinity_potency":[],"species_and_systems":"Human proteins and HUVECs; the in vivo mouse Matrigel result was reported for NRP1, not NRP2 [PMID:18065694].","localisation_and_range":"NRP2 is annotated as a transmembrane receptor [flag].","caveats":"Single paper, read as an abstract only. No affinity reported. Direct-binding method details are not available in our evidence.","key_references":[{"PMID":"18065694","why":"HGF binds NRP1 and NRP2; knockdown reduces c-Met signalling"}],"covers":["LR002712","LR005977"]},"LR000750":{"pair":"HLA-B -> KIR2DL3","headline":"Thin support: one abstract-level paper shows HLA-B*46:01 peptides forming KIR2DL3 ligands; not general HLA-B binding.","interaction_type":"functional only","direction_and_effect":"A minority (21%) of HLA-B*46:01 peptides, with common C-terminal characteristics, form ligands for KIR2DL3 [PMID:28514659]. The paper uses a functional NK-receptor binding assay with mass spectrometry peptidomics [PMID:28514659]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Peptide-dependent: KIR2DL3 recognition depends on the peptides presented by HLA-B*46:01 [PMID:28514659]. No complex-subunit information in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not recorded in our evidence [PMID:28514659].","localisation_and_range":"HLA-B is flagged transmembrane and KIR2DL3 a transmembrane receptor [flag]; contact-dependent.","caveats":"Evidence covers one allele, HLA-B*46:01 (an intergenic recombinant), and not HLA-B generally. Only the abstract was read. Two other papers were abstract-insufficient. No database records.","key_references":[{"PMID":"28514659","why":"HLA-B*46:01 peptides form KIR2DL3 ligands"}],"covers":["LR000750"]},"LR002721":{"pair":"HLA-C -> CD160","headline":"Single 2002 paper reports direct binding of recombinant HLA-Cw3 to CD160 and NK activation; thinly supported.","interaction_type":"direct binding","direction_and_effect":"HLA-C on K562 cells triggered NK cell lysis through CD160 engagement, so CD160 acts as an activating receptor for HLA-C here [PMID:12486241]. UniProt similarly states CD160 recognises HLA-C and triggers NK cytotoxicity [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond use of recombinant soluble HLA-Cw3 and CD160 [PMID:12486241].","affinity_potency":[],"species_and_systems":"Human NK cells, K562 targets and recombinant human proteins [PMID:12486241].","localisation_and_range":"HLA-C is annotated transmembrane; CD160 is annotated both secreted and transmembrane [flag]. Direction of use is cell contact in the paper's cytotoxicity assay [PMID:12486241].","caveats":"One paper, read as an abstract only; no affinity. The database support derives from the same paper [DB:UniProt]. CD158b inhibitory receptors partially interfered with CD160-mediated cytotoxicity [PMID:12486241].","key_references":[{"PMID":"12486241","why":"Direct interaction of soluble HLA-Cw3 and CD160, NK lysis of K562"}],"covers":["LR002721"]},"LR002730":{"pair":"HLA-F -> KIR3DS1","headline":"HLA-F open conformers are a high-affinity ligand of activating KIR3DS1; binding and functional evidence.","interaction_type":"direct binding","direction_and_effect":"KIR3DS1 bound HLA-F, confirmed biochemically and functionally; primary human KIR3DS1+ NK cells degranulated, produced antiviral cytokines and inhibited HIV-1 replication in vitro (agonist) [PMID:27455421]. HIV-1 infection increased HLA-F mRNA but decreased KIR3DS1 binding [PMID:27455421].","molecular_requirements":"Binding was to HLA-F open conformers [PMID:27455421]; KIR3DS1 gave a signal in Jurkat reporter cells using a chimeric construct with CD3zeta cytoplasmic domain and KIR3DL1 transmembrane domain, because adaptor DAP12 was absent [PMID:27455421].","affinity_potency":[{"value":"KD = (25 \u00b1 1) nM","assay":"surface plasmon resonance","system":"HLA-F OCs with KIR3DS1","cite":"PMID:27455421"}],"species_and_systems":"Human proteins, Jurkat reporter cells and primary human NK cells [PMID:27455421].","localisation_and_range":"Not reported in our evidence; HLA-F flagged transmembrane [flag].","caveats":"One paper (abstract plus full-text excerpts in sibling dossiers); the dossier here marks it abstract_only. Reporter cells used a chimeric receptor.","key_references":[{"PMID":"27455421","why":"HLA-F OCs as high-affinity KIR3DS1 ligands"}],"covers":["LR002730"]},"LR004233":{"pair":"HSP90B1 -> TLR4","headline":"Gp96 activates dendritic cells through TLR4 in mouse experiments; functional evidence only.","interaction_type":"functional only","direction_and_effect":"The Gp96-TLR2/4 interaction activates NF-kappaB reporters and MAPK/MSK, and induces IkappaBalpha degradation; bone-marrow dendritic cells from TLR4-mutant C3H/HeJ mice, and more markedly from C3H/HeJ TLR2-/- mice, fail to respond [PMID:11912201].","molecular_requirements":"Response requires Gp96 endocytosis; the paper names TLR2 and TLR4 together as a pathway [PMID:11912201]. UniProt states HSP90B1 interacts with TLR4 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse dendritic cells and TLR-expressing cell lines [PMID:11912201]. The mouse pair is ortholog-inferred.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; described as an ER-resident protein acting after release [PMID:11912201].","caveats":"Abstract-only reading; no direct binding or affinity reported, and the effect is not separated between TLR2 and TLR4.","key_references":[{"PMID":"11912201","why":"Gp96 activates DCs via TLR2/4; knockout cells fail to respond"}],"covers":["LR000774","LR004233"]},"LR004242":{"pair":"ICAM1 -> ITGAL","headline":"Well supported direct binding of ICAM-1 to the alphaL (LFA-1) I domain, with structures and affinity data; ITGAL acts in the ITGAL:ITGB2 integrin.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 is the ligand of the integrin alphaLbeta2 [PMID:15728350]. The alphaL I domain locked open bound ICAM-1 with a 9,000-fold affinity increase, reversed by disulfide reduction [PMID:11353828]. Engineered ICAM-1 mutants raised affinity for LFA-1 I domains 19-fold and 22-fold [PMID:16354667]. Effect is adhesive and stimulatory.","molecular_requirements":"The I domain of alphaL is the binding domain; in vivo the receptor is the alphaLbeta2 integrin [PMID:15728350]. The I domain alone was sufficient for full-affinity binding in the locked-open form [PMID:11353828]. Binding depends on integrin activation state and Mg2+ [PMID:11353828].","affinity_potency":[{"value":"9,000-fold increase over wild type","assay":"I domain locked open by disulfide, ICAM-1 binding kinetics","system":"recombinant protein","cite":"PMID:11353828"},{"value":"19-fold and 22-fold","assay":"improved ICAM-1 mutant vs wild type, intermediate- and high-affinity LFA-1 I domains","system":"recombinant human proteins","cite":"PMID:16354667"}],"species_and_systems":"Human recombinant proteins and cells; the structure used the ICAM-3 D1 domain, not ICAM-1 [PMID:15728350]. Mouse pair is ortholog-inferred.","localisation_and_range":"ICAM1 and ITGAL are flagged transmembrane or cell-surface [flag]; contact-dependent. Reactome shows the complex at the plasma membrane [DB:Reactome].","caveats":"All papers were abstract-only. The crystal structure is with ICAM-3, which only supports a shared docking mode [PMID:15728350]. Some affinity data use isolated I domains or mutants. Three other papers were abstract_insufficient.","key_references":[{"PMID":"11353828","why":"I domain affinity for ICAM-1 and sufficiency"},{"PMID":"16354667","why":"ICAM-1 variants with higher LFA-1 affinity"},{"PMID":"15728350","why":"Structure of ICAM-3 with alphaL I domain, ICAM-1/2/3 off-rates"}],"covers":["LR000784","LR004242"]},"LR004251":{"pair":"ICAM4 -> ITGAL","headline":"Two human studies show LFA-1 (alphaL) binding to ICAM-4-Fc, with domain 1 as the binding region; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Transfectants expressing alphaLbeta2 bind ICAM-4-Fc [PMID:15355350]. Anti-CD11a, anti-CD11b, anti-CD18 antibodies blocked L-cell adhesion to ICAM-4-Fc, and the interaction needed Ca2+ and Mg2+ [PMID:10846180]. UniProt lists ICAM4 among ITGAL/ITGB2 ligands [DB:UniProt].","molecular_requirements":"The alphaL/beta2 complex is the receptor. LFA-1 binds the first Ig-like domain of ICAM-4; Leu80, Trp93, Arg97 (CFG face) and Trp77 (E-F loop) of domain D1 may contact LFA-1 [PMID:10846180].","affinity_potency":[],"species_and_systems":"Human ICAM-4-Fc with human integrin transfectants and L-cells [PMID:15355350, PMID:10846180].","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"Both papers abstract only; the second is a functional adhesion assay. Affinity not reported. No mouse experiments.","key_references":[{"PMID":"10846180","why":"LFA-1 and Mac-1 binding sites on ICAM-4"},{"PMID":"15355350","why":"alphaLbeta2 transfectant binding to ICAM-4-Fc"}],"covers":["LR000797","LR004251"]},"LR006006":{"pair":"ICAM4 -> ITGAX","headline":"CD11c/CD18 (alphaXbeta2) is a macrophage receptor for red-cell ICAM-4; a single human study with binding-site mapping.","interaction_type":"direct binding","direction_and_effect":"ICAM-4 functions as a ligand for CD11c/CD18; curated as agonist. Anti-ICAM-4 and anti-integrin antibodies inhibit erythrophagocytosis, implicating the pair in senescent red-cell clearance [PMID:16985175]. UniProt agrees [DB:UniProt].","molecular_requirements":"The receptor is the CD11c/CD18 heterodimer. Both Ig domains of ICAM-4 contain binding sites; important residues cluster in two regions of domain 1 with an extension into domain 2, and two ICAM-4-derived peptides modulate binding [PMID:16985175].","affinity_potency":[],"species_and_systems":"Human proteins; CD11c/CD18 expressed on splenic and bone-marrow macrophages [PMID:16985175]. Mouse pair is ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion. Red-cell expression of ICAM-4 is stated in the abstract [PMID:16985175].","caveats":"One paper, abstract only. Affinity not reported in our evidence.","key_references":[{"PMID":"16985175","why":"ICAM-4 as ligand for CD11c/CD18; binding-site mapping"}],"covers":["LR002760","LR006006"]},"LR000804":{"pair":"ICAM5 -> ITGB2","headline":"beta2 (LFA-1) binding to ICAM-5 is supported by two human studies, a structure record and UniProt.","interaction_type":"direct binding","direction_and_effect":"ICAM-5 domain 1 supports CD11a/CD18 interaction [PMID:10741396]; LFA-1-mediated HL-60 adhesion to recombinant telencephalin, curated as agonist [PMID:8995416]. UniProt names ITGAX:ITGB2 as an ICAM5 receptor ensuring neuron-leukocyte adhesion [DB:UniProt].","molecular_requirements":"Evidence is for beta2 pairs (CD11a/CD18 and, per UniProt, CD11c/CD18) rather than beta2 alone. TLN-LFA-1 binding was divalent-cation- and PMA-independent [PMID:8995416].","affinity_potency":[{"value":"50 nM","assay":"lowest soluble ICAM-5 domain 1 concentration that inhibited T-cell binding to immobilized ICAM-5","system":"human T cells, immobilized ICAM-5","cite":"PMID:10741396"}],"species_and_systems":"Human proteins; human T cells on rat hippocampal neurons [PMID:10741396]; HL-60 cells [PMID:8995416]. Mouse pair ortholog-inferred.","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; the cloning paper reports a transmembrane region [PMID:8995416]; neuron-leukocyte adhesion is described in UniProt [DB:UniProt].","caveats":"Both papers abstract only; two more confirmed rows and one pending row not shown. The 50 nM figure is an inhibition concentration.","key_references":[{"PMID":"10741396","why":"ICAM-5 domain 1 and CD11a/CD18"},{"PMID":"8995416","why":"LFA-1-mediated adhesion to telencephalin"}],"covers":["LR000804","LR004258"]},"LR000813":{"pair":"IFNA1 -> IFNAR1","headline":"Direct binding of IFNA1 to the IFNAR1 chain alone is shown, with low (micromolar-range) affinity.","interaction_type":"direct binding","direction_and_effect":"IFNA1 is an agonist of IFNAR1 in GtoPdb [DB:GtoPdb]. In mouse cells expressing bovine IFNAR, human IFN alpha1 acted at low concentrations as a competitive antagonist to IFN alpha2 and alpha8 [PMID:7932753].","molecular_requirements":"IFNAR1 is one chain of a heterodimer with IFNAR2 [PMID:17174979]. This is chain-level evidence for IFNAR1 alone; competitive 1:1 binding was seen to ifnar1-EC and ifnar2-EC [PMID:17174979].","affinity_potency":[{"value":"IFNAR1 affinities 0.5-5 \u03bcM for alpha-IFNs (class statement)","assay":"binding of isolated receptor chains","system":"human alpha-IFN subtypes, isolated chains","cite":"PMID:21856167"},{"value":"KD in the \u03bcM range; IFN\u03b11 higher affinity than IFN\u03b12","assay":"real-time RIfS/TIRFS binding","system":"ifnar1-EC","cite":"PMID:17174979"}],"species_and_systems":"Human IFNs on human receptor extracellular domains [PMID:17174979] [PMID:21856167]; human IFN on mouse cells with bovine IFNAR [PMID:7932753].","localisation_and_range":"IFNA1 flagged secreted (paracrine/endocrine) [flag].","caveats":"Two papers are abstract only; the affinity range is a class statement not specific to IFNA1 [PMID:21856167]. The 17174979 row is a browser-read quote with spot-check pending. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"17174979","why":"Real-time binding of several IFNs to ifnar1-EC"},{"PMID":"21856167","why":"Affinities of 12 alpha-IFN subtypes to IFNAR1/2"},{"PMID":"7932753","why":"Human IFN\u03b11 on cells expressing bovine IFNAR"}],"covers":["LR000813","LR004265"]},"LR011712":{"pair":"IFNA10 -> IFNA2:IFNAR1:IFNAR2","headline":"No paper supports this three-member complex entity; GtoPdb only lists the single chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA10 as agonist of IFNAR1 and of IFNAR2 separately [DB:GtoPdb].","molecular_requirements":"The receptor entity includes IFNA2 as a member, which is itself a secreted ligand [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IFNA10 flagged secreted [flag].","caveats":"No verified papers (abstract-insufficient and different-entity rows only). Support is from database records of single chains.","key_references":[],"covers":["LR011712"]},"LR004260":{"pair":"Ifna15 -> Ifnar2","headline":"Mouse Ifna15 to Ifnar2 is inferred from human alpha-IFN binding data, not tested on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"Ifna15 is the secreted ligand and Ifnar2 the receptor chain [flag]. Human alpha-IFN subtypes bind isolated IFNAR2 chains with high affinity [PMID:21856167]; a second study showed competitive 1:1 binding of IFNs to ifnar2-EC and ifnar1-EC [PMID:17174979]. Activating or inhibitory effect not reported in our evidence.","molecular_requirements":"Binding to the IFNAR2 chain alone is shown; the IFNAR1 chain also binds, with much weaker affinity [PMID:21856167, PMID:17174979].","affinity_potency":[{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"The mouse pair is ortholog-inferred. All experiments used human ligands and human receptor chains, as isolated or solid-supported extracellular domains [PMID:21856167, PMID:17174979].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Both papers were read as abstracts only. PMID:21856167 reports class-wide values and does not name the individual subtypes; Ifna15 is not individually evidenced. No mouse experiments in our evidence.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."},{"PMID":"17174979","why":"Real-time binding of IFNs to ifnar1-EC and ifnar2-EC."}],"covers":["LR004260"]},"LR000822":{"pair":"IFNA5 -> IFNAR2","headline":"IFNA5 binds IFNAR2 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA5 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA5 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000822"]},"LR011721":{"pair":"IFNA7 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA7 to an IFNA2:IFNAR1:IFNAR2 complex rests only on GtoPdb records for the individual chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA7 as an agonist at IFNAR1 and at IFNAR2 separately [DB:GtoPdb]. No paper in our evidence supports the complex as defined.","molecular_requirements":"The receptor entity contains IFNA2 (flagged secreted, not a receptor) plus IFNAR1 and IFNAR2 [flag]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experiments in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"No curator-verified paper; judged papers were abstract_insufficient or about a different entity. Support is database-only and the complex composition looks unusual.","key_references":[],"covers":["LR011721"]},"LR000831":{"pair":"IFNG -> IFNGR1","headline":"IFN-gamma binds IFNGR1 directly; crystal structures and a human loss-of-binding study support it, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"IFN-gamma is the agonist ligand; GtoPdb lists Type=Agonist [DB:GtoPdb]. The curated modulatory effect is Stimulatory. Cells from patients with IFNGR1 ligand-binding-domain mutations showed no specific binding of (125)I-IFN-gamma and did not respond to IFN-gamma [PMID:10811850].","molecular_requirements":"IFNGR1 is the ligand-binding chain [PMID:10811850]. A 2:1 receptor-ligand complex plus an unexpected third receptor molecule (3:1) was seen in the crystal [PMID:10986460]. A monovalent IFN-gamma variant bound one IFNGR1 ectodomain and still had antiviral activity [PMID:11250200]. The second chain IFNGR2 forms the full signalling receptor (UniProt: heterodimer with IFNGR2) [DB:UniProt].","affinity_potency":[{"value":"Crystal structure at 2.9 A resolution","assay":"X-ray crystallography, multiwavelength anomalous diffraction (structural, not an affinity)","system":"human IFN-gamma with soluble glycosylated IFNGR1 extracellular part","cite":"PMID:10986460"}],"species_and_systems":"Human proteins throughout: crystallography with recombinant human ectodomains [PMID:10986460, PMID:11250200], patient-derived human cells [PMID:10811850], WISH and Jurkat cells [PMID:12165521]. The mouse pair is projected from human evidence (ortholog inferred), not tested.","localisation_and_range":"IFNG is flagged secreted and non-transmembrane [flag], so it is expected to act at a distance (paracrine/endocrine); the receptor is flagged transmembrane [flag].","caveats":"Most papers were read as abstracts only. The 12165521 paper is a trafficking study that assumes the pair and uses IFN-gamma binding only as a control. The monovalent ligand in 11250200 is engineered; native IFN-gamma is a homodimer. Structures also exist in PDB 1FG9, 1FYH, 6E3K and 6E3L [DB:PDB 1FG9].","key_references":[{"PMID":"10986460","why":"crystal structure of the human IFN-gamma/IFNGR1 complex"},{"PMID":"10811850","why":"loss of IFN-gamma binding with IFNGR1 mutations"},{"PMID":"11250200","why":"1:1 complex structure with monovalent IFN-gamma"}],"covers":["LR000831","LR004271"]},"LR000840":{"pair":"IGF1 -> IGF1R","headline":"Well-established IGF1 agonist at IGF1R, supported by structures and databases; our only verified paper is an older chimeric-receptor binding study.","interaction_type":"direct binding","direction_and_effect":"IGF1 is recorded as an agonist of IGF1R [DB:GtoPdb]; the interaction is annotated stimulatory. Chimeric receptor binding studies showed the cysteine-rich domain helps determine IGF-I specificity [PMID:1852007].","molecular_requirements":"Part of the IGF1R cysteine-rich domain determines IGF-I specificity; the insulin receptor N-terminal segment swapped into IGF1R raised insulin affinity but was not critical for high-affinity IGF-I binding [PMID:1852007]. Structures contain chains of both proteins [DB:PDB 4XSS].","affinity_potency":[],"species_and_systems":"Soluble chimeric insulin/IGF-I receptors expressed in mammalian cells (human on both sides) [PMID:1852007]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"IGF1 is flagged secreted and IGF1R transmembrane [flag].","caveats":"The one verified paper was read as an abstract only and addresses receptor specificity rather than measuring IGF1 affinity; no affinity is reported in our evidence. Two further papers are pending.","key_references":[{"PMID":"1852007","why":"Chimeric receptor mapping of IGF-I binding specificity"}],"covers":["LR000840","LR004272"]},"LR006015":{"pair":"IGF2 -> ITGA6","headline":"Integrin alpha6beta4 binds IGF2 in one verified study; ITGA6 is the alpha chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alpha6beta4 heterodimer was tested; ITGA6 alone is not shown [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002769","LR006015"]},"LR006024":{"pair":"IGFBP7 -> LRP1","headline":"One of ten ligands with direct LRP1 binding confirmed in a chondrocyte ligandome study (abstract only).","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding was confirmed for IGFBP7 with purified LRP1; affinity correlated with endocytosis rate, so LRP1 acts as an endocytic receptor [PMID:36028175]. Curator effect label: agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, purified proteins, LRP1-deficient cells, plus a conditional Lrp1-knockout mouse for in vivo relevance [PMID:36028175]. The mouse pair is projected.","localisation_and_range":"IGFBP7 is annotated as secreted [flag].","caveats":"Abstract-only read; the abstract names IGFBP7 among ten ligands without an IGFBP7-specific affinity. LRP1 is an endocytic scavenger, so this is clearance rather than signalling.","key_references":[{"PMID":"36028175","why":"Chondrocyte LRP1 ligandome; direct binding confirmed for IGFBP7"}],"covers":["LR002778","LR006024"]},"LR011730":{"pair":"IL15 -> IL15:IL15RA:IL2RB:IL2RG","headline":"Complex row with IL15 on both sides; no judged papers, database records only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: IL15 is expressed with its high-affinity IL15RA and signals to target cells [DB:UniProt]. GtoPdb lists agonist interactions [DB:GtoPdb].","molecular_requirements":"Subunits listed IL15RA, IL2RB and IL2RG; structures [DB:PDB 2Z3Q] [DB:PDB 4GS7]. Which subunits are essential is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human database records; no curated paper.","localisation_and_range":"Not reported in our evidence beyond annotation flags (IL15 secreted) [flag].","caveats":"Two papers pending; evidence rests on databases alone, and the receptor entity includes IL15 itself.","key_references":[],"covers":["LR011730"]},"LR005205":{"pair":"IL17C -> IL17RE","headline":"IL-17RE is reported as a receptor specific to IL-17C, working with IL-17RA; two abstract-only papers.","interaction_type":"functional only","direction_and_effect":"Agonist. IL-17C activated signalling through the IL-17RE-IL-17RA complex to induce antibacterial peptides and proinflammatory genes; IL-17RE-deficient mice had lower antibacterial gene expression, greater bacterial burden and early mortality [PMID:21993849]. IL-17C bound a receptor complex of IL-17RA and IL-17RE on epithelial cells [PMID:21993848]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-17RE signals with IL-17RA [PMID:21993849, PMID:21993848]. Whether IL-17RE alone binds IL-17C is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species is recorded as unspecified for PMID:21993849, although the abstract describes IL-17RE-deficient mice [PMID:21993849]; human is recorded for PMID:21993848. Both human and mouse pairs are listed as non-inferred.","localisation_and_range":"IL-17C annotated as secreted and non-transmembrane [flag]; IL-17RE as a receptor [flag]. PMID:21993848 describes autocrine action on epithelial cells.","caveats":"Both papers read as abstracts only; no affinity values. PMID:21993849 is classed functional_in_vitro rather than direct binding.","key_references":[{"PMID":"21993849","why":"IL-17RE as the functional receptor for IL-17C; knockout mice"},{"PMID":"21993848","why":"IL-17C autocrine signalling through IL-17RA/IL-17RE"}],"covers":["LR001859","LR005205"]},"LR011163":{"pair":"IL17RD -> FGFR1","headline":"Sef (IL17RD) interacts with FGFR1 and inhibits FGF signalling in mouse cells; a receptor-receptor interaction rather than a classic ligand.","interaction_type":"direct binding","direction_and_effect":"Inhibitory. Mouse Sef interacts with FGFR1 through its cytoplasmic domain, and overexpression in NIH3T3 cells reduced FGF-induced proliferation and FGFR1 Tyr phosphorylation, with reduced ERK activation [PMID:12604616]. BioGRID lists affinity capture-Western [DB:BioGRID].","molecular_requirements":"Cytoplasmic domain of Sef mediates the interaction [PMID:12604616]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse Sef in NIH3T3 cells [PMID:12604616]; the pair record is human.","localisation_and_range":"Both partners are annotated as receptors [flag]. Interaction is via the cytoplasmic domain, so it is not extracellular ligand binding.","caveats":"Abstract-only read. Sef is a transmembrane feedback inhibitor, so this is not a secreted ligand-receptor interaction.","key_references":[{"PMID":"12604616","why":"Mouse Sef interacts with FGFR1 and inhibits FGF signalling"}],"covers":["LR011163"]},"LR004305":{"pair":"IL18 -> IL18RAP","headline":"IL-18 engages IL18RAP as the signalling second chain within a ternary complex; structural and functional evidence, but not direct binding on its own.","interaction_type":"direct binding","direction_and_effect":"IL-18 signals through IL-18R beta (IL18RAP) as agonist: both IL-1R-rp1 and AcPL were required for NF-kappaB and JNK activation in response to IL-18 [PMID:9792649]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL18RAP does not bind IL-18 alone: AcPL alone was unable to bind IL-18 with any appreciable affinity [PMID:9792649]. A crystal structure shows IL-18 with both receptor ectodomains; IL-18R beta D2 and D3 contact IL-18/IL-18R alpha while D1 does not [PMID:25500532]. UniProt agrees IL18RAP is not the binding chain [DB:UniProt]. IL18R1 is therefore needed.","affinity_potency":[],"species_and_systems":"Structure with human IL-18 and receptor ectodomains [PMID:25500532]; reporter assays with species unspecified [PMID:9792649]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers were read as abstracts (structure paper also has full-text excerpts). IL18RAP binds only as part of the ternary complex, so single-chain scoring in CCC tools may overstate a direct ligand-IL18RAP interaction.","key_references":[{"PMID":"25500532","why":"Crystal structure of the IL-18/IL-18R alpha/IL-18R beta complex"},{"PMID":"9792649","why":"IL18RAP required for IL-18 signalling"}],"covers":["LR000875","LR004305"]},"LR007302":{"pair":"IL1A -> IL1R1:IL1RAP","headline":"IL-1alpha signals through IL1R1 plus IL1RAP; mouse knockout evidence shows IL1RAP is essential for signalling.","interaction_type":"functional only","direction_and_effect":"IL-1 agonists, including IL-1alpha, bound IL-1R AcP-deficient cells via type I IL-1R but failed to activate NF-kappaB or AP-1 signalling [PMID:9820540]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"The IL1R1/IL1RAP complex is required for signalling by all IL-1 agonists [PMID:9820540]. IL-1alpha binding is only moderately reduced without AcP, so IL1R1 alone binds it [PMID:9820540].","affinity_potency":[],"species_and_systems":"Mouse (AcP-deficient mice and fibroblasts; murine IL-1alpha) [PMID:9820540]. The human pair is not tested in this paper.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Single paper, abstract only. Binding to the complex as such is not measured; the result is a loss-of-function genetic readout.","key_references":[{"PMID":"9820540","why":"IL1RAP-knockout mice and fibroblasts"}],"covers":["LR007302"]},"LR006033":{"pair":"IL1B -> ITGAV","headline":"IL-1beta binds integrin alphaVbeta3 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alphaVbeta3); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGAV:ITGB3 binds to IL1B and this binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002790","LR006033"]},"LR004314":{"pair":"IL1F10 -> IL1R1","headline":"IL-1HY2 (IL1F10) protein binds soluble IL-1 receptor type I in one abstract-level report; effect not established.","interaction_type":"direct binding","direction_and_effect":"Purified recombinant IL-1HY2 bound soluble IL-1 receptor type I [PMID:11278614]. The paper notes 37% identity with the IL-1 receptor antagonist and a similar predicted fold, but the effect direction is not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond soluble IL-1RI; no accessory chain was tested.","affinity_potency":[],"species_and_systems":"Purified recombinant human IL-1HY2 with soluble human receptor; the mouse pair is inferred [PMID:11278614].","localisation_and_range":"IL-1HY2 protein is secreted from mammalian cells [PMID:11278614].","caveats":"Abstract only; no affinity, no functional readout at IL1R1. Other papers judged for this pair were insufficient or about a different entity.","key_references":[{"PMID":"11278614","why":"Cloning of IL-1HY2 and binding to soluble IL-1RI"}],"covers":["LR000884","LR004314"]},"LR008310":{"pair":"IL1RAPL2 -> FGFR3","headline":"IL1RAPL2 interacted with FGFR3 in a screen and by SPR; single paper.","interaction_type":"direct binding","direction_and_effect":"IL1RAPL2 additionally interacted with FGFR3 in the screen and by SPR [PMID:32822567]. Effect direction is not reported in our evidence.","molecular_requirements":"Ectodomain-Fc fusions were used; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ectodomain-Fc proteins, ELISA screen with SPR validation [PMID:32822567].","localisation_and_range":"FGFR3 is flagged transmembrane [flag]; IL1RAPL2 localisation not reported in our evidence.","caveats":"One primary paper, no affinity, no functional data, no database support. Which partner acts as ligand is arbitrary.","key_references":[{"PMID":"32822567","why":"Interactome screen reporting IL1RAPL2-FGFR3"}],"covers":["LR008310"]},"LR011226":{"pair":"IL1RN -> IL2RG","headline":"Only a GtoPdb antagonist record asserts this pair; no paper evidence, and judged papers named a different entity.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists the interaction as Antagonist [DB:GtoPdb]; no affinity is given.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experimental system in our evidence.","localisation_and_range":"IL1RN flagged secreted [flag].","caveats":"No verified papers; judged rows were different_entity or abstract_insufficient. The pair rests on one database record and may be spurious.","key_references":[],"covers":["LR011226"]},"LR000903":{"pair":"IL2 -> IL2RA","headline":"IL-2 binds IL2RA directly (human crystal structure); IL2RA alone is the low-affinity chain, and further papers are mostly about the multi-chain receptor.","interaction_type":"direct binding","direction_and_effect":"IL-2 docks onto IL-2Ralpha, which uses a composite surface to bind a groove on IL-2 that also binds antagonist drugs [PMID:15933202]. GtoPdb lists IL2-IL2RA as Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"IL-2Ralpha is described as one of three subunits (alpha, beta, gamma) binding IL-2 sequentially [PMID:15933202]; the high-affinity receptor needs IL2RA with the beta and gamma chains [PMID:3108674] and Tac/IL2RA associates extracellularly with a 75 kDa molecule without IL-2 [PMID:2487683].","affinity_potency":[],"species_and_systems":"Human IL-2 and IL-2Ralpha in a 2.8 angstrom crystal structure [PMID:15933202]; mouse EL4 T-cell transfectants for the subunit association [PMID:2487683]; human lymphocytes for [PMID:3108674]. Mouse pair is projected from human evidence.","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"All papers read as abstracts only. PMID:2487683 shows ligand-independent IL2RA-IL2RB association rather than IL-2 binding, and PMID:15265897 mentions the alpha chain only as background.","key_references":[{"PMID":"15933202","why":"Crystal structure of IL-2 bound to IL-2Ralpha"},{"PMID":"3108674","why":"IL2RA (Tac) takes part in high- and low-affinity IL-2 receptors with a second binding protein"}],"covers":["LR000903","LR004332"]},"LR004332":{"pair":"IL2 -> IL2RA","headline":"IL-2 binds IL2RA directly (human crystal structure); IL2RA alone is the low-affinity chain, and further papers are mostly about the multi-chain receptor.","interaction_type":"direct binding","direction_and_effect":"IL-2 docks onto IL-2Ralpha, which uses a composite surface to bind a groove on IL-2 that also binds antagonist drugs [PMID:15933202]. GtoPdb lists IL2-IL2RA as Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"IL-2Ralpha is described as one of three subunits (alpha, beta, gamma) binding IL-2 sequentially [PMID:15933202]; the high-affinity receptor needs IL2RA with the beta and gamma chains [PMID:3108674] and Tac/IL2RA associates extracellularly with a 75 kDa molecule without IL-2 [PMID:2487683].","affinity_potency":[],"species_and_systems":"Human IL-2 and IL-2Ralpha in a 2.8 angstrom crystal structure [PMID:15933202]; mouse EL4 T-cell transfectants for the subunit association [PMID:2487683]; human lymphocytes for [PMID:3108674]. Mouse pair is projected from human evidence.","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"All papers read as abstracts only. PMID:2487683 shows ligand-independent IL2RA-IL2RB association rather than IL-2 binding, and PMID:15265897 mentions the alpha chain only as background.","key_references":[{"PMID":"15933202","why":"Crystal structure of IL-2 bound to IL-2Ralpha"},{"PMID":"3108674","why":"IL2RA (Tac) takes part in high- and low-affinity IL-2 receptors with a second binding protein"}],"covers":["LR000903","LR004332"]},"LR007311":{"pair":"IL2 -> IL2RB:IL2RG","headline":"IL2RB:IL2RG is the intermediate-affinity IL-2 receptor; one binding paper supports it, and one 2026 study finds it not engaged in lung mast cells.","interaction_type":"conflicting","direction_and_effect":"The IL-2Rbetagamma receptor is a functional IL-2 receptor in its own right [PMID:8049354]; GtoPdb lists agonist records [DB:GtoPdb]. In human lung mast cells IL-33 raised CD25 and CD132 without CD122, giving absent IL-2-mediated signaling [PMID:41825599].","molecular_requirements":"IL2RB and IL2RG together form the intermediate-affinity receptor; alpha adds high affinity [PMID:8049354]. Beta binds IL-2 with low affinity and gamma very weakly alone [PMID:8049354].","affinity_potency":[],"species_and_systems":"Insect-cell soluble ectodomains [PMID:8049354]; purified human lung mast cells [PMID:41825599].","localisation_and_range":"IL-2 flagged secreted; complex flagged transmembrane [flag].","caveats":"The negative paper shows CD122 not upregulated in one cell type, so it speaks to expression rather than to binding; abstract only [PMID:41825599]. PMID:10662798 and PMID:15265897 are indirect (peptide structure, background).","key_references":[{"PMID":"8049354","why":"Names IL-2R beta+gamma as intermediate-affinity complex, soluble chain binding"},{"PMID":"41825599","why":"Verified negative: IL2RB not upregulated in lung mast cells"}],"covers":["LR007311"]},"LR004323":{"pair":"IL22 -> IL22RA1","headline":"IL-22 binds IL22RA1 directly, shown by a 1.9 A crystal structure and cross-linking; well supported in human.","interaction_type":"direct binding","direction_and_effect":"IL-22 binds IL-22R1 first and this dimer then recruits IL-10R2 [PMID:18675809]; IL22RA1 (CRF2-9) binds IL-TIF independently by cross-linking [PMID:11035029]. GtoPdb lists an agonist (pEC50) [DB:GtoPdb].","molecular_requirements":"IL22RA1 binds IL-22 alone; binding to the IL22RA1:IL10RB complex is greater than to IL22RA1 alone [PMID:11035029][DB:UniProt]. Site-directed mutagenesis confirmed key interface residues [PMID:18675809].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, crystal structure and transfected cells [PMID:18675809][PMID:11035029]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-22 is flagged secreted [flag].","caveats":"Both papers read as abstracts only. Two other rows were judged different_entity.","key_references":[{"PMID":"18675809","why":"1.9 A crystal structure of IL-22/IL-22R1"},{"PMID":"11035029","why":"cross-linking of IL-22 to IL22RA1 chain"}],"covers":["LR000893","LR004323"]},"LR007320":{"pair":"IL3 -> CSF2RB:IL3RA","headline":"IL-3 binds IL3RA and recruits CSF2RB to form the receptor; several abstract-level papers support the pair.","interaction_type":"direct binding","direction_and_effect":"Human IL-3 induces heterodimerization of IL-3R alpha and beta c, with disulfide linkage involved in receptor activation but not high-affinity binding (agonist) [PMID:8649415].","molecular_requirements":"Both chains contribute: IL-3 dependent dimers needed IL-3 interacting with both IL-3R alpha and beta c [PMID:8649415]. IL3RA alone binds IL-3 weakly, and high affinity needs the beta subunit [PMID:1833064]. Residue mapping of the IL-3 epitope for the alpha subunit is in [PMID:9278420]; SPR with the alpha subunit only is in [PMID:11700046]. Reactome lists the complex IL3:IL3RA:IL3RB:JAK2 [DB:Reactome].","affinity_potency":[{"value":"Kd = 120 +/- 60 nM","assay":"125I-IL-3 binding, alpha chain alone","system":"COS7 cells","cite":"PMID:1833064"},{"value":"Kd = 140 +/- 30 pM","assay":"125I-IL-3 binding, alpha plus beta","system":"COS7 cells","cite":"PMID:1833064"}],"species_and_systems":"Human proteins; COS7 cells, fibroblasts and human cells expressing IL-3R, plus recombinant IL-3R alpha in SPR [PMID:1833064][PMID:8649415][PMID:11700046].","localisation_and_range":"IL-3 is flagged secreted and non-transmembrane; the complex is flagged transmembrane [flag].","caveats":"All papers read as abstract only. The SPR (PMID:11700046) and structural-modelling (PMID:9278420) papers address the alpha chain, not the beta chain. Structure 6NMY contains P08700 and P32927 [DB:PDB 6NMY]. Two further papers were abstract_insufficient.","key_references":[{"PMID":"8649415","why":"IL-3 induces alpha/beta chain heterodimerization; both chains needed."},{"PMID":"1833064","why":"Alpha chain Kd 120 +/- 60 nM; high affinity with beta, Kd 140 +/- 30 pM."},{"PMID":"11700046","why":"SPR kinetics of IL-3 variants against IL-3R alpha."}],"covers":["LR007320"]},"LR006042":{"pair":"IL33 -> IL1RAP","headline":"IL1RAP is the co-receptor of the IL-33/ST2 complex, not a stand-alone IL-33 receptor; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"IL33 binds a complex of ST2L and IL1RAcP (IL1RAP), and IL33 stimulated proliferation and migration of human pancreatic myofibroblasts [PMID:19996325]. GtoPdb lists IL33-IL1RAP as agonist [DB:GtoPdb].","molecular_requirements":"UniProt describes a 1:1:1 heterotrimeric complex of IL33 with its primary high-affinity receptor IL1RL1 and the coreceptor IL1RAP [DB:UniProt O95760], and IL1RAP interacts with IL-33-bound IL1RL1 [DB:UniProt Q9NPH3]. Reactome lists IL33:IL1RL1 binding IL1RAP [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human pancreatic myofibroblasts from chronic pancreatitis tissue [PMID:19996325].","localisation_and_range":"IL1RAP is flagged both secreted and transmembrane, and IL33 secreted [flag].","caveats":"Abstract only. IL1RAP is a co-receptor that engages after IL33 binds IL1RL1; no direct IL33-IL1RAP binding is shown in our evidence [PMID:19996325]. Treat the IL1RAP:IL1RL1 complex as the functional unit. One further paper was abstract_insufficient.","key_references":[{"PMID":"19996325","why":"IL33, ST2L and IL1RAcP expressed together in human pancreatic myofibroblasts; IL33 stimulates them."}],"covers":["LR002800","LR006042"]},"LR002802":{"pair":"IL36B -> IL1RAP","headline":"IL1RAP is a required co-receptor for IL-36 signalling in one functional paper; no direct ligand binding shown.","interaction_type":"functional only","direction_and_effect":"Antibodies against IL-1RAcP and a cytoplasmically deleted IL-1RAcP blocked NF-kappaB activation by IL-1F6, IL-1F8 and IL-1F9, so IL-1RAcP is required alongside IL-1Rrp2 [PMID:14734551]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"IL1RAP acts as co-receptor with IL-1Rrp2 (IL1RL2); IL1RAP alone is not shown to bind the ligand [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human cell lines (Jurkat, NCI/ADR-RES) [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Single abstract-only paper. It names the ligands IL-1F6/F8/F9; the abstract does not state which is IL36B. Reactome entry links the paper to IL36:IL1RL2 binding IL1RAP [DB:Reactome].","key_references":[{"PMID":"14734551","why":"IL-1RAcP required for IL-1F6/F8/F9 signalling"}],"covers":["LR002802","LR006044"]},"LR000912":{"pair":"IL4 -> IL13RA2","headline":"No supporting paper; UniProt states IL13RA2 binds IL13 with high affinity but not IL4, so this pair looks unsupported.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence in our evidence. A UniProt note says the receptor interacts with high affinity with IL13 but not with IL4 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence (no experiments curated; mouse pair is ortholog-inferred).","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Papers judged: none confirmed (the curators' rows were different_entity or abstract_insufficient). The only database record argues against direct IL4 binding [DB:UniProt]. Treat as unsupported.","key_references":[],"covers":["LR000912","LR004340"]},"LR004341":{"pair":"IL4 -> IL2RG","headline":"IL2RG (common gamma chain) is a functional component of the IL4 receptor, shown by cross-linking and signalling in a 1993 paper.","interaction_type":"direct binding","direction_and_effect":"IL-2R gamma augments IL-4 binding affinity and is required for IL-4-mediated IRS-1 phosphorylation, i.e. it acts as a signalling subunit with agonist effect [PMID:8266078]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL2RG acts together with IL4R: UniProt describes IL4R dimerising with IL2RG to form the type 1 complex [DB:UniProt]; a ternary IL4-IL4R-gamma structure exists [DB:PDB 3BPL].","affinity_potency":[],"species_and_systems":"The curated rows give the experiment species as mouse for ligand and receptor [PMID:8266078]; the mouse pair is the ortholog-projected one. The same paper is recorded as human lymphoid cells in another dossier (see flag).","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"IL2RG alone is not a primary IL4 binder: evidence shows it augments IL4 binding to IL4R. Paper read as abstract only. Affinity not reported in our evidence.","key_references":[{"PMID":"8266078","why":"Cross-linking, affinity augmentation and IRS-1 requirement for IL-2R gamma in IL-4 receptor"}],"covers":["LR000913","LR004341"]},"LR004350":{"pair":"IL9 -> IL9R","headline":"IL9 to IL9R is supported by two functional human papers and databases; no direct binding measurement.","interaction_type":"functional only","direction_and_effect":"IL-9 signalling in bronchial epithelial cells was blocked by antibody to IL-9Ralpha [PMID:11588013]; IL-9 acts through IL-9R with JAK1/JAK3-STAT activation [PMID:9535918]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL-9Ralpha works with gammac; antibody to either blocked the response [PMID:11588013][PMID:9535918]; Tyr336 of IL-9Ralpha is crucial [PMID:9535918].","affinity_potency":[],"species_and_systems":"Human: primary and immortalized bronchial epithelial cells [PMID:11588013]; mast and T cell lines [PMID:9535918]. Mouse pair ortholog-inferred. BEAS-2B cells lacking the receptor did not respond [PMID:11588013].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Abstracts only; no binding assay. Two further papers are pending.","key_references":[{"PMID":"9535918","why":"IL-9R complex requirements and signalling"},{"PMID":"11588013","why":"Antibody blockade of IL-9 response in bronchial epithelium"}],"covers":["LR000927","LR004350"]},"LR000930":{"pair":"INHA -> TGFBR3","headline":"Betaglycan binds inhibin and mediates antagonism of activin signalling; two abstract-level direct-binding confirmations.","interaction_type":"direct binding","direction_and_effect":"Betaglycan binds inhibin and can mediate functional antagonism of activin signalling [PMID:10746731]; with betaglycan, inhibin competes with activin for type II activin receptors and prevents activin signalling [PMID:12493742]. Effect is inhibitory (antagonist) per annotation.","molecular_requirements":"Betaglycan is the co-receptor; inhibin then competes at type II receptors [PMID:12493742]. Reactome has an inhibin-A:TGFBR3:ACVR2A complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and cell system not reported in our evidence; abstracts only. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; betaglycan acts as membrane co-receptor.","caveats":"Both reads are abstract-level. One further paper was abstract_insufficient.","key_references":[{"PMID":"10746731","why":"Betaglycan binds inhibin, antagonizes activin"},{"PMID":"12493742","why":"Inhibin and betaglycan compete with activin at type II receptors"}],"covers":["LR000930","LR004353"]},"LR002811":{"pair":"INHBA -> BMPR2","headline":"Activin A binds BMPR2 in vitro, but BMPR2 is a lower-affinity receptor for it; verified papers are indirect.","interaction_type":"conflicting","direction_and_effect":"Many growth factors bind both BMPR2 and ACVR2A, but high-affinity BMPR2 growth factors are BMP15, BMP10 and Nodal, while those of ACVR2A include activin A [PMID:35643319]. UniProt says BMPR2 promotes signalling by binding activin A [DB:UniProt]; BioGRID records a Reconstituted Complex [DB:BioGRID]. Inhibin does not bind BMPRII without betaglycan [PMID:12493742].","molecular_requirements":"Not reported for activin A beyond the receptor itself in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in structural and binding work [PMID:35643319]; mouse pair projected.","localisation_and_range":"Ligand secreted flag [flag].","caveats":"Structure in the cited paper is BMPR2 with activin B and ACVR2A with activin A, not BMPR2 with activin A. Paper 12493742 concerns inhibin, not activin A. Abstract-level reading.","key_references":[{"PMID":"35643319","why":"Compares GF binding by BMPR2 and ACVR2A."}],"covers":["LR002811","LR006051"]},"LR006051":{"pair":"INHBA -> BMPR2","headline":"Activin A binds BMPR2 in vitro, but BMPR2 is a lower-affinity receptor for it; verified papers are indirect.","interaction_type":"conflicting","direction_and_effect":"Many growth factors bind both BMPR2 and ACVR2A, but high-affinity BMPR2 growth factors are BMP15, BMP10 and Nodal, while those of ACVR2A include activin A [PMID:35643319]. UniProt says BMPR2 promotes signalling by binding activin A [DB:UniProt]; BioGRID records a Reconstituted Complex [DB:BioGRID]. Inhibin does not bind BMPRII without betaglycan [PMID:12493742].","molecular_requirements":"Not reported for activin A beyond the receptor itself in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in structural and binding work [PMID:35643319]; mouse pair projected.","localisation_and_range":"Ligand secreted flag [flag].","caveats":"Structure in the cited paper is BMPR2 with activin B and ACVR2A with activin A, not BMPR2 with activin A. Paper 12493742 concerns inhibin, not activin A. Abstract-level reading.","key_references":[{"PMID":"35643319","why":"Compares GF binding by BMPR2 and ACVR2A."}],"covers":["LR002811","LR006051"]},"LR002820":{"pair":"INSL5 -> GPR142","headline":"INSL5 binds and activates the receptor named GPCR142 with nanomolar potency, but the receptor entity in this pair may be mismatched.","interaction_type":"direct binding","direction_and_effect":"Human INSL5 is a specific agonist of GPCR142: it displaces 125I-relaxin-3 with high affinity, binds in saturation assays and activates GTPgammaS and cAMP assays [PMID:15525639].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 1.5 nM","assay":"125I-relaxin-3 displacement","system":"GPCR142","cite":"PMID:15525639"},{"value":"Kd 2.5 nM","assay":"125I-INSL5 saturation binding","system":"GPCR142","cite":"PMID:15525639"},{"value":"EC50 1.3 nM and 1.2 nM","assay":"GTPgammaS and cAMP assays","system":"GPCR142","cite":"PMID:15525639"}],"species_and_systems":"Receptor-expressing cells including HEK293 with Galpha16; human INSL5 [PMID:15525639]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Abstract only. Two confirmed rows exist, one shown. INSL5 did not activate GPCR135 or LGR7 in that paper.","key_references":[{"PMID":"15525639","why":"INSL5 binds and activates GPCR142 with nanomolar affinity"}],"covers":["LR002820","LR006059"]},"LR006060":{"pair":"ISG15 -> ITGAL","headline":"ISG15 binds the alphaI domain of ITGAL (CD11a) and signals through LFA-1; direct binding plus knockout support, full text read.","interaction_type":"direct binding","direction_and_effect":"ISG15 acts as an agonist: it stimulates IFN-gamma and IL-10 secretion and activates SRC family kinases via LFA-1 [PMID:29100055]. CD11a-/- mouse splenocytes did not respond to ISG15 [PMID:29100055].","molecular_requirements":"ISG15 bound the alphaI domain of CD11a in vitro [PMID:29100055]. In HEK293T cells binding required CD11a and CD18 together; CD11b/CD18 or CD11c/CD18 did not confer binding [PMID:29100055]. Score as the ITGAL:ITGB2 complex.","affinity_potency":[],"species_and_systems":"Human NK-92 cells and PBMC assays, in vitro binding to the alphaI domain, HEK293T transfection, and CD11a-/- mouse splenocytes [PMID:29100055]. Mouse and human interactions are both listed.","localisation_and_range":"ISG15 is flagged secreted and ITGAL transmembrane [flag]; signalling is outside-in on cells [PMID:29100055].","caveats":"ISG15 binding was separable from ICAM1 binding to LFA-1 in this paper [PMID:29100055]. The curator row was read as abstract only, though full text was available. No affinity reported.","key_references":[{"PMID":"29100055","why":"Direct binding and knockout validation of LFA-1 as the ISG15 receptor"}],"covers":["LR002821","LR006060"]},"LR008004":{"pair":"ITGAV:ITGB5 -> ADGRB1","headline":"BAI1 (ADGRB1) thrombospondin repeats bind alphavbeta5 integrin; full-text evidence, effect antagonist.","interaction_type":"direct binding","direction_and_effect":"BAI1 inhibited HUVEC proliferation and this was blocked by anti-alphav integrin and anti-alphavbeta5 antibody; introducing alphavbeta5 into HEK293 cells made them susceptible to BAI1-induced death [PMID:14980512].","molecular_requirements":"The thrombospondin repeat domain bound alphavbeta5 but not alphavbeta3 in brain tissue [PMID:14980512]. Cleaved extracellular BAI1 acts, not the intact receptor [PMID:14980512].","affinity_potency":[],"species_and_systems":"Human HEK293 and HUVEC, mouse brain lysate immunoprecipitation [PMID:14980512].","localisation_and_range":"Cleaved extracellular fragment is secreted into conditioned media and acts in the extracellular space [PMID:14980512].","caveats":"Two other papers were review-only. No affinity reported. Binding rests on coimmunoprecipitation and colocalisation.","key_references":[{"PMID":"14980512","why":"BAI1-TSR binds alphavbeta5 and mediates antiproliferative effect"}],"covers":["LR008004"]},"LR005214":{"pair":"JAM2 -> JAM3","headline":"JAM2 and JAM3 are heterophilic binding partners, supported by several papers and database records.","interaction_type":"direct binding","direction_and_effect":"JAM3 ectodomain bound JAM2-Fc, also when JAM3-Fc captured cells expressing JAM2; JAM3 is the counter-receptor mediating JAM2 adhesion to T cells [PMID:11590146]. JAM-B and JAM-C heterophilically interact in cell-cell contacts, and soluble JAM-B dissociated JAM-C homodimers [PMID:16093349]. A functional JAM-B/JAM-C interaction was found between human HSPC and mesenchymal stem cells [PMID:24357068]. Reactome records the binding [DB:Reactome].","molecular_requirements":"The first Ig-like fold of JAM2 binds JAM3 [PMID:12070135]. JAM3 also binds integrin alphaMbeta2 and may be sequestered by JAM2 [PMID:16093349].","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:11590146][PMID:12070135][PMID:16093349]; mouse in vivo plus human cells [PMID:24357068].","localisation_and_range":"JAM2 flagged as not secreted [flag]; junctional or cell-contact interaction [PMID:16093349].","caveats":"All abstract-only; no affinity in our evidence. Species labelled human for a paper using mouse in vivo [PMID:24357068].","key_references":[{"PMID":"11590146","why":"Identifies JAM2-JAM3 binding"},{"PMID":"16093349","why":"Heterophilic interaction in cell contacts"},{"PMID":"24357068","why":"Functional role in HSPC homing"}],"covers":["LR001869","LR005214"]},"LR010830":{"pair":"KL -> FGFR1","headline":"Klotho binds FGFR1c as a co-receptor scaffold for FGF23; supported by structures and PDB records, abstracts only.","interaction_type":"direct binding","direction_and_effect":"Shed alpha-klotho binds FGFR1 and commits it to respond to FGF23, promoting FGF23 signalling; it is not itself a signalling agonist [PMID:29342138]. Klotho engages the FGF hormone and its FGFR together [PMID:37286607].","molecular_requirements":"Klotho acts as a co-receptor scaffold: in the structure KL tethers FGFR1c through its D3 domain and FGF23 through its C-terminal tail, and heparan sulfate is a required cofactor for dimerisation and activation [PMID:29342138]. A 1:2:1:1 FGF23-FGFR-alphaKlotho-heparan sulfate complex is described [PMID:37286607].","affinity_potency":[],"species_and_systems":"Human proteins in purified-protein crystallography and cryo-EM structures [PMID:29342138][PMID:37286607]. PDB 5W21 and 7YSH contain KL and FGFR1 chains [DB:PDB 5W21][DB:PDB 7YSH].","localisation_and_range":"The structure used the shed extracellular domain of alpha-klotho, so it can act as a soluble scaffold [PMID:29342138]; KL is flagged as a receptor itself [flag].","caveats":"Both papers were read as abstracts only. The ligand role for KL is a co-receptor role: the signalling ligand is FGF23, so scoring KL->FGFR1 alone misses the hormone requirement. Reactome describes FGF23 bound to Klotho and FGFR1c [DB:Reactome].","key_references":[{"PMID":"29342138","why":"Ternary KL-FGFR1c-FGF23 structure"},{"PMID":"37286607","why":"Cryo-EM quaternary complexes with heparan sulfate"}],"covers":["LR010830"]},"LR007050":{"pair":"L1CAM -> ITGA9:ITGB1","headline":"alpha9beta1 recognises the L1 FN3 domain and colocalises with L1 at cell contacts; one paper.","interaction_type":"functional only","direction_and_effect":"alpha9beta1 recognizes the FN3 domain and colocalizes with L1 restricted to sites of cell-cell contact [PMID:10871287].","molecular_requirements":"RGD-independent; requires FN3 homomultimerisation and dibasic RK841/KR845 sequences [PMID:10871287] (per curator annotation).","affinity_potency":[],"species_and_systems":"Human, melanoma cell colocalisation and peptide binding [PMID:10871287].","localisation_and_range":"Cell-contact sites [PMID:10871287].","caveats":"Abstract-level read in this row; the full-text lacks direct alpha9 detection by Western, so direct binding is unproven.","key_references":[{"PMID":"10871287","why":"FN3 recognised by alpha9beta1"}],"covers":["LR007050"]},"LR011037":{"pair":"LAMA1 -> ITGA6:ITGB1","headline":"No curator-confirmed paper; only a BioGRID ITGB1 record is linked to this complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Only a BioGRID reconstituted-complex record (LAMA1 with ITGB1) is available [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Two papers were abstract_insufficient. The BioGRID record concerns ITGB1 only, via a paper whose abstract names alpha1beta1 and alpha2beta1 [DB:BioGRID 315221].","key_references":[],"covers":["LR011037"]},"LR004404":{"pair":"LAMA2 -> ITGA2","headline":"Recombinant laminin alpha2 short-arm domains carry an alpha2beta1 integrin recognition site; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Using integrin-specific antibodies, recognition sites for alpha1beta1 and alpha2beta1 integrins were found in the short arms of the laminin alpha2 chain [PMID:9361014]. Labelled Stimulatory [flag].","molecular_requirements":"The alpha2beta1 heterodimer is the receptor; the curator maps the site to domain VI [PMID:9361014].","affinity_potency":[],"species_and_systems":"Recombinant laminin alpha2 domains VI-IVb; species not stated [PMID:9361014]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Abstract only; fragments tested, not full-length LAMA2. One review-only row not shown. No affinity reported.","key_references":[{"PMID":"9361014","why":"Alpha2 short-arm domains carry alpha2beta1 recognition site"}],"covers":["LR000984","LR004404"]},"LR004413":{"pair":"LAMA5 -> BCAM","headline":"Lutheran glycoprotein (BCAM) binds alpha5-containing laminin directly with high affinity; two abstract-level papers, human and mouse.","interaction_type":"direct binding","direction_and_effect":"Human and mouse Lutheran glycoprotein specifically bound laminin 10/11 with high affinity [PMID:11133776]. Soluble recombinant Lu bound laminin-10/11 by ELISA and did not bind sections of laminin alpha5 knockout embryos [PMID:12244066].","molecular_requirements":"The first 3 N-terminal Ig-superfamily domains of human Lu are critical [PMID:11133776]; the alpha5 LG3 module is essential on the laminin side [PMID:12244066]. Ligand tested as laminin-10/11 trimers.","affinity_potency":[],"species_and_systems":"Human and mouse Lu with human laminin [PMID:11133776]; soluble recombinant Lu with mouse transgenic tissue [PMID:12244066].","localisation_and_range":"LAMA5 flagged secreted [flag]; Lu is described as a transmembrane receptor and laminin alpha5 as subendothelial [PMID:12244066][PMID:11133776].","caveats":"No numeric affinity in our evidence; abstract-only reads. BioGRID, PDB 21IR and UniProt also support the pair [DB:BioGRID][DB:PDB 21IR][DB:UniProt].","key_references":[{"PMID":"11133776","why":"Human and mouse Lu bind laminin 10/11"},{"PMID":"12244066","why":"Lu binds laminin alpha5 LG3"}],"covers":["LR000994","LR004413"]},"LR011046":{"pair":"LAMB1 -> ITGA6:ITGB1","headline":"Complex row for laminin beta1 and integrin alpha6beta1; only PDB and similarity-based UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P07942 and a chain of P23229 [DB:PDB 7CEC]; UniProt notes ITGB1 interacts with LAMB1 (by similarity) [DB:UniProt].","molecular_requirements":"Receptor is the ITGA6:ITGB1 heterodimer per the entity record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA6:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Three papers pending, none judged. UniProt note is by similarity and concerns ITGB1.","key_references":[],"covers":["LR011046"]},"LR004422":{"pair":"LAMB1 -> ITGB4","headline":"Laminin beta1-containing laminins bind integrin alpha6beta4; Kd 25 nM recombinant plus radioligand and flow-adhesion studies.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha6beta4 [PMID:16413178]. Radioligand-binding and adhesion assays showed alpha6beta4 is a receptor for laminin 1, 2, 4 and 5 [PMID:7721947]. Laminin supported alpha6beta4-positive cell attachment under shear, blocked by an anti-alpha6 antibody [PMID:7699012]. Annotated stimulatory.","molecular_requirements":"The binder is the alpha6beta4 heterodimer and the ligand a whole laminin heterotrimer; ITGB4 and LAMB1 were not tested alone [PMID:16413178][PMID:7699012].","affinity_potency":[{"value":"Kd 25 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha6beta4)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; rat 804G bladder epithelial cells with laminin of unstated origin [PMID:7721947]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGB4 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The 804G system is rat and laminin origin is unstated [PMID:7721947]. The flow-assay paper is abstract-only [PMID:7699012]. Two further reads were abstract_insufficient and one review_only.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-511/521"},{"PMID":"7721947","why":"Radioligand binding of alpha6beta4 to laminin isoforms"},{"PMID":"7699012","why":"alpha6beta4 adhesion to laminin under flow"}],"covers":["LR001003","LR004422"]},"LR006105":{"pair":"LAMC1 -> DAG1","headline":"LAMC1 (in laminin-10/11) preferentially binds brain alpha-dystroglycan; one abstract-level report.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 preferentially bound brain alpha-dystroglycan compared with skeletal-muscle alpha-dystroglycan, suggesting tissue-specific glycosylation modifies laminin binding [PMID:16709410]. Annotated effect is Stimulatory [flag].","molecular_requirements":"The ligand is the laminin-10/11 heterotrimer, so LAMC1 acts as one chain; glycosylation of alpha-dystroglycan affects binding [PMID:16709410].","affinity_potency":[],"species_and_systems":"Mammalian brain and skeletal-muscle alpha-dystroglycan; the species is not stated in our evidence [PMID:16709410].","localisation_and_range":"Ligand flagged secreted [flag]; receptor DAG1 is flagged secreted, receptor and transmembrane [flag]. Range otherwise not reported.","caveats":"Only an abstract was read. The assay cannot isolate LAMC1 from the other chains. No affinity is reported. A second confirmed row has no paper shown.","key_references":[{"PMID":"16709410","why":"Laminin-10/11 binds brain alpha-dystroglycan, abstract only"}],"covers":["LR002871","LR006105"]},"LR011127":{"pair":"LAMC1 -> ITGA6:ITGB4","headline":"LAMC1 with ITGA6:ITGB4 has only a PDB record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P23229 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Complex flag information is not given for this row; ligand is annotated secreted [flag]. Range otherwise not reported.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Three papers were abstract_insufficient and one different_entity. The PDB entry lists no ITGB4 chain. Related chain-level LAMC1-ITGA6 row has papers, but none are credited to this complex row.","key_references":[],"covers":["LR011127"]},"LR011082":{"pair":"LAMC1 -> ITGA9:ITGB1","headline":"LAMC1 with ITGA9:ITGB1 has only a PDB record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P05556 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Four papers were abstract_insufficient and one different_entity. The PDB entry lists no ITGA9 chain.","key_references":[],"covers":["LR011082"]},"LR004431":{"pair":"LAMC1 -> ITGB4","headline":"Laminin (via LAMC1) engages integrin alpha6beta4 in a cell-adhesion assay; functional evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Laminin supported attachment of alpha6beta4-positive cells under fluid shear stress, and an anti-alpha6 antibody inhibited attachment and detached adherent cells [PMID:7699012]. Recorded effect: stimulatory [flag].","molecular_requirements":"The assayed ligand is the laminin heterotrimer (LAMA1/LAMB1/LAMC1) and the binder is the alpha6beta4 heterodimer, so LAMC1 and ITGB4 are chain-level proxies [PMID:7699012]. Laminin fragment E8 also supported attachment [PMID:7699012].","affinity_potency":[],"species_and_systems":"Human and other epithelial/carcinoma cell lines in laminar-flow adhesion assays; species of cell lines not stated in our evidence. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC1 is flagged secreted [flag]; the assay used laminin as a substrate.","caveats":"Abstract only; no binding constants; no direct binding of LAMC1 to ITGB4 shown; one paper; antibody against alpha6, not beta4. A beta1 antibody did not inhibit rapid attachment [PMID:7699012].","key_references":[{"PMID":"7699012","why":"Laminin adhesion under flow mediated by alpha6beta4"}],"covers":["LR001013","LR004431"]},"LR004440":{"pair":"LEP -> LRP2","headline":"Megalin (LRP2) binds and internalises leptin in rat cells, a clearance rather than signalling interaction.","interaction_type":"direct binding","direction_and_effect":"Megalin bound leptin in the presence of Ca(2+) and mediated its internalisation and degradation, indicating a clearance receptor role [PMID:15131016]. No signalling effect reported in our evidence.","molecular_requirements":"Binding was calcium dependent [PMID:15131016]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand blotting, quartz-crystal microbalance and degradation assays in megalin-expressing rat yolk sac L2 cells; histoautoradiography in rats with 125I-leptin. Curators list human leptin with rat receptor. Human and mouse pairs are ortholog-inferred [PMID:15131016].","localisation_and_range":"Circulating leptin is filtered by glomeruli and internalised by proximal convoluted tubules, where megalin is expressed; LEP-R localised to other nephron segments [PMID:15131016].","caveats":"Abstract-only read. This is scavenger/clearance biology, so a CCC tool may mislead if read as signalling; no database records.","key_references":[{"PMID":"15131016","why":"Megalin binds and degrades leptin in renal proximal tubules"}],"covers":["LR001022","LR004440"]},"LR006114":{"pair":"LGALS3 -> CDH5","headline":"VE-cadherin (CDH5) was one of four endothelial glycoproteins pulled down by galectin-3; weak support, CD146 was the functional partner.","interaction_type":"functional only","direction_and_effect":"Affinity purification with galectin-3 extracted VE-cadherin (CD144) among four endothelial membrane glycoproteins; CD146 was the major binder and its knockdown abolished galectin-3-induced IL-6 and G-CSF secretion [PMID:28364041]. Effect through CDH5 not reported in our evidence.","molecular_requirements":"Galectin-3 bound N-linked glycans on CD146; whether the same applies to CDH5 is not reported in our evidence [PMID:28364041].","affinity_potency":[],"species_and_systems":"Human vascular endothelial cells [PMID:28364041]. Mouse pair is ortholog-inferred.","localisation_and_range":"Galectin-3 flagged secreted; CDH5 flagged transmembrane [flag]. Circulating galectin-3 acts on endothelium [PMID:28364041].","caveats":"Only co-purification, no CDH5-specific validation; possible indirect pull-down via CD146 complexes. Abstract-only read.","key_references":[{"PMID":"28364041","why":"Galectin-3 affinity purification lists CD144/VE-cadherin"}],"covers":["LR002880","LR006114"]},"LR006123":{"pair":"LGALS3 -> PECAM1","headline":"PECAM1 (CD31) was co-purified from endothelial cells on galectin-3 affinity columns; binding is shown only by pull-down, with no functional confirmation.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 affinity purification extracted PECAM-1 among four endothelial membrane glycoproteins; effect direction is not established for PECAM1 [PMID:28364041].","molecular_requirements":"Not reported in our evidence for PECAM1. The major galectin-3 ligand in this paper was CD146, which was the one functionally validated by siRNA [PMID:28364041].","affinity_potency":[],"species_and_systems":"Human vascular endothelial cells; mouse pair is ortholog-inferred [PMID:28364041].","localisation_and_range":"PECAM1 carries a transmembrane flag [flag]; galectin-3 has a secreted flag [flag].","caveats":"Abstract only. PECAM1 is one of four co-purified glycoproteins; its functional role in galectin-3-induced cytokine secretion was not tested, and CD146 was the major ligand. Affinity purification may reflect glycan-mediated binding to a abundant glycoprotein rather than a dedicated receptor interaction.","key_references":[{"PMID":"28364041","why":"Galectin-3 affinity purification identifies PECAM-1 among endothelial binders"}],"covers":["LR002889","LR006123"]},"LR002901":{"pair":"LGALS8 -> LILRB4","headline":"Galectin-8 is reported as a high-affinity functional ligand of LILRB4 driving M-MDSC; one 2024 paper, abstract plus figure legends.","interaction_type":"direct binding","direction_and_effect":"Gal-8 ligation of LILRB4 induces M-MDSC by activating STAT3 and inhibiting NF-kB (agonist); Gal-8 expression promotes in vivo tumor growth in mice, attenuated by LILRB4 knockout [PMID:38232701].","molecular_requirements":"Gal-8 and APOE bind LILRB4 noncompetitively, but only Gal-8 induced MDSC [PMID:38232701].","affinity_potency":[],"species_and_systems":"Human proteins for binding; mouse tumor models for in vivo effect [PMID:38232701].","localisation_and_range":"Gal-8 carries a secreted flag [flag]; LILRB4 a transmembrane flag [flag].","caveats":"Described as high-affinity but the abstract gives no numeric value. Read as abstract with figure-legend excerpts, which mostly concern antibody epitope mapping. Antibodies blocking Gal-8 suppressed tumor growth in vivo [PMID:38232701].","key_references":[{"PMID":"38232701","why":"Gal-8 as functional LILRB4 ligand driving M-MDSC"}],"covers":["LR002901"]},"LR006132":{"pair":"LGALS9 -> BCR","headline":"Galectin-9 binds IgM B-cell receptor and strongly dampens BCR signalling; the entity named BCR here is likely the B-cell receptor, not the BCR gene.","interaction_type":"functional only","direction_and_effect":"Recombinant galectin-9 nearly completely abolished BCR signaling; Gal9-deficient B cells showed enhanced BCR microclusters and ERK1/2 phosphorylation (antagonist/inhibitory) [PMID:30120235].","molecular_requirements":"Galectin-9 merges IgM-BCR nanoclusters, immobilizes it, and relocalizes it with CD45 and CD22 [PMID:30120235].","affinity_potency":[],"species_and_systems":"Experiments used primary mouse naive B cells (WT and Gal9-KO); human pair is ortholog-inferred [PMID:30120235].","localisation_and_range":"Galectin-9 is secreted by flag [flag]; acts on the B cell surface.","caveats":"Abstract and excerpts only; curated assay class is functional. IgM-BCR as a ligand is stated in the abstract; no affinity. The entity symbol BCR may be ambiguous.","key_references":[{"PMID":"30120235","why":"IgM-BCR identified as galectin-9 ligand that suppresses BCR signaling"}],"covers":["LR002903","LR006132"]},"LR005223":{"pair":"LGALS9 -> CD44","headline":"Galectin-9 reported to bind CD44 on induced Treg cells; one abstract-only paper, plus a UniProt note.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 increased iTreg stability and function by directly binding CD44, which formed a complex with TGF-betaRI and activated Smad3; curator labels it agonist [PMID:25065622]. UniProt notes LGALS9 interaction activates LCK, ERK and MAPK signalling in NK cells [DB:UniProt].","molecular_requirements":"CD44 forms a complex with TGF-betaRI; galectin-9 acts synergistically with TGF-beta [PMID:25065622]. Extra receptor components beyond this are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator labels both partners human, but the full-text excerpts describe Lgals9-deficient mice and in vitro T-cell differentiation [PMID:25065622]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"Galectin-9 is flagged secreted and CD44 flagged transmembrane [flag]; range not further reported in our evidence.","caveats":"Only one paper, read as abstract only for the curator call. Binding was inferred from the abstract wording; excerpts show carbohydrate-dependence (lactose inhibited iTreg generation) [PMID:25065622]. UniProt evidence is functional [DB:UniProt].","key_references":[{"PMID":"25065622","why":"iTreg stability via galectin-9/CD44/TGF-betaRI/Smad3"}],"covers":["LR001881","LR005223"]},"LR002910":{"pair":"LGALS9 -> VSIR","headline":"Galectin-9 reported to bind VISTA with Kd 18 nM; functional AML immune-evasion data, one paper.","interaction_type":"direct binding","direction_and_effect":"VISTA on T cells recognises galectin-9 secreted by AML cells; soluble VISTA enhances galectin-9's effect, causing membrane-potential changes, granzyme B activation and T-cell apoptosis; curator labels it antagonist [PMID:33329552].","molecular_requirements":"Soluble VISTA from AML cells enhances galectin-9 action, likely via multiprotein complexes [PMID:33329552]. Other subunits not reported.","affinity_potency":[{"value":"Kd 18 nM","assay":"titration of human recombinant galectin-9 binding to VISTA (SRCD spectroscopy)","system":"recombinant proteins","cite":"PMID:33329552"}],"species_and_systems":"Human AML cells (THP-1, primary AML) and T cells; recombinant human galectin-9 [PMID:33329552].","localisation_and_range":"Galectin-9 secreted by AML cells; VISTA flagged transmembrane [flag][PMID:33329552]; soluble VISTA also released [PMID:33329552].","caveats":"One paper; VISTA was an immunoglobulin Fc fragment construct in the ELISA setup per the excerpts, so avidity may affect the Kd. No database support.","key_references":[{"PMID":"33329552","why":"VISTA binds galectin-9, Kd 18 nM; AML immune evasion"}],"covers":["LR002910"]},"LR005232":{"pair":"LGI3 -> ADAM23","headline":"LGI3 binds ADAM23 in three papers (adipocytes, brain proteomics); binding shown by pull-down and affinity purification, two papers read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"LGI3 associates with ADAM23 in adipose tissue and 3T3-L1 cells; LGI3 treatment attenuates adipogenesis and this is reversed by ADAM23 knockdown, so it acts as an antagonist of adipogenesis through ADAM23 [PMID:22405860]. In mouse brain LGI3 uses ADAM23 as a receptor [PMID:38194969].","molecular_requirements":"ADAM23 had the highest recovery among ADAM family members in LGI3 pull-downs, but ADAM22 and ADAM11 were also recovered, so ADAM23 is a predominant rather than sole partner [PMID:38194969]. LGI3 also co-assembles with Kv1 channels (Kv1.1, Kv1.2) [PMID:38194969]. A 60-kDa LGI3 form is the major secreted form in 3T3-L1 cells [PMID:22405860].","affinity_potency":[],"species_and_systems":"Adipocyte work used 3T3-L1 cells and ob/ob mouse adipose tissue [PMID:22405860]; the brain work used Lgi3 knock-in mice [PMID:38194969]. The human pair is ortholog-inferred; the mouse pair is directly supported.","localisation_and_range":"LGI3 is secreted (entity flag [flag]); in brain it is secreted from oligodendrocytes and accumulates at juxtaparanodes of myelinated axons [PMID:38194969]. ADAM23 is flagged as secreted and receptor [flag].","caveats":"Two of three papers were read as abstracts only [PMID:22405860][PMID:38194969]. A third paper's statement that LGI3 binds ADAM22/ADAM23 is a browser-read, unverified sentence from a paper about Lgi4 [PMID:20220021]. Reactome records binding of LGI3 to ADAM22, ADAM23 and syntaxin1 [DB:Reactome].","key_references":[{"PMID":"38194969","why":"LGI3 uses ADAM23 as receptor in vivo (affinity purification, Lgi3 knock-in mice)"},{"PMID":"22405860","why":"LGI3 associates with ADAM23 and suppresses adipogenesis through it"}],"covers":["LR001890","LR005232"]},"LR001029":{"pair":"LPA -> ITGB2","headline":"Lp(a) binds integrin Mac-1 (ITGAM/ITGB2) via apo(a); one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Through its apo(a) moiety Lp(a) specifically interacts with the beta2-integrin Mac-1, promoting monocyte adhesion and transendothelial migration; engagement activates NF-kappaB and induces tissue factor expression [PMID:16403785].","molecular_requirements":"The evidence is for the Mac-1 heterodimer (alphaM beta2), so ITGB2 alone is not shown to be sufficient [PMID:16403785]. Binding is blocked by plasminogen/angiostatin kringle 4 and strengthened by homocysteine [PMID:16403785].","affinity_potency":[],"species_and_systems":"Human proteins; monocytes and atherosclerotic plaques [PMID:16403785].","localisation_and_range":"LPA is flagged secreted [flag]; circulating lipoprotein acting on a cell-surface integrin.","caveats":"One paper, abstract only; no affinity reported. No database record.","key_references":[{"PMID":"16403785","why":"Lp(a) apo(a) binds Mac-1 and promotes monocyte adhesion"}],"covers":["LR001029"]},"LR006141":{"pair":"LRFN4 -> PTPRS","headline":"LRFN4 (SALM3) binds LAR-family RPTPs including PTPRS in a splice-dependent trans-synaptic interaction; one paper, plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SALM3 interacts with and requires all three LAR-RPTPs (LAR, PTP-sigma, PTP-delta) for presynaptic differentiation [PMID:26321637]. The interaction needs the mini-exon B insert in the LAR-RPTP [PMID:26321637]. Reactome lists SALM3 binding LAR-RPTP [DB:Reactome].","molecular_requirements":"LAR-RPTPs containing meB alone bound SALM3, those with only meA or neither did not; adding meA to meB increased binding. Ig1-3 domains of PTP-delta were sufficient [PMID:26321637].","affinity_potency":[],"species_and_systems":"Paper reports mouse SALM3 and mouse PTP-delta in its assays; dossier species fields say human and the mouse pair is ortholog-inferred [PMID:26321637]. Cell-binding and co-culture assays, plus Salm3 knockout mice [PMID:26321637].","localisation_and_range":"Both flagged transmembrane for the pair, so contact-dependent trans-synaptic adhesion [flag][PMID:26321637].","caveats":"Evidence is family-level for all LAR-RPTPs; pair-specific data for PTPRS are not separated in our evidence. Paper's text names PTP-sigma only in the statement covering all three RPTPs. Affinity not reported in our evidence.","key_references":[{"PMID":"26321637","why":"SALM3 binds LAR-RPTPs in a meB-dependent manner"}],"covers":["LR002916","LR006141"]},"LR006150":{"pair":"LRRC4 -> NTNG2","headline":"Netrin-G2 and its ligand bind with about 2.5 nM affinity, and mouse knockouts of either share an auditory startle phenotype; crystal structure record present.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist [PMID:17973922]. Genetic inhibition of either netrin-G2 or netrin-G2 ligand gave nearly identical loss of acoustic startle with normal ABR, so they act in the same pathway [PMID:17973922].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 2.5 nM","assay":"binding affinity, method not given in abstract","system":"mouse proteins","cite":"PMID:17973922"}],"species_and_systems":"Mouse proteins and mouse knockouts [PMID:17973922]. The human pair is ortholog-inferred, while the mouse pair is not. Databases hold a co-crystal structure [DB:PDB 3ZYI], BioGRID [DB:BioGRID] and IntAct SPR [DB:IntAct].","localisation_and_range":"Both partners are flagged non-secreted [flag]. Range not reported in our evidence.","caveats":"Abstract only, and the assay behind 2.5 nM is not stated. The paper uses the names netrin-G2 ligand; mapping to LRRC4 comes from the curators.","key_references":[{"PMID":"17973922","why":"About 2.5 nM affinity and matching knockout phenotypes"}],"covers":["LR002925","LR006150"]},"LR001038":{"pair":"LTA -> LTBR","headline":"LTBR binds LT alpha-beta membrane complexes (shown in mouse); LTA alone as a ligand is not shown in our evidence.","interaction_type":"direct binding","direction_and_effect":"A mouse LTbetaR-Fc chimera bound LT alpha-beta complexes on activated T cells and on insect cells expressing LT alpha and LT beta [PMID:7594541]. Curator labels this agonist; UniProt calls LTBR the receptor for heterotrimeric lymphotoxin containing LTA and LTB [DB:UniProt].","molecular_requirements":"The ligand is the LT alpha/beta heteromer, not LT alpha alone. UniProt says LTA binds LTBR in its heterotrimeric form with LTB, and that the LTA homotrimer binds TNFR1, TNFBR and HVEM [DB:UniProt]. A structure with chains of LTA and LTBR is deposited [DB:PDB 4MXW]; Reactome lists an LTBR:lymphotoxin,TNFSF14 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"The paper used mouse LTbetaR (76% identity to human) with baculovirus-infected insect cells and activated T cells [PMID:7594541]. Curated species labels say human.","localisation_and_range":"LT alpha is flagged secreted and LTBR transmembrane [flag], but the active ligand here is membrane-anchored [PMID:7594541].","caveats":"Abstract read only. The pair as listed credits LTA alone; the evidence supports a requirement for LTB. GtoPdb lists the interaction without type, action or affinity [DB:GtoPdb]. The human pair is projected from mouse evidence.","key_references":[{"PMID":"7594541","why":"Mouse LTbetaR-Fc binds LT alpha-beta complexes"}],"covers":["LR001038","LR004452"]},"LR005241":{"pair":"LY9 -> LY9","headline":"CD229 (LY9) binds itself homophilically; one paper with mutagenesis, human and mouse.","interaction_type":"direct binding","direction_and_effect":"CD229-Ig bound CD229-transfected cells but not cells expressing other CD150 family receptors; both human and mouse CD229 interacted with itself [PMID:15905546]. Curator labels agonist. CD229 relocalized to the T-B cell contact area during immune synapse formation [PMID:15905546].","molecular_requirements":"The N-terminal Ig domain mediates homophilic adhesion; E27A, E29A and R89A impaired binding and R44A enhanced it [PMID:15905546].","affinity_potency":[],"species_and_systems":"Soluble human CD229-Ig on transfected cells; human and mouse both tested; T-B cell conjugates [PMID:15905546]. IntAct lists a solid phase assay [DB:IntAct].","localisation_and_range":"Cell-surface, contact-dependent homophilic adhesion at the immune synapse [PMID:15905546]. The annotation flags it as secreted [flag], which the paper does not support.","caveats":"Abstract only. No affinity. Homophilic pairs mean one gene serves as both ligand and receptor, so CCC tools need that cell-pair context.","key_references":[{"PMID":"15905546","why":"CD229 homophilic binding mapped to N-terminal domain"}],"covers":["LR001899","LR005241"]},"LR001056":{"pair":"MDK -> ITGA4","headline":"Midkine binds integrin alpha4beta1 and alpha6beta1 in mouse embryo and cell assays; evidence is for heterodimers, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Midkine binds these integrins; alpha4beta1 and alpha6beta1 are concluded to be functional midkine receptors. Anti-alpha4 antibody inhibited midkine-dependent migration of osteoblastic cells and anti-alpha6 inhibited neurite outgrowth of embryonic neurons; midkine raised paxillin tyrosine phosphorylation [PMID:15466886].","molecular_requirements":"Needs alpha4 with beta1: purified alpha4beta1 bound midkine [PMID:15466886].","affinity_potency":[],"species_and_systems":"Mouse embryo (13-day) extracts and cell assays; curated as human/human, but the experiments used mouse material [PMID:15466886]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine growth factor.","caveats":"Single paper, abstract only. The integrins may cooperate with other midkine receptors (PTPRZ, LRP, ALK) [PMID:15466886]. UniProt records the interaction [DB:UniProt]. Alpha4 alone and alpha4beta7 not tested in our evidence.","key_references":[{"PMID":"15466886","why":"midkine-integrin binding and function"}],"covers":["LR001056","LR004469"]},"LR001065":{"pair":"MEPE -> PHEX","headline":"SPR shows MEPE binds soluble PHEX in a Zn-dependent way via the ASARM motif; one abstract-only paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"Soluble PHEX interacted specifically and dose-dependently with immobilised MEPE by SPR [PMID:15664000]. PHEX is described as binding without cleaving MEPE, protecting it from other proteases and limiting ASARM release [PMID:15664000].","molecular_requirements":"Interaction is Zn-dependent and localised to the MEPE C-terminal ASARM motif; phosphorylated ASARM peptide inhibited it (KD(app) 15 microM, 68% maximal inhibition) while control and RGD peptides did not [PMID:15664000].","affinity_potency":[{"value":"EC50 553 nM","assay":"SPR, secPHEX over immobilised MEPE","system":"recombinant soluble PHEX and MEPE","cite":"PMID:15664000"}],"species_and_systems":"Human proteins by SPR; in vivo ASARM peptide effects tested in mouse [PMID:15664000]. Mouse pair is ortholog-inferred.","localisation_and_range":"MEPE is flagged secreted [flag]; PHEX is a membrane endopeptidase, used as soluble form here [PMID:15664000].","caveats":"Single abstract-only paper; PHEX is an enzyme, so this is a binding partner rather than a signalling receptor. IntAct records the same SPR experiment [DB:IntAct].","key_references":[{"PMID":"15664000","why":"SPR of PHEX-MEPE, EC50 553 nM, ASARM motif dependence"}],"covers":["LR001065","LR004478"]},"LR001902":{"pair":"MICA -> KLRK1","headline":"NKG2D is identified as the receptor for MICA on NK and T cells; functional paper plus structures and SPR records.","interaction_type":"direct binding","direction_and_effect":"A receptor for MICA on gammadelta T, CD8+ alphabeta T and NK cells was identified as NKG2D; its engagement activated cytolysis of MICA-expressing targets [PMID:10426993].","molecular_requirements":"DAP10 partner is described for the complex in other work, not for this paper; not reported in our evidence for this row.","affinity_potency":[],"species_and_systems":"Human cells [PMID:10426993]. Database structures: PDB 1HYR [DB:PDB 1HYR]; SPR record [DB:IntAct].","localisation_and_range":"MICA is flagged membrane-bound, suggesting contact-dependent action [flag].","caveats":"The curated assay class is functional, and the abstract does not spell out the binding method; physical binding rests on database records.","key_references":[{"PMID":"10426993","why":"NKG2D identified as MICA receptor and activating"}],"covers":["LR001902"]},"LR001074":{"pair":"MMP1 -> ITGA2","headline":"MMP-1 binds the alpha2 integrin I domain and alpha2beta1 in two independent papers; a binding rather than classic signalling interaction.","interaction_type":"direct binding","direction_and_effect":"Direction and effect of signalling are not reported in our evidence; the integrin directs MMP-1 to its matrix target and pro-MMP-1 supports alpha2beta1-dependent platelet adhesion [PMID:11359786].","molecular_requirements":"The alpha2 integrin I domain bound pro and active MMP-1 in a divalent cation-dependent manner, not MMP-3 or MMP-13 [PMID:11359774]. Pro-MMP-1 co-immunoprecipitated with alpha2beta1 from keratinocytes; no other integrins bound MMP-1 [PMID:11359786]. The beta1 partner is thus part of the native complex.","affinity_potency":[],"species_and_systems":"Purified human MMP-1 and recombinant I domain by ELISA [PMID:11359774]; human keratinocytes [PMID:11359786].","localisation_and_range":"MMP-1 carries a secreted flag [flag]; matrix-associated, localised to alpha2beta1 contacts in migrating keratinocytes [PMID:11359786].","caveats":"Abstract-only reading; one further paper was abstract_insufficient. No affinity. Enzyme-matrix context may be more relevant than receptor signalling. BioGRID records exist [DB:BioGRID].","key_references":[{"PMID":"11359774","why":"ELISA: I domain binds pro and active MMP-1"},{"PMID":"11359786","why":"Co-IP of pro-MMP-1 with alpha2beta1"}],"covers":["LR001074"]},"LR005250":{"pair":"MRC1 -> PTPRC","headline":"MRC1 binds CD45 (PTPRC); two abstract-only papers, one glycoform-dependent.","interaction_type":"direct binding","direction_and_effect":"The mannose receptor cysteine-rich domain binds two low molecular weight CD45 isoforms in a sugar-dependent manner [PMID:10575006]. MRC1 on dendritic cells interacts directly with CD45 on T cells and inhibits its phosphatase activity, inducing T-cell tolerance [PMID:27601670].","molecular_requirements":"Binding depends on the cysteine-rich domain acting as a lectin and on cell-specific, possibly sulfated, CD45 glycoforms [PMID:10575006].","affinity_potency":[],"species_and_systems":"Ligand blots of mouse spleen and lymph node lysates [PMID:10575006]; DC/T-cell coculture in vitro and in vivo [PMID:27601670]. Dossier labels experiments human.","localisation_and_range":"Both are membrane proteins [flag], so contact-dependent between dendritic cells/macrophages and T cells.","caveats":"Both papers read as abstracts only. Binding is glycoform-conditional, so it will not hold in every CD45-expressing cell. One IntAct solid-phase record [DB:IntAct P22897-P08575].","key_references":[{"PMID":"10575006","why":"CR-Fc binds CD45 glycoforms"},{"PMID":"27601670","why":"Direct MR-CD45 interaction inhibits phosphatase"}],"covers":["LR001910","LR005250"]},"LR001911":{"pair":"MSMP -> CCR2","headline":"PSMP/MSMP acts as a chemokine ligand for CCR2, shown functionally in mice with full text.","interaction_type":"functional only","direction_and_effect":"PSMP chemo-attracts Ly6Chi monocytes in a CCR2-dependent manner; this was lost in CCR2 knockout mice and CCR2 antagonist RS504393 reduced recruitment [PMID:28698550]. UniProt also states it acts as a ligand for CCR2 [DB:UniProt].","molecular_requirements":"No co-receptor or subunit requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (adoptive transfer, colitis models); human and mouse PSMP both attract mouse macrophages in a CCR2-dependent manner [PMID:28698550].","localisation_and_range":"Secreted chemokine [flag], acting at a distance as a chemoattractant [PMID:28698550].","caveats":"Direct binding not shown in the abstract or excerpts; evidence is CCR2-dependent chemotaxis. Abstract plus excerpts only.","key_references":[{"PMID":"28698550","why":"CCR2-dependent chemotaxis by PSMP in vivo"}],"covers":["LR001911","LR005251"]},"LR010641":{"pair":"MUC2 -> AGR2","headline":"No paper-level evidence; support is database records of an MUC2-AGR2 interaction only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in database records; experimental systems not reported in our evidence.","localisation_and_range":"AGR2 is flagged secreted [flag]; otherwise not reported in our evidence.","caveats":"No curator-verified paper; the single judged row was classed as a different entity. IntAct lists co-immunoprecipitation records [DB:IntAct] and UniProt subunit notes state the interaction [DB:UniProt]. This looks more like a protein-protein association than a ligand-receptor pair.","key_references":[],"covers":["LR010641"]},"LR001083":{"pair":"MYOC -> FZD10","headline":"Myocilin-AP fusion bound FZD10 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. UniProt also records MYOC interacting with FZD10 [DB:UniProt].","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001083","LR004494"]},"LR006204":{"pair":"NCAN -> CNTN2","headline":"Neurocan binds TAG-1/axonin-1 (CNTN2) with high affinity in a binding assay; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Neurocan and phosphacan are high-affinity ligands of TAG-1/axonin-1; chondroitinase treatment did not affect neurocan binding [PMID:8663515].","molecular_requirements":"The chondroitin sulfate chains are not required for neurocan binding, unlike phosphacan (decreased by approximately 70%) [PMID:8663515].","affinity_potency":[{"value":"Kd 0.3 nM","assay":"binding assay","system":"neurocan with TAG-1/axonin-1","cite":"PMID:8663515"}],"species_and_systems":"Species not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Neurocan is flagged secreted [flag], so an extracellular matrix ligand for a cell-surface contactin.","caveats":"Abstract only. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"8663515","why":"Neurocan binds TAG-1/axonin-1, Kd 0.3 nM"}],"covers":["LR002979","LR006204"]},"LR001092":{"pair":"NDP -> LGR4","headline":"One abstract-only paper: Norrin activates Wnt signalling via LGR4, with binding suggested; both species rows are ortholog-inferred.","interaction_type":"conflicting","direction_and_effect":"Norrin stimulates Wnt signalling mediated by LGR4 but not LGR5 or LGR6 in mammalian cells [PMID:23444378].","molecular_requirements":"Not reported in our evidence beyond that Norrin also signals through Frizzled4 and acts as a BMP antagonist [PMID:23444378].","affinity_potency":[],"species_and_systems":"Mammalian cells; the paper's species of proteins is not specified in the abstract [PMID:23444378]. PDB lists four structures with chains of both proteins [DB:PDB 8WVX].","localisation_and_range":"Norrin is flagged secreted [flag].","caveats":"Binding studies suggested interactions with LGR4, 5 and 6 although only LGR4 was activated, so binding and function diverge [PMID:23444378]. Only an abstract was read; no affinity is given.","key_references":[{"PMID":"23444378","why":"Norrin stimulates LGR4-mediated Wnt signalling"}],"covers":["LR001092","LR004503"]},"LR004503":{"pair":"NDP -> LGR4","headline":"One abstract-only paper: Norrin activates Wnt signalling via LGR4, with binding suggested; both species rows are ortholog-inferred.","interaction_type":"conflicting","direction_and_effect":"Norrin stimulates Wnt signalling mediated by LGR4 but not LGR5 or LGR6 in mammalian cells [PMID:23444378].","molecular_requirements":"Not reported in our evidence beyond that Norrin also signals through Frizzled4 and acts as a BMP antagonist [PMID:23444378].","affinity_potency":[],"species_and_systems":"Mammalian cells; the paper's species of proteins is not specified in the abstract [PMID:23444378]. PDB lists four structures with chains of both proteins [DB:PDB 8WVX].","localisation_and_range":"Norrin is flagged secreted [flag].","caveats":"Binding studies suggested interactions with LGR4, 5 and 6 although only LGR4 was activated, so binding and function diverge [PMID:23444378]. Only an abstract was read; no affinity is given.","key_references":[{"PMID":"23444378","why":"Norrin stimulates LGR4-mediated Wnt signalling"}],"covers":["LR001092","LR004503"]},"LR001920":{"pair":"NECTIN2 -> CD226","headline":"Direct, bidirectional binding with functional NK activation shown in human cells; three curator-verified papers, all read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"Nectin-2 is an activating ligand for CD226 (DNAM-1): Nectin-2-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained Nectin-2-expressing CHO-K cells, and masking either partner reduced NK lysis of tumour cells [PMID:15607800]. Ectopic CD112 (Nectin-2) made mouse BW5147 cells more susceptible to IL-2-activated T and NK cytotoxicity, blocked by anti-CD226 mAb [PMID:15039383]. Ubiquitin-pathway inhibition raised surface Nectin2 and enhanced NK killing [PMID:30888046].","molecular_requirements":"CD226 acts together with LFA-1 in triggering cytotoxicity and cytokine secretion [PMID:15039383]. Homophilic interaction of cell-surface CD112 may reduce CD226 binding to cell-surface CD112 [PMID:15039383]. No subunit requirement beyond this is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in all three papers (recombinant Fc chimeras, transfectants, NK/T cells, tumour cell lines). The mouse pair is projected from human evidence [PMID:15607800] [PMID:15039383].","localisation_and_range":"Both partners carry membrane/transmembrane flags [flag]; the papers describe interaction between NK cell and target cell surfaces, i.e. contact-dependent [PMID:15607800].","caveats":"All papers read as abstracts only. Soluble CD226 binds CD155 and CD112 with comparable affinity but no value is given in our evidence [PMID:15039383]. Nectin-2 is mainly cytoplasmic in tumour lines, which limits surface availability [PMID:30888046]. Database support (BioGRID, IntAct, Reactome, UniProt) agrees [DB:UniProt] [DB:Reactome].","key_references":[{"PMID":"15607800","why":"Reciprocal Fc-chimera binding plus NK lysis"},{"PMID":"15039383","why":"Nectin-2 as CD226 ligand, functional cytotoxicity"},{"PMID":"30888046","why":"Surface Nectin2 regulated by ubiquitination, NK killing"}],"covers":["LR001920","LR005259"]},"LR006213":{"pair":"NFASC -> NRCAM","headline":"Direct neurofascin-NrCAM binding shown in transfected cells and immunoprecipitation; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Binding studies in transfected COS7 cells and immunoprecipitations reveal a direct interaction between neurofascin and NrCAM, mapped to the Ig domains of neurofascin [PMID:8922386]. Immobilised neurofascin-Fc stimulated tectal neurite outgrowth through NrCAM on the axon, but soluble neurofascin did not [PMID:8922386].","molecular_requirements":"Binding can be modulated by alternative splicing of specific stretches within neurofascin [PMID:8922386]. Subunit requirements beyond this are not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 cells and tectal cells; the species is not reported in our evidence. Paper read as abstract, with some full-text figure legends [PMID:8922386]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both are membrane glycoproteins acting heterophilically at the axon surface [PMID:8922386]. NRCAM carries a secreted flag as well as a transmembrane flag [flag].","caveats":"One paper, 1996; effect on the receptor side is shown as neurite outgrowth only when neurofascin is immobilised. Reactome records the NFASC:NRCAM complex [DB:Reactome].","key_references":[{"PMID":"8922386","why":"Direct NFASC-NRCAM interaction mapped to neurofascin Ig domains"}],"covers":["LR002988","LR006213"]},"LR004512":{"pair":"NID2 -> COL13A1","headline":"Single abstract-level report of nidogen-2 binding the type XIII collagen ectodomain by SPR, in nanomolar range; no signalling shown.","interaction_type":"direct binding","direction_and_effect":"Recombinant COL13A1 ectodomain interacted with immobilised nidogen-2 by surface plasmon resonance; nidogen-2 binding resided in pepsin-sensitive portions of the ectodomain [PMID:11956183]. No signalling or effect on a cell is shown; the curator notes the roles are inverted, with collagen XIII the transmembrane partner.","molecular_requirements":"The shed ectodomain forms 240-kDa trimers [PMID:11956183]; binding of the intact membrane protein is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant ectodomain from insect cells (curator species: human); mouse pair is ortholog-projected, not tested [PMID:11956183].","localisation_and_range":"Nidogen-2 is flagged secreted and COL13A1 transmembrane [flag]; this reads as a matrix-to-cell-surface adhesion contact rather than a diffusible signal.","caveats":"Abstract only; affinity is reported only as 'nanomolar range', with no value. Binding was shown with the shed ectodomain, not a full-length receptor. Adhesion rather than receptor signalling.","key_references":[{"PMID":"11956183","why":"SPR binding of COL13A1 ectodomain to nidogen-2"}],"covers":["LR001101","LR004512"]},"LR004521":{"pair":"NLGN3 -> NRXN3","headline":"One paper, read in full in a browser, reports all neuroligins bound all three neurexins in rat brain.","interaction_type":"direct binding","direction_and_effect":"All neuroligins bound preferentially to beta-neurexins lacking an insert, and all bound all three neurexins, by affinity chromatography of rat brain proteins on immobilised beta-neurexin-IgG [PMID:8576240].","molecular_requirements":"Preference for beta-neurexins lacking a splice insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat brain proteins (curator-listed) [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"The full-text quote is a browser read marked unverifiable with spot-check pending; the abstract itself speaks of beta-neurexins. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to all three neurexins"}],"covers":["LR001110","LR004521"]},"LR001119":{"pair":"NODAL -> ACVR2A","headline":"ACVR2A can serve as a Nodal type II receptor in a frog assay; dominant-negative evidence only, redundant with ACVR2B.","interaction_type":"functional only","direction_and_effect":"Dominant-negative receptor mutants in a Nodal-responsive frog animal cap assay indicated ALK4 plus either ActRIIA or ActRIIB acts as type I and type II receptor for Nodal; effect is agonist [PMID:11952836]. Lefty inhibition was rescued by excess ActRIIA or ActRIIB [PMID:11952836]. Nodal is annotated Stimulatory [flag].","molecular_requirements":"ACVR2A is interchangeable with ACVR2B ('either ... or'), so it is not obligate. ALK4 is the type I chain, and Cripto is described as a membrane-bound co-receptor [PMID:11952836]. BioGRID lists a reconstituted ACVR2A-NODAL complex [DB:BioGRID, PMID:28126904].","affinity_potency":[],"species_and_systems":"Mouse Nodal in Xenopus animal caps; abstract only. The human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Nodal is flagged secreted and ACVR2A transmembrane [flag]; Nodal diffused over a long distance in chick embryos [PMID:11952836].","caveats":"No binding measured for ACVR2A; dominant-negative inference, read as abstract only. Pair species are projected from non-mammalian evidence.","key_references":[{"PMID":"11952836","why":"Dominant-negative receptor assays: ALK4 with ActRIIA or ActRIIB"}],"covers":["LR001119","LR004530"]},"LR004530":{"pair":"NODAL -> ACVR2A","headline":"ACVR2A can serve as a Nodal type II receptor in a frog assay; dominant-negative evidence only, redundant with ACVR2B.","interaction_type":"functional only","direction_and_effect":"Dominant-negative receptor mutants in a Nodal-responsive frog animal cap assay indicated ALK4 plus either ActRIIA or ActRIIB acts as type I and type II receptor for Nodal; effect is agonist [PMID:11952836]. Lefty inhibition was rescued by excess ActRIIA or ActRIIB [PMID:11952836]. Nodal is annotated Stimulatory [flag].","molecular_requirements":"ACVR2A is interchangeable with ACVR2B ('either ... or'), so it is not obligate. ALK4 is the type I chain, and Cripto is described as a membrane-bound co-receptor [PMID:11952836]. BioGRID lists a reconstituted ACVR2A-NODAL complex [DB:BioGRID, PMID:28126904].","affinity_potency":[],"species_and_systems":"Mouse Nodal in Xenopus animal caps; abstract only. The human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Nodal is flagged secreted and ACVR2A transmembrane [flag]; Nodal diffused over a long distance in chick embryos [PMID:11952836].","caveats":"No binding measured for ACVR2A; dominant-negative inference, read as abstract only. Pair species are projected from non-mammalian evidence.","key_references":[{"PMID":"11952836","why":"Dominant-negative receptor assays: ALK4 with ActRIIA or ActRIIB"}],"covers":["LR001119","LR004530"]},"LR001128":{"pair":"NPPA -> NPR1","headline":"ANP is an established agonist of NPR1 (GC-A) with structural, database and functional support.","interaction_type":"direct binding","direction_and_effect":"ANP stimulates NPR1 to produce cGMP [DB:UniProt]; GtoPdb lists agonist [DB:GtoPdb]. In H295R cells ANP and a selective analogue raised cGMP and lowered forskolin- and angiotensin II-induced aldosterone and pregnenolone production [PMID:8700153].","molecular_requirements":"NPR1 is a dimer; ANP stabilises a dimeric NPRA by contacting both subunits, and a W74C covalent dimer could neither bind nor be activated by ANP until disulfides were opened [PMID:12547834]. Reactome lists NPPA(124-151):NPR1 dimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human receptor and ligand in recombinant or cell systems [PMID:12547834][PMID:8700153]. Mouse pair is projected. PDB structures exist of the ANP-NPR1 complex [DB:PDB 8TG9].","localisation_and_range":"ANP is annotated secreted and NPR1 transmembrane [flag].","caveats":"Both papers were abstract-only. PMID:12547834 is a mutant-receptor study, and its evidence sentence is background from an earlier paper. The ligand is annotated as 'mutant ANP' [flag].","key_references":[{"PMID":"8700153","why":"Functional cGMP and steroidogenesis response to ANP via NPR-A"},{"PMID":"12547834","why":"Dimer requirements for ANP binding to NPRA"}],"covers":["LR001128","LR004538"]},"LR006222":{"pair":"NPTX1 -> GRIA4","headline":"NPTX1 is reported to bind the GluR4 N-terminal domain in one coculture study; thin evidence.","interaction_type":"direct binding","direction_and_effect":"NP1 and NPR secreted from presynaptic neurons bind the GluR4 NTD and are required for GluR4 recruitment to synapses [PMID:17610819].","molecular_requirements":"GluR4 NTD is necessary and sufficient for recruitment; NP1 and NPR are both required [PMID:17610819]. NPTX1 may act with NPTXR.","affinity_potency":[],"species_and_systems":"Artificial-synapse coculture with RNAi and knockout; species not stated in dossier [PMID:17610819]. Both pairs are ortholog-inferred.","localisation_and_range":"NPTX1 is annotated secreted [flag]; the paper describes trans-synaptic action [PMID:17610819].","caveats":"One paper, abstract only; no database records. NP1 and NPR effects are not separated in the abstract. Not a classical signalling receptor interaction, rather a synaptic recruitment factor.","key_references":[{"PMID":"17610819","why":"NP1/NPR bind GluR4 NTD for synaptic recruitment"}],"covers":["LR002998","LR006222"]},"LR001137":{"pair":"NPVF -> NPFFR2","headline":"NPVF peptides bind human NPFFR2 with nanomolar affinity, but with slight preference for NPFFR1; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Pro-NPFF(B)-derived peptides are recognised by NPFF2 with nanomolar affinity; the paper reports a slight preference of these peptides for NPFF1 [PMID:12242085]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NPFF receptors expressed in CHO cells [PMID:12242085]. Mouse pair is projected from human.","localisation_and_range":"NPVF is flagged secreted and NPFFR2 transmembrane [flag].","caveats":"Single paper, read as abstract only [PMID:12242085]. The abstract gives no peptide-specific values for NPFF2, and GtoPdb lists pKi without values in the dossier [DB:GtoPdb]. Mainly a database plus one abstract.","key_references":[{"PMID":"12242085","why":"Human NPFF1/NPFF2 binding and cAMP in CHO cells"}],"covers":["LR001137","LR004547"]},"LR001146":{"pair":"NRG1 -> ERBB2","headline":"NRG1 binds ERBB2 only weakly on its own: ERBB3 is needed; evidence includes a pM-range binding claim and structures.","interaction_type":"conflicting","direction_and_effect":"Heregulin-alpha induced p185erbB2 phosphorylation, and recombinant HRG showed one high-affinity binding site on erbB2-expressing breast tumour cells [PMID:1350381]. Cross-linking showed direct heregulin contact with erbB2 and erbB3 [PMID:7514177].","molecular_requirements":"ERBB3 appears needed: not all erbB2-expressing cells respond, and erbB3 plus erbB2 reconstitutes a higher-affinity, signalling receptor [PMID:7514177]. Reactome lists NRG1:ERBB3:ERBB2 complexes [DB:Reactome R-HSA-1247502].","affinity_potency":[{"value":"Kd 105 pM","assay":"Scatchard analysis of recombinant HRG","system":"breast tumour cell line expressing p185erbB2","cite":"PMID:1350381"}],"species_and_systems":"Human ligand and receptor, tumour cell lines and transfected cells [PMID:1350381][PMID:7514177]. Mouse pair is projected from human.","localisation_and_range":"NRG1 is flagged secreted and transmembrane, ERBB2 transmembrane [flag]; membrane-bound or processed ligand forms are not distinguished in our evidence.","caveats":"Both papers are abstract only. The Kd was measured on cells that may express other ErbB receptors, so it cannot show ERBB2-alone binding. The dossier curator notes later work places ErbB2 as a heterodimer partner rather than a ligand binder; this is not in the papers shown. BioGRID and IntAct records exist [DB:IntAct].","key_references":[{"PMID":"1350381","why":"Heregulin-alpha purification and Kd 105 pM on erbB2 cells"},{"PMID":"7514177","why":"Heregulin cross-links erbB2 and erbB3; erbB3 needed for high affinity"}],"covers":["LR001146","LR004555"]},"LR006231":{"pair":"NRG1 -> ITGB4","headline":"Single abstract-level report that NRG1 binds integrin beta4 (ITGB4); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003007","LR006231"]},"LR003009":{"pair":"NRG3 -> ERBB2","headline":"NRG3 activates ERBB2 only when co-expressed with ERBB3, from one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"NRG-3 activated erbB2 and erbB3 when expressed together, an agonist effect [PMID:9772300].","molecular_requirements":"ERBB2 is not shown to respond alone; activation required erbB3 co-expression [PMID:9772300]. In scoring, ERBB2 should be treated as a heterodimer partner, not a standalone receptor.","affinity_potency":[],"species_and_systems":"Human breast cancer cells and transfected 32D cells [PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag].","caveats":"One paper, abstract only; activation not binding; no affinity. Direct binding to ERBB2 is not shown in our evidence.","key_references":[{"PMID":"9772300","why":"erbB2 and erbB3 activated together by NRG-3"}],"covers":["LR003009","LR006233"]},"LR012432":{"pair":"NRP2 -> FLT1:KDR","headline":"NRP2 with FLT1:KDR: one prostate-cancer paper reports NRP2-VEGFR2; FLT1 rests on Reactome.","interaction_type":"functional only","direction_and_effect":"NRP2 physically interacts with VEGFR2 (KDR) via the intracellular SEA domain, activating STAT3 phosphorylation and SOX2 in neuroendocrine prostate cancer [PMID:35986103].","molecular_requirements":"KDR is supported by the paper; FLT1 only by a Reactome record of NRP-2 associating with VEGFR1 [DB:Reactome]. A joint FLT1:KDR complex is not shown.","affinity_potency":[],"species_and_systems":"Prostate cancer cells and xenografts; species not stated in the abstract [PMID:35986103].","localisation_and_range":"NRP2 and the receptors are annotated transmembrane receptors [flag]; interaction is receptor-receptor in cis.","caveats":"Abstract only. 2 papers were different_entity and 3 abstract_insufficient. No affinity. This is a co-receptor association, not ligand binding.","key_references":[{"PMID":"35986103","why":"NRP2 interacts with VEGFR2 to activate STAT3 in NEPC"}],"covers":["LR012432"]},"LR001155":{"pair":"NRTN -> RET","headline":"Well supported: cryo-EM structure plus cell assays show neurturin activates RET, but only through a GFRA2 co-receptor.","interaction_type":"direct binding","direction_and_effect":"NRTN acts as an agonist: with GFRA2 it induces RET tyrosine phosphorylation, and the three proteins form a physical complex on the cell surface [PMID:9192898]. Fibroblasts expressing TrnR2 (GFRA2) and Ret are ~30-fold more sensitive to NTN than to GDNF [PMID:9182803].","molecular_requirements":"RET needs a GFR-alpha co-receptor. A cryo-EM structure of the NRTN-GFRalpha2-RET extracellular complex shows NRTN dimer contacting the RET cysteine-rich domain, with GFRalpha2 contacting RET via a calcium-binding site [PMID:31392261]. Reactome lists the reaction as GDNF,NRTN binding RET:GFRA1,GFRA2 [DB:Reactome]. RET alone with NRTN was not tested in our evidence; the structural paper reports no RET binding signal to NRTN or GFRalpha2 surfaces when RET was injected alone [PMID:31392261].","affinity_potency":[{"value":"Kd ~10 pM","assay":"NTN binding to NTNR-alpha (GFRA2), the co-receptor, not RET itself","system":"human","cite":"PMID:9192898"}],"species_and_systems":"Recombinant human proteins and fibroblast cells; the cryo-EM used reconstituted extracellular proteins at 5.7-Angstrom resolution [PMID:31392261]. Mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"NRTN is flagged secreted [flag]; RET is a transmembrane receptor with a GPI-linked co-receptor, so signalling is paracrine/juxtacrine at the receiving cell [PMID:9182803].","caveats":"The high-affinity value belongs to NRTN-GFRA2, not NRTN-RET. 31392261 and 9192898 were read as abstracts for the curator judgement. PDB structures (6GL7, 6Q2O, 6Q2R) are RET-GFRA2-type complexes [DB:PDB 6GL7].","key_references":[{"PMID":"31392261","why":"cryo-EM structure of NRTN-GFRalpha2-RET extracellular complex"},{"PMID":"9192898","why":"NTN/NTNRalpha/Ret form a physical complex and Ret phosphorylation; Kd ~10 pM"},{"PMID":"9182803","why":"GFRA2-Ret mediates NTN signalling, ~30-fold preferential to NTN"}],"covers":["LR001155","LR004564"]},"LR006240":{"pair":"NRXN1 -> CLSTN3","headline":"Direct binding of beta-neurexins to calsyntenin-3 reported; abstract only, NRXN1 not named, species unspecified.","interaction_type":"direct binding","direction_and_effect":"Beta-Nrxns bind Clstn3 directly through their LNS domain, and Clstn3 links to SS4-insert-positive Nrxns to induce presynaptic differentiation [PMID:32434929]. Direction: postsynaptic Clstn3 acts via presynaptic Nrxns [PMID:32434929].","molecular_requirements":"Needs SS4-positive beta-Nrxn variants; insert-negative variants did not reverse the Clstn3 synaptogenic defect. The Clstn3 cadherin domains are involved [PMID:32434929]. UniProt notes NRXN1 binds CLSTN3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not specified in the curation of this paper (mouse pair is the paper's likely context but is not stated here).","localisation_and_range":"Both are transmembrane [flag]; trans-synaptic contact.","caveats":"Abstract only. The abstract refers to beta-Nrxns as a group and does not name NRXN1. It also states that whether Nrxns bind Clstn3 directly had been debated.","key_references":[{"PMID":"32434929","why":"beta-Nrxn LNS domain binds Clstn3, SS4-dependent synaptogenic activity"}],"covers":["LR003016","LR006240"]},"LR003018":{"pair":"NRXN1 -> LRRTM1","headline":"Neurexin binding code reported conserved in LRRTM1 and functional in a coculture assay; abstract only.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds neurexin-1beta lacking an insert at splice site 4; the authors further show this binding code is conserved in LRRTM1 and functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Binding depends on neurexin splice site 4: LRRTM2 binds neurexins 1, 2, 3 alpha and beta variants lacking an insert at SS4; LRRTM1 is said to share this code [PMID:20519524].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; mouse and human pairs are ortholog-inferred.","localisation_and_range":"Both are transmembrane [flag]; trans-synaptic hemisynapse assay.","caveats":"Abstract only. The LRRTM1 result is stated briefly; details of the assay and affinity are not in our evidence. Biochemical characterisation was mainly for LRRTM2.","key_references":[{"PMID":"20519524","why":"LRRTM2 neurexin binding code conserved in LRRTM1"}],"covers":["LR003018","LR006242"]},"LR003027":{"pair":"NRXN2 -> LRRTM2","headline":"Direct neurexin-LRRTM2 binding is shown, but the full-text paper names neurexins generically; NRXN2 specifically is not pinned down.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds alpha- and beta-neurexins directly in cell-surface labeling assays and mediates cell adhesion in a trans-interaction [PMID:20064387]. Ca2+-dependent binding [PMID:20064387].","molecular_requirements":"Binding requires neurexins lacking an insert in splice site #4; Ca2+ dependent [PMID:20064387]. LRRTM2 and neuroligin-1 cannot bind neurexin-1beta simultaneously [PMID:20064387].","affinity_potency":[],"species_and_systems":"Recombinant Ig-fusions in HEK293/HEK293T cells and rat brain affinity chromatography [PMID:20064387]. The dossier covers human and mouse pairs; the human pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged as transmembrane, non-secreted [flag], so contact-dependent (juxtacrine/trans-synaptic) signalling is implied; the paper shows trans cell adhesion [PMID:20064387].","caveats":"The only verified paper tests neurexins generically (neurexin-1 alpha/beta in binding; excerpts do not show NRXN2 binding); two further papers were judged abstract-insufficient. The curator note says the sentence names neurexins generically and that all three beta-neurexins bound [PMID:20064387].","key_references":[{"PMID":"20064387","why":"Direct neurexin-LRRTM2 binding and trans cell adhesion"}],"covers":["LR003027","LR006251"]},"LR001164":{"pair":"NTN1 -> NEO1","headline":"Functional evidence only: neogenin mediates netrin-1-dependent cell clustering in mammary gland; direct binding is not shown in this dossier.","interaction_type":"functional only","direction_and_effect":"Neogenin mediates netrin-1-dependent cell clustering in cell aggregation assays; netrin-1 appears to act locally through neogenin to stabilise cap cells [PMID:12636918]. The effect is adhesive rather than guidance [PMID:12636918].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse mammary gland: loss of either gene disorganises terminal end buds [PMID:12636918]. The human pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted [flag]. In the mammary study netrin-1 is expressed in prelumenal cells and neogenin in adjacent cap cells [PMID:12636918].","caveats":"Paper read as abstract only and shows no direct binding. IntAct lists a co-immunoprecipitation [DB:IntAct] and Reactome a complex [DB:Reactome], but without details. One further paper is pending and not shown.","key_references":[{"PMID":"12636918","why":"Netrin-1/neogenin clustering and mouse mammary gland genetics"}],"covers":["LR001164","LR004573"]},"LR003036":{"pair":"NTN3 -> UNC5A","headline":"Murine netrin-3 binds the UNC5 family in one abstract-only paper; UNC5A is not named individually.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds the UNC5 family (UNC5H1, UNC5H2 and UNC5H3) with higher affinity than it binds DCC [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine netrin-3 protein; human pair is ortholog-inferred and the mouse pair too [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only. The evidence sentence names UNC5H1-3, and the mapping to this specific receptor is not stated in the abstract. No numbers are reported.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds UNC5 family receptors"}],"covers":["LR003036","LR006260"]},"LR001173":{"pair":"NTNG2 -> LRRC4","headline":"Netrin-G2 and its ligand (LRRC4/NGL-2) bind at about 2.5 nM, with matching mouse loss-of-function phenotypes and a co-crystal structure.","interaction_type":"direct binding","direction_and_effect":"Netrin-G2 and netrin-G2 ligand act in the same pathway: genetic inhibition of either gives no acoustic startle with auditory brainstem responses present [PMID:17973922].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"2.5 nM","assay":"affinity as stated in abstract; assay not specified","system":"netrin-G2 with netrin-G2 ligand","cite":"PMID:17973922"},{"value":"2.3 nM","assay":"comparison pair, assay not specified","system":"netrin-G1 with netrin-G1 ligand","cite":"PMID:17973922"}],"species_and_systems":"Mouse [PMID:17973922]. Records: BioGRID co-crystal, IntAct SPR and PDB 3ZYI [DB:PDB 3ZYI][DB:BioGRID][DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged not secreted [flag], consistent with membrane-anchored, contact-based signalling.","caveats":"Abstract only; assay format is not given. One further row is pending.","key_references":[{"PMID":"17973922","why":"About 2.5 nM affinity and matching knockout phenotypes"}],"covers":["LR001173","LR004582"]},"LR001182":{"pair":"OMG -> LINGO1","headline":"OMgp acts with a NgR1/p75/LINGO-1 complex; LINGO-1 is a co-receptor component, and direct OMgp-LINGO-1 binding is not shown.","interaction_type":"functional only","direction_and_effect":"In non-neuronal cells, coexpression of human NgR1, p75 and LINGO-1 conferred responsiveness to oligodendrocyte myelin glycoprotein, measured as RhoA activation [PMID:14966521]. Dominant-negative LINGO-1 attenuated myelin inhibition in primary neurons, and LINGO-1-Fc did similarly [PMID:14966521].","molecular_requirements":"LINGO-1 binds NgR1 and p75 and is an additional functional component of the NgR1/p75 signalling complex; NgR1 and p75 alone could not activate RhoA [PMID:14966521]. So the effective receptor is a multi-subunit complex.","affinity_potency":[],"species_and_systems":"Reconstitution in non-neuronal cells with human proteins, plus primary neuronal cultures [PMID:14966521]. Mouse pair is ortholog-inferred.","localisation_and_range":"OMG is flagged membrane-bound (not secreted) [flag]; LINGO-1 is a nervous system-specific transmembrane protein [PMID:14966521].","caveats":"Single abstract-only paper. LINGO-1 is shown to bind NgR1 and p75, not OMgp; the pair is therefore a co-receptor relationship, not demonstrated direct ligand binding. No affinity reported.","key_references":[{"PMID":"14966521","why":"LINGO-1 as a functional component of the NgR1/p75 complex for OMgp"}],"covers":["LR001182","LR004591"]},"LR003045":{"pair":"OMG -> PTPRF","headline":"OMG binds PTPRF by SPR in the micromolar range; the curated record is labelled as a screen hit, which the table contradicts.","interaction_type":"direct binding","direction_and_effect":"OMG is the ligand and PTPRF the receptor. SPR showed micromolar-range binding of OMG to all three R2A RPTPs including PTPRF [PMID:36178190]. PTPRF was also described as enriched in the OMG CRISPRa screen [PMID:36178190]. Effect (agonist or antagonist) is not reported in our evidence.","molecular_requirements":"PTPRF ectodomain alone; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"micromolar range","assay":"SPR, OMG vs RPTP ectodomains","system":"recombinant human proteins","cite":"PMID:36178190"}],"species_and_systems":"Human OMG and PTPRF recombinant ectodomains by SPR; pooled CRISPRa screen in cells [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. PTPRF is a flagged transmembrane receptor [flag].","caveats":"Single paper. The paper's Table 1 lists the OMG-PTPRF interaction with source PHA (homology-based) and assay SPR, while the text says PTPRF was enriched in the screen; the two are not reconciled in our excerpts [PMID:36178190]. No exact Kd reported. No database records.","key_references":[{"PMID":"36178190","why":"CRISPRa screen plus SPR for OMG-RPTP binding"}],"covers":["LR003045","LR006269"]},"LR001191":{"pair":"OXT -> AVPR1B","headline":"Oxytocin acts on V1b only weakly supported: one islet functional study in mouse and a comparator paper.","interaction_type":"functional only","direction_and_effect":"In mouse islets, a V1b antagonist plus an OT-receptor antagonist inhibited OT-induced glucagon secretion more (69%) than the OT-receptor antagonist alone (45%), indicating V1b can mediate the OT effect; in V1bR-/- mice OT still stimulated secretion with unchanged efficacy [PMID:17283236].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse islets (OT presumed human peptide in dossier) [PMID:17283236]; recombinant human receptors in CHO cells in the comparator paper [PMID:16158071]. Human pair is ortholog-inferred.","localisation_and_range":"OXT is flagged secreted; AVPR1B is a transmembrane receptor [flag].","caveats":"PMID:16158071 is a compound-characterisation paper in which V1b is a comparator, and native OT binding to V1b is not independently measured there. Both papers are abstract only. In the islet study, receptor compensation complicates attribution [PMID:17283236]. GtoPdb pKi 5.7 to 7.0 [DB:GtoPdb].","key_references":[{"PMID":"17283236","why":"genetic and pharmacological evidence that V1b mediates OT effect in islets"},{"PMID":"16158071","why":"V1b comparator data only"}],"covers":["LR001191","LR004600"]},"LR004602":{"pair":"OXT -> OXTR","headline":"Oxytocin is the cognate agonist of OXTR, with nanomolar binding and functional responses in human recombinant systems; many confirmations.","interaction_type":"direct binding","direction_and_effect":"OXT binds the oxytocin receptor with high affinity and stimulates inositol phosphate accumulation (EC50 = 4.1 nM) in 293 cells [PMID:7475979]. Expression-cloned human OXTR in Xenopus oocytes specifically responds to oxytocin with an inward current [PMID:1313946]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single GPCR chain; coupling to G protein shown by guanine nucleotide sensitivity of agonist affinity [PMID:7475979]. Co-receptor requirement not reported.","affinity_potency":[{"value":"Kd 0.32nM","assay":"[3H]OT saturation binding","system":"human OXTR stably expressed in 293 cells","cite":"PMID:7475979"},{"value":"Ki in mean = 6.8 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"EC50 = 4.1 nM","assay":"inositol phosphate accumulation","system":"293/OTR cells","cite":"PMID:7475979"}],"species_and_systems":"Human receptor in 293 cells, CHO cells and Xenopus oocytes; human and rat receptor in one paper [PMID:12660315]. Mouse pair is ortholog-inferred.","localisation_and_range":"OXT is flagged secreted and OXTR a transmembrane receptor [flag].","caveats":"All papers are abstract only. Several (PMID:16158071, PMID:12660315) use OXT only as background to characterise other compounds. PMID:10698266 is computational modelling, not experimental. PDB 7QVM and 7RYC contain chains of OXT and OXTR [DB:PDB].","key_references":[{"PMID":"7475979","why":"Kd and signalling of OT at cloned human OXTR"},{"PMID":"1313946","why":"expression cloning, oxytocin-specific response"},{"PMID":"10519430","why":"competition Ki, OXTR versus V1a"}],"covers":["LR001193","LR004602"]},"LR006303":{"pair":"PCDHGB6 -> PCDHGB6","headline":"Mouse gammaB6 engages homophilic interactions and reaches the cell surface in K562 assays; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Homophilic interaction; the paper states gamma and beta proteins tested show strict trans-homophilic specificity [PMID:25171406]. No agonist/antagonist effect reported.","molecular_requirements":"Cell-surface expression of gammaB6 was verified with extracellular c-Myc tags [PMID:25171406]. Cis interactions with other Pcdhs matter for Pcdh-alpha delivery [PMID:25171406].","affinity_potency":[],"species_and_systems":"Mouse isoforms in K562 cell aggregation assays [PMID:25171406]; human pair ortholog-inferred.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent.","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology.","key_references":[{"PMID":"25171406","why":"Names gammaB6 as homophilic and surface-expressed."}],"covers":["LR003080","LR006303"]},"LR006312":{"pair":"PDYN -> ACKR3","headline":"Dynorphin peptides activate ACKR3 as a scavenger receptor, shown with quantitative potency in one paper.","interaction_type":"functional only","direction_and_effect":"ACKR3 is a scavenger of opioid peptides, especially enkephalins and dynorphins, reducing their availability to classical opioid receptors [PMID:32561830]. It recruits beta-arrestin but did not show G-protein signalling in response to opioid peptides [PMID:32561830].","molecular_requirements":"Active peptides include dynorphin A, dynorphin A 1-13, dynorphin B, big dynorphin and leumorphin (PDYN-derived fragments), with different potencies [PMID:32561830].","affinity_potency":[{"value":"EC50 110 nM","assay":"beta-arrestin-1 recruitment","system":"ACKR3, U87 cells, dynorphin A","cite":"PMID:32561830"},{"value":"EC50 61.9 nM","assay":"beta-arrestin-1 recruitment","system":"ACKR3, U87 cells, dynorphin A 1-13","cite":"PMID:32561830"},{"value":"EC50 108 nM","assay":"beta-arrestin-1 recruitment","system":"ACKR3, U87 cells, big dynorphin","cite":"PMID:32561830"}],"species_and_systems":"Cell-based assays in U87 cells; rat brain used for a competitor peptide experiment [PMID:32561830]. Species of ACKR3 construct not stated in our excerpts.","localisation_and_range":"PDYN-derived peptides are secreted [flag]; ACKR3 is a transmembrane receptor [flag]; paracrine in brain per the paper's setting.","caveats":"Decoy or scavenger rather than classical agonist. Evidence is beta-arrestin recruitment, not binding. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"32561830","why":"ACKR3 scavenges opioid peptides including dynorphins"}],"covers":["LR003089","LR006312"]},"LR004611":{"pair":"PDYN -> OPRK1","headline":"Dynorphin A is a high-affinity agonist at the kappa opioid receptor, with binding in human and guinea pig and database records.","interaction_type":"direct binding","direction_and_effect":"Dynorphin A (1-17) bound human kappa receptor with high affinity [PMID:7869844]; the guinea pig receptor showed high affinity and stereospecificity toward dynorphin peptides and coupled to inhibit adenylyl cyclase and Ca2+ channels [PMID:8170987]. GtoPdb lists Agonist, Full agonist [DB:GtoPdb]. A biosensor paper used kappa receptor activation to report dynorphin release in mouse [PMID:39009835].","molecular_requirements":"Single receptor chain is sufficient in the cloned expression systems [PMID:7869844][PMID:8170987].","affinity_potency":[{"value":"pKi 8.0 to 9.9","assay":"GtoPdb affinity range, agonist","system":"not reported in our evidence","cite":"PMID:1967312"},{"value":"pKi 8.3 to 10.2","assay":"GtoPdb affinity range, agonist","system":"not reported in our evidence","cite":"PMID:7869844"}],"species_and_systems":"Human receptor in COS-1 cells [PMID:7869844]; guinea pig receptor in COS-7 cells [PMID:8170987]; mouse brain slices and in vivo with a kappa-receptor sensor [PMID:39009835]. All read as abstracts (the last with some full text).","localisation_and_range":"PDYN flagged secreted; the biosensor paper reports dynorphin volume transmission in brain slices [PMID:39009835].","caveats":"Binding papers are abstract-only; the guinea pig paper does not name PDYN-derived peptides by symbol. The 2024 biosensor paper is a tool paper, not a binding test. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"7869844","why":"Human kappa receptor binds dynorphin A (1-17) with high affinity"},{"PMID":"8170987","why":"Guinea pig kappa receptor: dynorphin affinity and signalling"},{"PMID":"39009835","why":"Mouse biosensor detecting dynorphin release via kappa receptor"}],"covers":["LR001202","LR004611"]},"LR003090":{"pair":"PECAM1 -> CD177","headline":"PECAM1 binds CD177 heterophilically; SPR and neutrophil transmigration blocking support it.","interaction_type":"direct binding","direction_and_effect":"CD177 was identified as a PECAM-1 binding partner by flow cytometry and immunoprecipitation; SPR confirmed a cation-dependent, specific interaction with the heterophilic domains of PECAM-1 [PMID:17580308]. Antibodies to CD177 or PECAM-1 domain 6 inhibited adhesion of CD177-expressing U937 cells and human neutrophil transendothelial migration [PMID:17580308].","molecular_requirements":"Cations are needed and PECAM-1 domain 6 is involved [PMID:17580308].","affinity_potency":[],"species_and_systems":"Human proteins and cells (U937 transfectants, human neutrophils); abstract only [PMID:17580308]. IntAct solid phase assay and Reactome binding records exist [DB:IntAct][DB:Reactome].","localisation_and_range":"Both membrane proteins; cell-cell (juxtacrine) adhesion between endothelium and neutrophils [PMID:17580308]. The CD177 secreted flag is an annotation flag [flag].","caveats":"Abstract only; no affinity in our evidence. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"17580308","why":"SPR and adhesion/transmigration data for PECAM-1/CD177"}],"covers":["LR003090","LR006313"]},"LR001209":{"pair":"PF4 -> CXCR3","headline":"PF4 binds the splice variant CXCR3-B with high affinity, not CXCR3-A; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CXCL4 binds CXCR3-B and inhibits proliferation of CXCR3-B transfectants; CXCR3-B overexpression reduces DNA synthesis and raises apoptosis [PMID:12782716].","molecular_requirements":"Isoform matters: CXCL4 bound CXCR3-B but not CXCR3-A [PMID:12782716].","affinity_potency":[{"value":"IC50 1.85 +/- 0.9 nM","assay":"unlabeled CXCL4 displacing 125I-CXCL4","system":"CXCR3-B transfectants","cite":"PMID:12782716"},{"value":"IC50 7.46 +/- 3.05 nM","assay":"CXCL4 displacing 125I-CXCL10","system":"CXCR3-B transfectants","cite":"PMID:12782716"},{"value":"IC50 448 +/- 152 nM","assay":"CXCL4 displacing 125I-CXCL10","system":"CXCR3-A transfectants","cite":"PMID:12782716"}],"species_and_systems":"Human HMEC-1 transfectants and primary human microvascular endothelial cells [PMID:12782716].","localisation_and_range":"PF4 is flagged secreted [flag].","caveats":"The generic CXCR3 pair is effectively PF4 -> CXCR3-B; CXCR3-A binding was very poor. Receptor effect is inhibitory in endothelial cells. BioGRID and UniProt agree [DB:BioGRID] [DB:UniProt].","key_references":[{"PMID":"12782716","why":"CXCL4 binds CXCR3-B with high affinity"}],"covers":["LR001209"]},"LR004620":{"pair":"PGF -> NRP2","headline":"Heparin-binding PlGF binds NRP2 per one abstract-only paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"NRP2 binds the heparin-binding form of placenta growth factor [PMID:10748121].","molecular_requirements":"Only the heparin-binding PlGF form binds [PMID:10748121].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells express NRP2 splice forms a17 and a22 [PMID:10748121]. Mouse pair is ortholog-inferred.","localisation_and_range":"PGF is flagged secreted [flag].","caveats":"One paper, abstract only; PlGF affinity not reported in our evidence. No database records.","key_references":[{"PMID":"10748121","why":"NRP2 binds heparin-binding PlGF"}],"covers":["LR001217","LR004620"]},"LR006321":{"pair":"PGLYRP1 -> TNFRSF1A","headline":"PGLYRP1/Tag7 peptide 17.1A binds and blocks TNFR1; one abstract plus excerpts paper, from one group.","interaction_type":"direct binding","direction_and_effect":"Peptide 17.1A, from the PGLYRP1 C-terminus, bound TNFR1 and blocked its cytotoxic signals; the paper says the Tag7 protein inhibits TNFalpha cytotoxicity via TNFR1 [PMID:34163464]. UniProt instead describes PGLYRP1 with HSPA1A activating TNFR1 [DB:UniProt].","molecular_requirements":"Peptide 17.1A (RSNYVLKG) is the minimal TNFR1-binding region, shown by affinity chromatography on sTNFRI [PMID:34163464].","affinity_potency":[],"species_and_systems":"Human cell assays; peptide tested in a mouse CFA arthritis model [PMID:34163464]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Binding was shown for the peptide, not full-length PGLYRP1; the inhibitory link for full-length protein cites earlier work. Direction conflicts with UniProt's activating description [DB:UniProt].","key_references":[{"PMID":"34163464","why":"Peptide 17.1A binds TNFR1 and blocks cytotoxicity"}],"covers":["LR003099","LR006321"]},"LR001218":{"pair":"PIP -> CD4","headline":"Secreted PIP (gp17) binds CD4; recombinant gp17-Ig binding and epitope mapping, supported by one abstract-only paper and BioGRID.","interaction_type":"direct binding","direction_and_effect":"gp17 (PIP), secreted from human seminal vesicles, binds CD4 with high affinity per the authors' earlier work, and gp17-Ig fusion showed binding affinity similar to native gp17 [PMID:10820003]. Previously reported inhibition of CD4/TCR-induced T lymphocyte apoptosis is stated as the authors' earlier finding [PMID:10820003]. BioGRID lists a reconstituted complex [DB:BioGRID 287024].","molecular_requirements":"Three residues in the carboxy-terminal region of gp17 form the major CD4-binding domain; two CD4-binding regions were mapped by overlapping peptides and mutagenesis [PMID:10820003].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; recombinant gp17-Ig (gp17 fused to human IgG1 Fc) [PMID:10820003]. Mouse pair is projected from human.","localisation_and_range":"Secreted, from the PIP secreted flag [flag] and the paper describing a secreted factor from seminal plasma [PMID:10820003].","caveats":"Abstract only; no numeric affinity in our evidence. The paper is about the gp17 binding site; the primary binding result is from earlier work cited in the abstract [PMID:10820003].","key_references":[{"PMID":"10820003","why":"Mapping the CD4-binding domain of gp17 (PIP)"}],"covers":["LR001218","LR004621"]},"LR003108":{"pair":"PLAUR -> FPR2","headline":"Functional evidence only, for a cleaved uPAR peptide (84-95) acting on FPRL1/FPR2; weak for full-length PLAUR.","interaction_type":"functional only","direction_and_effect":"The uPAR-derived peptide 84-95 induced human basophil chemotaxis, and uPA and its amino-terminal fragment were chemoattractants [PMID:15494526]. Desensitisation data point to FPRL2 as the main receptor, with FPRL1 (FPR2) contributing secondarily [PMID:15494526].","molecular_requirements":"The active ligand is the exposed epitope uPAR84-95, a cleaved form, not intact uPAR [PMID:15494526].","affinity_potency":[],"species_and_systems":"Human basophils; no binding measurement. Abstract only [PMID:15494526].","localisation_and_range":"Receptor is transmembrane [flag]; ligand flagged secreted [flag]. Range not otherwise reported.","caveats":"The row generalises a peptide to whole PLAUR, and FPR2 is not the primary receptor in this study. Mouse pair is projected.","key_references":[{"PMID":"15494526","why":"uPAR84-95 peptide chemoattracts basophils via FPRL1/FPRL2"}],"covers":["LR003108","LR006329"]},"LR006330":{"pair":"PLAUR -> IGF2R","headline":"Direct binding of purified uPAR to IGF2R (CIMPR) at micromolar affinity, mainly directing uPAR to lysosomes.","interaction_type":"direct binding","direction_and_effect":"Purified uPAR bound the cation-independent M6P/IGF2R but not the cation-dependent M6P receptor; wild-type CIMPR directed uPAR to lysosomes [PMID:9566979]. The record labels this agonist, but the role shown is uPAR disposal; signalling not reported.","molecular_requirements":"Binding involves uPAR domains DII+DIII, not the GPI anchor, at CIMPR sites distinct from mannose 6-phosphate/IGF-II sites; binding was not perturbed by uPA [PMID:9566979].","affinity_potency":[{"value":"Kd ~1 uM (0.9-1.3 uM in five separate experiments)","assay":"BIAcore real-time interaction analysis","system":"CIMPR from FCS binding immobilised baculovirus uPAR","cite":"PMID:9566979"}],"species_and_systems":"Human uPAR from U937/HeLa cells; murine uPAR also bound CIMPR in column assays; transfected cells for localisation [PMID:9566979]. Human pair is itself ortholog-inferred.","localisation_and_range":"Both partners carry transmembrane flags [flag]; uPAR is GPI-anchored in the paper's terms [PMID:9566979].","caveats":"Single paper (full text read). BIAcore stoichiometry was 0.1 mol CIMPR per mol uPAR [PMID:9566979]. Evidence concerns disposal rather than classic signalling.","key_references":[{"PMID":"9566979","why":"binding, affinity and lysosomal targeting"}],"covers":["LR003109","LR006330"]},"LR003117":{"pair":"PLG -> ANXA2","headline":"Plasminogen is reported on mesothelial cells with annexin A2 as one of three receptors; evidence is indirect and abstract-level.","interaction_type":"functional only","direction_and_effect":"Plasminogen bound mesothelial cells via its lysine-binding domain, and annexin A2 was among three plasminogen receptors found at the cell surface [PMID:35682663]. Bound plasminogen was activated to plasmin at the surface per the abstract [PMID:35682663].","molecular_requirements":"Binding via the lysine-binding domain; other receptors present are alpha-enolase and Plg-RKT [PMID:35682663].","affinity_potency":[],"species_and_systems":"Pleural and peritoneal mesothelial cells; species not stated in our evidence [PMID:35682663].","localisation_and_range":"Ligand flagged secreted; receptor flagged secreted [flag].","caveats":"Abstract only; no direct binding assay or affinity in our evidence. One other row was abstract-insufficient.","key_references":[{"PMID":"35682663","why":"mesothelial plasminogen receptors including annexin A2"}],"covers":["LR003117"]},"LR001236":{"pair":"PNOC -> OPRL1","headline":"Nociceptin (PNOC product) binds and activates OPRL1 with high affinity in human, rat and mouse systems; very well supported.","interaction_type":"direct binding","direction_and_effect":"Nociceptin/orphanin FQ is an agonist at OPRL1: it was purified as a ligand of the orphan receptor LC132, bound it saturably with high affinity, and nanomolar peptide inhibited forskolin-stimulated adenylyl cyclase, without activating opioid receptors [PMID:7481766]. Nociceptin inhibits cAMP in CHO cells expressing the receptor [PMID:10369464].","molecular_requirements":"Single receptor chain sufficient in recombinant cells. Mutagenesis of transmembrane residues (Asp130, Tyr131, Phe224 and others) reduces nociceptin affinity and reactivity [PMID:10692489]. Gln286Ala keeps binding but abolishes cAMP inhibition [PMID:10692489]. Gln280His leaves nociceptin affinity unchanged [PMID:8849681].","affinity_potency":[{"value":"Kd 0.22 nM","assay":"nociceptin binding, wild-type receptor","system":"recombinant CHO cells, human ORL1","cite":"PMID:10692489"},{"value":"50-100 pM","assay":"[3H]14-Tyr-nociceptin binding","system":"brain or CHO-ORL1 cell membranes","cite":"PMID:9413015"}],"species_and_systems":"Mouse and porcine brain-derived peptide on transfected cells [PMID:7481766]; rat brain membranes and human receptor in CHO cells [PMID:10369464]; human receptor in CHO cells [PMID:10692489][PMID:8849681]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; diffusible peptide acting on a cell-surface receptor.","caveats":"In intact cells most binding is to a low-affinity state of about 8 nM [PMID:9413015]. Several papers study analogues or mutants, with nociceptin as reference [PMID:11097863][PMID:12967935]. Most papers read as abstracts. Two papers are pending and two review-only.","key_references":[{"PMID":"7481766","why":"discovery of orphanin FQ as ligand of the orphan receptor"},{"PMID":"10692489","why":"nociceptin Kd for wild-type and mutant receptors"},{"PMID":"9413015","why":"binding versus functional potency"}],"covers":["LR001236","LR004638"]},"LR001245":{"pair":"POMC -> OPRK1","headline":"Supported only by GtoPdb records of partial agonism; no verified paper in the dossier.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records POMC at OPRK1 as an agonist with partial agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 6.3-7.9","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:7624359"}],"species_and_systems":"No curator-verified paper; species of the underlying experiments not reported in our evidence. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"POMC flagged secreted, OPRK1 transmembrane [flag].","caveats":"Rests on database records only. Curators judged 10 papers abstract_insufficient and 2 review_only, so none confirmed.","key_references":[],"covers":["LR001245","LR004647"]},"LR003126":{"pair":"POSTN -> ITGB5","headline":"Periostin-dependent cell adhesion is blocked by anti-alpha(V)beta(5) antibody, supporting ITGB5 as a periostin receptor; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Purified recombinant periostin supports adhesion of ovarian epithelial cells, inhibited by monoclonal antibodies against alpha(V)beta(3) or alpha(V)beta(5), but not by anti-beta(1) antibody [PMID:12235007]. The curator notes alphaVbeta3 colocalises to focal adhesions on periostin [PMID:12235007].","molecular_requirements":"The evidence concerns the alphaV-beta heterodimers, so alphaV with ITGB5 is needed; ITGB5 alone is not tested [PMID:12235007].","affinity_potency":[],"species_and_systems":"Human ovarian epithelial cells, recombinant periostin; read as abstract only [PMID:12235007]. The mouse pair is ortholog-inferred.","localisation_and_range":"Periostin is flagged secreted [flag]; adhesion to purified protein suggests matrix-bound action, which is an inference.","caveats":"Antibody blocking is indirect; the abstract does not report binding or affinity. The same antibody result covers both beta chains and does not separate them. Only one paper confirmed in the shown dossier.","key_references":[{"PMID":"12235007","why":"Antibody-blocked adhesion to periostin via alphaV integrins"}],"covers":["LR003126","LR006347"]},"LR001254":{"pair":"PRL -> PRLR","headline":"Well-established prolactin receptor pair: NMR structure, 2:1 complex, Kd 4x10(-10) M in transfected cells, many PDB entries.","interaction_type":"direct binding","direction_and_effect":"Prolactin activates PRLR in a 2:1 complex; hormone binding switches the WSXWS motif from a T-stack to a Trp/Arg-ladder and influences receptor dimerisation [PMID:22325776]. Tagged PRLR bound PRL and stimulated transcription of a beta-casein gene [PMID:9175708].","molecular_requirements":"Two receptor chains per hormone (2:1 complex) with receptor-receptor dimerisation at site 3 [PMID:22325776].","affinity_potency":[{"value":"Kd = 4x10(-10) M","assay":"PRL binding to Flag-tagged receptor","system":"transfected cells, rat PRLR","cite":"PMID:9175708"}],"species_and_systems":"NMR work on the human PRLR membrane-proximal domain [PMID:22325776]; the affinity study used rat PRLR cDNAs in transfected cells and does not state the PRL species [PMID:9175708]. Structures exist [DB:PDB 3D48].","localisation_and_range":"PRL is flagged secreted and PRLR transmembrane [flag].","caveats":"Both papers were abstract-only. Four further papers were pending and four abstract_insufficient. IntAct and PDB records also report the complex [DB:IntAct].","key_references":[{"PMID":"22325776","why":"NMR structure, hormone-dependent WSXWS switch, 2:1 complex"},{"PMID":"9175708","why":"PRL binds tagged PRLR, Kd 4x10(-10) M"}],"covers":["LR001254","LR004655"]},"LR003135":{"pair":"PRNP -> NRP1","headline":"Direct binding of normal PrP to immobilised neuropilin-1 in a biosensor assay, among many heparin-binding proteins; one paper.","interaction_type":"direct binding","direction_and_effect":"Normal protease-sensitive prion protein interacted with Npn-1 immobilised on an optical biosensor [PMID:15695515]. Functional effect on neuropilin-1 is not reported in our evidence.","molecular_requirements":"Interactions with heparin-binding proteins are ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515].","affinity_potency":[],"species_and_systems":"Biosensor assay with purified proteins; curator labels species human [PMID:15695515].","localisation_and_range":"PRNP is flagged non-secreted, NRP1 secreted and transmembrane [flag].","caveats":"PrP is one of many proteins listed as binding Npn-1, and the 'strong binding' sentence the curator quoted refers to four FGFs, not PrP [PMID:15695515]. No affinity for PrP. Specificity is uncertain.","key_references":[{"PMID":"15695515","why":"Biosensor screen of heparin-binding proteins binding Npn-1"}],"covers":["LR003135","LR006356"]},"LR001263":{"pair":"PSAP -> GPR37","headline":"Prosaptide, the active PSAP fragment, binds and activates GPR37 (pEC50 8.15); full-length prosaposin also stimulates; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Prosaptide was the sole hit in an orphan-neuropeptide screen, promoted GPR37 endocytosis, bound it and activated signalling; it induced ERK phosphorylation, 35S-GTPgammaS binding and inhibited forskolin-stimulated cAMP [PMID:23690594]. GtoPdb lists agonist with pEC50 [DB:GtoPdb].","molecular_requirements":"Prosaptide is the active fragment; full-length prosaposin also stimulated GPR37 signalling [PMID:23690594]. Receptor is a single GPCR chain.","affinity_potency":[{"value":"pEC50 8.15","assay":"prosaptide agonist activity","system":"human prosaptide at human GPR37","cite":"PMID:23690594"}],"species_and_systems":"Human proteins in cells; primary astrocytes were protected from oxidative stress, attenuated by siRNA knockdown of GPR37/GPR37L1 [PMID:23690594]. Mouse pair is ortholog-inferred.","localisation_and_range":"PSAP flagged secreted and GPR37 transmembrane [flag]; paracrine.","caveats":"One paper, abstract-only; two further rows pending. Astrocyte knockdown targeted GPR37 and GPR37L1 together [PMID:23690594].","key_references":[{"PMID":"23690594","why":"Deorphanisation of GPR37 by prosaptide and prosaposin."}],"covers":["LR001263","LR004663"]},"LR001272":{"pair":"PTHLH -> PTH2R","headline":"Our evidence points to no PTHrP activity at PTH2R; the one judged paper is a verified negative, while GtoPdb asserts an agonist.","interaction_type":"conflicting","direction_and_effect":"Native PTHrP responds poorly at the PTH2 receptor: the receptor responds potently to PTH but not to PTHrP [PMID:8702701]. Only after residues 5 and 23 were changed to the PTH residues did PTHrP bind and fully stimulate cAMP; [Trp23]hPTHrP-(1-36) was an antagonist at PTH2R [PMID:8702701]. GtoPdb nonetheless lists a full agonist [DB:GtoPdb].","molecular_requirements":"Residue 5 (His in PTHrP, Ile in PTH) determines signalling capability and residue 23 (Phe in PTHrP, Trp in PTH) determines binding affinity at PTH2R [PMID:8702701].","affinity_potency":[],"species_and_systems":"Human PTH-2 receptor with human hybrid peptides [PMID:8702701]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"PTHLH is flagged as secreted and PTH2R as transmembrane [flag].","caveats":"The curated judgement is pair_absent (abstract only) [PMID:8702701]. Five other rows were abstract_insufficient and one was a different entity, so there is no positive primary evidence. GtoPdb agonist entries cite 11602681 and 8702701 [DB:GtoPdb], but the latter is the negative result.","key_references":[{"PMID":"8702701","why":"Shows PTH2R responds to PTH but not PTHrP"}],"covers":["LR001272","LR004672"]},"LR003144":{"pair":"PTK7 -> ADGRD1","headline":"PTK7 binds the ADGRD1 (GPR133) N-terminal fragment and raises its signalling in trans in glioblastoma models; direct binding is supported.","interaction_type":"direct binding","direction_and_effect":"PTK7 is a positive allosteric modulator of GPR133: expressed in trans in neighbouring cells it increased cAMP, additive with the orthosteric Stachel-mimicking peptide [PMID:37354459]. No cAMP increase was seen when both were co-expressed in the same cells [PMID:37354459].","molecular_requirements":"PTK7 binds the autoproteolytically generated N-terminal fragment; the effect requires GPR133 intramolecular cleavage and PTK7 plasma-membrane anchoring, and a secreted PTK7 NTF did not work [PMID:37354459]. The PTX domain is not needed for binding [PMID:37354459].","affinity_potency":[],"species_and_systems":"Human proteins; affinity proteomics in patient-derived glioblastoma cells, validation in HEK293T cells [PMID:37354459]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound PTK7 acting on neighbouring cells (juxtacrine) [PMID:37354459]. The ligand is flagged as secreted [flag], but the paper found the secreted form inactive.","caveats":"Single paper; no affinity reported. Mechanism is allosteric modulation rather than classical agonism. A secreted-flag annotation on PTK7 conflicts with the paper's anchoring requirement.","key_references":[{"PMID":"37354459","why":"Identifies PTK7 as GPR133 binder and positive allosteric modulator"}],"covers":["LR003144","LR006365"]},"LR010650":{"pair":"PTN -> PLXNB2","headline":"Database-only pair from a two-hybrid pooling screen; no papers confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; IntAct record only [DB:IntAct].","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. PLXNB2 is flagged as transmembrane [flag].","caveats":"One review_only row and a high-throughput two-hybrid IntAct record [DB:IntAct]; no validation or functional data.","key_references":[],"covers":["LR010650"]},"LR003153":{"pair":"PTN -> ROR1","headline":"One SPR study shows human PTN binding the ROR1 ectodomain; no functional data.","interaction_type":"direct binding","direction_and_effect":"Human PTN as analyte bound the ROR1 ectodomain by surface plasmon resonance, validating a CRISPRa screen hit; the comparator MDK showed no binding [PMID:36178190]. Functional effect not reported in our evidence.","molecular_requirements":"Receptor ectodomain only; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant ectodomains, SPR [PMID:36178190].","localisation_and_range":"ROR1 is flagged transmembrane and PTN secreted [flag].","caveats":"Single paper, in vitro; no affinity value in our evidence; the paper also reports a 'steady-state curve' but no number is given here.","key_references":[{"PMID":"36178190","why":"SPR binding of PTN to ROR1-ECD"}],"covers":["LR003153","LR006374"]},"LR003162":{"pair":"PTPRD -> SLITRK3","headline":"Cell-aggregation evidence in mouse for PTPRD and SLITRK3; single paper, human and mouse pairs both inferred.","interaction_type":"functional only","direction_and_effect":"Slitrk3-expressing L cells specifically aggregated with PTP-delta-expressing L cells [PMID:23345436]. Effect direction on either partner is not reported in our evidence.","molecular_requirements":"Not reported in our evidence; the paper says Slitrks need distinct LAR-RPTP members for synapse formation, with PTP-delta needed for inhibitory synapse differentiation [PMID:23345436].","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells [PMID:23345436]. Both human and mouse pairs are ortholog-inferred, so no direct human data are shown.","localisation_and_range":"Both flagged transmembrane [flag]; cell-cell aggregation suggests contact-dependent action [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check. No database record supports this pair.","key_references":[{"PMID":"23345436","why":"Cell-aggregation assay Slitrk3 with PTP-delta cells"}],"covers":["LR003162","LR006383"]},"LR003171":{"pair":"PTPRS -> SLITRK2","headline":"Mouse cell-aggregation evidence that PTP-sigma and SLITRK2 adhere; single paper.","interaction_type":"functional only","direction_and_effect":"Slitrk2-expressing cells aggregated with PTP-sigma-expressing cells; the paper concludes PTP-sigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Slitrks require distinct LAR-RPTP family members for synapse formation, in an isoform-dependent manner [PMID:23345436]. Subunit needs beyond that are not reported.","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells; the abstract also uses rat brain [PMID:23345436]. Human pair is direct; mouse pair is ortholog-inferred.","localisation_and_range":"Cell-cell aggregation implies contact-dependent action; PTPRS is flagged secreted [flag] [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check.","key_references":[{"PMID":"23345436","why":"Slitrk-PTP-sigma cell aggregation and synapse-formation requirement"}],"covers":["LR003171","LR006392"]},"LR001281":{"pair":"PYY -> NPY2R","headline":"PYY binds and activates NPY2R (Y2) with high affinity in human and rat systems; three papers read as abstracts.","interaction_type":"direct binding","direction_and_effect":"PYY is an agonist: human PYY decreased cAMP and raised intracellular calcium in hY2-transfected 293 cells [PMID:7592910]. In rat, PYY inhibits cAMP and intestinal secretion through a Y2 receptor, reversed by antagonist BIIE0246 [PMID:11408607].","molecular_requirements":"Not reported in our evidence; single receptor chain.","affinity_potency":[{"value":"pKd 10.17","assay":"125I-PYY saturation binding","system":"human Y2 transiently expressed","cite":"PMID:7592910"},{"value":"pKi 9.47","assay":"displacement of 125I-PYY by PYY","system":"human Y2 transiently expressed","cite":"PMID:7592910"}],"species_and_systems":"Human Y2 cloned from hippocampus (293 cells) [PMID:7592910]; human brain Y2 cloned, high affinity for NPY, PYY and C-terminal fragments [PMID:8632753]; rat intestinal crypt membranes and rat Y2 in CHO cells [PMID:11408607].","localisation_and_range":"PYY is flagged secreted [flag]; the rat paper shows an endocrine/paracrine action on intestinal secretion [PMID:11408607].","caveats":"All three papers were abstract only. PMID:8632753 gives no number in our excerpt. NPY is similarly potent (pKi = 9.27), so PYY is not selective over NPY [PMID:7592910].","key_references":[{"PMID":"7592910","why":"Saturable PYY binding and cAMP/Ca2+ response at human Y2"},{"PMID":"11408607","why":"Rat peripheral Y2 as PYY receptor, binding and in vivo function"},{"PMID":"8632753","why":"Independent cloning of human brain Y2 with high PYY affinity"}],"covers":["LR001281","LR004681"]},"LR003180":{"pair":"RBP4 -> TLR4","headline":"RBP4 is reported to prime the NLRP3 inflammasome through TLR4/MD2 and TLR2 in adipose tissue; a single abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"RBP4 primes the NLRP3 inflammasome for IL1beta release, in a glucose-dependent manner, through the TLR4/MD2 receptor complex and TLR2, impairing insulin signaling in adipocytes [PMID:33214151].","molecular_requirements":"The TLR4/MD2 complex and TLR2 are named; which is required is not reported in our evidence. Holo- or apo-RBP4 injection both caused insulin resistance [PMID:33214151].","affinity_potency":[],"species_and_systems":"Mice (RBP4-overexpressing and wild-type, injections, TLR4 inhibition) and adipocytes; curators label human/human but the abstract describes mouse work [PMID:33214151].","localisation_and_range":"RBP4 is flagged secreted [flag].","caveats":"Only functional evidence, no direct binding to TLR4 shown in our evidence. Paper read as abstract only; TLR4 inhibition effects do not prove direct ligand-receptor binding. No database support.","key_references":[{"PMID":"33214151","why":"RBP4 primes NLRP3 via TLR4/MD2 and TLR2"}],"covers":["LR003180","LR006400"]},"LR001290":{"pair":"RELN -> ITGA3","headline":"Reelin associates with alpha3beta1 integrin in one primary paper; support is chain-level (ITGA3 alone) and single-source.","interaction_type":"direct binding","direction_and_effect":"Recombinant and native Reelin co-immunoprecipitated with alpha3 and beta1 integrin beads, and Reelin inhibited cortical neuron migration in a manner dependent on alpha3beta1 [PMID:10939329]. The curated effect is stimulatory by annotation [flag], whereas the paper reports inhibition of migration.","molecular_requirements":"The evidence is for the alpha3beta1 heterodimer; this ITGA3-alone row does not show that alpha3 suffices [PMID:10939329]. Alpha3beta1 is described as acting with VLDLR and ApoER2 in a complex [PMID:10939329].","affinity_potency":[],"species_and_systems":"Experiments used mouse and rat embryonic cortex, cultured cortical neurons and recombinant Reelin from 293T cells [PMID:10939329]. The human pair is ortholog-inferred; the mouse pair is direct.","localisation_and_range":"RELN is flagged secreted [flag]. Reelin-coated microspheres acted locally in tissue [PMID:10939329].","caveats":"Single paper only; the curator record was an abstract read, though full-text excerpts were available. Chain-only (ITGA3) attribution of a heterodimer result.","key_references":[{"PMID":"10939329","why":"Reelin binds alpha3beta1 integrin; integrin-null neurons ignore Reelin"}],"covers":["LR001290","LR004689"]},"LR004701":{"pair":"RLN3 -> RXFP4","headline":"Relaxin-3 binds and activates RXFP4 (GPCR142) with nanomolar potency across species, with a mouse binding-signalling discordance.","interaction_type":"direct binding","direction_and_effect":"Relaxin-3 activates GPCR142 at nanomolar concentrations while other insulin-like peptides do not [PMID:14522967]. It activates ERK1/2, p38MAPK and Akt and causes receptor internalisation, slightly more potently than INSL5 for ERK1/2 and Akt [PMID:27888281]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"GPCR142 couples to calcium mobilisation only via Galpha16, not Gqi5 [PMID:14522967]. Other subunit needs are not reported in our evidence.","affinity_potency":[{"value":"IC50 < 5 nM","assay":"relaxin-3 binding to GPCR142 orthologues","system":"human, mouse, monkey, cow and pig GPCR142","cite":"PMID:15367576"},{"value":"pIC50 8.800000190734863 to 9.0","assay":"GtoPdb affinity range (pIC50)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in recombinant cells; mouse and other species orthologues tested for binding [PMID:15367576]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"Relaxin-3 bound mouse GPCR142 at high affinity but did not stimulate a Ca2+ response with Galpha16, unlike other species; rat GPCR142 is a pseudogene [PMID:15367576]. Papers read as abstracts only; one further abstract was judged review only.","key_references":[{"PMID":"14522967","why":"Identification of relaxin-3 as GPCR142 agonist"},{"PMID":"15367576","why":"Cross-species binding and the mouse functional discordance"},{"PMID":"27888281","why":"Relaxin-3 versus INSL5 signalling at RXFP4"}],"covers":["LR001303","LR004701"]},"LR006411":{"pair":"ROBO1 -> ROBO3","headline":"ROBO3 binds ROBO1 heterophilically per one abstract-only paper; no database support.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind heterophilically to Robo1 (and NCAM) [PMID:16226035]. This is adhesion between family members; no signalling effect for this pair is reported.","molecular_requirements":"Two human Robo3 isoforms (Robo3A/Robo3B) differ by a 26-residue N-terminal insertion and differ in Slit binding; which isoform binds Robo1 is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; orthologs reported expressed in mouse embryo [PMID:16226035]. Mouse pair is ortholog-projected.","localisation_and_range":"Both entities carry a membrane-bound flag [flag]; no range data from the paper.","caveats":"Abstract only; one sentence supports the Robo1 interaction and the assay type is not detailed. No database records.","key_references":[{"PMID":"16226035","why":"Robo3 binds Robo1 heterophilically; isoform study"}],"covers":["LR003191","LR006411"]},"LR001308":{"pair":"RSPO1 -> LGR5","headline":"RSPO1 is an agonist ligand of LGR5, with binding, functional and structural support.","interaction_type":"direct binding","direction_and_effect":"R-spondins function as ligands of LGR4 and LGR5 and enhance Wnt/beta-catenin signalling [PMID:21693646]. All four R-spondins bind LGR5 and RSPO1 enhances WNT3A signalling [PMID:21727895]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"LGR5 associates with the Frizzled/Lrp complex; LGR4, -5 or -6 can rescue RSPO1 enhancement [PMID:21727895]. Neither receptor couples to G proteins or beta-arrestin [PMID:21693646].","affinity_potency":[{"value":"pEC50 11.1","assay":"Wnt reporter assay","system":"intestinal crypts / reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human proteins; intestinal crypts and Wnt reporter assays [PMID:21693646]; mouse gut and HEK293 [PMID:21727895]. Mouse pair is ortholog-inferred.","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Both papers abstract only. RSPO1 modulates Wnt rather than signalling alone [PMID:21693646]. IntAct has SPR and co-IP records and PDB lists structures 4BSR-4BSU [DB:IntAct][DB:PDB 4BSR].","key_references":[{"PMID":"21693646","why":"RSPOs as LGR4/5 ligands, pEC50"},{"PMID":"21727895","why":"R-spondin binding to LGR4/5/6"}],"covers":["LR001308","LR004705"]},"LR004710":{"pair":"RSPO2 -> LGR5","headline":"RSPO2 binds and activates LGR5, with binding, functional and genetic evidence.","interaction_type":"direct binding","direction_and_effect":"R-spondins function as ligands of LGR4 and LGR5 [PMID:21693646]. Human RSPO2 mutants show impaired binding to LGR4/5/6 and RNF43/ZNRF3 [PMID:29769720]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR5 associates with the Frizzled/Lrp complex [PMID:21727895]. RSPO2 limb function acted independently of LGR4/5/6 via RNF43/ZNRF3 [PMID:29769720].","affinity_potency":[{"value":"pEC50 12.0","assay":"Wnt reporter assay","system":"intestinal crypts / reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human proteins in intestinal crypts and reporter assays [PMID:21693646]; human tetra-amelia mutations [PMID:29769720]; mouse gut deletion [PMID:21727895].","localisation_and_range":"RSPO2 secreted per flag [flag].","caveats":"All papers abstract only. The 21727895 evidence sentence concerns Lgr5/Lgr4 co-expression, not RSPO2 binding. One review-only row. BioGRID has affinity-capture and reconstituted records [DB:BioGRID].","key_references":[{"PMID":"21693646","why":"R-spondins as LGR4/5 ligands, pEC50"},{"PMID":"29769720","why":"RSPO2 mutants lose LGR4/5/6 binding"},{"PMID":"21727895","why":"LGR4/5 mediate R-spondin signalling"}],"covers":["LR001313","LR004710"]},"LR001317":{"pair":"RSPO3 -> LGR5","headline":"RSPO3 acting through LGR5 is supported by family-level abstracts and databases; LGR5 enhances Wnt signalling as a facultative component.","interaction_type":"direct binding","direction_and_effect":"RSPO3 acts as an agonist at LGR5, potentiating Wnt/beta-catenin signalling [PMID:21693646]; GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 and LGR5 enhance Wnt-induced LRP6 phosphorylation [PMID:21693646]. Lgr5 homologues are described as facultative Wnt receptor components associating with the Frizzled/Lrp complex; removing LGR4 abrogates RSPO1-driven enhancement, rescued by LGR4, -5 or -6 [PMID:21727895].","affinity_potency":[{"value":"pEC50 11.0","assay":"Wnt reporter assay, as recorded by curators","system":"intestinal crypts; Wnt reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Curators record human ligand and receptor; the underlying work used mouse gut conditional knockouts and HEK293 cells with RSPO1 [PMID:21727895].","localisation_and_range":"RSPO3 is flagged secreted and LGR5 transmembrane [flag].","caveats":"All three papers were read as abstracts only and name R-spondins generally. PMID 29769720 is an RSPO2 paper reporting impaired LGR4/5/6 binding of mutants. No RSPO3-specific measurement is reported in our evidence beyond database records [DB:UniProt] [DB:Reactome].","key_references":[{"PMID":"21693646","why":"R-spondins as LGR4/5 ligands"},{"PMID":"21727895","why":"Lgr4/5 mediate R-spondin signalling"}],"covers":["LR001317","LR004714"]},"LR001326":{"pair":"RTN4 -> RTN4R","headline":"Nogo-66 binds NgR1 (RTN4R) with high affinity and inhibits axon regeneration; the canonical, well supported Nogo receptor pair.","interaction_type":"direct binding","direction_and_effect":"Nogo-66 binds NgR1 and inhibits axonal extension; receptor expression is sufficient to confer Nogo-66 inhibition on unresponsive neurons [PMID:11201742]. The NgR1 complex with p75 and LINGO-1 represses axon regeneration on binding myelin components [PMID:15694322]; UniProt lists NgR1 as receptor for RTN4, OMG and MAG [DB:UniProt].","molecular_requirements":"The signalling complex comprises NgR1, p75 and LINGO-1; TAJ can replace p75 and activate RhoA [PMID:15694322].","affinity_potency":[],"species_and_systems":"Curators record human ligand and receptor; the 2001 paper used neurons and cells, the 2005 paper mouse neurons [PMID:11201742] [PMID:15694322].","localisation_and_range":"RTN4 is flagged non-secreted and RTN4R transmembrane [flag]; Nogo-66 is the extracellular domain acting on GPI-linked NgR1 [PMID:11201742].","caveats":"Both papers abstract-only; \"high affinity\" is stated without a number. The second paper treats the pair as background.","key_references":[{"PMID":"11201742","why":"Identification of NgR as Nogo-66 receptor"},{"PMID":"15694322","why":"NgR1/p75/LINGO-1 complex; TAJ substitutes for p75"}],"covers":["LR001326","LR004723"]},"LR006420":{"pair":"RTN4R -> ADGRB3","headline":"Direct nanomolar binding of RTN4R to BAI3 supported by one paper with full-text SPR data; the human pair is projected from other evidence.","interaction_type":"direct binding","direction_and_effect":"RTN4R ectodomain binds BAI3 (ADGRB3); BAI3-expressing cells aggregated specifically with RTN4R-expressing cells [PMID:34758294]. Signalling effect is not reported in our evidence for this pair.","molecular_requirements":"The single TSR2 domain of BAI3 bound RTN4Rs avidly and formed a complex with RTN4R by SEC [PMID:34758294]. EGTA did not reduce binding, so it is Ca2+ independent; C1ql3 did not compete with RTN4R for BAI binding [PMID:34758294].","affinity_potency":[{"value":"Kd = 1.9 nM","assay":"surface plasmon resonance, recombinant ectodomains (highest of the BAI-RTN4R pairs; BAI3-RTN4R)","system":"purified recombinant proteins","cite":"PMID:34758294"}],"species_and_systems":"Mouse C1ql3 and recombinant ectodomains, HEK 293F cell aggregation and SPR [PMID:34758294]. The human interaction is flagged as ortholog-inferred; a mouse pair is listed as not inferred. The curator row was originally recorded from the abstract only, but full-text excerpts are present.","localisation_and_range":"Trans-cellular adhesion complex, so contact-dependent [PMID:34758294]. ADGRB3 has no secreted flag in the dossier; RTN4R is not flagged secreted [flag].","caveats":"Only one paper. The crystal structure is of BAI1, not BAI3 [PMID:34758294]. The 1.9 nM Kd is reported as the BAI3-RTN4R value; species of the SPR proteins is not stated in the excerpts.","key_references":[{"PMID":"34758294","why":"SPR, cell aggregation and domain mapping for BAI3 and RTN4R"}],"covers":["LR003200","LR006420"]},"LR003207":{"pair":"S100A10 -> CFTR","headline":"One paper reports direct SPR binding of p11/S100A10 to the CFTR NBD1 domain; evidence is a single, domain-level in vitro result.","interaction_type":"direct binding","direction_and_effect":"p11 binds the NBD1 domain of CFTR; other tested proteins (ANXA1, cPLA2alpha/ANXA1 complex) did not bind NBD1 [PMID:19847291]. Functional data suggest CFTR restrains eicosanoid release by this complex, but this is inferred, not a ligand effect [PMID:19847291].","molecular_requirements":"Binding was shown to the isolated NBD1 domain of CFTR, not full-length channel; p11 is proposed as the link to a cPLA2alpha/ANXA1 complex [PMID:19847291].","affinity_potency":[],"species_and_systems":"SPR with human proteins in vitro; cell work in Calu-3 cells (human) [PMID:19847291]. Mouse pair is projected from human evidence.","localisation_and_range":"S100A10 is not flagged secreted in the entity annotation [flag]; the paper places the proteins in detergent-resistant membrane fractions [PMID:19847291]. Intracellular partner rather than a classic secreted ligand.","caveats":"Affinity not reported in our evidence. Curator read only the abstract, though full-text excerpts were available. Not a classic ligand-receptor relation; it is an intracellular adaptor interaction.","key_references":[{"PMID":"19847291","why":"SPR binding of p11 to CFTR NBD1"}],"covers":["LR003207","LR006427"]},"LR003216":{"pair":"S100A4 -> CXCR3","headline":"No verified paper; support comes only from UniProt text describing the Tag7-S100A4 complex acting via CXCR3.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the PGLYRP1-S100A4 complex promotes lymphocyte migration via CCR5 and CXCR3 [DB:UniProt].","molecular_requirements":"The assertion concerns the complex with PGLYRP1, not S100A4 alone [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence.","localisation_and_range":"S100A4 is flagged secreted and CXCR3 transmembrane [flag].","caveats":"Two papers judged abstract_insufficient; no curator-verified evidence for direct S100A4-CXCR3 binding. Treat as database-asserted.","key_references":[],"covers":["LR003216","LR006434"]},"LR003225":{"pair":"S100A8 -> CD36","headline":"S100A8/A9 carrying arachidonic acid interacts with CD36 as a fatty acid transporter, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Arachidonate uptake by HUVEC, mediated mostly by FAT/CD36, was inhibited by sulfo-N-succinimidyl oleate and doubled in CD36-transfected COS-7 cells; an in vitro assay confirmed interaction of CD36 with the S100A8/A9-AA complex [PMID:11141076].","molecular_requirements":"The interacting species is the S100A8/A9 heterodimer with arachidonic acid [PMID:11141076].","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC) and COS-7 cells [PMID:11141076].","localisation_and_range":"S100A8 is flagged secreted and CD36 transmembrane [flag].","caveats":"Abstract only. Cargo transport, not receptor signalling. Complex-level evidence inherited by the S100A8 subunit.","key_references":[{"PMID":"11141076","why":"CD36-dependent uptake of S100A8/A9-arachidonate"}],"covers":["LR003225","LR006442"]},"LR003234":{"pair":"S100A9 -> BSG","headline":"EMMPRIN/BSG is described as an S100A9 receptor, but only as background citing prior work.","interaction_type":"functional only","direction_and_effect":"The abstract states that a positive feedback loop between S100A8/A9 and proinflammatory cytokines is mediated by EMMPRIN, an S100A9 receptor; this is cited as the group's earlier finding, not shown here [PMID:27388991]. EMMPRIN and neuroplastin-beta form a heterodimer on keratinocytes, proposed as a functional receptor for the S100A8/A9 heterodimer [PMID:27388991].","molecular_requirements":"Possible heterodimer with neuroplastin-beta; knockdown of both receptors suppressed proliferation and cytokine induction [PMID:27388991].","affinity_potency":[],"species_and_systems":"Cultured normal human keratinocytes [PMID:27388991].","localisation_and_range":"Ligand secreted [flag]; BSG flagged transmembrane [flag].","caveats":"The S100A9-BSG result is background from earlier work, not tested in this paper; abstract only; no binding data or affinity in our evidence.","key_references":[{"PMID":"27388991","why":"Describes EMMPRIN/BSG as S100A9 receptor (background) and its heterodimer"}],"covers":["LR003234","LR006451"]},"LR003243":{"pair":"SAA1 -> TLR2","headline":"SAA activates TLR2 signalling and binds the TLR2 ectodomain in one abstract-level study; moderately supported.","interaction_type":"direct binding","direction_and_effect":"TLR2-expressing HeLa cells responded to SAA with NF-kappaB activation, MAPK phosphorylation and IkappaBalpha degradation; a solid-phase binding assay showed SAA interaction with the TLR2 ectodomain [PMID:18566366]. SAA-induced gene expression was selectively reduced in tlr2-/- mouse macrophages [PMID:18566366].","molecular_requirements":"TLR1 co-expression enhanced the response, and TIR-deletion mutants of TLR1, TLR2 and TLR6 blocked it [PMID:18566366].","affinity_potency":[],"species_and_systems":"Human SAA and TLR2 in HeLa cells, plus mouse macrophages for knockout data [PMID:18566366].","localisation_and_range":"Secreted ligand acting on a membrane receptor [flag].","caveats":"Read as abstract only; no affinity reported. A second confirmed paper exists but is not shown.","key_references":[{"PMID":"18566366","why":"TLR2 as functional SAA receptor: binding and signalling"}],"covers":["LR003243","LR006459"]},"LR001335":{"pair":"SCT -> SCTR","headline":"Secretin is a well-supported direct agonist of its receptor SCTR, with binding, cAMP and structural evidence.","interaction_type":"direct binding","direction_and_effect":"Secretin binds the human secretin receptor with high affinity and stimulates adenylyl cyclase and cAMP in a dose-dependent manner [PMID:7612008]. GtoPdb lists it as a full agonist [DB:GtoPdb]. A recombinant SCTR N-terminal ectodomain inhibited secretin-induced cAMP and PKA activity, acting as an antagonist [PMID:9440501].","molecular_requirements":"The N-terminal ectodomain is the main determinant of secretin versus VIP selectivity and the first loop contributes [PMID:7782300]. Lys173 in the first extracellular loop likely interacts with Asp3 of secretin [PMID:8579602]. Complex structures exist [DB:PDB 6WI9] [DB:PDB 6WZG] [DB:PDB 7D3S].","affinity_potency":[{"value":"IC50 2.2 nM","assay":"competitive binding, secretin at wild-type secretin receptor","system":"COS cells","cite":"PMID:7782300"},{"value":"EC50 1.5 nM","assay":"cAMP generation by secretin at wild-type secretin receptor","system":"COS cells","cite":"PMID:7782300"},{"value":"pEC50 9.699999809265137","assay":"affinity value recorded for secretin at the human receptor","system":"COS-7 cells","cite":"PMID:7612008"}],"species_and_systems":"Human receptor in COS-7 and COS cells [PMID:7612008] [PMID:7782300]; rat receptor loop work in CHO cells [PMID:8579602]. Mouse pair is projected from human.","localisation_and_range":"Secretin is flagged secreted and SCTR transmembrane [flag]; UniProt describes secretin acting through a receptor in the basolateral domain of several cells [DB:UniProt].","caveats":"All four cited papers were read as abstracts only. Several papers study receptor mutants or chimeras rather than the native pair.","key_references":[{"PMID":"7612008","why":"Cloning of human SCTR with high-affinity secretin binding and cAMP coupling"},{"PMID":"7782300","why":"Chimeric receptors; IC50 2.2 nM and domain mapping"},{"PMID":"9440501","why":"Ectodomain alone antagonises secretin signalling"}],"covers":["LR001335","LR004731"]},"LR003252":{"pair":"SCUBE2 -> PTCH1","headline":"SCUBE2 is reported to interact with PTCH1 and enhance SHH signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Human SCUBE2 interacts with SHH and with PTCH1 and enhances SHH signalling in cholesterol-rich raft microdomains, acting as a positive component upstream of ligand binding [PMID:19480626]. UniProt notes the PTCH1 interaction [DB:UniProt].","molecular_requirements":"SCUBE2 engages both SHH and PTCH1; the spacer region and cysteine-rich repeats matter for membrane association [PMID:19480626]. It functions as a co-regulator, not a classical ligand.","affinity_potency":[],"species_and_systems":"Human SCUBE2 overexpressed as recombinant protein, with biochemical and reporter assays; the human and mouse pairs are ortholog-inferred [PMID:19480626].","localisation_and_range":"Secreted but surface-anchored glycoprotein when overexpressed, active in lipid rafts [PMID:19480626]; SCUBE2 flagged secreted [flag].","caveats":"Single paper read from abstract only; no affinity and the assay type is not detailed. The interaction is as a co-regulator of SHH-PTCH1.","key_references":[{"PMID":"19480626","why":"SCUBE2 interacts with SHH and PTCH1 and boosts SHH signalling"}],"covers":["LR003252","LR006468"]},"LR003261":{"pair":"SELPLG -> SIGLEC1","headline":"Sialoadhesin binds PSGL-1 in one mouse study, read as abstract only; thin support.","interaction_type":"direct binding","direction_and_effect":"Sialoadhesin-Fc fusion proteins precipitated a 240-kDa glycoprotein from murine TK-1 T cells that was identified as PSGL-1 (CD162) [PMID:11238599]. Which partner signals is not reported; effect on cells is not reported in our evidence.","molecular_requirements":"Binding to the glycoproteins was sialic acid dependent and abolished by the R97A mutation in the sialic acid binding site of sialoadhesin [PMID:11238599]. The paper's main finding concerns CD43 as counterreceptor.","affinity_potency":[],"species_and_systems":"Mouse sialoadhesin-Fc and mouse TK-1 T cells [PMID:11238599]. The human pair is inferred from the mouse evidence (ortholog_inferred).","localisation_and_range":"The receptor is flagged secreted and transmembrane [flag]; the experiment used the membrane form on cells binding a soluble Fc fusion [PMID:11238599].","caveats":"Only one paper, read as abstract only; PSGL-1 is a secondary finding after CD43. No database records. Binding is glycan-mediated rather than protein-protein [PMID:11238599].","key_references":[{"PMID":"11238599","why":"Sialoadhesin-Fc precipitates PSGL-1 from mouse T cells"}],"covers":["LR003261","LR006477"]},"LR001344":{"pair":"SEMA3A -> PLXNA3","headline":"PlexinA3 is genetically required for Sema3A-induced neuronal death in vitro; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"PlexinA3 is the key receptor subunit responsible for Sema3A-induced cell death; both PlexinA3 and PlexinA4 contribute in vitro, with PlexinA3 absolutely required and PlexinA4 contributing less [PMID:19020035].","molecular_requirements":"Plexins are described as Sema3A coreceptors [PMID:19020035]; whether NRP1 is needed is not reported in our evidence beyond Reactome's Nrp-1-bound-to-PlexinA record [DB:Reactome].","affinity_potency":[],"species_and_systems":"Knockout neurons (mouse implied; species fields empty in dossier) and PlexinA3-/- mice [PMID:19020035]; human pair is ortholog-inferred [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"One paper, with the key sentence browser-read and spot-check pending; evidence is a genetic requirement, not binding. Described as borderline by the curator.","key_references":[{"PMID":"19020035","why":"PlexinA3 required for Sema3A-induced neuronal apoptosis"}],"covers":["LR001344","LR004740"]},"LR003270":{"pair":"SEMA3D -> PLXND1","headline":"Co-immunoprecipitation in pancreatic cancer and zebrafish genetics support SEMA3D acting via PlexinD1; both papers abstract-level.","interaction_type":"functional only","direction_and_effect":"Secreted Sema3D co-immunoprecipitated with plexin D1 on PDA cells and promoted metastasis [PMID:26243191]. In zebrafish, mesenchymal Sema3d repels the common cardinal vein through PlexinD1 [PMID:27799363].","molecular_requirements":"PlexinD1 is described as a co-receptor in the PDA paper [PMID:26243191]; in zebrafish it acted independently of Nrp1 for the repulsion function [PMID:27799363].","affinity_potency":[],"species_and_systems":"Mouse KPC pancreatic cancer model [PMID:26243191]; zebrafish embryos [PMID:27799363]. The curator lists species as human for both; the mouse pair is not ortholog-inferred.","localisation_and_range":"SEMA3D is annotated secreted [flag]; autocrine in PDA cells [PMID:26243191] and mesenchymal paracrine in zebrafish [PMID:27799363].","caveats":"Both read as abstracts; co-IP is in cells not purified protein; effect labels differ (agonist vs antagonist) by context. No affinity data.","key_references":[{"PMID":"26243191","why":"Sema3D co-IP with PlxnD1 in pancreatic cancer"},{"PMID":"27799363","why":"Mesenchymal Sema3d repulsion via PlexinD1 in zebrafish"}],"covers":["LR003270","LR006486"]},"LR001353":{"pair":"SEMA3F -> NRP1","headline":"NRP1 reported as a SEMA3F receptor by binding screen and cell assays; mixed abstract-level and full-text evidence.","interaction_type":"direct binding","direction_and_effect":"SEMA3F inhibited cell contacts, with loss of membrane E-cadherin and beta-catenin, in NRP1-only MCF7 cells [PMID:15802023]. The 1997 paper states neuropilin-1 binds Sema III, Sema E and Sema IV with high affinity [PMID:9331348].","molecular_requirements":"NRP1 alone suffices in MCF7 cells, which express only NRP1 [PMID:15802023]. A screen reports direct Sema-Nrp interactions without specifying plexin needs [PMID:26633812].","affinity_potency":[],"species_and_systems":"Human cells and proteins in the cited papers [PMID:15802023][PMID:9331348][PMID:26633812]. The mouse pair is ortholog-inferred.","localisation_and_range":"SEMA3F is annotated secreted [flag].","caveats":"Mostly abstract-only. In the C100 line, repulsion was blocked by anti-NRP2 and not tested against anti-NRP1 [PMID:15802023]. The 1997 sentence shown concerns NRP2 selectivity. Mapping Sema IV to SEMA3F is from curator notes. Other confirmed rows are not shown; no affinity reported.","key_references":[{"PMID":"9331348","why":"NRP1 binds Sema IV; NRP2 identified"},{"PMID":"15802023","why":"SEMA3F acts on NRP1-only MCF7 cells"},{"PMID":"26633812","why":"Biochemical screen of Sema-Nrp binding"}],"covers":["LR001353","LR004749"]},"LR008031":{"pair":"SEMA4D -> MET:PLXNB1","headline":"Sema4D acts through a PlexinB1-Met complex; Met is functionally required. One abstract-level paper plus structural and interaction records for PLXNB1.","interaction_type":"functional only","direction_and_effect":"Sema4D binding to PlexinB1 activates Met kinase and phosphorylates both receptors in cells expressing endogenous proteins [PMID:12198496].","molecular_requirements":"PlexinB1 and Met associate in a complex; cells lacking Met do not respond to Sema4D unless Met is restored [PMID:12198496]. Binding itself is to PlexinB1 per curator notes; database records below concern SEMA4D-PLXNB1, not the whole complex.","affinity_potency":[],"species_and_systems":"Epithelial cells, human labels [PMID:12198496]. PDB 3OL2 has a structure of chains from Q92854 and O43157 [DB:PDB 3OL2]; IntAct lists surface plasmon resonance [DB:IntAct]; UniProt calls O43157 a receptor for SEMA4D [DB:UniProt].","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag].","caveats":"Abstract only; no affinity. Reactome also records an ErbB2 version of the complex [DB:Reactome], so the receptor complex may vary by cell type.","key_references":[{"PMID":"12198496","why":"Plexin B1-Met coupling in Sema4D signalling"}],"covers":["LR008031"]},"LR001362":{"pair":"SEMA4D -> PLXNB1","headline":"SEMA4D-PLXNB1 is a well-established receptor pair with binding, functional and structural database support.","interaction_type":"direct binding","direction_and_effect":"Plexin-B1 is a receptor for Sema4D (CD100) [PMID:10520995]. Sema4D triggers invasive growth through Plexin B1/Met [PMID:12198496], and acts on platelets via plexin-B1 [PMID:17244710]. In mouse hippocampus, Sema4D-Plexin-B1 regulates inhibitory synapse development without affecting excitatory synapses [PMID:29981480].","molecular_requirements":"Plexin-B1 is sufficient for binding; Met and ErbB-2 are associated co-receptors for signalling [PMID:12198496][DB:Reactome]. Active Rac enhances Sema4D binding to plexin-B1 [PMID:11937491].","affinity_potency":[],"species_and_systems":"Human recombinant and cell assays [PMID:10520995][PMID:11937491]; mouse hippocampal neurons [PMID:29981480]. PDB 3OL2 gives a structure of the pair [DB:PDB 3OL2]; IntAct surface plasmon resonance [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag]; platelet work shows membrane form followed by ADAM17 shedding [PMID:17244710].","caveats":"Papers were read as abstracts, except 29981480 with excerpts. No affinity in our evidence. In 11937491 Sema4D binding is a readout of Rac effects, not the paper's subject.","key_references":[{"PMID":"10520995","why":"Plexin-B1 assigned as Sema4D receptor"},{"PMID":"11937491","why":"Sema4D binding to plexin-B1 regulated by Rac"},{"PMID":"12198496","why":"Plexin B1-Met coupling"}],"covers":["LR001362","LR004758"]},"LR007401":{"pair":"SEMA6D -> KDR:PLXNA1","headline":"Complex-level support is functional: Plexin-A1 partners VEGFR2 for Sema6D responses in chick heart, and the two associate in mesothelioma cells.","interaction_type":"functional only","direction_and_effect":"In chick cardiac conotruncal explants, Plexin-A1 forms a receptor complex with VEGFR2 that mediates Sema6D's migration-promoting effect; with Off-track in the ventricle the effect is inhibitory [PMID:14977921]. In mesothelioma cells Sema6D and plexin-A1 trigger a prosurvival program, and plexin-A1 and VEGF-R2 are associated in a complex [PMID:19176370].","molecular_requirements":"Both PLXNA1 and KDR (VEGFR2) are implicated; which co-receptor is used depends on tissue [PMID:14977921].","affinity_potency":[],"species_and_systems":"Chick embryonic heart [PMID:14977921]; human malignant pleural mesothelioma cells [PMID:19176370]. Dossier pair is human.","localisation_and_range":"Ligand flagged membrane-bound; receptors flagged transmembrane [flag].","caveats":"Both papers abstract only; the mesothelioma abstract is truncated and its stored evidence sentence is generic. Opposite outcomes with different co-receptors make effect sign context-dependent.","key_references":[{"PMID":"14977921","why":"Plexin-A1 with VEGFR2 or Off-track mediates Sema6D in chick heart"},{"PMID":"19176370","why":"Plexin-A1/VEGF-R2 complex in Sema6D-expressing mesothelioma cells"}],"covers":["LR007401"]},"LR006501":{"pair":"SEMA6D -> NRCAM","headline":"Nr-CAM is reported as a receptor for Sema6D at the optic chiasm, with full-text excerpts describing binding.","interaction_type":"direct binding","direction_and_effect":"Nr-CAM functions as a receptor for Sema6D; Sema6D with Nr-CAM and Plexin-A1 converts repulsion of contralateral RGCs to growth promotion, and all three are required for efficient decussation [PMID:22632726]. Nr-CAM-Sema6D binding was perturbed by anti-Sema6D treatment [PMID:22632726].","molecular_requirements":"Nr-CAM acts together with Plexin-A1 in the signalling context [PMID:22632726].","affinity_potency":[],"species_and_systems":"Optic chiasm cultures and mouse in vivo per curator fields; the human pair is ortholog-inferred and the mouse pair is not.","localisation_and_range":"Sema6D and Nr-CAM are expressed on midline radial glia while Plexin-A1 is on chiasm neurons, so cell-to-cell contact signalling [PMID:22632726].","caveats":"Single paper; binding rests on one assay shown in excerpts and no affinity is reported. Receptor carries secreted and transmembrane flags [flag].","key_references":[{"PMID":"22632726","why":"Nr-CAM as Sema6D receptor in RGC decussation"}],"covers":["LR003285","LR006501"]},"LR001371":{"pair":"SEMA7A -> PLXNC1","headline":"Direct binding is supported by structural and biophysical database records and two papers, though both papers are abstract-only.","interaction_type":"direct binding","direction_and_effect":"Plexin-C1 is described as a receptor for the GPI-anchored semaphorin Sema7A [PMID:10520995]. Human melanocytes express Plexin C1, a receptor for Semaphorin 7a, and Sema7a affects melanocyte dendricity [PMID:17671519]. Effect is annotated stimulatory.","molecular_requirements":"No co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the first paper unspecified; human melanocytes in the second. Human pair is not ortholog-inferred, mouse pair is.","localisation_and_range":"Ligand is GPI-anchored per the abstract [PMID:10520995]; flagged secreted and transmembrane [flag]. Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"Both papers abstract only; neither gives affinity. Database records include ITC, X-ray crystallography and solid phase assay and PDB 3NVQ [DB:IntAct][DB:PDB 3NVQ].","key_references":[{"PMID":"10520995","why":"Plexin-C1 identified as a Sema7A receptor"},{"PMID":"17671519","why":"Melanocytes express Plexin C1, a Sema7a receptor"}],"covers":["LR001371","LR004767"]},"LR001380":{"pair":"SERPING1 -> SELP","headline":"C1 inhibitor binds P-selectin via glycans and inhibits adhesion; one abstract-only paper shared with E-selectin.","interaction_type":"direct binding","direction_and_effect":"Plasma C1INH bound P- and E-selectins by FACS and immunoprecipitation, and inhibited endothelial-leukocyte adhesion with significant (>50%) inhibition at 250 microg/mL or higher [PMID:14568956].","molecular_requirements":"Binding relies on sialyl Lewis(x)-related N-glycan moieties of C1INH [PMID:14568956].","affinity_potency":[],"species_and_systems":"Species not specified in the curated row; plasma C1INH and tissue-culture adhesion model [PMID:14568956]. BioGRID lists an affinity-capture-western record [DB:BioGRID].","localisation_and_range":"P-selectin is flagged as receptor and transmembrane [flag]; contact-dependent.","caveats":"Same single paper as the E-selectin pair; no affinity reported; the stored evidence sentence is the paper title; abstract only.","key_references":[{"PMID":"14568956","why":"C1INH binds selectins and blocks adhesion"}],"covers":["LR001380","LR004775"]},"LR011802":{"pair":"SFRP2 -> WNT6","headline":"SFRP2 binds WNT6 and inhibits its canonical pathway in cardiac progenitor cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"SFRP2 inhibits WNT6: Sfrp2 binding to Wnt6 and inhibition of the Wnt6 canonical pathway was essential for inhibition of CPC proliferation [PMID:26071893]. This is a ligand-ligand pair.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cardiac progenitor cells (isolated from FVB mice) [PMID:26071893]. The binding assay type is not stated in the abstract or excerpts.","localisation_and_range":"Both partners are flagged secreted [flag].","caveats":"One paper, read as abstract; the excerpts do not describe the binding assay itself. One more abstract was insufficient.","key_references":[{"PMID":"26071893","why":"Sfrp2 binding to Wnt6 and canonical pathway inhibition in cardiac progenitors"}],"covers":["LR011802"]},"LR006510":{"pair":"SFTPA1 -> LY96","headline":"SP-A binds MD-2 directly and antagonises LPS signalling; supported by one paper with several binding assays plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SP-A binding to TLR4/MD-2 is antagonist: it attenuated smooth-LPS cell-surface binding and NF-kappaB activation in TLR4/MD-2-expressing cells [PMID:16754682].","molecular_requirements":"Binding to MD-2 was Ca2+-dependent and involves the carbohydrate recognition domain; supratrimeric oligomerisation matters, because the trimeric CRF fragment had approximately 600- and 155-fold higher KD for TLR4 and MD-2 than SP-A [PMID:16754682]. Reactome lists the TLR4:LY96 complex as the binder [DB:Reactome].","affinity_potency":[{"value":"600-fold higher KD (CRF vs full SP-A), TLR4","assay":"BIAcore/solid-phase binding","system":"recombinant soluble TLR4","cite":"PMID:16754682"},{"value":"155-fold higher KD (CRF vs full SP-A), MD-2","assay":"BIAcore/solid-phase binding","system":"recombinant soluble MD-2","cite":"PMID:16754682"}],"species_and_systems":"Recombinant soluble human TLR4 and MD-2 with SP-A; cell assays in TLR4/MD-2-expressing cells. Mouse pair is ortholog-inferred [PMID:16754682].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One paper, abstract only; absolute KD values are not given, only fold differences. The paper concerns SP-A generally.","key_references":[{"PMID":"16754682","why":"Direct SP-A binding to TLR4 and MD-2 with oligomerisation dependence"}],"covers":["LR003294","LR006510"]},"LR005304":{"pair":"SFTPD -> LAIR1","headline":"SP-D binds LAIR-1 through its collagenous domain and inhibits FcalphaR-driven reactive oxygen; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Inhibitory: SP-D induces LAIR-1 cross-linking in a reporter assay and inhibits FcalphaR-mediated reactive oxygen production via LAIR-1 [PMID:24585933].","molecular_requirements":"The collagenous domain mediates binding; this does not affect SP-D mannan-binding [PMID:24585933]. The related LAIR-2 also binds.","affinity_potency":[],"species_and_systems":"Binding assays and cellular reporter assay; human ligand and receptor listed; mouse pair is ortholog-inferred [PMID:24585933].","localisation_and_range":"SP-D is flagged secreted and LAIR1 transmembrane [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"24585933","why":"SP-D collagenous domain binds LAIR-1 and inhibits ROS"}],"covers":["LR001974","LR005304"]},"LR007410":{"pair":"SHH -> CDON:PTCH2","headline":"Complex CDON:PTCH2 rests on one abstract showing PTCH2 is a functional SHH receptor; CDON's role is not shown.","interaction_type":"functional only","direction_and_effect":"Ptch2 is reported to be a functional Shh receptor that regulates Smo localization and activity in vitro [PMID:25448692]. UniProt records SHH acting by binding patched receptors PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"The paper concerns Ptch2 alone; CDON is not mentioned [PMID:25448692]. Reactome lists Hh-Npp:CDON:PTCH, not specific to PTCH2 [DB:Reactome].","affinity_potency":[],"species_and_systems":"In vitro work and mouse limb bud genetics; cell system not specified [PMID:25448692].","localisation_and_range":"SHH is flagged secreted [flag]; the receptor is flagged transmembrane [flag], so signalling is paracrine to a membrane receptor.","caveats":"Abstract-only. Support is for PTCH2, not for the CDON:PTCH2 complex.","key_references":[{"PMID":"25448692","why":"Ptch2 is a functional Shh receptor in vitro"}],"covers":["LR007410"]},"LR003306":{"pair":"SIGLEC15 -> CD44","headline":"Siglec-15 interacts with CD44 in human hepatoma cells in a sialylation-dependent way; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Siglec-15 interacts with CD44 and promotes CD44 stability by preventing its lysosomal-mediated degradation, promoting hepatoma cell migration [PMID:34328657].","molecular_requirements":"Interaction depends on CD44 alpha2,6-linked sialic acids on N-glycans; removal of sialic acid suppressed the interaction [PMID:34328657].","affinity_potency":[],"species_and_systems":"Human hepatoma cells [PMID:34328657]. Mouse pair is ortholog-inferred.","localisation_and_range":"CD44 is flagged secreted [flag] and transmembrane [flag]; the paper treats it as a transmembrane glycoprotein [PMID:34328657]. SIGLEC15 not flagged secreted [flag].","caveats":"Abstract-only. The effect (stabilisation) is on the receptor protein, not classical ligand signalling. One review-only paper not shown. No affinity.","key_references":[{"PMID":"34328657","why":"Siglec-15 interacts with and stabilises CD44"}],"covers":["LR003306","LR006520"]},"LR005313":{"pair":"SLIT1 -> ROBO2","headline":"Functional evidence only for SLIT1-ROBO2 from two abstract-only papers; ortholog-inferred in both species.","interaction_type":"functional only","direction_and_effect":"Endogenous Robos mediate Slit's growth-promoting effects on axons and dendrites in Robo1;Robo2 deficient neurons [PMID:21600986]. In a mouse stroke model, neuroblasts use Slit1-Robo2 signalling to disrupt the actin cytoskeleton in reactive astrocytes; Slit1 overexpression improved neuroblast positioning and functional recovery [PMID:30547091].","molecular_requirements":"Robo1 and Robo2 are deleted together in PMID:21600986, so Robo2 alone is not isolated there.","affinity_potency":[],"species_and_systems":"Mouse cortical neurons [PMID:21600986]; mouse ischemic-stroke model [PMID:30547091].","localisation_and_range":"SLIT1 flagged secreted and ROBO2 secreted/transmembrane [flag]; Reactome has a SLIT1:ROBO2 plasma membrane complex [DB:Reactome].","caveats":"No direct binding assay in our evidence; both papers abstract-only. The curator labelled PMID:30547091 antagonist, which is not explained in the abstract. No affinity.","key_references":[{"PMID":"30547091","why":"Slit1-Robo2 signalling in neuroblast migration in vivo"},{"PMID":"21600986","why":"Robo-dependent Slit growth effects in neurons"}],"covers":["LR001984","LR005313"]},"LR003315":{"pair":"SLIT3 -> ROBO3","headline":"SLIT3 directly associates with ROBO3 in ELISA and, in chicken granulosa cells, interacts physically with all four ROBOs.","interaction_type":"direct binding","direction_and_effect":"SLIT3 directly associated with ROBO1 and ROBO3, and siRNA knockdown of both blocked SLIT3 suppression of preosteoclast migration and osteoclastogenesis [PMID:29504949]. SLIT3 was reported to interact physically with the four ROBO receptors in chicken granulosa cells [PMID:30288875].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding ELISA and siRNA in osteoclast-lineage cells [PMID:29504949]; chicken granulosa cells [PMID:30288875]. Human pair is ortholog-inferred.","localisation_and_range":"SLIT3 flagged secreted, ROBO3 transmembrane [flag]; SLIT3 acts in an autocrine/paracrine fashion [PMID:30288875].","caveats":"ROBO1 and ROBO3 are reported together. The chicken paper is abstract only and the method for physical interaction is not described in it; ROBO1/2 expression was more regulated by SLIT3 than ROBO3/4 [PMID:30288875]. Four abstracts insufficient.","key_references":[{"PMID":"29504949","why":"ELISA binding and knockdown for ROBO1/ROBO3"},{"PMID":"30288875","why":"Physical interaction with four ROBOs, chicken"}],"covers":["LR003315","LR006529"]},"LR005322":{"pair":"SLITRK3 -> PTPRS","headline":"SLITRK3-PTPsigma rests on one family-level cell aggregation assay.","interaction_type":"functional only","direction_and_effect":"Slitrk3-expressing cells aggregated with PTPsigma-expressing cells [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cells [PMID:23345436]. Both pairs ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; SLITRK3 flagged transmembrane [flag].","caveats":"Single paper, browser-read with spot-check pending; direct binding not shown, no affinity.","key_references":[{"PMID":"23345436","why":"Slitrk3 and PTPsigma aggregation"}],"covers":["LR001993","LR005322"]},"LR003324":{"pair":"SMOC2 -> FZD6","headline":"One cancer-cell paper reports SMOC-2 co-immunoprecipitating with FZD6 and enhancing WNT signalling; support rests on a co-IP.","interaction_type":"direct binding","direction_and_effect":"By co-culture IP, SMOC-2 directly interacted with the WNT receptors Fzd6 and LRP6, enhanced ligand-receptor interaction with canonical WNT ligands (Wnt3a and Wnt10b) and activated the WNT/beta-catenin pathway in endometrial cancer [PMID:30594556]. This acts as a positive facilitator, not a classical WNT ligand, per the curator note.","molecular_requirements":"Fzd6 and LRP6 were both reported as interactors, so a FZD-LRP complex may be involved; whether FZD6 alone is sufficient is not reported [PMID:30594556].","affinity_potency":[],"species_and_systems":"Species: not stated for the co-culture IP in our excerpts; endometrial cancer cell lines (AN3CA, Ishikawa, HEC-1A, ECC-1) and mouse xenografts were used elsewhere in the paper [PMID:30594556]. The mouse pair is projected from human evidence.","localisation_and_range":"SMOC2 is flagged as secreted and as a receptor [flag]; FZD6 is flagged as a receptor [flag]. Paracrine or autocrine range is not tested in our evidence.","caveats":"Evidence is a co-culture IP in cancer cells; 'directly' is the authors' wording and affinity is not reported. The excerpts available to us are mostly general statements. Only one paper.","key_references":[{"PMID":"30594556","why":"Co-IP of SMOC-2 with Fzd6 and LRP6 and WNT pathway activation in endometrial cancer"}],"covers":["LR003324","LR006531"]},"LR005331":{"pair":"SPN -> SIGLEC1","headline":"CD43 is a T-cell counterreceptor for sialoadhesin (Siglec-1) from one abstract-level mouse paper.","interaction_type":"direct binding","direction_and_effect":"Sialoadhesin-Fc precipitated CD43 from murine T cells and CD43 expressed in COS cells supported increased binding to immobilised sialoadhesin [PMID:11238599]. CD43 is the counterreceptor; any signalling effect is not reported in our evidence.","molecular_requirements":"Binding was sialic acid dependent and abolished by the R97A mutation in sialoadhesin's membrane-distal Ig-like domain; both core-1 and core-2 O-linked CD43 glycoforms bound [PMID:11238599].","affinity_potency":[],"species_and_systems":"Mouse T cell line TK-1, COS and CHO cells [PMID:11238599]. IntAct solid phase assay record exists [DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Both are membrane proteins, suggesting cell-cell contact interaction [flag].","caveats":"Abstract only; no affinity. Binding relies on glycosylation.","key_references":[{"PMID":"11238599","why":"CD43 identified as sialoadhesin counterreceptor"}],"covers":["LR002003","LR005331"]},"LR004800":{"pair":"SPP1 -> ITGA4","headline":"Thrombin-cleaved osteopontin acts on alpha4beta1 and alpha9beta1 integrins in hemopoietic stem cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"The N-terminal thrombin cleavage fragment of OPN, through binding to alpha9beta1 and alpha4beta1, attracts and retains hemopoietic stem and progenitor cells; trOPN is a chemoattractant [PMID:19417209].","molecular_requirements":"The active form is thrombin-cleaved N-terminal OPN; alpha4 acts as the alpha4beta1 heterodimer [PMID:19417209]. Reactome lists an SPP1:Integrin alpha4beta1 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Murine and human HSCs studied; ligand and receptor species recorded as unspecified [PMID:19417209].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA4 secretion flag not given in our evidence.","caveats":"One paper, read as abstract; it does not separate alpha4 from alpha9 contributions, and the pair is for a cleaved fragment. Reactome citation is a different paper [DB:Reactome].","key_references":[{"PMID":"19417209","why":"Thrombin-cleaved OPN migration via alpha9beta1 and alpha4beta1"}],"covers":["LR001405","LR004800"]},"LR001407":{"pair":"SPP1 -> ITGA9","headline":"Osteopontin binds alpha9beta1 via a non-RGD SVVYGLR sequence exposed by thrombin cleavage; three abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"alpha9-transfected cells adhere to an N-terminal osteopontin fragment and the SVVYGLR sequence directly binds alpha9beta1 [PMID:10593924]. Thrombin-cleaved OPN binds alpha9beta1 and alpha4beta1 to attract hemopoietic stem and progenitor cells [PMID:19417209].","molecular_requirements":"The thrombin-cleaved N-terminal fragment is a much better ligand than full-length osteopontin; alpha9beta1 does not use RGD; an MMP-predicted fragment did not support adhesion [PMID:16005200][PMID:10593924].","affinity_potency":[],"species_and_systems":"Human cells and proteins in adhesion assays (SW480, CHO, L-cells transfected with alpha9) [PMID:10593924]; murine and human HSCs [PMID:19417209].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; cleavage-dependent.","caveats":"All three papers are abstract-only; the binding is to a cleaved fragment, not necessarily full SPP1. Two further papers were abstract_insufficient.","key_references":[{"PMID":"10593924","why":"SVVYGLR sequence binds alpha9beta1"},{"PMID":"16005200","why":"Thrombin cleavage potentiates alpha9beta1; RGD-independent"},{"PMID":"19417209","why":"Thrombin-cleaved OPN and HSC migration via alpha9beta1"}],"covers":["LR001407","LR004802"]},"LR003333":{"pair":"SRPX2 -> PLAUR","headline":"SRPX2 was pulled down as a uPAR ligand in endothelial cells; single abstract-level paper, no database records.","interaction_type":"direct binding","direction_and_effect":"Pulldown experiments identified Srpx2 as a ligand for vascular uPAR; Srpx2 silencing attenuates endothelial migration and delays sprout formation [PMID:19667118]. Activating effect on uPAR signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells; curators record human species, but the abstract does not state it [PMID:19667118].","localisation_and_range":"SRPX2 is flagged secreted [flag]; Srpx2 and uPAR are coexpressed on vascular endothelium [PMID:19667118].","caveats":"Single paper, abstract only; no database records. Pulldown shows association but not affinity or mechanism. The mouse pair is a separate entry; the human pair is ortholog-inferred.","key_references":[{"PMID":"19667118","why":"Pulldown identifies Srpx2 as uPAR ligand"}],"covers":["LR003333","LR006540"]},"LR001416":{"pair":"TAC1 -> TACR2","headline":"Neurokinin A (TAC1) binds and activates the NK2 receptor (TACR2); supported by binding papers in human and rat, but all read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"Agonist. NKA is described as the physiological peptide ligand of the NK2 receptor [PMID:7961636]; NKA(4-10) analogues act as agonists or partial agonists in human colon muscle [PMID:11137709]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence as a complex requirement. Mutagenesis of the human NK2 receptor identified Gln109, His198, Ile202 and Gly273 as critical for NKA binding [PMID:7961636]. In NKA(4-10), Asp4, Phe6, Val7, Leu9 and Met10 side chains matter for agonist activity [PMID:11137709].","affinity_potency":[{"value":"pKi 8.0-9.1","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human NK2 receptor mutants [PMID:7961636]; human colon circular muscle radioligand binding and contraction [PMID:11137709]; cultured rat anterior pituitary cells [PMID:12954451]. Structures of the complex are listed in PDB [DB:PDB 7XWO] [DB:PDB 9W1J]. The mouse pair is projected from human evidence.","localisation_and_range":"TAC1 is flagged secreted and TACR2 as a transmembrane receptor [flag], so signalling is expected to be paracrine or endocrine onto a membrane GPCR; this comes from annotation flags only.","caveats":"All papers were read as abstracts only. In rat pituitary cells NKA only fitted a two-site model with high and low affinity and the [3H]SR48968 binding had lower affinity than typical NK2-expressing cells [PMID:12954451]. Binding in that study used a labelled antagonist, not NKA itself. PMID 11786503 concerns hemokinin-1, with NKA only as tracer, and reports Ki=560 nM for hemokinin-1 at human NK2, not for NKA.","key_references":[{"PMID":"7961636","why":"Mutagenesis mapping of NKA binding residues in human NK2 receptor"},{"PMID":"11137709","why":"NKA(4-10) binding and function in human colon"},{"PMID":"12954451","why":"NKA displaces antagonist binding in rat pituitary cells"}],"covers":["LR001416","LR004811"]},"LR003351":{"pair":"TAFA3 -> NRXN1","headline":"TAFA3 (FAM19A3) binds neurexins, including NRXN1; one paper, mainly recombinant HEK293T work.","interaction_type":"direct binding","direction_and_effect":"FAM19A3 was tested as a homologue of FAM19A1/A2 and, with FAM19A1-A4, bound all neurexin isoforms and splice variants tested in HEK293T surface-exposure assays [PMID:32706374]. Effect on neurexin function is reported only for FAM19A1 [PMID:32706374].","molecular_requirements":"FAM19A1-A4 bind the cysteine-loop domain of neurexins by forming intermolecular disulfide bonds; both the cysteines and an adjacent neurexin sequence were required [PMID:32706374]. FAM19A5 does not bind [PMID:32706374].","affinity_potency":[],"species_and_systems":"Recombinant FAM19A3 (V5-tagged) with Nrxn1\u03b2-ECD in HEK293T cells [PMID:32706374]. Human pair projected from mouse evidence.","localisation_and_range":"TAFA3 annotated secreted; NRXN1 annotated transmembrane [flag].","caveats":"Supported by one paper read as an abstract plus full-text excerpts; the abstract states that neurexin-1\u03b3 is the exception [PMID:32706374]. Binding is covalent and forms during transit through the secretory pathway, which is unusual for a ligand-receptor pair. Excerpts for FAM19A3 specifically are brief.","key_references":[{"PMID":"32706374","why":"FAM19A1-A4, including FAM19A3, bind neurexins"}],"covers":["LR003351","LR006554"]},"LR001434":{"pair":"TF -> TFRC","headline":"Well-supported direct ligand-receptor pair: transferrin binds the dimeric transferrin receptor, with structures and several papers.","interaction_type":"direct binding","direction_and_effect":"Fe-Tf binds TfR directly, competing with HFE at overlapping sites on each receptor chain, though HFE and Fe-Tf can bind simultaneously to form a ternary complex [PMID:15056661]. Ferritransferrin, not apo-transferrin, decreases shedding of soluble TfR in CHO cells transfected with human TfR, consistent with a direct interaction [PMID:16354665].","molecular_requirements":"The solubilized human placental receptor is a dimer able to bind two transferrin molecules [PMID:6268632]. Binding is per receptor chain [PMID:15056661]. Reactome lists holoTF:TFRC dimer complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human placental trophoblast receptor [PMID:6268632]; MOLT-4 human T-cell line with OKT9 co-precipitation [PMID:6270680]; soluble heterodimeric TfR constructs and transfected cells [PMID:15056661]; CHO cells with human TfR [PMID:16354665]. Structures in PDB (1SUV, 3S9L, 3S9M) [DB:PDB 1SUV].","localisation_and_range":"TF is annotated secreted and TFRC as a transmembrane receptor [flag]; binding at the plasma membrane and endosome membrane is described in Reactome [DB:Reactome].","caveats":"All four papers were read as abstracts only. No affinity value is in our evidence. The 1981 papers characterize the receptor biophysically or by co-precipitation, not a quantified affinity. IntAct lists SPR and crystallography records [DB:IntAct].","key_references":[{"PMID":"15056661","why":"Fe-Tf and HFE compete for TfR chains"},{"PMID":"6268632","why":"Receptor dimer binds two transferrin molecules"},{"PMID":"16354665","why":"Ferritransferrin binding regulates TfR shedding"}],"covers":["LR001434"]},"LR001461":{"pair":"TG -> LRP2","headline":"Purified rat megalin (LRP2) binds rat thyroglobulin in solid-phase assays with Kd 9.2 nM.","interaction_type":"direct binding","direction_and_effect":"Megalin binds thyroglobulin; the authors propose it may participate in thyroglobulin endocytosis from the colloid [PMID:9492085].","molecular_requirements":"Binding was calcium dependent and almost completely inhibited by excess Tg, lactoferrin, lipoprotein lipase, apolipoprotein J and RAP; megalin bound both monomeric (330 kD) and dimeric (660 kD) Tg [PMID:9492085].","affinity_potency":[{"value":"Kd 9.2 nM","assay":"solid-phase binding, estimated Kd +/- 0.6 nM","system":"purified rat megalin and rat thyroglobulin","cite":"PMID:9492085"}],"species_and_systems":"Rat proteins in vitro; human and mouse pairs are both ortholog-inferred [PMID:9492085].","localisation_and_range":"TG is annotated secreted [flag]; megalin is described as acting on absorptive epithelial cells including thyroid [PMID:9492085].","caveats":"Abstract only. Three anti-megalin antibodies only partially inhibited binding. Rat data; endocytic function is proposed, not shown.","key_references":[{"PMID":"9492085","why":"Megalin binds thyroglobulin, Kd 9.2 nM"}],"covers":["LR001461","LR004856"]},"LR001443":{"pair":"TGFB1 -> TGFBR1","headline":"Established type I TGF-beta receptor; binding needs TGFBR2, and structure and expression data support it.","interaction_type":"direct binding","direction_and_effect":"Tsk 7L (ALK5) is a type I receptor for TGF-beta [PMID:8235612]. GtoPdb lists agonist [DB:GtoPdb]. A structure shows TGF-beta bound to betaglycan, TGFBR1 and TGFBR2 [PMID:40011426]. A tumour-fibroblast loop via TGFB1-TGFBR1 is reported [PMID:39095854].","molecular_requirements":"Requires coexpression of type II receptor (TGFBR2) for ligand binding [PMID:8235612]; ligand specificity conferred by the type II receptor [PMID:8235612]. Betaglycan hands off ligand to the receptors [PMID:40011426].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:8235612]; structures used TGF-beta3 variants and rat BG, with TGF-beta1 in a low-resolution cryo-EM map [PMID:40011426]; human HCC data [PMID:39095854].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptors are membrane-bound; colocalisation seen on tumour cell membranes [PMID:39095854].","caveats":"TGFBR1 alone does not bind ligand [PMID:8235612]; the structural paper mainly used TGF-beta3 and TGF-beta2. PMID:39095854 is single-cell/spatial inference with limited direct testing. One review-only paper and one different-entity paper excluded. Affinity values not given in the dossier.","key_references":[{"PMID":"8235612","why":"TGFBR1 needs type II receptor for TGF-beta binding"},{"PMID":"40011426","why":"Structure of TGF-beta with betaglycan, TGFBR1, TGFBR2"}],"covers":["LR001443","LR004838"]},"LR001452":{"pair":"TGFB3 -> TGFBR2","headline":"Directly bound by TGFBR2: a crystal structure and SPR kinetics, plus database records; TGF-beta3 is the ligand.","interaction_type":"direct binding","direction_and_effect":"TGF-beta initiates receptor assembly by binding with high affinity to the type II receptor [PMID:11850637]. GtoPdb lists the interaction as agonist [DB:GtoPdb].","molecular_requirements":"The 2.15 A structure shows the human TGFBR2 ectodomain binding both ends of homodimeric TGF-beta3 [PMID:11850637]. One dimeric ligand binds two receptors [PMID:12729750]. The type I receptor is recruited afterwards [PMID:11850637].","affinity_potency":[{"value":"Kd approximately 5pM (TGF-beta1 and -beta3)","assay":"SPR (BIACORE), immobilised type II receptor ectodomain; avidity contributes","system":"purified proteins, species unspecified","cite":"PMID:12729750"}],"species_and_systems":"Crystal structure used human proteins [PMID:11850637]. SPR papers do not state species [PMID:12729750][PMID:11382746]. The mouse pair is projected from human.","localisation_and_range":"The ligand is flagged secreted [flag]; it is also flagged transmembrane [flag]. Range is not discussed in our evidence.","caveats":"All three papers were read as abstracts only. The stated affinity is an avidity-enhanced apparent value.","key_references":[{"PMID":"11850637","why":"Crystal structure of the TGFBR2 ectodomain with TGF-beta3"},{"PMID":"12729750","why":"SPR kinetics, stoichiometry and affinity"},{"PMID":"11382746","why":"SPR kinetics of TGF-beta isoforms with type II ectodomain"}],"covers":["LR001452","LR004847"]},"LR001470":{"pair":"THBS1 -> LRP1","headline":"THBS1 binds LRP1 with high affinity; LRP1 acts as an endocytic clearance receptor, well supported by three binding papers.","interaction_type":"direct binding","direction_and_effect":"LRP1 mediates uptake and lysosomal degradation of THBS1; anti-LRP antibodies blocked 125I-TSP1 uptake in smooth muscle cells and fibroblasts but not endothelial cells [PMID:7775583]. This is clearance rather than signalling.","molecular_requirements":"The amino-terminal heparin-binding domain (residues 1-214) binds LRP [PMID:9045712]; a 1-90 fragment keeps high-affinity LRP-1 binding without heparin binding [PMID:14991768]. Binding does not need heparan sulfate proteoglycans, but endocytosis does [PMID:14991768]. Cell-surface proteoglycans are involved in clearance [PMID:7775583].","affinity_potency":[{"value":"Kd 5 nM","assay":"solid-phase binding","system":"LRP with TSP1","cite":"PMID:7775583"},{"value":"KD 10 to 25 nM","assay":"binding of GST-HBD (dimer) to purified LRP","system":"mouse TSP-1 residues 1-214","cite":"PMID:9045712"},{"value":"KD 830 nM","assay":"binding of monomeric rHBD to purified LRP","system":"mouse TSP-1 HBD","cite":"PMID:9045712"}],"species_and_systems":"Human and mouse cells and proteins (curated species human; the mouse pair is ortholog-inferred); smooth muscle cells, endothelial cells, fibroblasts, purified LRP [PMID:7775583, PMID:9045712].","localisation_and_range":"THBS1 is flagged secreted [flag]; ECM-associated protein that binds cell-surface proteoglycans before internalisation [PMID:7775583].","caveats":"Endothelial-cell uptake of TSP1 was not LRP-mediated [PMID:7775583]. Affinity depends on oligomeric state (dimeric vs monomeric HBD) [PMID:9045712]. All abstract-level except partial full text for PMID:7775583. BioGRID reconstituted-complex records agree [DB:BioGRID].","key_references":[{"PMID":"7775583","why":"Identifies LRP as endocytic THBS1 receptor, Kd 5 nM"},{"PMID":"9045712","why":"Maps binding to the N-terminal heparin-binding domain"},{"PMID":"14991768","why":"Binding separable from HSPG-dependent endocytosis"}],"covers":["LR001470","LR004865"]},"LR002019":{"pair":"THBS1 -> PTPRJ","headline":"THBS1 binds the CD148 (PTPRJ) ectodomain and raises its phosphatase activity, inhibiting endothelial growth; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Soluble THBS1 binds the extracellular part of CD148 with high affinity and specificity, and binding increases CD148 catalytic activity, causing substrate dephosphorylation [PMID:22308318]. CD148 mediates THBS1-induced growth inhibition, which soluble CD148 ectodomain or gene silencing antagonises [PMID:22308318]. The curated effect_direction label is antagonist, but the text describes activation of CD148 activity.","molecular_requirements":"Introduction of CD148 conferred THBS1 growth inhibition on cells lacking it [PMID:22308318]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD148 and THBS1; HA-tagged CD148 expressed in cultured endothelial cells, identified by mass spectrometry [PMID:22308318].","localisation_and_range":"THBS1 is flagged secreted [flag]; soluble THBS1 acts on the cell-surface receptor [PMID:22308318].","caveats":"One paper, read as an abstract only; numeric affinity not given in the abstract. No database records.","key_references":[{"PMID":"22308318","why":"THBS1 identified as CD148 ligand that activates its phosphatase"}],"covers":["LR002019","LR005347"]},"LR006600":{"pair":"THY1 -> SDC4","headline":"Thy-1 binds syndecan-4 at single-molecule level and cooperates with alpha5beta1; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Thy-1 independently binds syndecan-4; with alpha5beta1 present they bind cooperatively, forming a trimolecular complex showing 'dynamic catch' [PMID:25216363].","molecular_requirements":"Syndecan-4 alone suffices for binding, but alpha5beta1 and Syn4 together bind cooperatively [PMID:25216363].","affinity_potency":[],"species_and_systems":"Single-molecule force spectroscopy; melanoma cells; human [PMID:25216363].","localisation_and_range":"Membrane-bound; contact-dependent.","caveats":"Abstract only; no affinity values; mouse pair is ortholog-inferred.","key_references":[{"PMID":"25216363","why":"Thy-1 binds Syn4 and alpha5beta1"}],"covers":["LR003399","LR006600"]},"LR003405":{"pair":"TIMP3 -> ITGA7","headline":"ITGA7 binds TIMP3 in prostate cancer cells with growth-suppressing signalling; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"ITGA7 bound TIMP3 in prostate cancer cells, lowering TNF-alpha, causing cytoplasmic NF-kappaB translocation and cyclin D1 down-regulation, with G0/G1 accumulation and growth suppression; TIMP3 knockdown or interfering with ITGA7/TIMP3 binding largely abrogated this, and a mutant ITGA7 lacking TIMP3 binding had no tumour-suppressor activity [PMID:23830872].","molecular_requirements":"Knocking down laminin beta1 (ITGA7's canonical ligand) enhanced ITGA7-TIMP3 signalling [PMID:23830872]. Partner integrin beta chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human prostate cancer cells [PMID:23830872]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 is flagged secreted; ITGA7 flagged receptor [flag].","caveats":"Single abstract-read paper; no affinity reported.","key_references":[{"PMID":"23830872","why":"ITGA7-TIMP3 binding and tumour-suppressive signalling"}],"covers":["LR003405","LR006606"]},"LR003414":{"pair":"TNFRSF1B -> IL17RD","headline":"TNFR2 forms a signalling heteromer with IL-17RD in one abstract-level paper; receptor-receptor, not a classic ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"TNFR2 but not TNFR1 forms a heteromer with IL-17RD (Sef). The association causes mutual receptor aggregation and TRAF2 recruitment and activates NF-kappaB; IL-17RD depletion impaired TNFR2-mediated NF-kappaB activation [PMID:25378394].","molecular_requirements":"TNFR1 does not form this heteromer [PMID:25378394]. TRAF2 recruitment is part of the signalling cascade [PMID:25378394].","affinity_potency":[],"species_and_systems":"Human proteins as recorded; the abstract also reports increased IL-17RD and a strong TNFR2-IL-17RD interaction in renal epithelia of nephritis rats [PMID:25378394]. The mouse pair is projected from human evidence.","localisation_and_range":"TNFR2 is flagged secreted and transmembrane [flag]; IL-17RD has no localisation flag in the dossier.","caveats":"Single paper, read as an abstract only; no database records. The abstract does not name a binding assay, and which partner acts as ligand is not reported in our evidence [PMID:25378394].","key_references":[{"PMID":"25378394","why":"TNFR2-IL-17RD heteromer and NF-kappaB activation"}],"covers":["LR003414","LR006615"]},"LR001506":{"pair":"TNFSF14 -> LTBR","headline":"LIGHT binds LTBR; one abstract-only mutagenesis paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Point mutations in LIGHT altered binding to LTbetaR and HveA; a HveA-selective mutant was inactive for cell death, isolating the LTbetaR-dependent pathway, with TRAF3 recruitment [PMID:10799510].","molecular_requirements":"LTBR also binds the heterotrimeric lymphotoxin; Reactome lists a 3xLTBR:lymphotoxin,TNFSF14 trimer complex [DB:Reactome][DB:UniProt].","affinity_potency":[],"species_and_systems":"Reconstituted complex in BioGRID [DB:BioGRID]; species of the paper not stated in our evidence beyond human annotation; mouse pair is orthology-projected.","localisation_and_range":"LIGHT flagged secreted and transmembrane; LTBR transmembrane [flag].","caveats":"Abstract only; two other papers abstract_insufficient. Also IntAct yeast display [DB:IntAct] and GtoPdb [DB:GtoPdb].","key_references":[{"PMID":"10799510","why":"LIGHT residues mapped for LTbetaR binding"}],"covers":["LR001506","LR004896"]},"LR001515":{"pair":"TRH -> TRHR","headline":"TRH activates the TRH receptor in expression cloning, COS-1, and HEK293 assays; multiple papers, a classic agonist GPCR pair.","interaction_type":"direct binding","direction_and_effect":"Agonist: TRH stimulated inositol phosphate formation in COS-1 cells expressing the cloned receptor [PMID:2175902]; in HEK293 cells TRHR-Timer gave an 11-fold increase in inositol phosphate formation, increased intracellular free calcium and internalization of 75% of bound [3H][N3-methyl-His2]TRH within 10 min [PMID:15117874]. The TRH-TRHR complex and G11alpha both internalise in clathrin-coated vesicles [PMID:9794253].","molecular_requirements":"Single GPCR; couples to Gq/11, with G11alpha co-internalised [PMID:9794253].","affinity_potency":[],"species_and_systems":"Mouse pituitary receptor cDNA in Xenopus oocytes and COS-1 cells [PMID:2175902]; HEK293 cells [PMID:15117874]; cell system for the third paper not stated in the abstract. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"TRH flagged secreted and not transmembrane; TRHR transmembrane [flag]; secreted peptide acting on a cell surface receptor.","caveats":"All three papers were read as abstracts. The oocyte paper reports 'appropriate affinities' without a value [PMID:2175902]. Two papers concern receptor trafficking rather than binding.","key_references":[{"PMID":"2175902","why":"Expression cloning of the mouse TRH receptor"},{"PMID":"15117874","why":"TRH-induced inositol phosphate, calcium and internalisation in HEK293"},{"PMID":"9794253","why":"Co-internalisation of TRH-TRHR and G11alpha"}],"covers":["LR001515","LR004905"]},"LR003423":{"pair":"TSKU -> FZD4","headline":"Tsukushi binds the cysteine-rich domain of Fzd4 with 2.3 x 10-10 M and competes with Wnt2b; well supported inhibitor.","interaction_type":"direct binding","direction_and_effect":"Antagonist/Wnt inhibitor: TSK binds directly to the cysteine-rich domain of Fzd4 and competes with Wnt2b; TSK overexpression antagonized Wnt2b signaling in chicken embryonic retinal cells and repressed Wnt-dependent peripheral eye fates; TSK knockout mice had ciliary body expansion and up-regulated Wnt2b and Fzd4 [PMID:21856951]. UniProt agrees [DB:UniProt].","molecular_requirements":"Fzd4 cysteine-rich domain is the binding site [PMID:21856951]; LRP5/6 requirement not reported in our evidence.","affinity_potency":[{"value":"2.3 x 10-10 M","assay":"direct binding to Fzd4 cysteine-rich domain","system":"not specified in abstract","cite":"PMID:21856951"}],"species_and_systems":"Chick eye in vivo and in vitro, mouse knockout [PMID:21856951]. Human pair is ortholog-inferred.","localisation_and_range":"Secreted protein expressed in the ciliary/iris epithelium acting on the adjacent optic vesicle rim, so short-range paracrine [PMID:21856951].","caveats":"Abstract read only; assay system for the Kd is not specified.","key_references":[{"PMID":"21856951","why":"TSK-Fzd4 binding and Wnt2b competition in eye development"}],"covers":["LR003423","LR006624"]},"LR008211":{"pair":"TSPAN1 -> ITGA6:ITGB1","headline":"Midkine facilitates TSPAN1 association with integrin alpha6beta1 in HNSCC cells; a receptor-receptor, midkine-dependent association.","interaction_type":"functional only","direction_and_effect":"Midkine interacted with TSPAN1 and facilitated TSPAN1 association with alpha6beta1 integrin in head and neck squamous cell carcinoma cells, driving FAK tyrosine phosphorylation, paxillin and Stat1alpha activation and MMP-2/MMP-26 expression [PMID:18851943].","molecular_requirements":"Requires midkine (MK) as a third partner; ITGA6 and ITGB1 together form the integrin [PMID:18851943].","affinity_potency":[],"species_and_systems":"HNSCC cell lines; RNAi of signalling intermediates reduced migration and invasiveness [PMID:18851943].","localisation_and_range":"TSPAN1 is flagged receptor, with no secretion flag [flag]; membrane association implied.","caveats":"Not a ligand-receptor pair: TSPAN1 is a tetraspanin, interaction class is Receptor-Receptor, and association depends on midkine. Abstract read only; binding affinity not reported in our evidence.","key_references":[{"PMID":"18851943","why":"Midkine-facilitated TSPAN1-alpha6beta1 association in HNSCC"}],"covers":["LR008211"]},"LR011190":{"pair":"UBC -> ADRB2","headline":"Database-asserted only: one IntAct co-immunoprecipitation record; ubiquitin is a modifier, not a ligand.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct: anti-tag coimmunoprecipitation (PMID 19424180) [DB:IntAct].","localisation_and_range":"Entity flags give no localisation [flag].","caveats":"No papers confirmed; three judged rows were different_entity. The dossier does not show ligand-like signalling.","key_references":[],"covers":["LR011190"]},"LR002028":{"pair":"ULBP1 -> KLRK1","headline":"ULBP1 engages the NKG2D receptor on NK cells; one full-text functional paper plus database records, no affinity data.","interaction_type":"functional only","direction_and_effect":"Agonist, activating: ULBPs stimulate cytokine and chemokine production from NK cells and make NK-resistant target cells susceptible to NK cytotoxicity [PMID:11239445].","molecular_requirements":"NKG2D (KLRK1) is an essential component of the ULBP receptor complex: anti-NKG2D antiserum blocked ULBP1-Fc binding to human NKL cells [PMID:11239445]. Whether DAP10 is also needed is not reported in our evidence for this receptor row.","affinity_potency":[],"species_and_systems":"Human proteins and human NKL cells, using Fc fusion proteins [PMID:11239445]. IntAct lists a surface plasmon resonance record [DB:IntAct] [PMID:28559451]; UniProt notes interaction with KLRK1/NKG2D [DB:UniProt] [PMID:11777960].","localisation_and_range":"Ligand is membrane-bound [flag]; the paper describes ULBPs as GPI-linked glycoproteins [PMID:11239445], so signalling is by cell contact.","caveats":"Blocking evidence was shown with ULBP1-Fc, with the paper's text extending it to all ULBP/MIC-Fc fusions per the curator. Binding affinity is not reported in our evidence. Only one paper supports this pair [PMID:11239445]; it is functional in vitro (human NKL cells), read in full text. Database records add physical-interaction support only.","key_references":[{"PMID":"11239445","why":"ULBPs bind NKG2D on NK cells and stimulate cytotoxicity"}],"covers":["LR002028"]},"LR001524":{"pair":"ULBP2 -> KLRK1","headline":"ULBP2 engages the NKG2D receptor on NK cells; one full-text functional paper plus database records, no affinity data.","interaction_type":"functional only","direction_and_effect":"Agonist, activating: ULBPs stimulate cytokine and chemokine production from NK cells and make NK-resistant target cells susceptible to NK cytotoxicity [PMID:11239445].","molecular_requirements":"NKG2D (KLRK1) is an essential component of the ULBP receptor complex: anti-NKG2D antiserum blocked ULBP1-Fc binding to human NKL cells [PMID:11239445]. Whether DAP10 is also needed is not reported in our evidence for this receptor row.","affinity_potency":[],"species_and_systems":"Human proteins and human NKL cells, using Fc fusion proteins [PMID:11239445]. IntAct lists FACS and surface plasmon resonance records [DB:IntAct] [PMID:19424970] [PMID:28559451]; UniProt notes interaction with KLRK1/NKG2D [DB:UniProt] [PMID:11777960].","localisation_and_range":"Annotation flags mark the ligand as both secreted and transmembrane [flag]; the paper describes ULBPs as GPI-linked glycoproteins [PMID:11239445].","caveats":"Blocking evidence was shown with ULBP1-Fc, with the paper's text extending it to all ULBP/MIC-Fc fusions per the curator. Binding affinity is not reported in our evidence. Only one paper supports this pair [PMID:11239445]; it is functional in vitro (human NKL cells), read in full text. Database records add physical-interaction support only.","key_references":[{"PMID":"11239445","why":"ULBPs bind NKG2D on NK cells and stimulate cytotoxicity"}],"covers":["LR001524"]},"LR003441":{"pair":"UNC5D -> FLRT3","headline":"Extracellular binding of UNC5D and FLRT3 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5D is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5D stripes repelled 12% of neurons (n=49/407) [PMID:26633812]. UniProt records the extracellular-domain interaction [DB:UniProt]. The 2011 EMBO J abstract in the sibling dossier describes Unc5D as binding specifically to FLRT2, which sits in some tension with this pair.","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003441","LR006642"]},"LR001533":{"pair":"VCAN -> CD44","headline":"Versican binds CD44 through its chondroitin sulfate chains in solid-phase assays; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Human ACHN-derived versican binds CD44, mediated by its chondroitin sulfate chain [PMID:10950950]. Direction or signalling effect not reported in our evidence.","molecular_requirements":"CS chain of versican engages CD44; CD44 binding was inhibited by hyaluronic acid and several chondroitin sulfates but not heparan sulfate [PMID:10950950]. Cross-blocking shows CD44 recognises a site separate from selectins [PMID:10950950].","affinity_potency":[],"species_and_systems":"Human versican from a renal adenocarcinoma line, soluble CD44, solid-phase [PMID:10950950]. Mouse pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted; CD44 flagged secreted, receptor and transmembrane [flag].","caveats":"Glycan-mediated binding, not protein-protein. Single abstract-level paper. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10950950","why":"versican CS chains bind CD44, L- and P-selectin"}],"covers":["LR001533","LR004922"]},"LR008400":{"pair":"VCAN -> SELL","headline":"Versican binds L-selectin via its chondroitin sulfate chain; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Human ACHN-derived versican binds L-selectin through its CS chain and the selectin carbohydrate-binding domain [PMID:10950950].","molecular_requirements":"Binding inhibited by CS B, CS E and heparan sulfate but not other GAGs tested; L- and P-selectin recognise close or overlapping versican sites [PMID:10950950].","affinity_potency":[],"species_and_systems":"Human versican with soluble selectin, solid-phase [PMID:10950950].","localisation_and_range":"Versican flagged secreted; SELL flagged transmembrane receptor [flag].","caveats":"Glycan-mediated, not a protein epitope. One abstract-level paper; a review-only row exists. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10950950","why":"versican CS chain binds L-selectin"}],"covers":["LR008400"]},"LR001542":{"pair":"VEGFA -> NRP1","headline":"VEGFA, especially VEGF165, binds neuropilin-1 directly and NRP1 acts as a VEGFR2 coreceptor; well supported.","interaction_type":"direct binding","direction_and_effect":"NRP1 was identified as the isoform-specific VEGF165 receptor, binding VEGF165 but not VEGF121, and it enhances VEGF165 binding to KDR and chemotaxis [PMID:9529250]. VEGF binding to NRP1 is essential for endothelial migration, NRP1-VEGFR2 complex formation and FAK signalling [PMID:21653826]. VEGF189 also binds NRP1 and promotes neuronal responses [PMID:25519242].","molecular_requirements":"Binding localises to the intact b1b2 domain; neither b1 nor b2 alone binds, and heparin enhances binding [PMID:11986311]. NRP1 acts with VEGFR2; point mutants Y297A and D320A abolish VEGF binding [PMID:21653826]. NRP1 glycosaminoglycan modification changes VEGF responsiveness in ECs versus SMCs [PMID:16763549].","affinity_potency":[],"species_and_systems":"Mostly human cells and recombinant domains; mouse neurodevelopment for VEGF189 [PMID:25519242]; bovine endothelial cells for PGI2 [PMID:15637071]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGF is secreted and NRP1 a membrane receptor; heparin-binding isoforms are the NRP1 binders [PMID:11986311].","caveats":"Isoform dependent (VEGF121 fails to bind). No affinity values in our evidence. Several papers are abstract-only; PMID 15695515 uses VEGF165 binding only as a positive control.","key_references":[{"PMID":"9529250","why":"Identification of NRP1 as VEGF165 receptor"},{"PMID":"11986311","why":"Mapping of binding to NRP1 b1b2 domain"},{"PMID":"21653826","why":"NRP1 mutants lacking VEGF binding"}],"covers":["LR001542","LR004931"]},"LR004134":{"pair":"VEGFD -> ITGB1","headline":"VEGF-D binds alpha9beta1 integrin; ITGB1 credited only as a chain of the heterodimer from one paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-D bound purified alpha9beta1 integrin and adhesion/migration on VEGF-D was alpha9beta1-dependent [PMID:15590642].","molecular_requirements":"ITGB1 alone not tested; alpha9 chain (ITGA9) is needed by the evidence [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant protein plus cell assays; cells include mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells [PMID:15590642]. Interactions are ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Chain-only evidence; beta1 pairs with many alpha chains. Single abstract-read paper; no affinity.","key_references":[{"PMID":"15590642","why":"VEGF-D binds alpha9beta1 integrin"}],"covers":["LR000650","LR004134"]},"LR000651":{"pair":"VEGFD -> KDR","headline":"VEGF-D is a ligand for KDR (VEGFR-2) from one foundational abstract-level paper plus database records.","interaction_type":"direct binding","direction_and_effect":"VEGF-D is a ligand for VEGFR-2 and VEGFR-3 and can activate them; it does not bind VEGFR-1 [PMID:9435229]. Curators label it stimulatory agonist.","molecular_requirements":"No complex requirement in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor, abstract-level reading [PMID:9435229]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Single confirmed paper shown, read as abstract; no affinity. BioGRID reconstituted-complex record [DB:BioGRID] and Reactome [DB:Reactome]. Two review-only rows not shown.","key_references":[{"PMID":"9435229","why":"VEGF-D binds and activates VEGFR-2 and VEGFR-3"}],"covers":["LR000651","LR004135"]},"LR001551":{"pair":"VIM -> CD44","headline":"Direct binding reported between soluble CD44 and cell-surface vimentin in one human study; single paper, abstract-level curation but full text excerpts support it.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD44 hyaluronan-binding domain (CD44HABD) and a non-HA-binding triple mutant (CD443MUT) pulled down recombinant vimentin and bound vimentin's N-terminal head domain; binding is independent of hyaluronan [PMID:22216242]. Vimentin-knockout mouse lung endothelial cells did not internalise CD44HABD/CD443MUT, so vimentin is required for CD44 endocytosis there [PMID:22216242]. Net effect on signalling is not reported in our evidence.","molecular_requirements":"Vimentin N-terminal head domain binds CD44HABD [PMID:22216242]. Full-length CD44 standard isoform (Flag-tagged) co-immunoprecipitated vimentin-Myc in MCF-7 cells [PMID:22216242]. Stoichiometry in SPR was about 6 mol/mol [PMID:22216242].","affinity_potency":[{"value":"Kd 12-37 nM","assay":"SPR, CD443MUT binding vimentin in solution","system":"recombinant human proteins","cite":"PMID:22216242"},{"value":"Kd 74 nM","assay":"ITC / immobilised vimentin","system":"recombinant human proteins","cite":"PMID:22216242"}],"species_and_systems":"Human proteins (HUVEC, MCF-7 cells, recombinant); internalisation tested in lung endothelial cells from wild-type vs vimentin-null mice [PMID:22216242].","localisation_and_range":"CD44 is flagged secreted and transmembrane, vimentin is not flagged secreted [flag]. The paper describes soluble CD44 binding vimentin exposed on the endothelial cell surface [PMID:22216242]; range is therefore likely contact or paracrine, but this is the paper's framing, not a flag.","caveats":"Single paper. A minor fraction of vimentin co-precipitated with CD44 from HUVEC, and anti-vimentin IP did not detect CD44 [PMID:22216242]. Affinity measured with a mutant domain (CD443MUT), not full-length native CD44. The paper says the exact binding mode, and whether it overlaps the HA site, is not known [PMID:22216242]. Mouse pair is projected from human evidence.","key_references":[{"PMID":"22216242","why":"Only primary paper: direct binding, affinity and vimentin-dependent uptake"}],"covers":["LR001551","LR004940"]},"LR001560":{"pair":"VTN -> ITGAV","headline":"Vitronectin engages alphaV integrins, but specificity depends on the beta partner; several papers, mostly abstract-only.","interaction_type":"direct binding","direction_and_effect":"Purified alphaVbeta5 bound preferentially to vitronectin while alphaVbeta3 bound vitronectin, fibrinogen, von Willebrand factor and fibronectin [PMID:1694173]. In hESCs, integrin-blocking antibodies showed alphaVbeta5 mediates adhesion to vitronectin [PMID:18599809], and ITGAV knockdown disrupted vitronectin-promoted endoderm differentiation [PMID:23154389]. A VTN(381-397) fragment bound only alphaVbeta6 and prevented TGF-beta1 activation (antagonist) [PMID:33526813].","molecular_requirements":"The beta chain determines specificity: alphaVbeta5 binds vitronectin but alphaVbeta6 bound fibronectin and not vitronectin in FG-2 cell lysates [PMID:1532572]; in neuroblastoma extracts vitronectin binding was mediated by alphaVbeta3, not an alphaV-beta-n complex [PMID:1693626]. ITGAV alone is not shown to suffice.","affinity_potency":[{"value":"IC50 = 3.2 \u00b5M","assay":"competition with radiolabelled echistatin for VTN(381-397) peptide","system":"recombinant human alphaVbeta6","cite":"PMID:33526813"}],"species_and_systems":"Human ligands and receptors throughout: purified placental protein, tumour cell lysates, hESCs [PMID:1694173] [PMID:18599809] [PMID:23154389]. Mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Gene-level ITGAV row is only valid through specific heterodimers, not alphaVbeta6 for full vitronectin [PMID:1532572]. Most papers were read as abstract only. The antagonist effect at alphaVbeta6 is for a fragment, not full-length vitronectin [PMID:33526813]. hESC papers are functional, not binding [PMID:18599809] [PMID:23154389].","key_references":[{"PMID":"1694173","why":"Purified alphaVbeta5 as a vitronectin-selective receptor"},{"PMID":"33526813","why":"VTN fragment binds alphaVbeta6 (IC50 = 3.2 \u00b5M) and antagonises TGF-beta1 activation"},{"PMID":"23154389","why":"ITGAV knockdown impairs vitronectin-promoted endoderm differentiation in hESCs"}],"covers":["LR001560","LR004949"]},"LR003450":{"pair":"VWF -> CLEC4M","headline":"CLEC4M binds and internalises VWF; one abstract-only paper with cell binding and genetic data.","interaction_type":"direct binding","direction_and_effect":"CLEC4M-Fc bound VWF, and HEK 293 cells transfected with CLEC4M bound and internalised VWF; mice expressing CLEC4M after hydrodynamic liver transfer had a 46% decrease in plasma VWF [PMID:23529928]. It acts as a clearance receptor.","molecular_requirements":"The neck-region VNTR matters: cells with 4 or 9 copies showed reduced VWF interaction relative to 7 copies (4%-60% and 9%-45% reduction) [PMID:23529928].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 cells; mouse in vivo liver transfer; genotyping of 491 participants [PMID:23529928].","localisation_and_range":"VWF is flagged secreted; CLEC4M is flagged secreted, receptor and transmembrane [flag]. Acts on plasma VWF clearance [PMID:23529928].","caveats":"Abstract-only read. No affinity reported in our evidence.","key_references":[{"PMID":"23529928","why":"CLEC4M binds, internalises and clears VWF; VNTR modulates binding"}],"covers":["LR003450"]},"LR011244":{"pair":"WNT10A -> FZD7:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD7:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: abstract_insufficient 1.","key_references":[],"covers":["LR011244"]},"LR002037":{"pair":"WNT10B -> FZD7","headline":"One abstract identifies FZD7 as the cognate WNT10B receptor for trophoblast migration; functional, human cells.","interaction_type":"functional only","direction_and_effect":"WNT10B signalling stimulated cytoskeletal remodelling via Rac1, and FZD7 was identified as the cognate receptor for WNT10B to up-regulate cell migration; SFRP3 blocks the FZD7-WNT10B interaction and decreases BeWo migration [PMID:29979633].","molecular_requirements":"Not reported in our evidence; LRP co-receptor not discussed.","affinity_potency":[],"species_and_systems":"Human BeWo and JAR trophoblast cells [PMID:29979633]; mouse entry is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; decidual cells secrete the antagonist SFRP3 acting in a paracrine way in coculture [PMID:29979633].","caveats":"Abstract only; how FZD7 was identified (binding or knockdown) is not reported in our evidence.","key_references":[{"PMID":"29979633","why":"FZD7 as cognate WNT10B receptor; SFRP3 blocks it"}],"covers":["LR002037","LR005363"]},"LR007500":{"pair":"WNT11 -> FZD7:LRP6","headline":"WNT11 to FZD7:LRP6 is inferred from a FZD7-only paper; the co-receptor was not tested.","interaction_type":"functional only","direction_and_effect":"A colorectal cancer paper reports Wnt11 directly interacts with FZD7 to activate PCP/ROCK signalling [PMID:42760160].","molecular_requirements":"Evidence concerns FZD7 alone; the contribution of LRP6 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human colorectal cancer cells, abstract read only [PMID:42760160].","localisation_and_range":"Ligand is flagged secreted [flag]; Reactome lists a generic WNT:FZD plasma-membrane complex [DB:Reactome].","caveats":"The LRP6 chain is unsupported; complex scoring would rely on FZD7 evidence only. One review-only and two abstract_insufficient rows.","key_references":[{"PMID":"42760160","why":"Wnt11-FZD7 interaction in CRC (FZD7 only)"}],"covers":["LR007500"]},"LR008040":{"pair":"WNT2 -> FZD1:LRP6","headline":"WNT2 to FZD1:LRP6 rests on a FZD1-only reporter paper and UniProt; LRP6 was not tested.","interaction_type":"functional only","direction_and_effect":"Human Fzd1 enhanced TCF signalling with Wnt-2 to a lesser extent than with Wnt-3a, -3 and -1 [PMID:10557084]; UniProt agrees [DB:UniProt].","molecular_requirements":"LRP6 contribution is not reported in our evidence.","affinity_potency":[],"species_and_systems":"TCF reporter assay; abstract only [PMID:10557084].","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"Four other rows are review-only. No binding data for Wnt2.","key_references":[{"PMID":"10557084","why":"Weak Wnt-2 cooperation with Hfz1 in TCF reporter"}],"covers":["LR008040"]},"LR011271":{"pair":"WNT2B -> FZD7:LRP5","headline":"Supported only through the FZD7 subunit; LRP5 not tested.","interaction_type":"direct binding","direction_and_effect":"Fzd7 binds Wnt2b by co-immunoprecipitation of epitope-tagged proteins in HEK293T cells, extending an earlier Wnt3 finding [PMID:25892522]. Conditional Fzd7 deletion causes intestinal stem cell loss in vivo [PMID:25892522].","molecular_requirements":"Evidence covers FZD7 only; LRP5 is not reported in the excerpts [PMID:25892522].","affinity_potency":[],"species_and_systems":"HEK293T co-IP and mouse knockouts [PMID:25892522].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Complex is inferred from the FZD7 result; no data on LRP5 [PMID:25892522].","key_references":[{"PMID":"25892522","why":"Fzd7 binds Wnt2b"}],"covers":["LR011271"]},"LR008112":{"pair":"WNT3 -> FZD1:LRP5","headline":"Functional support only for the FZD1 subunit; LRP5 not tested.","interaction_type":"functional only","direction_and_effect":"FZD1, FZD2 and FZD7 specifically induce signalling after binding Wnt3 and Wnt3a [PMID:28733458]. UniProt lists WNT3 as an activator of FZD1 [DB:UniProt].","molecular_requirements":"Evidence covers FZD1 alone; LRP5 not reported [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human HEK293T CRISPR mutant cells [PMID:28733458].","localisation_and_range":"Not reported in our evidence.","caveats":"Assay class is recorded as direct_binding but the paper's quoted result is a signalling readout; binding was not directly measured in the excerpts.","key_references":[{"PMID":"28733458","why":"FZD1/2/7 respond to Wnt3 and Wnt3a"}],"covers":["LR008112"]},"LR003504":{"pair":"WNT5A -> APP","headline":"Wnt5a binds APP's cysteine-rich domain in one paper (co-IP) and drives its lysosomal targeting; single-study support.","interaction_type":"direct binding","direction_and_effect":"Wnt5a binds APP and promotes APP targeting to lysosomal compartments, reducing full-length APP levels, the opposite of Wnt3a, which promotes recycling and stability [PMID:34515635].","molecular_requirements":"The conserved extracellular cysteine-rich domain (CRD) of APP is required for Wnt binding; deleting it abrogates the effects [PMID:34515635]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-IP of Wnt5a-myc with human APP-flag and mouse APP-flag, with reciprocal co-IP, in transfected cells; trafficking and Bafilomycin-A rescue in mouse embryonic primary cortical neurons [PMID:34515635]. Fly APPL also binds Wnt5 in the same paper.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation. APP is annotated as transmembrane and secreted [flag].","caveats":"Only one paper supports this pair, and the curator read it as abstract only, though full-text excerpts were available. No affinity is reported. The binding experiments are co-IP of tagged, overexpressed proteins.","key_references":[{"PMID":"34515635","why":"Co-IP shows Wnt5a binds APP via its CRD; opposite trafficking outcome to Wnt3a"}],"covers":["LR003504","LR006704"]},"LR001605":{"pair":"WNT5A -> FZD6","headline":"WNT-5A acts on FZD6 in a FRAP mobility assay and in human genetics; evidence is functional, with no direct binding data.","interaction_type":"functional only","direction_and_effect":"WNT-5A increased the mobile fraction of FZD6-GFP in HEK293 cells in a pertussis-toxin- and NEM-sensitive way, consistent with Gi/o coupling [PMID:24873871]. Human fibroblasts with an FZD6 nonsense mutation responded aberrantly to WNT-5A [PMID:21665003]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Gi/o G-protein coupling was needed for the receptor mobility effect [PMID:24873871]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse reagents in HEK293 cells for FRAP [PMID:24873871]; human fibroblasts and Fzd6-/- mice [PMID:21665003]. The dossier includes a human pair and an ortholog-inferred mouse pair.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The assay class of direct_binding for PMID 24873871 is not supported: the evidence sentence is a background statement that WNT-5A is known to functionally interact with FZD6, while the paper's own result is a mobility effect. PMID 21665003 was read as abstract only.","key_references":[{"PMID":"24873871","why":"FRAP shows WNT-5A changes FZD6 mobility via Gi/o"},{"PMID":"21665003","why":"FZD6 mutation alters fibroblast response to WNT-5A"}],"covers":["LR001605","LR004994"]},"LR002046":{"pair":"WNT5B -> FZD2","headline":"WNT5B binds the FZD2 CRD weakly in vitro, but FZD2 mediates WNT-5B-induced CXCL8 in human lung fibroblasts.","interaction_type":"direct binding","direction_and_effect":"Stimulatory: WNT-5B-induced CXCL8 release was mediated primarily via Frizzled-2 and TAK1, independent of canonical beta-catenin signalling [PMID:27036869].","molecular_requirements":"Only FZD2 and TAK1 are named; LRP co-receptor need not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc, weak binding","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Binding with mouse proteins [PMID:25605717]; function in human lung fibroblasts (MRC-5, COPD and control primary cells) with recombinant WNT-5B [PMID:27036869].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding is weak (KD > 40 nm) yet function is clear in fibroblasts, and the functional paper was curated from the abstract only [PMID:25605717, PMID:27036869].","key_references":[{"PMID":"25605717","why":"FZD2 CRD binding by WNT-5B"},{"PMID":"27036869","why":"FZD2-dependent WNT-5B signalling in human lung fibroblasts"}],"covers":["LR002046","LR005372"]},"LR003513":{"pair":"WNT5B -> FZD4","headline":"WNT5B binds the FZD4 CRD only weakly in a single BLI mapping study.","interaction_type":"direct binding","direction_and_effect":"Binding only: WNT-5B showed weak binding (KD > 40 nm) to FZD1/2/4 CRDs [PMID:25605717].","molecular_requirements":"CRD only; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read.","key_references":[{"PMID":"25605717","why":"BLI mapping of WNT-FZD CRD binding"}],"covers":["LR003513","LR006713"]},"LR008121":{"pair":"WNT7A -> FZD10:LRP5","headline":"Complex rests on a Wnt7a-Fzd10 co-IP; the LRP5 chain is not tested in the paper.","interaction_type":"direct binding","direction_and_effect":"Wnt7a coimmunoprecipitates with Fzd10 in Ishikawa cells [PMID:18567805]; Fzd10-mediated Wnt7a signalling was noncanonical and JNK-responsive [PMID:18567805].","molecular_requirements":"LRP5 is not mentioned in the evidence shown; the complex is inferred from the FZD10 result.","affinity_potency":[],"species_and_systems":"Human Ishikawa cells [PMID:18567805].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP5 is flagged transmembrane [flag].","caveats":"Abstract only; evidence concerns FZD10 alone, so it is chain-only support for this complex.","key_references":[{"PMID":"18567805","why":"Wnt7a co-IPs with Fzd10 in Ishikawa cells"}],"covers":["LR008121"]},"LR001614":{"pair":"WNT7A -> FZD5","headline":"Well supported: purified Wnt7a binds Fzd5 CRD in the nanomolar range, with functional data in rat PC12 cells.","interaction_type":"direct binding","direction_and_effect":"Purified Wnt7a binds the extracellular cysteine-rich domain of Fzd5 by ELISA, with a split-eGFP readout of pathway activation [PMID:18230341]. Wnt7a acts via a Frizzled-5.LRP6 complex in PC12 cells, antagonised by Dickkopf-1 and Dickkopf-3 [PMID:12857724]. A CRISPR rescue study found Wnt7a seems to bind FZD5 by TCF4 reporter activity [PMID:28733458].","molecular_requirements":"Fzd5 with LRP6 in PC12 cells [PMID:12857724].","affinity_potency":[{"value":"nanomolar range","assay":"ELISA protein-protein binding to Fzd5 CRD","system":"purified proteins","cite":"PMID:18230341"}],"species_and_systems":"Human proteins for binding; rat PC12 cells for function [PMID:12857724]; HEK cell reporters [PMID:28733458]. Mouse pair projected.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; UniProt lists WNT7A-FZD5 interaction [DB:UniProt].","caveats":"Two of three papers are abstract-only; the reporter evidence is indirect; one dossier row is pending.","key_references":[{"PMID":"18230341","why":"Wnt7a binds Fzd5 CRD, nanomolar"},{"PMID":"12857724","why":"Wnt7a acts via Fzd5.LRP6 in PC12"},{"PMID":"28733458","why":"Wnt-Fzd reporter map"}],"covers":["LR001614","LR005003"]},"LR003522":{"pair":"WNT7A -> FZD7","headline":"WNT7A C-terminal linker binds FZD7 in one abstract-only study.","interaction_type":"direct binding","direction_and_effect":"The linker region in WNT7A's C-terminus binds the FZD7 receptor but does not activate non-canonical signalling; the hairpin region does [PMID:36420144]. Both regions can activate canonical signalling [PMID:36420144].","molecular_requirements":"Binding maps to the WNT7A linker region; the hairpin drives non-canonical output [PMID:36420144].","affinity_potency":[],"species_and_systems":"Human proteins per curator row; myogenic cells [PMID:36420144]. Mouse pair projected.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; FZD7 is the receptor in skeletal muscle per the paper background [PMID:36420144].","caveats":"Abstract only; the binding is of a WNT7A fragment, not full-length. Two other abstracts were insufficient.","key_references":[{"PMID":"36420144","why":"WNT7A linker binds FZD7"}],"covers":["LR003522","LR006722"]},"LR005007":{"pair":"WNT7B -> FZD10","headline":"WNT7B-FZD10: cell-surface binding in one abstract and a hedged knockdown result in another.","interaction_type":"direct binding","direction_and_effect":"Wnt7b bound Fzd10 on the cell surface and cooperatively activated canonical signalling with LRP5 [PMID:15923619]. Fzd10 knockdown reduced Wnt7b- and Wnt10a-induced Wnt/beta-catenin activation, which authors say implies they may be ligands [PMID:29844390].","molecular_requirements":"LRP5 is needed for cooperative canonical activation [PMID:15923619].","affinity_potency":[],"species_and_systems":"Human per curator fields; lung cells and bleomycin in vivo model in the second study, species not stated in the abstract [PMID:29844390].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Both abstract only. The second paper's evidence is inferential. Fzd10 is expressed in airway epithelium [PMID:15923619].","key_references":[{"PMID":"15923619","why":"Cell-surface binding of Wnt7b to Fzd10"},{"PMID":"29844390","why":"Fzd10 knockdown reduces Wnt7b-induced signalling"}],"covers":["LR001618","LR005007"]},"LR002055":{"pair":"WNT8A -> FZD8","headline":"WNT8A induces signalling via FZD8 (and FZD5) in a FZD-knockout reporter map; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 [PMID:28733458]; it acts through a restricted set of FZD genes [PMID:28733458].","molecular_requirements":"FZD8 alone sufficed in the rescue setup; co-receptor need is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in HEK293 reporter cells with FZD knockouts [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map in HEK293 cells; promiscuous FZD5/FZD8 (about 70% homology) may be redundant [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR002055","LR005381"]},"LR003531":{"pair":"WNT8A -> LRP6","headline":"WNT8A-LRP6 has two papers: Xenopus competition binding with Wise (Wnt8 not resolved to a paralog) and a neuron pull-down.","interaction_type":"direct binding","direction_and_effect":"Wise physically interacts with LRP6 and competes with Wnt8 for LRP6 binding [PMID:12900447]. In neurons, endogenous LRP6 was pulled down in Wnt8A-myc transfected cells but not mock cells (data not shown); Wnt8A promotes synaptogenesis via LRP6 [PMID:24316074].","molecular_requirements":"LRP6 acts as co-receptor for canonical Wnt ligands [PMID:24316074]; Frizzled requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus for [PMID:12900447]; HEK cells and dissociated neuron cultures for [PMID:24316074]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"[PMID:12900447] is abstract-only and refers to 'Wnt8' generically, so paralog identity is unresolved. The pull-down in [PMID:24316074] is 'data not shown', background to a synapse study. Three further papers were abstract_insufficient.","key_references":[{"PMID":"12900447","why":"Wise competes with Wnt8 for LRP6 binding"},{"PMID":"24316074","why":"Wnt8A pulls down LRP6 and promotes synaptogenesis via LRP6"}],"covers":["LR003531","LR006731"]},"LR003540":{"pair":"WNT9A -> FZD8","headline":"WNT9A-FZD8 is supported by a single prostate-cancer abstract; binding is stated but not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Castration enhanced FZD8 binding to Wnt9A and mediated cellular plasticity by activating the non-canonical Wnt (FZD8/FYN/STAT3) pathway [PMID:37771187].","molecular_requirements":"Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Prostate cancer cells (species not stated in the abstract) [PMID:37771187]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Abstract only; the binding assay is not described. The effect is non-canonical signalling after YY1-driven FZD8 transcription, so the evidence is context-specific. A second judged row was abstract_insufficient.","key_references":[{"PMID":"37771187","why":"Reports enhanced FZD8-Wnt9A binding and FZD8/FYN/STAT3 signalling in prostate cancer cells."}],"covers":["LR003540","LR006740"]},"LR010803":{"pair":"WNT9A -> FZD9:LRP6","headline":"WNT9A signalling through FZD9 with LRP6: functional evidence from one zebrafish/human-cell study, with LRP6 shown necessary for signalling.","interaction_type":"functional only","direction_and_effect":"The study reports that Wnt9a signals through Fzd9b, the co-receptor LRP5 or LRP6, and EGFR; the Wnt9a-Fzd9b complex was endocytosed and this was required for signalling [PMID:38626007].","molecular_requirements":"LRP5/6 double knockout HEK293 cells showed no Wnt9a-Fzd9b signalling, so LRP5/6 are required for signal transduction but not for endocytosis; AXIN also required for signalling; EGFR-dependent endocytosis is needed [PMID:38626007]. The study does not separate LRP5 from LRP6 (double knockout and 'LRP5/6').","affinity_potency":[],"species_and_systems":"Human cells (HEK293) with fluorescent Wnt9a and Fzd9b (zebrafish Fzd9b) fusion proteins; zebrafish used for development [PMID:38626007].","localisation_and_range":"WNT9A/WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor chains are membrane receptors [flag].","caveats":"Curator row is abstract_only although full-text excerpts were available. Study concerns zebrafish Fzd9b, not human FZD9 directly; no binding assay or affinity reported. LRP5 and LRP6 not distinguished.","key_references":[{"PMID":"38626007","why":"Wnt9a-Fzd9b endocytosis and LRP5/6 requirement"}],"covers":["LR010803"]},"LR001623":{"pair":"ZG16B -> TLR2","headline":"Well supported direct binding: PAUF binds TLR2 in receptor screen, ELISA, co-IP and cell-surface assays, and activates ERK signalling.","interaction_type":"direct binding","direction_and_effect":"PAUF was identified as an endogenous ligand of TLR2 by screening extracellular-domain receptor pools; the screen gave a positive signal for TLR2 only, and ELISA with purified ectodomain showed dose-dependent binding [PMID:20802527]. PAUF induced ERK phosphorylation via the IKK-beta-mediated TPL2/MEK/ERK pathway through TLR2 but did not activate NF-kB [PMID:20802527].","molecular_requirements":"Binding occurred with E. coli-produced (non-glycosylated) PAUF, and tunicamycin did not block the interaction, so glycosylation is not required [PMID:20802527]. Co-receptor need is not reported; PAUF also associates with CXCR4-TLR2 [PMID:20802527].","affinity_potency":[],"species_and_systems":"Human proteins: purified receptor ectodomain, full-length proteins in HEK293T cells, and THP-1 cells, where anti-TLR2 antibody reduced PAUF binding [PMID:20802527]. IntAct records an ELISA [DB:IntAct].","localisation_and_range":"ZG16B (PAUF) is flagged secreted [flag] and the paper treats it as a soluble ligand acting on cell-surface receptors [PMID:20802527].","caveats":"No affinity constant is reported in our evidence. Binding signal is shared with TLR4 and the paper reports TLR5 and TLR6 association too, so paralog specificity is limited.","key_references":[{"PMID":"20802527","why":"PAUF binds TLR2 directly; ERK activation"}],"covers":["LR001623"]},"LR012153":{"pair":"ZNRF3 -> FZD6:LRP5","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O60353) [DB:IntAct]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD6 partner is named in the UniProt statement; LRP5 evidence is limited to the UniProt statement or absent [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012153"]},"LR005340":{"pair":"SPX -> GALR3","headline":"Spexin is an agonist of GALR3, supported by receptor activation assays and an adipocyte study.","interaction_type":"functional only","direction_and_effect":"Agonist. SPX activated human, Xenopus and zebrafish GALR2/3 family receptors but not GALR1, and showed much higher potency at GALR3 than galanin [PMID:24517231]. In adipocytes, SPX effects were mediated via GALR2 and GALR3 [PMID:30305242]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Single receptor. In adipocytes both GALR2 and GALR3 were implicated [PMID:30305242]. Subunit needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Receptor activation across human, Xenopus and zebrafish receptors [PMID:24517231]; murine 3T3-L1 cells and human adipocytes [PMID:30305242]. Mouse pair is listed separately.","localisation_and_range":"SPX is annotated secreted and GALR3 transmembrane [flag]; paracrine or endocrine.","caveats":"Both papers abstract only. No assay of direct binding is shown; the potency number is not quoted. The adipocyte study cannot separate GALR2 from GALR3. UniProt names SPX as a GALR2/GALR3 ligand [DB:UniProt].","key_references":[{"PMID":"24517231","why":"SPX activates GALR2/3, more potent than galanin at GALR3."},{"PMID":"30305242","why":"SPX effects in adipocytes mediated via GALR2 and GALR3."}],"covers":["LR002012","LR005340"]}};